INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u5-C1','math',6,2,'u5',2,'원주 — 원의 중심·반지름·지름을 되짚고 원의 둘레를 원주라 하며, 원 안 정육각형(지름의 3배)과 원 밖 정사각형(지름의 4배)으로 원주가 지름의 3배보다 길고 4배보다 짧음을 알기',ARRAY['6수03-15']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u5-C2','math',6,2,'u5',3,'원주율 — 원의 지름에 대한 원주의 비율이 모든 원에서 일정함을 알고 (원주율) = (원주) ÷ (지름), 끝없이 이어지는 소수라 3.14로 어림해 쓰기',ARRAY['6수03-15']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u5-C3','math',6,2,'u5',4,'원주 구하기 — (원주) = (지름) × (원주율), 반지름만 알면 2를 먼저 곱해 지름을 만든 뒤 원주율을 곱하고, 굴러간 거리 문제에 쓰기',ARRAY['6수03-16']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u5-C4','math',6,2,'u5',4,'지름·반지름 구하기 — (지름) = (원주) ÷ (원주율)로 곱셈을 되짚어 지름과 반지름을 구하고, 원주·지름·반지름이 섞인 원의 크기를 견주기',ARRAY['6수03-16']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u5-C5','math',6,2,'u5',5,'원의 넓이 어림하기 — 모눈 칸(온전한 칸·걸친 칸)과 원 안·밖 정사각형으로 넓이가 들어갈 범위를 찾고, (반지름) × (반지름)의 2배와 4배 사이(약 3배)임을 알기',ARRAY['6수03-16']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u5-C6','math',6,2,'u5',6,'원의 넓이 구하기 — 원을 한없이 잘라 이어 붙인 직사각형(가로 원주의 반, 세로 반지름)으로 (원의 넓이) = (반지름) × (반지름) × (원주율)을 이끌어 내고 쓰기',ARRAY['6수03-16']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u5-C7','math',6,2,'u5',7,'원의 넓이 활용 — 고리 모양은 큰 원에서 작은 원을 빼고, 잘라 옮겨도 넓이는 그대로이며, 반원·사분원·조각은 원의 넓이를 나누어 구하기',ARRAY['6수03-16']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u5-C8','math',6,2,'u5',8,'반지름과 넓이의 관계 — 반지름이 □배가 되면 원주는 □배, 원의 넓이는 반지름을 두 번 곱하므로 □ × □배가 됨을 알고 쓰기',ARRAY['6수03-16']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u5-X01','math',6,'u5',ARRAY['M6-2-u5-C1','M6-2-u5-C3','M6-2-u5-C4','M6-2-u5-C6']::text[],'원의 중심·반지름·지름을 혼동하거나 (지름) = (반지름) × 2 관계를 거꾸로 쓴다','지름은 반지름 두 개') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u5-X02','math',6,'u5',ARRAY['M6-2-u5-C1','M6-2-u5-C2']::text[],'원주를 지름·반지름 같은 선분과 혼동하거나, 원주가 지름의 3배(4배)와 정확히 같다고 단정하거나, 다각형처럼 변을 더해 구하려 한다','3배보다 길고 4배보다 짧아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u5-X03','math',6,'u5',ARRAY['M6-2-u5-C1']::text[],'원 안 정육각형의 한 변을 지름으로, 원 밖 정사각형의 한 변을 반지름으로 바꾸어 본다','육각형 한 변 = 반지름') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u5-X04','math',6,'u5',ARRAY['M6-2-u5-C2']::text[],'원주율을 (지름) ÷ (원주)나 (원주) ÷ (반지름)으로 구한다(기준량을 잘못 잡음)','기준량은 지름') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u5-X05','math',6,'u5',ARRAY['M6-2-u5-C2']::text[],'원이 커지면 원주율도 커진다고, 또는 원마다 원주율이 다르다고 본다','원주율은 늘 같아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u5-X06','math',6,'u5',ARRAY['M6-2-u5-C2']::text[],'3.14가 원주율의 정확한 값이라 보거나, 잰 값의 작은 차이를 원주율이 달라서라고 본다','3.14는 어림한 값') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u5-X07','math',6,'u5',ARRAY['M6-2-u5-C3','M6-2-u5-C4']::text[],'반지름만 주어졌을 때 2를 곱하지 않고 반지름에 바로 원주율을 곱한다','반지름 × 2부터') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u5-X08','math',6,'u5',ARRAY['M6-2-u5-C3','M6-2-u5-C4']::text[],'원주를 구할 때 나누거나 지름을 구할 때 곱하는 등 곱셈·나눗셈을 거꾸로 쓴다','지름 × 3.14 = 원주') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u5-X09','math',6,'u5',ARRAY['M6-2-u5-C4']::text[],'반지름을 물었는데 지름을(또는 그 반대를) 답으로 쓴다','무엇을 묻나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u5-X10','math',6,'u5',ARRAY['M6-2-u5-C5']::text[],'넓이 어림에서 온전한 칸과 걸친 칸을 바꾸거나, 범위를 벗어난 값을 고르거나, 어림을 정확한 값으로 단정한다','어림은 범위') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u5-X11','math',6,'u5',ARRAY['M6-2-u5-C5']::text[],'원 안·밖 정사각형의 넓이가 (반지름) × (반지름)의 몇 배인지(2배·4배) 혼동한다','안은 2개, 밖은 4개') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u5-X12','math',6,'u5',ARRAY['M6-2-u5-C6','M6-2-u5-C7','M6-2-u5-C8']::text[],'원의 넓이를 원주 식((지름) × (원주율))으로 구하거나 원주와 넓이 식을 바꾸어 쓴다','넓이는 반지름을 두 번') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u5-X13','math',6,'u5',ARRAY['M6-2-u5-C6','M6-2-u5-C7']::text[],'원의 넓이를 구할 때 반지름 대신 지름을 두 번 곱한다','지름 말고 반지름') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u5-X14','math',6,'u5',ARRAY['M6-2-u5-C6','M6-2-u5-C8']::text[],'원의 넓이를 구할 때 반지름을 한 번만 곱한다((반지름) × (원주율))','반지름을 두 번') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u5-X15','math',6,'u5',ARRAY['M6-2-u5-C6']::text[],'원을 잘라 이어 붙인 직사각형의 가로를 원주 전체로, 세로를 지름으로 본다','가로는 원주의 반') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u5-X16','math',6,'u5',ARRAY['M6-2-u5-C7']::text[],'고리 모양의 넓이를 반지름의 차로 만든 원의 넓이로 구하거나 작은 원을 빼지 않는다','큰 원 - 작은 원') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u5-X17','math',6,'u5',ARRAY['M6-2-u5-C7']::text[],'잘라 옮기면 넓이가 변한다고 보거나, 반원·사분원·조각에서 나누기를 빠뜨리거나 잘못 나눈다','몇 조각 중 하나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u5-X18','math',6,'u5',ARRAY['M6-2-u5-C2','M6-2-u5-C8']::text[],'반지름(지름)이 □배일 때 원주·넓이가 몇 배인지 잘못 본다(넓이도 □배, 원주도 □ × □배, 차이로 늘리기)','넓이는 □ × □배') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u5-X19','math',6,'u5',ARRAY['M6-2-u5-C1','M6-2-u5-C2','M6-2-u5-C3','M6-2-u5-C4','M6-2-u5-C5','M6-2-u5-C6','M6-2-u5-C7','M6-2-u5-C8']::text[],'묻는 말을 거꾸로 읽는다 — 잘못된↔알맞은, 반지름↔지름, 큰↔작은','물음의 「잘못·않은」에 동그라미') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u5-X20','math',6,'u5',ARRAY['M6-2-u5-C1','M6-2-u5-C2','M6-2-u5-C3','M6-2-u5-C4','M6-2-u5-C5','M6-2-u5-C6','M6-2-u5-C7','M6-2-u5-C8']::text[],'소수 곱셈·나눗셈의 자릿수나 단위(cm·m)를 바꾸는 계산을 잘못한다','어림해서 확인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u5-X21','math',6,'u5',ARRAY['M6-2-u5-C6','M6-2-u5-C7']::text[],'직사각형 안에 그릴 수 있는 가장 큰 원의 지름을 긴 변으로 잡는다 — 원이 직사각형 밖으로 나가므로 지름은 짧은 변의 길이다','가장 큰 원의 지름 = 짧은 변') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u5-X22','math',6,'u5',ARRAY['M6-2-u5-C6']::text[],'원을 한없이 잘라 이어 붙여도 직사각형이 될 수 없다고 보거나, 8·16등분처럼 몇 번만 잘라 이어 붙인 모양을 이미 완전한 직사각형이라고 본다','잘게 자를수록 가까워지고, 한없이 자르면 직사각형') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u5-X23','math',6,'u5',ARRAY['M6-2-u5-C2']::text[],'원 안쪽에 맞닿는 정다각형의 (둘레)÷(지름)이 원주율과 같거나 더 크다고 보거나, 변의 수가 늘수록 원주율에서 멀어진다고 본다','원 안 다각형의 둘레는 원주보다 짧아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L02_basic#1','math',6,2,'u5','L02','tb_g6_2_math_u5_L02_basic','lesson_basic','M6-2-u5-C1',1,'mc','auto','원의 중심과 원 위의 한 점을 이은 선분을 무엇이라고 하나요?',ARRAY['M6-2-u5-X02','M6-2-u5-X01']::text[],true,'{"seq":1,"concept":"M6-2-u5-C1","difficulty":1,"kind":"mc","stem":"원의 중심과 원 위의 한 점을 이은 선분을 무엇이라고 하나요?","options":[{"t":"반지름","correct":true},{"t":"원주","mis":"M6-2-u5-X02"},{"t":"지름","mis":"M6-2-u5-X01"},{"t":"원의 중심","mis":"M6-2-u5-X01"}],"explanation":["원의 중심과 원 위의 한 점을 이은 선분을 반지름이라고 해요.","원의 중심과 원 위의 한 점을 이으면 반지름, 중심을 지나 원 위의 두 점을 이으면 지름이에요.","원주는 원의 둘레의 길이를 말하기도 해요."],"variant_rule":{"alt":[{"stem":"원의 중심을 지나도록 원 위의 두 점을 이은 선분을 무엇이라고 하나요?","options":[{"t":"지름","correct":true},{"t":"원주","mis":"M6-2-u5-X02"},{"t":"반지름","mis":"M6-2-u5-X01"},{"t":"원의 중심","mis":"M6-2-u5-X01"}],"explanation":["원의 중심을 지나도록 원 위의 두 점을 이은 선분을 지름이라고 해요.","원의 중심과 원 위의 한 점을 이으면 반지름, 중심을 지나 원 위의 두 점을 이으면 지름이에요.","원주는 원의 둘레의 길이를 말하기도 해요."]},{"stem":"원을 그릴 때 누름 못이 꽂혔던 점을 무엇이라고 하나요?","options":[{"t":"원의 중심","correct":true},{"t":"원주","mis":"M6-2-u5-X02"},{"t":"반지름","mis":"M6-2-u5-X01"},{"t":"지름","mis":"M6-2-u5-X01"}],"explanation":["원을 그릴 때 누름 못이 꽂혔던 점을 원의 중심이라고 해요.","원의 중심과 원 위의 한 점을 이으면 반지름, 중심을 지나 원 위의 두 점을 이으면 지름이에요.","원주는 원의 둘레의 길이를 말하기도 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L02_basic#2','math',6,2,'u5','L02','tb_g6_2_math_u5_L02_basic','lesson_basic','M6-2-u5-C6',1,'sa','auto','5학년 때 배운 넓이를 떠올려요. 가로가 3 cm, 세로가 2 cm인 직사각형의 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":2,"concept":"M6-2-u5-C6","difficulty":1,"kind":"sa","stem":"5학년 때 배운 넓이를 떠올려요. 가로가 3 cm, 세로가 2 cm인 직사각형의 넓이는 몇 cm²인가요?","answer":["6"],"explanation":["직사각형의 넓이는 (가로) × (세로)예요.","3 × 2를 계산해요.","3 × 2 = 6 — 넓이는 6 cm²예요."],"variant_rule":{"alt":[{"stem":"5학년 때 배운 넓이를 떠올려요. 한 변이 4 cm인 정사각형의 넓이는 몇 cm²인가요?","answer":["16"],"explanation":["정사각형의 넓이는 (한 변) × (한 변)이에요.","4 × 4를 계산해요.","4 × 4 = 16 — 넓이는 16 cm²예요."]},{"stem":"5학년 때 배운 넓이를 떠올려요. 두 대각선이 10 cm, 14 cm인 마름모의 넓이는 몇 cm²인가요?","answer":["70"],"explanation":["마름모의 넓이는 (한 대각선) × (다른 대각선) ÷ 2예요.","10 × 14 ÷ 2를 계산해요.","10 × 14 ÷ 2 = 70 — 넓이는 70 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L02_basic#3','math',6,2,'u5','L02','tb_g6_2_math_u5_L02_basic','lesson_basic','M6-2-u5-C1',1,'sa','auto','원 모양 얼음판의 지름은 16 m예요. 이 얼음판의 반지름은 몇 m인가요?','{}'::text[],true,'{"seq":3,"concept":"M6-2-u5-C1","difficulty":1,"kind":"sa","stem":"원 모양 얼음판의 지름은 16 m예요. 이 얼음판의 반지름은 몇 m인가요?","answer":["8"],"explanation":["반지름은 지름의 반이에요.","(반지름) = (지름) ÷ 2예요.","16 ÷ 2 = 8 — 반지름은 8 m예요."],"variant_rule":{"alt":[{"stem":"반지름이 5 cm인 원이 있어요. 이 원의 지름은 몇 cm인가요?","answer":["10"],"explanation":["지름은 원의 중심을 지나니 반지름 두 개를 이은 길이예요.","(지름) = (반지름) × 2예요.","5 × 2 = 10 — 지름은 10 cm예요."]},{"stem":"반지름이 8 cm인 원이 있어요. 이 원의 지름은 몇 cm인가요?","answer":["16"],"explanation":["지름은 원의 중심을 지나니 반지름 두 개를 이은 길이예요.","(지름) = (반지름) × 2예요.","8 × 2 = 16 — 지름은 16 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L02_basic#4','math',6,2,'u5','L02','tb_g6_2_math_u5_L02_basic','lesson_basic','M6-2-u5-C1',1,'mc','auto','친구들이 지름이 16 m인 원 모양 얼음판 위를 한 바퀴 돌았어요. 친구들이 돈 거리는 무엇과 같나요?',ARRAY['M6-2-u5-X02','M6-2-u5-X01','M6-2-u5-X12']::text[],true,'{"seq":4,"concept":"M6-2-u5-C1","difficulty":1,"kind":"mc","stem":"친구들이 지름이 16 m인 원 모양 얼음판 위를 한 바퀴 돌았어요. 친구들이 돈 거리는 무엇과 같나요?","options":[{"t":"원의 둘레","correct":true},{"t":"원의 지름","mis":"M6-2-u5-X02"},{"t":"원의 반지름","mis":"M6-2-u5-X01"},{"t":"원의 넓이","mis":"M6-2-u5-X12"}],"explanation":["한 바퀴 돌면 원 위를 빠짐없이 한 번 따라간 거예요.","그래서 돈 거리는 원의 둘레와 같아요.","원의 둘레를 원주라고 해요."],"variant_rule":{"alt":[{"stem":"원의 둘레를 무엇이라고 하나요?","options":[{"t":"원주","correct":true},{"t":"반지름","mis":"M6-2-u5-X02"},{"t":"지름","mis":"M6-2-u5-X02"},{"t":"원의 중심","mis":"M6-2-u5-X02"}],"explanation":["원의 둘레를 원주라고 해요.","원의 중심과 원 위의 한 점을 이으면 반지름, 중심을 지나 원 위의 두 점을 이으면 지름이에요.","원주는 원의 둘레의 길이를 말하기도 해요."]},{"stem":"500원짜리 동전과 100원짜리 동전의 둘레를 따라 손가락으로 그렸어요. 그린 선의 길이를 무엇이라고 하나요?","options":[{"t":"원주","correct":true},{"t":"지름","mis":"M6-2-u5-X02"},{"t":"반지름","mis":"M6-2-u5-X02"},{"t":"원의 중심","mis":"M6-2-u5-X01"}],"explanation":["동전은 원 모양이에요.","원의 둘레를 원주라고 해요.","원주는 원의 둘레의 길이를 말하기도 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L02_basic#5','math',6,2,'u5','L02','tb_g6_2_math_u5_L02_basic','lesson_basic','M6-2-u5-C1',2,'mc','auto','500원짜리 동전의 둘레를 털실로 두른 다음 곧게 펼쳤어요. 털실 위에 500원짜리 동전을 지름에 맞추어 겹치지 않게 나란히 이어 붙였더니 3개를 붙이고 조금 남았어요. 동전의 둘레는 동전의 지름의 약 몇 배인가요?',ARRAY['M6-2-u5-X02','M6-2-u5-X01']::text[],true,'{"seq":5,"concept":"M6-2-u5-C1","difficulty":2,"kind":"mc","stem":"500원짜리 동전의 둘레를 털실로 두른 다음 곧게 펼쳤어요. 털실 위에 500원짜리 동전을 지름에 맞추어 겹치지 않게 나란히 이어 붙였더니 3개를 붙이고 조금 남았어요. 동전의 둘레는 동전의 지름의 약 몇 배인가요?","options":[{"t":"약 3배","correct":true},{"t":"약 2배","mis":"M6-2-u5-X02"},{"t":"약 4배","mis":"M6-2-u5-X02"},{"t":"약 6배","mis":"M6-2-u5-X01"}],"explanation":["털실의 길이는 동전의 둘레(원주)와 같아요.","털실 위에 지름이 3번 들어가고 조금 남았어요.","그래서 동전의 둘레는 지름의 약 3배 — 3배보다 조금 길어요."],"variant_rule":{"alt":[{"stem":"지름이 4 cm인 원의 둘레에 맞추어 지름 막대를 이어 붙였어요. 3개로는 못 미치고 4개면 넘어섰어요. 이것으로 알 수 있는 것은 어느 것인가요?","options":[{"t":"원주는 지름의 3배보다 길고 4배보다 짧아요","correct":true},{"t":"원주는 지름의 3배와 정확히 같아요","mis":"M6-2-u5-X02"},{"t":"원주는 지름의 4배와 정확히 같아요","mis":"M6-2-u5-X02"},{"t":"원주는 지름보다 짧아요","mis":"M6-2-u5-X02"}],"explanation":["지름 막대 3개는 12 cm, 4개는 16 cm예요.","3개로는 못 미쳤으니 원주는 12 cm보다 길어요.","4개면 넘어섰으니 16 cm보다 짧아요 — 지름의 3배와 4배 사이예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L02_basic#6','math',6,2,'u5','L02','tb_g6_2_math_u5_L02_basic','lesson_basic','M6-2-u5-C1',2,'sa','auto','지름이 6 cm인 원 안에 꼭 맞는 정육각형이 있어요. 이 정육각형의 둘레는 몇 cm인가요?','{}'::text[],true,'{"seq":6,"concept":"M6-2-u5-C1","difficulty":2,"kind":"sa","stem":"지름이 6 cm인 원 안에 꼭 맞는 정육각형이 있어요. 이 정육각형의 둘레는 몇 cm인가요?","answer":["18"],"explanation":["원 안에 꼭 맞는 정육각형의 한 변은 반지름과 같아요.","반지름은 3이고 변이 6개이니 둘레는 3 × 6이에요.","3 × 6 = 18 — 지름의 3배인 18 cm예요."],"variant_rule":{"alt":[{"stem":"지름이 4 cm인 원 안에 꼭 맞는 정육각형이 있어요. 이 정육각형의 둘레는 몇 cm인가요?","answer":["12"],"explanation":["원 안에 꼭 맞는 정육각형의 한 변은 반지름과 같아요.","반지름은 2이고 변이 6개이니 둘레는 2 × 6이에요.","2 × 6 = 12 — 지름의 3배인 12 cm예요."]},{"stem":"지름이 10 cm인 원 안에 꼭 맞는 정육각형이 있어요. 이 정육각형의 둘레는 몇 cm인가요?","answer":["30"],"explanation":["원 안에 꼭 맞는 정육각형의 한 변은 반지름과 같아요.","반지름은 5이고 변이 6개이니 둘레는 5 × 6이에요.","5 × 6 = 30 — 지름의 3배인 30 cm예요."]}]},"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"O":[60,60],"h0":[110.0,60.0],"h1":[85.0,16.7],"h2":[35.0,16.7],"h3":[10.0,60.0],"h4":[35.0,103.3],"h5":[85.0,103.3]},"show":[],"circle":[["O",50],["O",2]],"poly":[["h0","h1","h2","h3","h4","h5"]],"seg":[["O","h0"],["O","h1"]],"lab":[[[78,30],"반지름"]]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L02_basic#7','math',6,2,'u5','L02','tb_g6_2_math_u5_L02_basic','lesson_basic','M6-2-u5-C1',2,'sa','auto','지름이 6 cm인 원 밖에 꼭 맞는 정사각형이 있어요. 이 정사각형의 둘레는 몇 cm인가요?','{}'::text[],true,'{"seq":7,"concept":"M6-2-u5-C1","difficulty":2,"kind":"sa","stem":"지름이 6 cm인 원 밖에 꼭 맞는 정사각형이 있어요. 이 정사각형의 둘레는 몇 cm인가요?","answer":["24"],"explanation":["원 밖에 꼭 맞는 정사각형의 한 변은 지름과 같아요.","한 변이 6 cm이고 변이 4개예요.","6 × 4 = 24 — 지름의 4배인 24 cm예요."],"variant_rule":{"alt":[{"stem":"지름이 4 cm인 원 밖에 꼭 맞는 정사각형이 있어요. 이 정사각형의 둘레는 몇 cm인가요?","answer":["16"],"explanation":["원 밖에 꼭 맞는 정사각형의 한 변은 지름과 같아요.","한 변이 4 cm이고 변이 4개예요.","4 × 4 = 16 — 지름의 4배인 16 cm예요."]},{"stem":"지름이 10 cm인 원 밖에 꼭 맞는 정사각형이 있어요. 이 정사각형의 둘레는 몇 cm인가요?","answer":["40"],"explanation":["원 밖에 꼭 맞는 정사각형의 한 변은 지름과 같아요.","한 변이 10 cm이고 변이 4개예요.","10 × 4 = 40 — 지름의 4배인 40 cm예요."]}]},"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"O":[60,60],"A":[10,10],"B":[110,10],"C":[110,110],"D":[10,110],"L":[10,60],"R":[110,60]},"show":[],"poly":[["A","B","C","D"]],"circle":[["O",50],["O",2]],"seg":[["L","R"]],"lab":[[[60,50],"지름"]]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L02_basic#8','math',6,2,'u5','L02','tb_g6_2_math_u5_L02_basic','lesson_basic','M6-2-u5-C1',2,'mc','auto','원 안에 꼭 맞는 정육각형의 한 변은 원의 무엇과 길이가 같나요?',ARRAY['M6-2-u5-X03','M6-2-u5-X02']::text[],true,'{"seq":8,"concept":"M6-2-u5-C1","difficulty":2,"kind":"mc","stem":"원 안에 꼭 맞는 정육각형의 한 변은 원의 무엇과 길이가 같나요?","options":[{"t":"반지름","correct":true},{"t":"지름","mis":"M6-2-u5-X03"},{"t":"원주","mis":"M6-2-u5-X02"},{"t":"원주의 반","mis":"M6-2-u5-X02"}],"explanation":["정육각형은 원의 중심을 꼭짓점으로 하는 정삼각형 6개로 나뉘어요.","정삼각형의 두 변이 반지름이니 정육각형의 한 변도 반지름과 같아요.","그래서 정육각형의 둘레는 반지름의 6배, 곧 지름의 3배예요."],"variant_rule":{"alt":[{"stem":"원 밖에 꼭 맞는 정사각형의 한 변은 원의 무엇과 길이가 같나요?","options":[{"t":"지름","correct":true},{"t":"반지름","mis":"M6-2-u5-X03"},{"t":"원주","mis":"M6-2-u5-X02"},{"t":"원주의 반","mis":"M6-2-u5-X02"}],"explanation":["정사각형이 원을 꼭 감싸면 마주 보는 두 변 사이가 원의 지름만큼 떨어져 있어요.","그래서 정사각형의 한 변은 지름과 같아요.","정사각형의 둘레는 지름의 4배예요."]},{"stem":"원 안에 꼭 맞는 정육각형의 둘레는 원의 지름의 몇 배인가요?","options":[{"t":"3배","correct":true},{"t":"6배","mis":"M6-2-u5-X03"},{"t":"2배","mis":"M6-2-u5-X03"},{"t":"4배","mis":"M6-2-u5-X03"}],"explanation":["정육각형의 한 변은 반지름과 같아요.","변이 6개이니 둘레는 반지름의 6배예요.","반지름 2개가 지름이니 반지름의 6배는 지름의 3배예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L02_basic#9','math',6,2,'u5','L02','tb_g6_2_math_u5_L02_basic','lesson_basic','M6-2-u5-C1',2,'ox','auto','원주는 지름의 정확히 3배예요.',ARRAY['M6-2-u5-X02']::text[],true,'{"seq":9,"concept":"M6-2-u5-C1","difficulty":2,"kind":"ox","stem":"원주는 지름의 정확히 3배예요.","answer":"X","reason_options":[{"t":"원주는 원 안 정육각형의 둘레(지름의 3배)보다 길기 때문에","correct":true},{"t":"원 안 정육각형의 둘레가 지름의 3배이기 때문에","mis":"M6-2-u5-X02"}],"mis":"M6-2-u5-X02","explanation":["원 안 정육각형의 둘레는 지름의 3배예요.","원 밖 정사각형의 둘레는 지름의 4배예요.","원주는 그 사이 — 지름의 3배보다 길고 4배보다 짧아요."],"variant_rule":{"alt":[{"stem":"원주는 원 밖에 꼭 맞는 정사각형의 둘레보다 짧아요.","answer":"O","reason_options":[{"t":"꺾인 선보다 원의 굽은 선이 더 짧기 때문에","correct":true},{"t":"정사각형의 한 변이 반지름과 같기 때문에","mis":"M6-2-u5-X03"}],"explanation":["원 안 정육각형의 둘레는 지름의 3배예요.","원 밖 정사각형의 둘레는 지름의 4배예요.","원주는 그 사이 — 지름의 3배보다 길고 4배보다 짧아요."]},{"stem":"원 안에 꼭 맞는 정육각형의 둘레는 원주보다 짧아요.","answer":"O","reason_options":[{"t":"두 점 사이를 이을 때 곧은 선이 굽은 선보다 짧기 때문에","correct":true},{"t":"정육각형의 한 변이 지름과 같기 때문에","mis":"M6-2-u5-X03"}],"explanation":["원 안 정육각형의 둘레는 지름의 3배예요.","원 밖 정사각형의 둘레는 지름의 4배예요.","원주는 그 사이 — 지름의 3배보다 길고 4배보다 짧아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L02_basic#10','math',6,2,'u5','L02','tb_g6_2_math_u5_L02_basic','lesson_basic','M6-2-u5-C1',3,'mc','auto','지름이 10 cm인 원의 원주가 될 수 있는 길이는 어느 것인가요?',ARRAY['M6-2-u5-X02']::text[],true,'{"seq":10,"concept":"M6-2-u5-C1","difficulty":3,"kind":"mc","stem":"지름이 10 cm인 원의 원주가 될 수 있는 길이는 어느 것인가요?","options":[{"t":"31.4 cm","correct":true},{"t":"29 cm","mis":"M6-2-u5-X02"},{"t":"42 cm","mis":"M6-2-u5-X02"},{"t":"10 cm","mis":"M6-2-u5-X02"}],"explanation":["원주는 지름의 3배보다 길고 4배보다 짧아요.","지름이 10 cm이면 원주는 30 cm와 40 cm 사이예요.","보기 가운데 그 사이에 있는 것은 31.4 cm뿐이에요."],"variant_rule":{"alt":[{"stem":"지름이 2 cm인 원의 둘레와 더 가까운 길이는 어느 것인가요?","options":[{"t":"7 cm","correct":true},{"t":"12 cm","mis":"M6-2-u5-X02"},{"t":"2 cm","mis":"M6-2-u5-X02"},{"t":"4 cm","mis":"M6-2-u5-X02"}],"explanation":["원주는 지름의 3배보다 길고 4배보다 짧아요.","지름이 2 cm이면 원주는 6 cm보다 길고 8 cm보다 짧아요.","보기 가운데 그 사이에 있는 것은 7 cm예요."]},{"stem":"지름이 6 cm인 원의 원주가 될 수 있는 길이는 어느 것인가요?","options":[{"t":"18.84 cm","correct":true},{"t":"17 cm","mis":"M6-2-u5-X02"},{"t":"26 cm","mis":"M6-2-u5-X02"},{"t":"6 cm","mis":"M6-2-u5-X02"}],"explanation":["원주는 지름의 3배보다 길고 4배보다 짧아요.","지름이 6 cm이면 원주는 18 cm와 24 cm 사이예요.","보기 가운데 그 사이에 있는 것은 18.84 cm뿐이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L02_challenge#1','math',6,2,'u5','L02','tb_g6_2_math_u5_L02_challenge','lesson_challenge','M6-2-u5-C1',2,'match','auto','원의 각 부분과 이름을 이으세요.','{}'::text[],true,'{"seq":1,"concept":"M6-2-u5-C1","difficulty":2,"kind":"match","stem":"원의 각 부분과 이름을 이으세요.","pairs":[{"l":"원을 그릴 때 누름 못이 꽂혔던 점","r":"원의 중심"},{"l":"원의 중심과 원 위의 한 점을 이은 선분","r":"반지름"},{"l":"원의 중심을 지나도록 원 위의 두 점을 이은 선분","r":"지름"}],"mis":"M6-2-u5-X01","explanation":["원을 그릴 때 누름 못이 꽂혔던 점이 원의 중심이에요.","원의 중심과 원 위의 한 점을 이으면 반지름이에요.","원의 중심을 지나 원 위의 두 점을 이으면 지름이에요."],"variant_rule":{"alt":[{"stem":"알맞은 것끼리 이으세요.","pairs":[{"l":"원의 중심과 원 위의 한 점을 이은 선분","r":"반지름"},{"l":"원의 중심을 지나 원 위의 두 점을 이은 선분","r":"지름"},{"l":"원의 둘레","r":"원주"}],"explanation":["원 안 정육각형의 한 변은 반지름, 원 밖 정사각형의 한 변은 지름이에요.","정육각형 둘레는 지름의 3배, 정사각형 둘레는 지름의 4배예요.","원 위를 한 바퀴 돈 거리가 원주예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L02_challenge#2','math',6,2,'u5','L02','tb_g6_2_math_u5_L02_challenge','lesson_challenge','M6-2-u5-C1',2,'mc','auto','한 변이 8 cm인 정사각형의 둘레는 변 네 개를 더해 32 cm예요. 원의 둘레를 이처럼 변을 더해서 구할 수 없는 까닭은 무엇인가요?',ARRAY['M6-2-u5-X02','M6-2-u5-X01']::text[],true,'{"seq":2,"concept":"M6-2-u5-C1","difficulty":2,"kind":"mc","stem":"한 변이 8 cm인 정사각형의 둘레는 변 네 개를 더해 32 cm예요. 원의 둘레를 이처럼 변을 더해서 구할 수 없는 까닭은 무엇인가요?","options":[{"t":"원에는 곧은 변이 하나도 없어서","correct":true},{"t":"원의 변은 지름 하나뿐이어서","mis":"M6-2-u5-X02"},{"t":"원은 꼭짓점이 너무 많아서","mis":"M6-2-u5-X02"},{"t":"원의 둘레는 반지름과 같아서","mis":"M6-2-u5-X01"}],"explanation":["다각형은 곧은 변의 길이를 더하면 둘레가 나와요.","원은 굽은 선 하나로 되어 있어 곧은 변이 없어요.","그래서 원의 둘레를 구하는 새로운 방법이 필요해요."],"variant_rule":{"alt":[{"stem":"한 변이 8 cm인 정사각형 안에 원이 꼭 맞게 들어 있어요. 원의 둘레는 정사각형의 둘레 32 cm와 견주어 어떤가요?","options":[{"t":"32 cm보다 짧아요","correct":true},{"t":"32 cm보다 길어요","mis":"M6-2-u5-X02"},{"t":"32 cm와 같아요","mis":"M6-2-u5-X02"},{"t":"8 cm보다 짧아요","mis":"M6-2-u5-X02"}],"explanation":["정사각형의 한 변 8 cm는 원의 지름과 같아요.","정사각형의 둘레 32 cm는 지름의 4배예요.","원주는 지름의 4배보다 짧으니 32 cm보다 짧아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L02_challenge#3','math',6,2,'u5','L02','tb_g6_2_math_u5_L02_challenge','lesson_challenge','M6-2-u5-C1',3,'error','auto','지름이 6 cm인 원의 원주를 두고 친구들이 말했어요. 잘못 말한 것은 어느 것인가요?',ARRAY['M6-2-u5-X02','M6-2-u5-X19']::text[],true,'{"seq":3,"concept":"M6-2-u5-C1","difficulty":3,"kind":"error","stem":"지름이 6 cm인 원의 원주를 두고 친구들이 말했어요. 잘못 말한 것은 어느 것인가요?","options":[{"t":"㉠ 「원주는 정확히 지름의 3배인 18 cm야.」","correct":true,"mis_target":"M6-2-u5-X02"},{"t":"㉡ 「원 안 정육각형의 둘레는 18 cm야.」","mis":"M6-2-u5-X19"},{"t":"㉢ 「원 밖 정사각형의 둘레는 24 cm야.」","mis":"M6-2-u5-X19"},{"t":"㉣ 「원주는 18 cm보다 길고 24 cm보다 짧아.」","mis":"M6-2-u5-X19"}],"explanation":["원 안 정육각형의 둘레는 18 cm, 원 밖 정사각형의 둘레는 24 cm예요.","원주는 정육각형의 둘레보다 길어요.","그래서 원주가 정확히 18 cm라는 ㉠의 말이 잘못되었어요."],"variant_rule":{"alt":[{"stem":"지름이 4 cm인 원의 원주를 두고 친구들이 말했어요. 잘못 말한 것은 어느 것인가요?","options":[{"t":"㉠ 「원주는 정확히 지름의 3배인 12 cm야.」","correct":true,"mis_target":"M6-2-u5-X02"},{"t":"㉡ 「원 안 정육각형의 둘레는 12 cm야.」","mis":"M6-2-u5-X19"},{"t":"㉢ 「원 밖 정사각형의 둘레는 16 cm야.」","mis":"M6-2-u5-X19"},{"t":"㉣ 「원주는 12 cm보다 길고 16 cm보다 짧아.」","mis":"M6-2-u5-X19"}],"explanation":["원 안 정육각형의 둘레는 12 cm, 원 밖 정사각형의 둘레는 16 cm예요.","원주는 정육각형의 둘레보다 길어요.","그래서 원주가 정확히 12 cm라는 ㉠의 말이 잘못되었어요."]},{"stem":"지름이 10 cm인 원의 원주를 두고 친구들이 말했어요. 잘못 말한 것은 어느 것인가요?","options":[{"t":"㉠ 「원주는 정확히 지름의 3배인 30 cm야.」","correct":true,"mis_target":"M6-2-u5-X02"},{"t":"㉡ 「원 안 정육각형의 둘레는 30 cm야.」","mis":"M6-2-u5-X19"},{"t":"㉢ 「원 밖 정사각형의 둘레는 40 cm야.」","mis":"M6-2-u5-X19"},{"t":"㉣ 「원주는 30 cm보다 길고 40 cm보다 짧아.」","mis":"M6-2-u5-X19"}],"explanation":["원 안 정육각형의 둘레는 30 cm, 원 밖 정사각형의 둘레는 40 cm예요.","원주는 정육각형의 둘레보다 길어요.","그래서 원주가 정확히 30 cm라는 ㉠의 말이 잘못되었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L02_challenge#4','math',6,2,'u5','L02','tb_g6_2_math_u5_L02_challenge','lesson_challenge','M6-2-u5-C1',3,'sa','auto','어떤 원 안에 꼭 맞는 정육각형의 둘레가 18 cm예요. 같은 원 밖에 꼭 맞는 정사각형의 둘레는 몇 cm인가요?','{}'::text[],true,'{"seq":4,"concept":"M6-2-u5-C1","difficulty":3,"kind":"sa","stem":"어떤 원 안에 꼭 맞는 정육각형의 둘레가 18 cm예요. 같은 원 밖에 꼭 맞는 정사각형의 둘레는 몇 cm인가요?","answer":["24"],"explanation":["원 안 정육각형의 둘레는 지름의 3배예요.","18 ÷ 3 = 6 — 지름은 6 cm예요.","원 밖 정사각형의 둘레는 지름의 4배 — 6 × 4 = 24 cm예요."],"variant_rule":{"alt":[{"stem":"어떤 원 안에 꼭 맞는 정육각형의 둘레가 12 cm예요. 같은 원 밖에 꼭 맞는 정사각형의 둘레는 몇 cm인가요?","answer":["16"],"explanation":["원 안 정육각형의 둘레는 지름의 3배예요.","12 ÷ 3 = 4 — 지름은 4 cm예요.","원 밖 정사각형의 둘레는 지름의 4배 — 4 × 4 = 16 cm예요."]},{"stem":"어떤 원 안에 꼭 맞는 정육각형의 둘레가 30 cm예요. 같은 원 밖에 꼭 맞는 정사각형의 둘레는 몇 cm인가요?","answer":["40"],"explanation":["원 안 정육각형의 둘레는 지름의 3배예요.","30 ÷ 3 = 10 — 지름은 10 cm예요.","원 밖 정사각형의 둘레는 지름의 4배 — 10 × 4 = 40 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L02_challenge#5','math',6,2,'u5','L02','tb_g6_2_math_u5_L02_challenge','lesson_challenge','M6-2-u5-C1',3,'sa','auto','어떤 원 밖에 꼭 맞는 정사각형의 둘레가 24 cm예요. 이 원의 반지름은 몇 cm인가요?','{}'::text[],true,'{"seq":5,"concept":"M6-2-u5-C1","difficulty":3,"kind":"sa","stem":"어떤 원 밖에 꼭 맞는 정사각형의 둘레가 24 cm예요. 이 원의 반지름은 몇 cm인가요?","answer":["3"],"explanation":["원 밖 정사각형의 한 변은 지름과 같아요.","24 ÷ 4 = 6 — 지름은 6 cm예요.","반지름은 지름의 반 — 6 ÷ 2 = 3 cm예요."],"mis":"M6-2-u5-X09","variant_rule":{"alt":[{"stem":"어떤 원 밖에 꼭 맞는 정사각형의 둘레가 40 cm예요. 이 원의 반지름은 몇 cm인가요?","answer":["5"],"explanation":["원 밖 정사각형의 한 변은 지름과 같아요.","40 ÷ 4 = 10 — 지름은 10 cm예요.","반지름은 지름의 반 — 10 ÷ 2 = 5 cm예요."]},{"stem":"어떤 원 밖에 꼭 맞는 정사각형의 둘레가 16 cm예요. 이 원의 반지름은 몇 cm인가요?","answer":["2"],"explanation":["원 밖 정사각형의 한 변은 지름과 같아요.","16 ÷ 4 = 4 — 지름은 4 cm예요.","반지름은 지름의 반 — 4 ÷ 2 = 2 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L02_challenge#6','math',6,2,'u5','L02','tb_g6_2_math_u5_L02_challenge','lesson_challenge','M6-2-u5-C1',3,'mc','auto','지름이 6 cm인 원 안에 꼭 맞는 정육각형과 원 밖에 꼭 맞는 정사각형이 있어요. 정육각형의 둘레, 원주, 정사각형의 둘레를 짧은 것부터 차례로 놓은 것은 어느 것인가요?',ARRAY['M6-2-u5-X02','M6-2-u5-X03']::text[],true,'{"seq":6,"concept":"M6-2-u5-C1","difficulty":3,"kind":"mc","stem":"지름이 6 cm인 원 안에 꼭 맞는 정육각형과 원 밖에 꼭 맞는 정사각형이 있어요. 정육각형의 둘레, 원주, 정사각형의 둘레를 짧은 것부터 차례로 놓은 것은 어느 것인가요?","options":[{"t":"정육각형의 둘레, 원주, 정사각형의 둘레","correct":true},{"t":"원주, 정육각형의 둘레, 정사각형의 둘레","mis":"M6-2-u5-X02"},{"t":"정육각형의 둘레, 정사각형의 둘레, 원주","mis":"M6-2-u5-X02"},{"t":"정사각형의 둘레, 원주, 정육각형의 둘레","mis":"M6-2-u5-X03"}],"explanation":["정육각형의 둘레는 지름의 3배인 18 cm, 정사각형의 둘레는 지름의 4배인 24 cm예요.","두 점 사이는 곧은 선이 굽은 선보다 짧고, 꺾인 선은 굽은 선보다 길어요.","그래서 18 cm < 원주 < 24 cm — 정육각형, 원주, 정사각형 차례예요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"O":[60,60],"A":[10,10],"B":[110,10],"C":[110,110],"D":[10,110],"h0":[110.0,60.0],"h1":[85.0,16.7],"h2":[35.0,16.7],"h3":[10.0,60.0],"h4":[35.0,103.3],"h5":[85.0,103.3]},"show":[],"poly":[["A","B","C","D"],["h0","h1","h2","h3","h4","h5"]],"circle":[["O",50],["O",2]]}]},"variant_rule":{"alt":[{"stem":"지름이 4 cm인 원 안에 꼭 맞는 정육각형과 원 밖에 꼭 맞는 정사각형이 있어요. 정육각형의 둘레, 원주, 정사각형의 둘레를 짧은 것부터 차례로 놓은 것은 어느 것인가요?","options":[{"t":"정육각형의 둘레, 원주, 정사각형의 둘레","correct":true},{"t":"원주, 정육각형의 둘레, 정사각형의 둘레","mis":"M6-2-u5-X02"},{"t":"정육각형의 둘레, 정사각형의 둘레, 원주","mis":"M6-2-u5-X02"},{"t":"정사각형의 둘레, 원주, 정육각형의 둘레","mis":"M6-2-u5-X03"}],"explanation":["정육각형의 둘레는 지름의 3배인 12 cm, 정사각형의 둘레는 지름의 4배인 16 cm예요.","두 점 사이는 곧은 선이 굽은 선보다 짧고, 꺾인 선은 굽은 선보다 길어요.","그래서 12 cm < 원주 < 16 cm — 정육각형, 원주, 정사각형 차례예요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"O":[60,60],"A":[10,10],"B":[110,10],"C":[110,110],"D":[10,110],"h0":[110.0,60.0],"h1":[85.0,16.7],"h2":[35.0,16.7],"h3":[10.0,60.0],"h4":[35.0,103.3],"h5":[85.0,103.3]},"show":[],"poly":[["A","B","C","D"],["h0","h1","h2","h3","h4","h5"]],"circle":[["O",50],["O",2]]}]}},{"stem":"지름이 10 cm인 원 안에 꼭 맞는 정육각형과 원 밖에 꼭 맞는 정사각형이 있어요. 정육각형의 둘레, 원주, 정사각형의 둘레를 짧은 것부터 차례로 놓은 것은 어느 것인가요?","options":[{"t":"정육각형의 둘레, 원주, 정사각형의 둘레","correct":true},{"t":"원주, 정육각형의 둘레, 정사각형의 둘레","mis":"M6-2-u5-X02"},{"t":"정육각형의 둘레, 정사각형의 둘레, 원주","mis":"M6-2-u5-X02"},{"t":"정사각형의 둘레, 원주, 정육각형의 둘레","mis":"M6-2-u5-X03"}],"explanation":["정육각형의 둘레는 지름의 3배인 30 cm, 정사각형의 둘레는 지름의 4배인 40 cm예요.","두 점 사이는 곧은 선이 굽은 선보다 짧고, 꺾인 선은 굽은 선보다 길어요.","그래서 30 cm < 원주 < 40 cm — 정육각형, 원주, 정사각형 차례예요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"O":[60,60],"A":[10,10],"B":[110,10],"C":[110,110],"D":[10,110],"h0":[110.0,60.0],"h1":[85.0,16.7],"h2":[35.0,16.7],"h3":[10.0,60.0],"h4":[35.0,103.3],"h5":[85.0,103.3]},"show":[],"poly":[["A","B","C","D"],["h0","h1","h2","h3","h4","h5"]],"circle":[["O",50],["O",2]]}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L02_challenge#7','math',6,2,'u5','L02','tb_g6_2_math_u5_L02_challenge','lesson_challenge','M6-2-u5-C1',3,'match','auto','알맞은 것끼리 이으세요.','{}'::text[],true,'{"seq":7,"concept":"M6-2-u5-C1","difficulty":3,"kind":"match","stem":"알맞은 것끼리 이으세요.","pairs":[{"l":"원 안 정육각형의 둘레","r":"지름의 3배"},{"l":"원 밖 정사각형의 둘레","r":"지름의 4배"},{"l":"지름","r":"반지름의 2배"}],"mis":"M6-2-u5-X01","explanation":["원 안 정육각형의 한 변은 반지름, 원 밖 정사각형의 한 변은 지름이에요.","정육각형 둘레는 지름의 3배, 정사각형 둘레는 지름의 4배예요.","원 위를 한 바퀴 돈 거리가 원주예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 알맞은 것끼리 이으세요.","pairs":[{"l":"원 안 정육각형의 한 변","r":"반지름"},{"l":"원 밖 정사각형의 한 변","r":"지름"},{"l":"원 위를 한 바퀴 돈 거리","r":"원주"}],"explanation":["원 안 정육각형의 한 변은 반지름, 원 밖 정사각형의 한 변은 지름이에요.","정육각형 둘레는 지름의 3배, 정사각형 둘레는 지름의 4배예요.","원 위를 한 바퀴 돈 거리가 원주예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L02_challenge#8','math',6,2,'u5','L02','tb_g6_2_math_u5_L02_challenge','lesson_challenge','M6-2-u5-C1',4,'sa','auto','어떤 원 안에 꼭 맞는 정육각형의 둘레와 원 밖에 꼭 맞는 정사각형의 둘레를 더했더니 42 cm였어요. 이 원의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":8,"concept":"M6-2-u5-C1","difficulty":4,"kind":"sa","stem":"어떤 원 안에 꼭 맞는 정육각형의 둘레와 원 밖에 꼭 맞는 정사각형의 둘레를 더했더니 42 cm였어요. 이 원의 지름은 몇 cm인가요?","answer":["6"],"explanation":["정육각형의 둘레는 지름의 3배, 정사각형의 둘레는 지름의 4배예요.","두 둘레를 더하면 지름의 7배예요.","42 ÷ 7 = 6 — 지름은 6 cm예요."],"variant_rule":{"alt":[{"stem":"어떤 원 안에 꼭 맞는 정육각형의 둘레와 원 밖에 꼭 맞는 정사각형의 둘레를 더했더니 70 cm였어요. 이 원의 반지름은 몇 cm인가요?","answer":["5"],"explanation":["두 둘레를 더하면 지름의 3배 + 4배 = 7배예요.","70 ÷ 7 = 10 — 지름은 10 cm예요.","반지름은 10 ÷ 2 = 5 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L02_challenge#9','math',6,2,'u5','L02','tb_g6_2_math_u5_L02_challenge','lesson_challenge','M6-2-u5-C1',4,'essay','teacher','반지름이 3 cm인 원 안에 꼭 맞는 정육각형과 원 밖에 꼭 맞는 정사각형을 그렸어요. 두 도형의 둘레를 구하고, 원주가 지름의 몇 배보다 길고 몇 배보다 짧은지 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M6-2-u5-C1","difficulty":4,"kind":"essay","stem":"반지름이 3 cm인 원 안에 꼭 맞는 정육각형과 원 밖에 꼭 맞는 정사각형을 그렸어요. 두 도형의 둘레를 구하고, 원주가 지름의 몇 배보다 길고 몇 배보다 짧은지 설명해 보세요.","answer_guide":{"answer":"예: 정육각형의 한 변은 반지름 3 cm와 같아 둘레는 3 × 6 = 18 cm로 지름 6 cm의 3배이다. 정사각형의 한 변은 지름 6 cm와 같아 둘레는 6 × 4 = 24 cm로 지름의 4배이다. 원주는 정육각형의 둘레보다 길고 정사각형의 둘레보다 짧으므로 지름의 3배보다 길고 4배보다 짧다.","scoring_points":["정육각형의 둘레 18 cm(지름의 3배)를 구했는가","정사각형의 둘레 24 cm(지름의 4배)를 구했는가","원주가 지름의 3배보다 길고 4배보다 짧다고 설명했는가"]},"explanation":["정육각형의 둘레는 3 × 6 = 18 cm예요.","정사각형의 둘레는 6 × 4 = 24 cm예요.","원주는 그 사이 — 지름의 3배보다 길고 4배보다 짧아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L02_challenge#10','math',6,2,'u5','L02','tb_g6_2_math_u5_L02_challenge','lesson_challenge','M6-2-u5-C1',4,'essay','teacher','털실 위에 500원짜리 동전을 이어 붙였더니 3개로는 털실 끝에 못 미치고, 4개를 붙이면 털실 끝을 넘어섰어요. 이 활동으로 원주와 지름의 관계를 설명하고, 동전끼리 겹치지 않게 붙여야 하는 까닭도 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u5-C1","difficulty":4,"kind":"essay","stem":"털실 위에 500원짜리 동전을 이어 붙였더니 3개로는 털실 끝에 못 미치고, 4개를 붙이면 털실 끝을 넘어섰어요. 이 활동으로 원주와 지름의 관계를 설명하고, 동전끼리 겹치지 않게 붙여야 하는 까닭도 써 보세요.","answer_guide":{"answer":"예: 털실의 길이가 동전의 원주이다. 지름 3개로는 못 미치고 4개면 넘으므로 원주는 지름의 3배보다 길고 4배보다 짧다(약 3배). 동전끼리 겹치면 지름보다 짧은 길이로 세게 되어 원주가 지름의 몇 배인지 바르게 알 수 없다.","scoring_points":["털실의 길이가 원주임을 밝혔는가","원주가 지름의 3배보다 길고 4배보다 짧다고 썼는가","겹치지 않게 붙이는 까닭을 썼는가"]},"explanation":["털실의 길이 = 동전의 원주예요.","지름 3개 < 원주 < 지름 4개예요.","겹치면 지름을 바르게 셀 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L03_basic#1','math',6,2,'u5','L03','tb_g6_2_math_u5_L03_basic','lesson_basic','M6-2-u5-C2',1,'mc','auto','원의 지름에 대한 원주의 비율을 무엇이라고 하나요?',ARRAY['M6-2-u5-X02','M6-2-u5-X01']::text[],true,'{"seq":1,"concept":"M6-2-u5-C2","difficulty":1,"kind":"mc","stem":"원의 지름에 대한 원주의 비율을 무엇이라고 하나요?","options":[{"t":"원주율","correct":true},{"t":"원주","mis":"M6-2-u5-X02"},{"t":"반지름","mis":"M6-2-u5-X01"},{"t":"지름","mis":"M6-2-u5-X01"}],"explanation":["원의 둘레가 원주예요.","모든 원에서 지름에 대한 원주의 비율은 일정해요.","그 비율을 원주율이라고 해요."],"variant_rule":{"alt":[{"stem":"원의 둘레를 ( ㉠ )(이)라고 하고, 원의 지름에 대한 원주의 비율을 ( ㉡ )(이)라고 해요. ㉠과 ㉡에 알맞은 말을 차례로 쓴 것은 어느 것인가요?","options":[{"t":"원주, 원주율","correct":true},{"t":"원주율, 원주","mis":"M6-2-u5-X04"},{"t":"지름, 원주","mis":"M6-2-u5-X02"},{"t":"원주, 반지름","mis":"M6-2-u5-X01"}],"explanation":["원의 둘레를 원주라고 해요.","원의 지름에 대한 원주의 비율을 원주율이라고 해요.","그래서 ㉠ 원주, ㉡ 원주율이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L03_basic#2','math',6,2,'u5','L03','tb_g6_2_math_u5_L03_basic','lesson_basic','M6-2-u5-C2',1,'mc','auto','원주율을 구하는 식으로 알맞은 것은 어느 것인가요?',ARRAY['M6-2-u5-X04']::text[],true,'{"seq":2,"concept":"M6-2-u5-C2","difficulty":1,"kind":"mc","stem":"원주율을 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"(원주) ÷ (지름)","correct":true},{"t":"(지름) ÷ (원주)","mis":"M6-2-u5-X04"},{"t":"(원주) × (지름)","mis":"M6-2-u5-X04"},{"t":"(원주) ÷ (반지름)","mis":"M6-2-u5-X04"}],"explanation":["원주율은 원의 지름에 대한 원주의 비율이에요.","비율은 (비교하는 양) ÷ (기준량) — 기준량은 지름이에요.","그래서 (원주율) = (원주) ÷ (지름)이에요."],"variant_rule":{"alt":[{"stem":"㉠ 「원주율은 (지름) ÷ (원주)입니다.」 ㉡ 「원주는 원의 둘레입니다.」 바르게 설명한 것은 어느 것인가요?","options":[{"t":"㉡","correct":true},{"t":"㉠","mis":"M6-2-u5-X04"},{"t":"㉠과 ㉡ 모두","mis":"M6-2-u5-X04"},{"t":"하나도 없어요","mis":"M6-2-u5-X19"}],"explanation":["원주율은 지름에 대한 원주의 비율 — (원주) ÷ (지름)이에요.","그래서 ㉠은 기준량을 거꾸로 잡았어요.","원주는 원의 둘레이니 ㉡이 바른 설명이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L03_basic#3','math',6,2,'u5','L03','tb_g6_2_math_u5_L03_basic','lesson_basic','M6-2-u5-C2',1,'mc','auto','주변에 있는 원 모양 물건의 원주를 재려고 해요. 원주를 잴 때 쓰기 알맞은 도구는 어느 것인가요?',ARRAY['M6-2-u5-X02']::text[],true,'{"seq":3,"concept":"M6-2-u5-C2","difficulty":1,"kind":"mc","stem":"주변에 있는 원 모양 물건의 원주를 재려고 해요. 원주를 잴 때 쓰기 알맞은 도구는 어느 것인가요?","options":[{"t":"줄자","correct":true},{"t":"곧은 자 하나","mis":"M6-2-u5-X02"},{"t":"삼각자 두 개","mis":"M6-2-u5-X02"},{"t":"각도기","mis":"M6-2-u5-X02"}],"explanation":["원주는 굽은 선의 길이예요.","줄자는 휘어져서 물건의 둘레를 따라 감을 수 있어요.","종이 끈이나 실을 원주만큼 잘라 눈금자로 재어도 돼요."],"variant_rule":{"alt":[{"stem":"주변에 있는 원 모양 물건의 지름을 재려고 해요. 알맞은 방법은 어느 것인가요?","options":[{"t":"삼각자 두 개 사이에 물건을 두고 삼각자 사이의 거리를 잰다","correct":true},{"t":"줄자로 물건을 한 바퀴 두른다","mis":"M6-2-u5-X02"},{"t":"물건의 둘레를 털실로 감아 잰다","mis":"M6-2-u5-X02"},{"t":"물건의 중심에서 가장자리까지 잰다","mis":"M6-2-u5-X09"}],"explanation":["지름은 원을 지나는 가장 긴 선분이에요.","자 위에 물건을 놓고 양쪽에 삼각자를 대면 그 사이가 지름이에요.","줄자로 한 바퀴 두르면 지름이 아니라 원주를 재요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L03_basic#4','math',6,2,'u5','L03','tb_g6_2_math_u5_L03_basic','lesson_basic','M6-2-u5-C2',1,'mc','auto','원 모양 접시의 원주가 31.4 cm, 지름이 10 cm예요. (원주) ÷ (지름)을 계산하면 얼마인가요?',ARRAY['M6-2-u5-X04','M6-2-u5-X20']::text[],true,'{"seq":4,"concept":"M6-2-u5-C2","difficulty":1,"kind":"mc","stem":"원 모양 접시의 원주가 31.4 cm, 지름이 10 cm예요. (원주) ÷ (지름)을 계산하면 얼마인가요?","options":[{"t":"3.14","correct":true},{"t":"6.28","mis":"M6-2-u5-X04"},{"t":"21.4","mis":"M6-2-u5-X20"},{"t":"31.4","mis":"M6-2-u5-X20"}],"explanation":["(원주) ÷ (지름)을 계산해요.","31.4 ÷ 10 = 3.14예요.","이 값이 원주율 — 어떤 원에서도 3.14쯤 나와요."],"variant_rule":{"alt":[{"stem":"원 모양 쟁반의 원주가 62.8 cm, 지름이 20 cm예요. (원주) ÷ (지름)을 계산하면 얼마인가요?","options":[{"t":"3.14","correct":true},{"t":"6.28","mis":"M6-2-u5-X04"},{"t":"42.8","mis":"M6-2-u5-X20"},{"t":"31.4","mis":"M6-2-u5-X20"}],"explanation":["(원주) ÷ (지름)을 계산해요.","62.8 ÷ 20 = 3.14예요.","이 값이 원주율 — 어떤 원에서도 3.14쯤 나와요."]},{"stem":"원 모양 시계의 원주가 47.1 cm, 지름이 15 cm예요. (원주) ÷ (지름)을 계산하면 얼마인가요?","options":[{"t":"3.14","correct":true},{"t":"6.28","mis":"M6-2-u5-X04"},{"t":"32.1","mis":"M6-2-u5-X20"},{"t":"31.4","mis":"M6-2-u5-X20"}],"explanation":["(원주) ÷ (지름)을 계산해요.","47.1 ÷ 15 = 3.14예요.","이 값이 원주율 — 어떤 원에서도 3.14쯤 나와요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L03_basic#5','math',6,2,'u5','L03','tb_g6_2_math_u5_L03_basic','lesson_basic','M6-2-u5-C2',2,'mc','auto','냄비 뚜껑의 원주를 재었더니 66 cm, 지름은 21 cm였어요. (원주) ÷ (지름)을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?',ARRAY['M6-2-u5-X20','M6-2-u5-X04']::text[],true,'{"seq":5,"concept":"M6-2-u5-C2","difficulty":2,"kind":"mc","stem":"냄비 뚜껑의 원주를 재었더니 66 cm, 지름은 21 cm였어요. (원주) ÷ (지름)을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"3.14","correct":true},{"t":"3.15","mis":"M6-2-u5-X20"},{"t":"3.1","mis":"M6-2-u5-X20"},{"t":"0.32","mis":"M6-2-u5-X04"}],"explanation":["66 ÷ 21 = 3.142857…이에요.","소수 셋째 자리를 보고 반올림해요.","그래서 3.14 — 원주율과 같은 값이에요."],"variant_rule":{"alt":[{"stem":"물병의 원주를 재었더니 20.4 cm, 지름은 6.5 cm였어요. (원주) ÷ (지름)을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"3.14","correct":true},{"t":"3.15","mis":"M6-2-u5-X20"},{"t":"3.1","mis":"M6-2-u5-X20"},{"t":"0.32","mis":"M6-2-u5-X04"}],"explanation":["20.4 ÷ 6.5 = 3.138461…이에요.","소수 셋째 자리를 보고 반올림해요.","그래서 3.14 — 원주율과 같은 값이에요."]},{"stem":"연필꽂이의 원주를 재었더니 23.9 cm, 지름은 7.6 cm였어요. (원주) ÷ (지름)을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"3.14","correct":true},{"t":"3.15","mis":"M6-2-u5-X20"},{"t":"3.1","mis":"M6-2-u5-X20"},{"t":"0.32","mis":"M6-2-u5-X04"}],"explanation":["23.9 ÷ 7.6 = 3.144736…이에요.","소수 셋째 자리를 보고 반올림해요.","그래서 3.14 — 원주율과 같은 값이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L03_basic#6','math',6,2,'u5','L03','tb_g6_2_math_u5_L03_basic','lesson_basic','M6-2-u5-C2',2,'mc','auto','「알지오매스 키즈」로 원을 그려 표를 만들었어요. 빈칸(?)에 들어갈 (원주) ÷ (지름)을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?',ARRAY['M6-2-u5-X20','M6-2-u5-X04']::text[],true,'{"seq":6,"concept":"M6-2-u5-C2","difficulty":2,"kind":"mc","stem":"「알지오매스 키즈」로 원을 그려 표를 만들었어요. 빈칸(?)에 들어갈 (원주) ÷ (지름)을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"3.14","correct":true},{"t":"3.15","mis":"M6-2-u5-X20"},{"t":"0.32","mis":"M6-2-u5-X04"},{"t":"6.28","mis":"M6-2-u5-X04"}],"explanation":["반지름이 7 cm니 지름은 14 cm예요.","43.98 ÷ 14 = 3.141…이에요.","소수 셋째 자리에서 반올림하면 3.14예요."],"asset":{"type":"expr_grid","rows":[["반지름 (cm)","지름 (cm)","원주 (cm)","(원주) ÷ (지름)"],["3","6","18.85","3.14"],["7","14","43.98",null]]},"variant_rule":{"alt":[{"stem":"「알지오매스 키즈」로 반지름이 3 cm인 원을 그렸더니 둘레가 18.85 cm였어요. (원주) ÷ (지름)을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"3.14","correct":true},{"t":"3.15","mis":"M6-2-u5-X20"},{"t":"0.32","mis":"M6-2-u5-X04"},{"t":"6.28","mis":"M6-2-u5-X04"}],"explanation":["반지름이 3 cm니 지름은 6 cm예요.","18.85 ÷ 6 = 3.141…이에요.","소수 셋째 자리에서 반올림하면 3.14예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L03_basic#7','math',6,2,'u5','L03','tb_g6_2_math_u5_L03_basic','lesson_basic','M6-2-u5-C2',2,'mc','auto','원주가 6.28 cm일 때 지름은 2 cm, 원주가 12.56 cm일 때 지름은 4 cm, 원주가 25.12 cm일 때 지름은 8 cm예요. 지름이 길어질 때 원주율은 어떻게 되나요?',ARRAY['M6-2-u5-X05','M6-2-u5-X06']::text[],true,'{"seq":7,"concept":"M6-2-u5-C2","difficulty":2,"kind":"mc","stem":"원주가 6.28 cm일 때 지름은 2 cm, 원주가 12.56 cm일 때 지름은 4 cm, 원주가 25.12 cm일 때 지름은 8 cm예요. 지름이 길어질 때 원주율은 어떻게 되나요?","options":[{"t":"일정합니다","correct":true},{"t":"커집니다","mis":"M6-2-u5-X05"},{"t":"작아집니다","mis":"M6-2-u5-X05"},{"t":"알 수 없습니다","mis":"M6-2-u5-X06"}],"explanation":["6.28 ÷ 2 = 3.14, 12.56 ÷ 4 = 3.14예요.","25.12 ÷ 8 = 3.14예요.","지름이 길어지면 원주도 함께 길어져 원주율은 일정해요."],"asset":{"type":"expr_grid","rows":[["원주 (cm)","지름 (cm)","(원주) ÷ (지름)"],["6.28","2","3.14"],["12.56","4","3.14"],["25.12","8",null]]},"variant_rule":{"alt":[{"stem":"지름이 7 cm인 원의 원주는 21.98 cm, 반지름이 4 cm인 원의 원주는 25.12 cm예요. 두 원의 (원주) ÷ (지름)을 비교하여 ○ 안에 >, =, < 중에서 알맞은 것은 어느 것인가요?","options":[{"t":"=","correct":true},{"t":">","mis":"M6-2-u5-X05"},{"t":"<","mis":"M6-2-u5-X05"},{"t":"비교할 수 없어요","mis":"M6-2-u5-X19"}],"explanation":["21.98 ÷ 7 = 3.14예요.","반지름 4 cm인 원의 지름은 8 cm — 25.12 ÷ 8 = 3.14예요.","두 값은 같아요 — 원의 크기가 달라도 원주율은 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L03_basic#8','math',6,2,'u5','L03','tb_g6_2_math_u5_L03_basic','lesson_basic','M6-2-u5-C2',2,'mc','auto','원주율에 대한 설명으로 잘못된 문장은 어느 것인가요?',ARRAY['M6-2-u5-X19']::text[],true,'{"seq":8,"concept":"M6-2-u5-C2","difficulty":2,"kind":"mc","stem":"원주율에 대한 설명으로 잘못된 문장은 어느 것인가요?","options":[{"t":"원주에 대한 원의 지름의 비율을 원주율이라고 합니다.","correct":true},{"t":"원의 크기가 달라져도 원주율은 일정합니다.","mis":"M6-2-u5-X19"},{"t":"반지름이 길어지면 원주도 길어집니다.","mis":"M6-2-u5-X19"},{"t":"원주율을 소수로 나타내면 끝없이 계속됩니다.","mis":"M6-2-u5-X19"}],"explanation":["보기를 하나씩 원주율의 뜻과 견주어 봐요.","원주율은 지름에 대한 원주의 비율 — 기준량이 지름이에요.","나머지 세 문장은 모두 바른 설명이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 원주율에 대한 설명으로 잘못된 문장은 어느 것인가요?","options":[{"t":"원이 커지면 원주율도 커집니다.","correct":true},{"t":"지름이 길어지면 원주도 길어집니다.","mis":"M6-2-u5-X19"},{"t":"원주는 지름의 약 3.14배입니다.","mis":"M6-2-u5-X19"},{"t":"원주율을 소수로 나타내면 끝없이 계속됩니다.","mis":"M6-2-u5-X19"}],"explanation":["보기를 하나씩 원주율의 뜻과 견주어 봐요.","원이 커져도 원주와 지름이 함께 늘어 원주율은 그대로예요.","나머지 세 문장은 모두 바른 설명이에요."]},{"stem":"이번에는 다른 보기예요. 원주율에 대한 설명으로 잘못된 문장은 어느 것인가요?","options":[{"t":"원주율은 정확히 3.14입니다.","correct":true},{"t":"원주율은 원의 크기와 상관없이 일정합니다.","mis":"M6-2-u5-X19"},{"t":"원주율은 (원주) ÷ (지름)으로 구합니다.","mis":"M6-2-u5-X19"},{"t":"원주는 지름의 3배보다 길고 4배보다 짧습니다.","mis":"M6-2-u5-X19"}],"explanation":["보기를 하나씩 원주율의 뜻과 견주어 봐요.","3.14는 끝없이 이어지는 원주율을 어림한 값이에요.","나머지 세 문장은 모두 바른 설명이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L03_basic#9','math',6,2,'u5','L03','tb_g6_2_math_u5_L03_basic','lesson_basic','M6-2-u5-C2',2,'ox','auto','지름이 길어지면 원주율도 커져요.',ARRAY['M6-2-u5-X05']::text[],true,'{"seq":9,"concept":"M6-2-u5-C2","difficulty":2,"kind":"ox","stem":"지름이 길어지면 원주율도 커져요.","answer":"X","reason_options":[{"t":"지름이 길어지면 원주도 함께 길어져 비율은 그대로이기 때문에","correct":true},{"t":"큰 원일수록 둘레가 길어 원주율도 크기 때문에","mis":"M6-2-u5-X05"}],"mis":"M6-2-u5-X05","explanation":["원주율은 원의 지름에 대한 원주의 비율이에요.","원이 커지면 원주와 지름이 함께 늘어 비율은 변하지 않아요.","원주율은 3.14159…로 끝없이 이어져 3.14로 어림해 써요."],"variant_rule":{"alt":[{"stem":"작은 동전과 큰 접시의 원주율은 같아요.","answer":"O","reason_options":[{"t":"모든 원에서 지름에 대한 원주의 비율은 일정하기 때문에","correct":true},{"t":"동전과 접시는 크기가 달라 원주율도 달라야 하기 때문에","mis":"M6-2-u5-X05"}],"explanation":["원주율은 원의 지름에 대한 원주의 비율이에요.","원이 커지면 원주와 지름이 함께 늘어 비율은 변하지 않아요.","원주율은 3.14159…로 끝없이 이어져 3.14로 어림해 써요."]},{"stem":"원주율 3.14는 정확한 값이에요.","answer":"X","reason_options":[{"t":"원주율은 끝없이 이어지는 소수라 3.14는 어림한 값이기 때문에","correct":true},{"t":"원주를 지름으로 나누면 언제나 3.14로 딱 떨어지기 때문에","mis":"M6-2-u5-X06"}],"explanation":["원주율은 원의 지름에 대한 원주의 비율이에요.","원이 커지면 원주와 지름이 함께 늘어 비율은 변하지 않아요.","원주율은 3.14159…로 끝없이 이어져 3.14로 어림해 써요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L03_basic#10','math',6,2,'u5','L03','tb_g6_2_math_u5_L03_basic','lesson_basic','M6-2-u5-C2',3,'mc','auto','냄비 뚜껑의 (원주) ÷ (지름)은 3.142857…, 물병의 값은 3.138461…였어요. 값이 조금씩 다른 까닭은 무엇인가요?',ARRAY['M6-2-u5-X05','M6-2-u5-X06']::text[],true,'{"seq":10,"concept":"M6-2-u5-C2","difficulty":3,"kind":"mc","stem":"냄비 뚜껑의 (원주) ÷ (지름)은 3.142857…, 물병의 값은 3.138461…였어요. 값이 조금씩 다른 까닭은 무엇인가요?","options":[{"t":"원주와 지름을 정확하게 재기 어렵기 때문에","correct":true},{"t":"원마다 원주율이 다르기 때문에","mis":"M6-2-u5-X05"},{"t":"큰 원일수록 원주율이 크기 때문에","mis":"M6-2-u5-X05"},{"t":"원주율이 3.14로 정해져 있지 않기 때문에","mis":"M6-2-u5-X06"}],"explanation":["원주율은 모든 원에서 일정해요.","줄자·자로 재는 값에는 작은 차이가 생겨요.","그래서 잰 값이 조금씩 달라도 늘 3.14쯤이 나와요."],"variant_rule":{"alt":[{"stem":"물병의 (원주) ÷ (지름)은 3.138461…, 연필꽂이의 값은 3.144736…였어요. 값이 조금씩 다른 까닭은 무엇인가요?","options":[{"t":"원주와 지름을 정확하게 재기 어렵기 때문에","correct":true},{"t":"원마다 원주율이 다르기 때문에","mis":"M6-2-u5-X05"},{"t":"큰 원일수록 원주율이 크기 때문에","mis":"M6-2-u5-X05"},{"t":"원주율이 3.14로 정해져 있지 않기 때문에","mis":"M6-2-u5-X06"}],"explanation":["원주율은 모든 원에서 일정해요.","줄자·자로 재는 값에는 작은 차이가 생겨요.","그래서 잰 값이 조금씩 달라도 늘 3.14쯤이 나와요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L03_challenge#1','math',6,2,'u5','L03','tb_g6_2_math_u5_L03_challenge','lesson_challenge','M6-2-u5-C2',2,'sa','auto','지름이 2 cm일 때 원주는 6.28 cm, 지름이 4 cm일 때 원주는 12.56 cm예요. 지름이 2배가 될 때 원주는 몇 배가 되나요?','{}'::text[],true,'{"seq":1,"concept":"M6-2-u5-C2","difficulty":2,"kind":"sa","stem":"지름이 2 cm일 때 원주는 6.28 cm, 지름이 4 cm일 때 원주는 12.56 cm예요. 지름이 2배가 될 때 원주는 몇 배가 되나요?","answer":["2"],"explanation":["12.56 ÷ 6.28 = 2예요.","지름이 2배가 되니 원주도 2배가 되었어요.","원주율이 일정해서 원주는 지름과 같은 배수로 늘어요."],"variant_rule":{"alt":[{"stem":"지름이 2 cm일 때 원주는 6.28 cm, 지름이 8 cm일 때 원주는 25.12 cm예요. 지름이 4배가 될 때 원주는 몇 배가 되나요?","answer":["4"],"explanation":["25.12 ÷ 6.28 = 4예요.","지름이 4배가 되니 원주도 4배가 되었어요.","원주율이 일정해서 원주는 지름과 같은 배수로 늘어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L03_challenge#2','math',6,2,'u5','L03','tb_g6_2_math_u5_L03_challenge','lesson_challenge','M6-2-u5-C2',2,'error','auto','원주율을 두고 친구들이 말했어요. 잘못 말한 것은 어느 것인가요?',ARRAY['M6-2-u5-X05','M6-2-u5-X19']::text[],true,'{"seq":2,"concept":"M6-2-u5-C2","difficulty":2,"kind":"error","stem":"원주율을 두고 친구들이 말했어요. 잘못 말한 것은 어느 것인가요?","options":[{"t":"㉠ 「큰 원은 원주율도 더 커.」","correct":true,"mis_target":"M6-2-u5-X05"},{"t":"㉡ 「원주율은 (원주) ÷ (지름)이야.」","mis":"M6-2-u5-X19"},{"t":"㉢ 「원주율은 원의 크기와 상관없이 일정해.」","mis":"M6-2-u5-X19"},{"t":"㉣ 「원주율은 끝없이 이어지는 소수야.」","mis":"M6-2-u5-X19"}],"explanation":["원주율은 (원주) ÷ (지름)이에요.","모든 원에서 일정하고 3.14159…로 끝없이 이어져요.","그래서 ㉠의 말이 잘못되었어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 원주율을 두고 친구들이 말했어요. 잘못 말한 것은 어느 것인가요?","options":[{"t":"㉠ 「원주율은 (지름) ÷ (원주)로 구해.」","correct":true,"mis_target":"M6-2-u5-X04"},{"t":"㉡ 「원주율은 (원주) ÷ (지름)이야.」","mis":"M6-2-u5-X19"},{"t":"㉢ 「원주율은 원의 크기와 상관없이 일정해.」","mis":"M6-2-u5-X19"},{"t":"㉣ 「원주율은 끝없이 이어지는 소수야.」","mis":"M6-2-u5-X19"}],"explanation":["원주율은 (원주) ÷ (지름)이에요.","모든 원에서 일정하고 3.14159…로 끝없이 이어져요.","그래서 ㉠의 말이 잘못되었어요."]},{"stem":"이번에는 다른 보기예요. 원주율을 두고 친구들이 말했어요. 잘못 말한 것은 어느 것인가요?","options":[{"t":"㉠ 「3.14는 원주율의 정확한 값이야.」","correct":true,"mis_target":"M6-2-u5-X06"},{"t":"㉡ 「원주율은 (원주) ÷ (지름)이야.」","mis":"M6-2-u5-X19"},{"t":"㉢ 「원주율은 원의 크기와 상관없이 일정해.」","mis":"M6-2-u5-X19"},{"t":"㉣ 「원주율은 끝없이 이어지는 소수야.」","mis":"M6-2-u5-X19"}],"explanation":["원주율은 (원주) ÷ (지름)이에요.","모든 원에서 일정하고 3.14159…로 끝없이 이어져요.","그래서 ㉠의 말이 잘못되었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L03_challenge#3','math',6,2,'u5','L03','tb_g6_2_math_u5_L03_challenge','lesson_challenge','M6-2-u5-C2',3,'mc','auto','「알지오매스 키즈」로 반지름이 5 cm인 원 안쪽에 맞닿는 정다각형을 그려 둘레를 재었어요. 정사각형 28.28 cm, 정육각형 30 cm, 정십이각형 31.08 cm, 정이십이각형 31.24 cm예요. (둘레) ÷ (지름)이 원주율에 가장 가까운 것은 어느 것인가요?',ARRAY['M6-2-u5-X23']::text[],true,'{"seq":3,"concept":"M6-2-u5-C2","difficulty":3,"kind":"mc","stem":"「알지오매스 키즈」로 반지름이 5 cm인 원 안쪽에 맞닿는 정다각형을 그려 둘레를 재었어요. 정사각형 28.28 cm, 정육각형 30 cm, 정십이각형 31.08 cm, 정이십이각형 31.24 cm예요. (둘레) ÷ (지름)이 원주율에 가장 가까운 것은 어느 것인가요?","options":[{"t":"정이십이각형","correct":true},{"t":"정사각형","mis":"M6-2-u5-X23"},{"t":"정육각형","mis":"M6-2-u5-X23"},{"t":"정십이각형","mis":"M6-2-u5-X23"}],"explanation":["지름은 10 cm — 28.28 ÷ 10 = 2.828, 30 ÷ 10 = 3이에요.","31.08 ÷ 10 = 3.108, 31.24 ÷ 10 = 3.124예요.","변의 수가 늘수록 원에 가까워져 원주율 3.14에 가장 가까운 것은 정이십이각형이에요."],"variant_rule":{"alt":[{"stem":"「알지오매스 키즈」로 반지름이 5 cm인 원 안쪽에 맞닿는 정육각형을 그렸더니 둘레가 30 cm였어요. (정육각형의 둘레) ÷ (지름)은 얼마인가요?","options":[{"t":"3","correct":true},{"t":"6","mis":"M6-2-u5-X04"},{"t":"3.14","mis":"M6-2-u5-X23"},{"t":"0.3","mis":"M6-2-u5-X20"}],"explanation":["원의 반지름이 5 cm니 지름은 10 cm예요.","30 ÷ 10 = 3이에요.","원 안쪽 다각형의 둘레는 원주보다 짧아서 이 값은 원주율 3.14보다 작아요."]},{"stem":"「알지오매스 키즈」로 반지름이 5 cm인 원 안쪽에 맞닿는 정십이각형을 그렸더니 둘레가 31.08 cm였어요. (정십이각형의 둘레) ÷ (지름)은 얼마인가요?","options":[{"t":"3.108","correct":true},{"t":"6.216","mis":"M6-2-u5-X04"},{"t":"3.14","mis":"M6-2-u5-X23"},{"t":"0.3108","mis":"M6-2-u5-X20"}],"explanation":["원의 반지름이 5 cm니 지름은 10 cm예요.","31.08 ÷ 10 = 3.108이에요.","원 안쪽 다각형의 둘레는 원주보다 짧아서 이 값은 원주율 3.14보다 작아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L03_challenge#4','math',6,2,'u5','L03','tb_g6_2_math_u5_L03_challenge','lesson_challenge','M6-2-u5-C2',3,'ox','auto','반지름에 대한 원주의 비율도 3.14예요.',ARRAY['M6-2-u5-X04']::text[],true,'{"seq":4,"concept":"M6-2-u5-C2","difficulty":3,"kind":"ox","stem":"반지름에 대한 원주의 비율도 3.14예요.","answer":"X","reason_options":[{"t":"원주는 반지름의 약 6.28배이기 때문에","correct":true},{"t":"반지름도 원의 길이니 비율이 같기 때문에","mis":"M6-2-u5-X04"}],"mis":"M6-2-u5-X04","explanation":["(원주율) = (원주) ÷ (지름)이에요.","원이 커져도 원주와 지름이 함께 늘어요.","그래서 원주율은 늘 약 3.14예요."],"variant_rule":{"alt":[{"stem":"원주가 길어지면 원주율도 커져요.","answer":"X","reason_options":[{"t":"원주가 길어지면 지름도 함께 길어져 비율은 그대로이기 때문에","correct":true},{"t":"원주율은 원주에 비례하기 때문에","mis":"M6-2-u5-X05"}],"explanation":["(원주율) = (원주) ÷ (지름)이에요.","원이 커져도 원주와 지름이 함께 늘어요.","그래서 원주율은 늘 약 3.14예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L03_challenge#5','math',6,2,'u5','L03','tb_g6_2_math_u5_L03_challenge','lesson_challenge','M6-2-u5-C2',3,'match','auto','알맞은 것끼리 이으세요.','{}'::text[],true,'{"seq":5,"concept":"M6-2-u5-C2","difficulty":3,"kind":"match","stem":"알맞은 것끼리 이으세요.","pairs":[{"l":"원주","r":"원의 둘레"},{"l":"원주율","r":"(원주) ÷ (지름)"},{"l":"지름","r":"(원주) ÷ (원주율)"}],"mis":"M6-2-u5-X04","explanation":["원주율은 (원주) ÷ (지름)이에요.","원주는 (지름) × (원주율), 지름은 (원주) ÷ (원주율)이에요.","원주율은 약 3.14로 어림해 써요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 알맞은 것끼리 이으세요.","pairs":[{"l":"원주","r":"(지름) × (원주율)"},{"l":"원주율","r":"약 3.14"},{"l":"반지름","r":"(지름) ÷ 2"}],"explanation":["원주율은 (원주) ÷ (지름)이에요.","원주는 (지름) × (원주율), 지름은 (원주) ÷ (원주율)이에요.","원주율은 약 3.14로 어림해 써요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L03_challenge#6','math',6,2,'u5','L03','tb_g6_2_math_u5_L03_challenge','lesson_challenge','M6-2-u5-C2',3,'mc','auto','지름이 2 cm인 원의 원주는 6.28 cm예요. 지름이 8 cm인 원의 원주는 몇 cm인가요?',ARRAY['M6-2-u5-X18','M6-2-u5-X20']::text[],true,'{"seq":6,"concept":"M6-2-u5-C2","difficulty":3,"kind":"mc","stem":"지름이 2 cm인 원의 원주는 6.28 cm예요. 지름이 8 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"25.12 cm","correct":true},{"t":"12.28 cm","mis":"M6-2-u5-X18"},{"t":"100.48 cm","mis":"M6-2-u5-X18"},{"t":"12.56 cm","mis":"M6-2-u5-X20"}],"explanation":["지름이 4배가 되었어요.","원주율이 일정하니 원주도 4배가 돼요.","6.28 × 4 = 25.12 cm예요."],"variant_rule":{"alt":[{"stem":"지름이 2 cm인 원의 원주는 6.28 cm예요. 지름이 4 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"12.56 cm","correct":true},{"t":"8.28 cm","mis":"M6-2-u5-X18"},{"t":"25.12 cm","mis":"M6-2-u5-X18"},{"t":"6.28 cm","mis":"M6-2-u5-X20"}],"explanation":["지름이 2배가 되었어요.","원주율이 일정하니 원주도 2배가 돼요.","6.28 × 2 = 12.56 cm예요."]},{"stem":"지름이 4 cm인 원의 원주는 12.56 cm예요. 지름이 8 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"25.12 cm","correct":true},{"t":"16.56 cm","mis":"M6-2-u5-X18"},{"t":"50.24 cm","mis":"M6-2-u5-X18"},{"t":"12.56 cm","mis":"M6-2-u5-X20"}],"explanation":["지름이 2배가 되었어요.","원주율이 일정하니 원주도 2배가 돼요.","12.56 × 2 = 25.12 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L03_challenge#7','math',6,2,'u5','L03','tb_g6_2_math_u5_L03_challenge','lesson_challenge','M6-2-u5-C2',3,'mc','auto','지윤이가 원 모양인 거울의 반지름과 원주를 재었더니 반지름이 7 cm, 원주가 43.96 cm였어요. (원주) ÷ (지름)은 얼마인가요?',ARRAY['M6-2-u5-X04','M6-2-u5-X20']::text[],true,'{"seq":7,"concept":"M6-2-u5-C2","difficulty":3,"kind":"mc","stem":"지윤이가 원 모양인 거울의 반지름과 원주를 재었더니 반지름이 7 cm, 원주가 43.96 cm였어요. (원주) ÷ (지름)은 얼마인가요?","options":[{"t":"3.14","correct":true},{"t":"6.28","mis":"M6-2-u5-X04"},{"t":"0.32","mis":"M6-2-u5-X04"},{"t":"3.15","mis":"M6-2-u5-X20"}],"explanation":["반지름이 7 cm니 지름은 14 cm예요.","43.96 ÷ 14 = 3.14예요.","반지름으로 나누면 6.28이 나와요 — 원주율은 지름으로 나눠요."],"variant_rule":{"alt":[{"stem":"원 모양 접시의 원주는 47.1 cm, 지름은 15 cm예요. 원주는 지름의 몇 배인가요?","options":[{"t":"3.14배","correct":true},{"t":"6.28배","mis":"M6-2-u5-X04"},{"t":"0.32배","mis":"M6-2-u5-X04"},{"t":"32.1배","mis":"M6-2-u5-X20"}],"explanation":["(원주) ÷ (지름)을 계산해요.","47.1 ÷ 15 = 3.14예요.","원주는 지름의 3.14배 — 이 값이 원주율이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L03_challenge#8','math',6,2,'u5','L03','tb_g6_2_math_u5_L03_challenge','lesson_challenge','M6-2-u5-C2',4,'mc','auto','⟨22/7⟩를 소수로 나타내면 3.142857…이에요. 원주율 3.14159…에 더 가까운 것은 ⟨22/7⟩와 3.14 가운데 어느 것인가요?',ARRAY['M6-2-u5-X06','M6-2-u5-X19']::text[],false,'{"seq":8,"concept":"M6-2-u5-C2","difficulty":4,"kind":"mc","stem":"⟨22/7⟩를 소수로 나타내면 3.142857…이에요. 원주율 3.14159…에 더 가까운 것은 ⟨22/7⟩와 3.14 가운데 어느 것인가요?","options":[{"t":"⟨22/7⟩","correct":true},{"t":"3.14","mis":"M6-2-u5-X06"},{"t":"두 수가 똑같이 가까워요","mis":"M6-2-u5-X06"},{"t":"비교할 수 없어요","mis":"M6-2-u5-X19"}],"explanation":["3.14159… 와 3.14의 차는 0.0015…예요.","3.142857… 와 3.14159…의 차는 0.0012…예요.","⟨22/7⟩가 조금 더 가깝지만 둘 다 원주율을 어림한 값이에요(7월 22일 「유사 파이 데이」)."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L03_challenge#9','math',6,2,'u5','L03','tb_g6_2_math_u5_L03_challenge','lesson_challenge','M6-2-u5-C2',4,'essay','teacher','원주가 6.28 cm인 원의 지름은 2 cm, 12.56 cm인 원의 지름은 4 cm, 25.12 cm인 원의 지름은 8 cm예요. 세 원의 원주율을 구하고, 원이 커져도 원주율이 변하지 않는 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M6-2-u5-C2","difficulty":4,"kind":"essay","stem":"원주가 6.28 cm인 원의 지름은 2 cm, 12.56 cm인 원의 지름은 4 cm, 25.12 cm인 원의 지름은 8 cm예요. 세 원의 원주율을 구하고, 원이 커져도 원주율이 변하지 않는 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 6.28 ÷ 2 = 3.14, 12.56 ÷ 4 = 3.14, 25.12 ÷ 8 = 3.14로 모두 같다. 지름이 2배, 4배가 되면 원주도 2배, 4배가 되어 지름에 대한 원주의 비율은 그대로이기 때문이다.","scoring_points":["세 원의 (원주) ÷ (지름)을 구해 3.14를 보였는가","원주율이 일정하다고 썼는가","지름과 원주가 함께 늘어 비율이 그대로라고 설명했는가"]},"explanation":["세 원 모두 (원주) ÷ (지름) = 3.14예요.","지름이 늘면 원주도 같은 배수로 늘어요.","그래서 원주율은 원의 크기와 상관없이 일정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L03_challenge#10','math',6,2,'u5','L03','tb_g6_2_math_u5_L03_challenge','lesson_challenge','M6-2-u5-C2',4,'essay','teacher','반지름이 5 cm인 원 안쪽에 맞닿는 정다각형의 둘레를 재었더니 정사각형 28.28 cm, 정육각형 30 cm, 정십이각형 31.08 cm, 정이십이각형 31.24 cm였어요. 각각 (둘레) ÷ (지름)을 구하고, 변의 수가 늘어날수록 어떻게 되는지 원주율과 견주어 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u5-C2","difficulty":4,"kind":"essay","stem":"반지름이 5 cm인 원 안쪽에 맞닿는 정다각형의 둘레를 재었더니 정사각형 28.28 cm, 정육각형 30 cm, 정십이각형 31.08 cm, 정이십이각형 31.24 cm였어요. 각각 (둘레) ÷ (지름)을 구하고, 변의 수가 늘어날수록 어떻게 되는지 원주율과 견주어 설명해 보세요.","answer_guide":{"answer":"예: 2.828, 3, 3.108, 3.124이다. 변의 수가 늘어날수록 정다각형은 원에 가까워지고 (둘레) ÷ (지름)도 원주율 3.14에 가까워진다. 원 안쪽에 있는 다각형의 둘레는 원주보다 짧으므로 값은 3.14보다 조금 작다.","scoring_points":["네 값을 바르게 구했는가","변의 수가 늘수록 3.14에 가까워진다고 썼는가","원 안 다각형이라 3.14보다 작다는 까닭을 썼는가"]},"explanation":["28.28 ÷ 10 = 2.828, 30 ÷ 10 = 3이에요.","31.08 ÷ 10 = 3.108, 31.24 ÷ 10 = 3.124예요.","변이 많아질수록 원에 가까워지고 값은 3.14에 가까워져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L04_basic#1','math',6,2,'u5','L04','tb_g6_2_math_u5_L04_basic','lesson_basic','M6-2-u5-C3',1,'mc','auto','지름을 알 때 원주를 구하는 식으로 알맞은 것은 어느 것인가요?',ARRAY['M6-2-u5-X08']::text[],true,'{"seq":1,"concept":"M6-2-u5-C3","difficulty":1,"kind":"mc","stem":"지름을 알 때 원주를 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"(지름) × (원주율)","correct":true},{"t":"(지름) ÷ (원주율)","mis":"M6-2-u5-X08"},{"t":"(지름) + (원주율)","mis":"M6-2-u5-X08"},{"t":"(원주율) ÷ (지름)","mis":"M6-2-u5-X08"}],"explanation":["(원주율) = (원주) ÷ (지름)이에요.","거꾸로 하면 (원주) = (지름) × (원주율)이에요.","지름에 3.14를 곱하면 원주가 나와요."],"variant_rule":{"alt":[{"stem":"(원주) = (지름) × ( □ )에서 □에 알맞은 말은 어느 것인가요?","options":[{"t":"원주율","correct":true},{"t":"반지름","mis":"M6-2-u5-X07"},{"t":"원주","mis":"M6-2-u5-X08"},{"t":"지름","mis":"M6-2-u5-X01"}],"explanation":["(원주율) = (원주) ÷ (지름)이에요.","거꾸로 하면 (원주) = (지름) × (원주율)이에요.","□에는 원주율이 들어가요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L04_basic#2','math',6,2,'u5','L04','tb_g6_2_math_u5_L04_basic','lesson_basic','M6-2-u5-C3',1,'mc','auto','자전거 바퀴의 지름은 80 cm예요. 자전거 바퀴가 한 바퀴 굴러간 거리는 몇 cm인가요?',ARRAY['M6-2-u5-X01','M6-2-u5-X12']::text[],true,'{"seq":2,"concept":"M6-2-u5-C3","difficulty":1,"kind":"mc","stem":"자전거 바퀴의 지름은 80 cm예요. 자전거 바퀴가 한 바퀴 굴러간 거리는 몇 cm인가요?","options":[{"t":"251.2 cm","correct":true},{"t":"125.6 cm","mis":"M6-2-u5-X01"},{"t":"502.4 cm","mis":"M6-2-u5-X01"},{"t":"5024 cm","mis":"M6-2-u5-X12"}],"explanation":["(원주) = (지름) × (원주율)이에요.","80 × 3.14를 계산해요.","80 × 3.14 = 251.2 — 원주는 251.2 cm예요."],"variant_rule":{"alt":[{"stem":"지름이 20 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"62.8 cm","correct":true},{"t":"31.4 cm","mis":"M6-2-u5-X01"},{"t":"125.6 cm","mis":"M6-2-u5-X01"},{"t":"314 cm","mis":"M6-2-u5-X12"}],"explanation":["(원주) = (지름) × (원주율)이에요.","20 × 3.14를 계산해요.","20 × 3.14 = 62.8 — 원주는 62.8 cm예요."]},{"stem":"지름이 4 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"12.56 cm","correct":true},{"t":"6.28 cm","mis":"M6-2-u5-X01"},{"t":"25.12 cm","mis":"M6-2-u5-X01"},{"t":"7.14 cm","mis":"M6-2-u5-X08"}],"explanation":["(원주) = (지름) × (원주율)이에요.","4 × 3.14를 계산해요.","4 × 3.14 = 12.56 — 원주는 12.56 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L04_basic#3','math',6,2,'u5','L04','tb_g6_2_math_u5_L04_basic','lesson_basic','M6-2-u5-C3',1,'mc','auto','반지름이 6 cm인 원의 원주는 몇 cm인가요?',ARRAY['M6-2-u5-X07','M6-2-u5-X12','M6-2-u5-X01']::text[],true,'{"seq":3,"concept":"M6-2-u5-C3","difficulty":1,"kind":"mc","stem":"반지름이 6 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"37.68 cm","correct":true},{"t":"18.84 cm","mis":"M6-2-u5-X07"},{"t":"113.04 cm","mis":"M6-2-u5-X12"},{"t":"75.36 cm","mis":"M6-2-u5-X01"}],"explanation":["반지름에 바로 원주율을 곱하면 안 돼요.","반지름 6 cm에 2를 곱해 지름 12 cm를 먼저 만들어요.","12 × 3.14 = 37.68 — 원주는 37.68 cm예요."],"variant_rule":{"alt":[{"stem":"반지름이 9 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"56.52 cm","correct":true},{"t":"28.26 cm","mis":"M6-2-u5-X07"},{"t":"254.34 cm","mis":"M6-2-u5-X12"},{"t":"113.04 cm","mis":"M6-2-u5-X01"}],"explanation":["반지름에 바로 원주율을 곱하면 안 돼요.","반지름 9 cm에 2를 곱해 지름 18 cm를 먼저 만들어요.","18 × 3.14 = 56.52 — 원주는 56.52 cm예요."]},{"stem":"반지름이 5.5 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"34.54 cm","correct":true},{"t":"17.27 cm","mis":"M6-2-u5-X07"},{"t":"94.985 cm","mis":"M6-2-u5-X12"},{"t":"69.08 cm","mis":"M6-2-u5-X01"}],"explanation":["반지름에 바로 원주율을 곱하면 안 돼요.","반지름 5.5 cm에 2를 곱해 지름 11 cm를 먼저 만들어요.","11 × 3.14 = 34.54 — 원주는 34.54 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L04_basic#4','math',6,2,'u5','L04','tb_g6_2_math_u5_L04_basic','lesson_basic','M6-2-u5-C4',1,'sa','auto','단풍 축제가 열리는 공원에 원 모양 호수가 있어요. 호수의 둘레는 157 m이고, 호수의 중심을 지나는 다리가 있어요. 다리의 길이는 몇 m인가요?','{}'::text[],true,'{"seq":4,"concept":"M6-2-u5-C4","difficulty":1,"kind":"sa","stem":"단풍 축제가 열리는 공원에 원 모양 호수가 있어요. 호수의 둘레는 157 m이고, 호수의 중심을 지나는 다리가 있어요. 다리의 길이는 몇 m인가요?","answer":["50"],"explanation":["(지름) = (원주) ÷ (원주율)이에요.","157 ÷ 3.14를 계산해요.","157 ÷ 3.14 = 50이에요."],"variant_rule":{"alt":[{"stem":"원 모양 접시의 원주를 재었더니 31.4 cm였어요. 이 접시의 지름은 몇 cm인가요?","answer":["10"],"explanation":["(지름) = (원주) ÷ (원주율)이에요.","31.4 ÷ 3.14를 계산해요.","31.4 ÷ 3.14 = 10이에요."]},{"stem":"원 모양 탬버린의 원주를 재었더니 62.8 cm였어요. 이 탬버린의 지름은 몇 cm인가요?","answer":["20"],"explanation":["(지름) = (원주) ÷ (원주율)이에요.","62.8 ÷ 3.14를 계산해요.","62.8 ÷ 3.14 = 20이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L04_basic#5','math',6,2,'u5','L04','tb_g6_2_math_u5_L04_basic','lesson_basic','M6-2-u5-C3',2,'mc','auto','원주를 알 때 지름을 구하는 식으로 알맞은 것은 어느 것인가요?',ARRAY['M6-2-u5-X08']::text[],true,'{"seq":5,"concept":"M6-2-u5-C3","difficulty":2,"kind":"mc","stem":"원주를 알 때 지름을 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"(원주) ÷ (원주율)","correct":true},{"t":"(원주) × (원주율)","mis":"M6-2-u5-X08"},{"t":"(원주) − (원주율)","mis":"M6-2-u5-X08"},{"t":"(원주율) ÷ (원주)","mis":"M6-2-u5-X08"}],"explanation":["(원주) = (지름) × (원주율)이에요.","곱셈으로 간 길을 나눗셈으로 되짚어요.","그래서 (지름) = (원주) ÷ (원주율)이에요."],"variant_rule":{"alt":[{"stem":"반지름을 알 때 원주를 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"(반지름) × 2 × (원주율)","correct":true},{"t":"(반지름) × (원주율)","mis":"M6-2-u5-X07"},{"t":"(반지름) × (반지름) × (원주율)","mis":"M6-2-u5-X12"},{"t":"(반지름) ÷ (원주율)","mis":"M6-2-u5-X08"}],"explanation":["원주는 지름에 원주율을 곱해요.","반지름만 알면 2를 먼저 곱해 지름을 만들어요.","그래서 (반지름) × 2 × (원주율)이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L04_basic#6','math',6,2,'u5','L04','tb_g6_2_math_u5_L04_basic','lesson_basic','M6-2-u5-C3',2,'mc','auto','지름이 20 cm인 원판을 10바퀴 굴렸어요. 원판이 굴러간 거리는 몇 cm인가요?',ARRAY['M6-2-u5-X19','M6-2-u5-X07','M6-2-u5-X02']::text[],true,'{"seq":6,"concept":"M6-2-u5-C3","difficulty":2,"kind":"mc","stem":"지름이 20 cm인 원판을 10바퀴 굴렸어요. 원판이 굴러간 거리는 몇 cm인가요?","options":[{"t":"628 cm","correct":true},{"t":"62.8 cm","mis":"M6-2-u5-X19"},{"t":"314 cm","mis":"M6-2-u5-X07"},{"t":"200 cm","mis":"M6-2-u5-X02"}],"explanation":["한 바퀴 굴러간 거리는 원주와 같아요.","원주는 20 × 3.14 = 62.8 cm예요.","10바퀴면 62.8 × 10 = 628 cm예요."],"variant_rule":{"alt":[{"stem":"지름이 40 cm인 굴렁쇠를 3바퀴 굴렸어요. 굴렁쇠가 굴러간 거리는 몇 cm인가요?","options":[{"t":"376.8 cm","correct":true},{"t":"125.6 cm","mis":"M6-2-u5-X19"},{"t":"188.4 cm","mis":"M6-2-u5-X07"},{"t":"120 cm","mis":"M6-2-u5-X02"}],"explanation":["한 바퀴 굴러간 거리는 원주와 같아요.","원주는 40 × 3.14 = 125.6 cm예요.","3바퀴면 125.6 × 3 = 376.8 cm예요."]},{"stem":"지름이 48 cm인 굴렁쇠를 5바퀴 굴렸어요. 굴렁쇠가 굴러간 거리는 몇 cm인가요?","options":[{"t":"753.6 cm","correct":true},{"t":"150.72 cm","mis":"M6-2-u5-X19"},{"t":"376.8 cm","mis":"M6-2-u5-X07"},{"t":"240 cm","mis":"M6-2-u5-X02"}],"explanation":["한 바퀴 굴러간 거리는 원주와 같아요.","원주는 48 × 3.14 = 150.72 cm예요.","5바퀴면 150.72 × 5 = 753.6 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L04_basic#7','math',6,2,'u5','L04','tb_g6_2_math_u5_L04_basic','lesson_basic','M6-2-u5-C4',2,'sa','auto','체육 시간에 협동 놀이를 하려고 줄을 이용하여 원주가 25.12 m인 원을 그리려고 해요. 원의 중심에 줄 한쪽 끝을 고정할 때 필요한 줄의 길이는 몇 m인가요? (기둥에 묶인 매듭의 길이는 생각하지 않아요.)','{}'::text[],true,'{"seq":7,"concept":"M6-2-u5-C4","difficulty":2,"kind":"sa","stem":"체육 시간에 협동 놀이를 하려고 줄을 이용하여 원주가 25.12 m인 원을 그리려고 해요. 원의 중심에 줄 한쪽 끝을 고정할 때 필요한 줄의 길이는 몇 m인가요? (기둥에 묶인 매듭의 길이는 생각하지 않아요.)","answer":["4"],"explanation":["먼저 지름을 구해요: 25.12 ÷ 3.14 = 8이에요.","반지름은 지름의 반이에요.","8 ÷ 2 = 4 — 반지름은 4예요."],"mis":"M6-2-u5-X09","variant_rule":{"alt":[{"stem":"원주가 43.96 cm인 원의 반지름은 몇 cm인가요?","answer":["7"],"explanation":["먼저 지름을 구해요: 43.96 ÷ 3.14 = 14예요.","반지름은 지름의 반이에요.","14 ÷ 2 = 7 — 반지름은 7이에요."]},{"stem":"원주가 37.68 cm인 원의 반지름은 몇 cm인가요?","answer":["6"],"explanation":["먼저 지름을 구해요: 37.68 ÷ 3.14 = 12예요.","반지름은 지름의 반이에요.","12 ÷ 2 = 6 — 반지름은 6이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L04_basic#8','math',6,2,'u5','L04','tb_g6_2_math_u5_L04_basic','lesson_basic','M6-2-u5-C4',2,'sa','auto','원주가 15.7 cm인 원의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":8,"concept":"M6-2-u5-C4","difficulty":2,"kind":"sa","stem":"원주가 15.7 cm인 원의 지름은 몇 cm인가요?","answer":["5"],"explanation":["(지름) = (원주) ÷ (원주율)이에요.","15.7 ÷ 3.14를 계산해요.","15.7 ÷ 3.14 = 5예요."],"variant_rule":{"alt":[{"stem":"원주가 28.26 cm인 원의 지름은 몇 cm인가요?","answer":["9"],"explanation":["(지름) = (원주) ÷ (원주율)이에요.","28.26 ÷ 3.14를 계산해요.","28.26 ÷ 3.14 = 9예요."]},{"stem":"원 모양 컵 받침의 둘레가 25.12 cm예요. 컵 받침의 지름은 몇 cm인가요?","answer":["8"],"explanation":["(지름) = (원주) ÷ (원주율)이에요.","25.12 ÷ 3.14를 계산해요.","25.12 ÷ 3.14 = 8이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L04_basic#9','math',6,2,'u5','L04','tb_g6_2_math_u5_L04_basic','lesson_basic','M6-2-u5-C4',2,'mc','auto','지름이 15 cm인 원과 원주가 43.96 cm인 원이 있어요. 크기가 더 큰 원은 어느 것인가요?',ARRAY['M6-2-u5-X08','M6-2-u5-X20','M6-2-u5-X19']::text[],true,'{"seq":9,"concept":"M6-2-u5-C4","difficulty":2,"kind":"mc","stem":"지름이 15 cm인 원과 원주가 43.96 cm인 원이 있어요. 크기가 더 큰 원은 어느 것인가요?","options":[{"t":"지름이 15 cm인 원","correct":true},{"t":"원주가 43.96 cm인 원","mis":"M6-2-u5-X08"},{"t":"두 원의 크기가 같아요","mis":"M6-2-u5-X20"},{"t":"견줄 수 없어요","mis":"M6-2-u5-X19"}],"explanation":["같은 것끼리 견주려고 원주를 지름으로 바꾸어요.","43.96 ÷ 3.14 = 14 — 원주가 43.96 cm인 원의 지름은 14 cm예요.","지름 15 cm와 14 cm를 견주면 지름이 15 cm인 원이 더 커요."],"variant_rule":{"alt":[{"stem":"지름이 22 cm인 원과 원주가 81.64 cm인 원이 있어요. 크기가 더 큰 원은 어느 것인가요?","options":[{"t":"원주가 81.64 cm인 원","correct":true},{"t":"지름이 22 cm인 원","mis":"M6-2-u5-X08"},{"t":"두 원의 크기가 같아요","mis":"M6-2-u5-X20"},{"t":"견줄 수 없어요","mis":"M6-2-u5-X19"}],"explanation":["같은 것끼리 견주려고 원주를 지름으로 바꾸어요.","81.64 ÷ 3.14 = 26 — 원주가 81.64 cm인 원의 지름은 26 cm예요.","지름 22 cm와 26 cm를 견주면 원주가 81.64 cm인 원이 더 커요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L04_basic#10','math',6,2,'u5','L04','tb_g6_2_math_u5_L04_basic','lesson_basic','M6-2-u5-C4',3,'mc','auto','지름이 12 cm인 원과 반지름이 8 cm인 원이 있어요. 두 원의 원주의 차는 몇 cm인가요?',ARRAY['M6-2-u5-X02','M6-2-u5-X19','M6-2-u5-X09']::text[],true,'{"seq":10,"concept":"M6-2-u5-C4","difficulty":3,"kind":"mc","stem":"지름이 12 cm인 원과 반지름이 8 cm인 원이 있어요. 두 원의 원주의 차는 몇 cm인가요?","options":[{"t":"12.56 cm","correct":true},{"t":"4 cm","mis":"M6-2-u5-X02"},{"t":"87.92 cm","mis":"M6-2-u5-X19"},{"t":"50.24 cm","mis":"M6-2-u5-X09"}],"explanation":["지름 12 cm인 원의 원주는 12 × 3.14 = 37.68 cm예요.","반지름 8 cm인 원의 지름은 16 cm — 원주는 16 × 3.14 = 50.24 cm예요.","50.24 − 37.68 = 12.56 cm예요."],"variant_rule":{"alt":[{"stem":"반지름이 15 cm인 원판을 몇 바퀴 굴렸더니 471 cm만큼 굴러갔어요. 원판이 굴러간 바퀴 수는 몇 바퀴인가요?","options":[{"t":"5바퀴","correct":true},{"t":"10바퀴","mis":"M6-2-u5-X07"},{"t":"2.5바퀴","mis":"M6-2-u5-X01"},{"t":"15바퀴","mis":"M6-2-u5-X20"}],"explanation":["한 바퀴 굴러간 거리는 원판의 원주예요.","지름 30 cm — 원주는 30 × 3.14 = 94.2 cm예요.","471 ÷ 94.2 = 5 — 5바퀴예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L04_challenge#1','math',6,2,'u5','L04','tb_g6_2_math_u5_L04_challenge','lesson_challenge','M6-2-u5-C3',2,'error','auto','반지름이 6 cm인 원의 원주를 구했어요. 잘못 구한 것은 어느 것인가요?',ARRAY['M6-2-u5-X07','M6-2-u5-X19']::text[],true,'{"seq":1,"concept":"M6-2-u5-C3","difficulty":2,"kind":"error","stem":"반지름이 6 cm인 원의 원주를 구했어요. 잘못 구한 것은 어느 것인가요?","options":[{"t":"㉠ 「6 × 3.14 = 18.84, 원주는 18.84 cm야.」","correct":true,"mis_target":"M6-2-u5-X07"},{"t":"㉡ 「지름이 12 cm니 12 × 3.14 = 37.68이야.」","mis":"M6-2-u5-X19"},{"t":"㉢ 「6 × 2 × 3.14 = 37.68이야.」","mis":"M6-2-u5-X19"},{"t":"㉣ 「원주는 37.68 cm야.」","mis":"M6-2-u5-X19"}],"explanation":["원주는 (지름) × (원주율)이에요.","반지름 6 cm에 2를 먼저 곱해 지름 12 cm를 만들어야 해요.","㉠의 말은 반지름에 바로 3.14를 곱한 거예요 — 원주는 37.68 cm예요."],"variant_rule":{"alt":[{"stem":"반지름이 9 cm인 원의 원주를 구했어요. 잘못 구한 것은 어느 것인가요?","options":[{"t":"㉠ 「9 × 3.14 = 28.26, 원주는 28.26 cm야.」","correct":true,"mis_target":"M6-2-u5-X07"},{"t":"㉡ 「지름이 18 cm니 18 × 3.14 = 56.52야.」","mis":"M6-2-u5-X19"},{"t":"㉢ 「9 × 2 × 3.14 = 56.52야.」","mis":"M6-2-u5-X19"},{"t":"㉣ 「원주는 56.52 cm야.」","mis":"M6-2-u5-X19"}],"explanation":["원주는 (지름) × (원주율)이에요.","반지름 9 cm에 2를 먼저 곱해 지름 18 cm를 만들어야 해요.","㉠의 말은 반지름에 바로 3.14를 곱한 거예요 — 원주는 56.52 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L04_challenge#2','math',6,2,'u5','L04','tb_g6_2_math_u5_L04_challenge','lesson_challenge','M6-2-u5-C3',2,'ox','auto','반지름이 같은 두 원은 원주도 같아요.',ARRAY['M6-2-u5-X05']::text[],true,'{"seq":2,"concept":"M6-2-u5-C3","difficulty":2,"kind":"ox","stem":"반지름이 같은 두 원은 원주도 같아요.","answer":"O","reason_options":[{"t":"반지름이 같으면 지름이 같아 지름 × 3.14도 같기 때문에","correct":true},{"t":"반지름이 같아도 원주는 원마다 다르기 때문에","mis":"M6-2-u5-X05"}],"mis":"M6-2-u5-X05","explanation":["(원주) = (지름) × (원주율)이에요.","반지름만 알면 2를 먼저 곱해요.","지름이 같으면 원주도 같고, 지름이 2배면 원주도 2배예요."],"variant_rule":{"alt":[{"stem":"지름이 2배인 원은 원주도 2배예요.","answer":"O","reason_options":[{"t":"원주는 지름에 3.14를 곱한 값이기 때문에","correct":true},{"t":"원주는 지름에 3.14를 더한 값이기 때문에","mis":"M6-2-u5-X08"}],"explanation":["(원주) = (지름) × (원주율)이에요.","반지름만 알면 2를 먼저 곱해요.","지름이 같으면 원주도 같고, 지름이 2배면 원주도 2배예요."]},{"stem":"반지름이 5 cm인 원의 원주는 5 × 3.14 = 15.7 cm예요.","answer":"X","reason_options":[{"t":"반지름에 2를 먼저 곱해 지름 10 cm로 계산해야 하기 때문에","correct":true},{"t":"원주는 반지름에 원주율을 곱한 값이기 때문에","mis":"M6-2-u5-X07"}],"explanation":["(원주) = (지름) × (원주율)이에요.","반지름만 알면 2를 먼저 곱해요.","지름이 같으면 원주도 같고, 지름이 2배면 원주도 2배예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L04_challenge#3','math',6,2,'u5','L04','tb_g6_2_math_u5_L04_challenge','lesson_challenge','M6-2-u5-C3',3,'match','auto','알맞은 것끼리 이으세요.','{}'::text[],true,'{"seq":3,"concept":"M6-2-u5-C3","difficulty":3,"kind":"match","stem":"알맞은 것끼리 이으세요.","pairs":[{"l":"반지름 2 cm","r":"원주 12.56 cm"},{"l":"지름 5 cm","r":"원주 15.7 cm"},{"l":"반지름 4 cm","r":"원주 25.12 cm"}],"mis":"M6-2-u5-X07","explanation":["(원주) = (지름) × 3.14예요.","반지름이면 2를 먼저 곱해 지름을 만들어요.","원주를 알면 3.14로 나누어 지름을 구해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 알맞은 것끼리 이으세요.","pairs":[{"l":"지름 3 cm","r":"원주 9.42 cm"},{"l":"반지름 3 cm","r":"원주 18.84 cm"},{"l":"지름 8 cm","r":"원주 25.12 cm"}],"explanation":["(원주) = (지름) × 3.14예요.","반지름이면 2를 먼저 곱해 지름을 만들어요.","원주를 알면 3.14로 나누어 지름을 구해요."]},{"stem":"이번에는 다른 보기예요. 알맞은 것끼리 이으세요.","pairs":[{"l":"원주 31.4 cm","r":"지름 10 cm"},{"l":"원주 62.8 cm","r":"지름 20 cm"},{"l":"원주 15.7 cm","r":"지름 5 cm"}],"explanation":["(원주) = (지름) × 3.14예요.","반지름이면 2를 먼저 곱해 지름을 만들어요.","원주를 알면 3.14로 나누어 지름을 구해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L04_challenge#4','math',6,2,'u5','L04','tb_g6_2_math_u5_L04_challenge','lesson_challenge','M6-2-u5-C3',3,'mc','auto','바깥쪽 원의 지름이 40 cm인 굴렁쇠를 3바퀴 굴렸어요. 이 굴렁쇠가 굴러간 거리는 몇 m인가요?',ARRAY['M6-2-u5-X20','M6-2-u5-X19','M6-2-u5-X07']::text[],true,'{"seq":4,"concept":"M6-2-u5-C3","difficulty":3,"kind":"mc","stem":"바깥쪽 원의 지름이 40 cm인 굴렁쇠를 3바퀴 굴렸어요. 이 굴렁쇠가 굴러간 거리는 몇 m인가요?","options":[{"t":"3.768 m","correct":true},{"t":"376.8 m","mis":"M6-2-u5-X20"},{"t":"1.256 m","mis":"M6-2-u5-X19"},{"t":"1.884 m","mis":"M6-2-u5-X07"}],"explanation":["한 바퀴 굴러간 거리는 40 × 3.14 = 125.6 cm예요.","3바퀴면 125.6 × 3 = 376.8 cm예요.","100 cm = 1 m니 3.768 m예요."],"variant_rule":{"alt":[{"stem":"바깥쪽 원의 지름이 48 cm인 굴렁쇠를 5바퀴 굴렸어요. 이 굴렁쇠가 굴러간 거리는 몇 m인가요?","options":[{"t":"7.536 m","correct":true},{"t":"753.6 m","mis":"M6-2-u5-X20"},{"t":"1.5072 m","mis":"M6-2-u5-X19"},{"t":"3.768 m","mis":"M6-2-u5-X07"}],"explanation":["한 바퀴 굴러간 거리는 48 × 3.14 = 150.72 cm예요.","5바퀴면 150.72 × 5 = 753.6 cm예요.","100 cm = 1 m니 7.536 m예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L04_challenge#5','math',6,2,'u5','L04','tb_g6_2_math_u5_L04_challenge','lesson_challenge','M6-2-u5-C4',3,'sa','auto','원주가 31.4 cm인 원 안에 꼭 맞는 정육각형이 있어요. 이 정육각형의 둘레는 몇 cm인가요?','{}'::text[],true,'{"seq":5,"concept":"M6-2-u5-C4","difficulty":3,"kind":"sa","stem":"원주가 31.4 cm인 원 안에 꼭 맞는 정육각형이 있어요. 이 정육각형의 둘레는 몇 cm인가요?","answer":["30"],"explanation":["지름은 31.4 ÷ 3.14 = 10 cm예요.","정육각형의 둘레는 지름의 3배예요.","10 × 3 = 30 cm예요."],"variant_rule":{"alt":[{"stem":"원주가 62.8 cm인 원 안에 꼭 맞는 정육각형이 있어요. 이 정육각형의 둘레는 몇 cm인가요?","answer":["60"],"explanation":["지름은 62.8 ÷ 3.14 = 20 cm예요.","정육각형의 둘레는 지름의 3배예요.","20 × 3 = 60 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L04_challenge#6','math',6,2,'u5','L04','tb_g6_2_math_u5_L04_challenge','lesson_challenge','M6-2-u5-C4',3,'sa','auto','길이가 18.84 cm인 종이띠를 겹치지 않게 붙여 원을 만들었어요. 만든 원의 반지름은 몇 cm인가요?','{}'::text[],true,'{"seq":6,"concept":"M6-2-u5-C4","difficulty":3,"kind":"sa","stem":"길이가 18.84 cm인 종이띠를 겹치지 않게 붙여 원을 만들었어요. 만든 원의 반지름은 몇 cm인가요?","answer":["3"],"explanation":["먼저 지름을 구해요: 18.84 ÷ 3.14 = 6이에요.","반지름은 지름의 반이에요.","6 ÷ 2 = 3 — 반지름은 3이에요."],"mis":"M6-2-u5-X09","variant_rule":{"alt":[{"stem":"원주가 43.96 cm인 원 모양 시계가 있어요. 이 시계의 반지름은 몇 cm인가요?","answer":["7"],"explanation":["먼저 지름을 구해요: 43.96 ÷ 3.14 = 14예요.","반지름은 지름의 반이에요.","14 ÷ 2 = 7 — 반지름은 7이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L04_challenge#7','math',6,2,'u5','L04','tb_g6_2_math_u5_L04_challenge','lesson_challenge','M6-2-u5-C4',3,'mc','auto','지름이 20 cm인 원판을 몇 바퀴 굴렸더니 628 cm만큼 굴러갔어요. 원판이 굴러간 바퀴 수는 몇 바퀴인가요?',ARRAY['M6-2-u5-X07','M6-2-u5-X01','M6-2-u5-X20']::text[],true,'{"seq":7,"concept":"M6-2-u5-C4","difficulty":3,"kind":"mc","stem":"지름이 20 cm인 원판을 몇 바퀴 굴렸더니 628 cm만큼 굴러갔어요. 원판이 굴러간 바퀴 수는 몇 바퀴인가요?","options":[{"t":"10바퀴","correct":true},{"t":"20바퀴","mis":"M6-2-u5-X07"},{"t":"5바퀴","mis":"M6-2-u5-X01"},{"t":"30바퀴","mis":"M6-2-u5-X20"}],"explanation":["한 바퀴 굴러간 거리는 원판의 원주예요.","지름 20 cm — 원주는 20 × 3.14 = 62.8 cm예요.","628 ÷ 62.8 = 10 — 10바퀴예요."],"variant_rule":{"alt":[{"stem":"지름이 40 cm인 원판을 몇 바퀴 굴렸더니 376.8 cm만큼 굴러갔어요. 원판이 굴러간 바퀴 수는 몇 바퀴인가요?","options":[{"t":"3바퀴","correct":true},{"t":"6바퀴","mis":"M6-2-u5-X07"},{"t":"1.5바퀴","mis":"M6-2-u5-X01"},{"t":"9바퀴","mis":"M6-2-u5-X20"}],"explanation":["한 바퀴 굴러간 거리는 원판의 원주예요.","지름 40 cm — 원주는 40 × 3.14 = 125.6 cm예요.","376.8 ÷ 125.6 = 3 — 3바퀴예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L04_challenge#8','math',6,2,'u5','L04','tb_g6_2_math_u5_L04_challenge','lesson_challenge','M6-2-u5-C3',4,'essay','teacher','자전거 바퀴의 지름이 80 cm예요. 자전거 바퀴가 한 바퀴 굴러간 거리를 원주를 직접 재지 않고 구하는 방법을 설명하고, 거리를 구해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M6-2-u5-C3","difficulty":4,"kind":"essay","stem":"자전거 바퀴의 지름이 80 cm예요. 자전거 바퀴가 한 바퀴 굴러간 거리를 원주를 직접 재지 않고 구하는 방법을 설명하고, 거리를 구해 보세요.","answer_guide":{"answer":"예: 한 바퀴 굴러간 거리는 바퀴의 원주와 같다. (원주율) = (원주) ÷ (지름)이므로 (원주) = (지름) × (원주율)이다. 80 × 3.14 = 251.2 cm이다.","scoring_points":["한 바퀴 굴러간 거리가 원주임을 밝혔는가","(원주) = (지름) × (원주율)을 썼는가","251.2 cm를 구했는가"]},"explanation":["한 바퀴 굴러간 거리 = 원주예요.","(원주) = (지름) × (원주율)이에요.","80 × 3.14 = 251.2 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L04_challenge#9','math',6,2,'u5','L04','tb_g6_2_math_u5_L04_challenge','lesson_challenge','M6-2-u5-C4',4,'essay','teacher','원주가 25.12 m인 원을 그리는 데 필요한 줄의 길이를 8 m라고 답한 친구가 있어요. 무엇이 잘못되었는지 쓰고 바르게 구해 보세요. (줄의 한쪽 끝을 원의 중심에 고정해요.)','{}'::text[],false,'{"seq":9,"concept":"M6-2-u5-C4","difficulty":4,"kind":"essay","stem":"원주가 25.12 m인 원을 그리는 데 필요한 줄의 길이를 8 m라고 답한 친구가 있어요. 무엇이 잘못되었는지 쓰고 바르게 구해 보세요. (줄의 한쪽 끝을 원의 중심에 고정해요.)","answer_guide":{"answer":"예: 25.12 ÷ 3.14 = 8 m는 원의 지름이다. 원의 중심에 줄 한쪽 끝을 고정하므로 줄의 길이는 반지름과 같다. 따라서 8 ÷ 2 = 4 m가 필요하다.","scoring_points":["8 m가 지름임을 밝혔는가","줄의 길이가 반지름과 같다고 썼는가","4 m를 구했는가"]},"explanation":["25.12 ÷ 3.14 = 8 — 8 m는 지름이에요.","줄은 중심에서 원 위까지 — 반지름이에요.","8 ÷ 2 = 4 m예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L04_challenge#10','math',6,2,'u5','L04','tb_g6_2_math_u5_L04_challenge','lesson_challenge','M6-2-u5-C4',4,'mc','auto','세 원의 크기를 견주려고 해요. ㉠ 지름이 15 cm · ㉡ 원주가 43.96 cm · ㉢ 반지름이 8 cm — 큰 원부터 차례로 놓은 것은 어느 것인가요?',ARRAY['M6-2-u5-X01','M6-2-u5-X20']::text[],true,'{"seq":10,"concept":"M6-2-u5-C4","difficulty":4,"kind":"mc","stem":"세 원의 크기를 견주려고 해요. ㉠ 지름이 15 cm · ㉡ 원주가 43.96 cm · ㉢ 반지름이 8 cm — 큰 원부터 차례로 놓은 것은 어느 것인가요?","options":[{"t":"㉢, ㉠, ㉡","correct":true},{"t":"㉡, ㉠, ㉢","mis":"M6-2-u5-X01"},{"t":"㉠, ㉡, ㉢","mis":"M6-2-u5-X20"},{"t":"㉡, ㉢, ㉠","mis":"M6-2-u5-X20"}],"explanation":["세 원의 지름을 구해 같은 것으로 견주어요.","㉠ 지름 15 cm · ㉡ 지름 14 cm · ㉢ 지름 16 cm예요.","지름이 긴 원부터 놓으면 ㉢, ㉠, ㉡이에요."],"variant_rule":{"alt":[{"stem":"세 원의 크기를 견주려고 해요. ㉠ 지름이 22 cm · ㉡ 원주가 81.64 cm · ㉢ 반지름이 12 cm — 큰 원부터 차례로 놓은 것은 어느 것인가요?","options":[{"t":"㉡, ㉢, ㉠","correct":true},{"t":"㉡, ㉠, ㉢","mis":"M6-2-u5-X01"},{"t":"㉠, ㉢, ㉡","mis":"M6-2-u5-X19"},{"t":"㉠, ㉡, ㉢","mis":"M6-2-u5-X20"}],"explanation":["세 원의 지름을 구해 같은 것으로 견주어요.","㉠ 지름 22 cm · ㉡ 지름 26 cm · ㉢ 지름 24 cm예요.","지름이 긴 원부터 놓으면 ㉡, ㉢, ㉠이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L05_basic#1','math',6,2,'u5','L05','tb_g6_2_math_u5_L05_basic','lesson_basic','M6-2-u5-C5',1,'mc','auto','한 칸이 1 cm²인 모눈 위의 원에서 온전히 들어간 칸은 60칸, 걸친 칸까지 세면 88칸이에요. 원의 넓이가 들어갈 범위로 알맞은 것은 어느 것인가요?',ARRAY['M6-2-u5-X10']::text[],true,'{"seq":1,"concept":"M6-2-u5-C5","difficulty":1,"kind":"mc","stem":"한 칸이 1 cm²인 모눈 위의 원에서 온전히 들어간 칸은 60칸, 걸친 칸까지 세면 88칸이에요. 원의 넓이가 들어갈 범위로 알맞은 것은 어느 것인가요?","options":[{"t":"60 cm²보다 넓고 88 cm²보다 좁아요","correct":true},{"t":"60 cm²보다 좁아요","mis":"M6-2-u5-X10"},{"t":"88 cm²보다 넓어요","mis":"M6-2-u5-X10"},{"t":"60 cm²와 정확히 같아요","mis":"M6-2-u5-X10"}],"explanation":["온전히 들어간 칸만큼은 반드시 원 안에 있어요.","걸친 칸까지 세면 원을 다 덮어요.","그래서 넓이는 60 cm²보다 넓고 88 cm²보다 좁아요."],"variant_rule":{"alt":[{"stem":"한 칸이 1 cm²인 모눈 위의 원에서 온전히 들어간 칸은 45칸, 걸친 칸까지 세면 77칸이에요. 원의 넓이가 들어갈 범위로 알맞은 것은 어느 것인가요?","options":[{"t":"45 cm²보다 넓고 77 cm²보다 좁아요","correct":true},{"t":"45 cm²보다 좁아요","mis":"M6-2-u5-X10"},{"t":"77 cm²보다 넓어요","mis":"M6-2-u5-X10"},{"t":"45 cm²와 정확히 같아요","mis":"M6-2-u5-X10"}],"explanation":["온전히 들어간 칸만큼은 반드시 원 안에 있어요.","걸친 칸까지 세면 원을 다 덮어요.","그래서 넓이는 45 cm²보다 넓고 77 cm²보다 좁아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L05_basic#2','math',6,2,'u5','L05','tb_g6_2_math_u5_L05_basic','lesson_basic','M6-2-u5-C5',1,'mc','auto','원 안에 꼭 맞는 정사각형은 반지름을 한 변으로 하는 정사각형 몇 개와 넓이가 같나요?',ARRAY['M6-2-u5-X11','M6-2-u5-X10']::text[],true,'{"seq":2,"concept":"M6-2-u5-C5","difficulty":1,"kind":"mc","stem":"원 안에 꼭 맞는 정사각형은 반지름을 한 변으로 하는 정사각형 몇 개와 넓이가 같나요?","options":[{"t":"2개","correct":true},{"t":"4개","mis":"M6-2-u5-X11"},{"t":"1개","mis":"M6-2-u5-X11"},{"t":"3개","mis":"M6-2-u5-X10"}],"explanation":["원 안 정사각형을 두 대각선으로 자르면 직각삼각형 4개예요.","반지름을 한 변으로 하는 정사각형 하나는 그 삼각형 2개예요.","그래서 정사각형 2개와 넓이가 같아요."],"variant_rule":{"alt":[{"stem":"원 밖에 꼭 맞는 정사각형은 반지름을 한 변으로 하는 정사각형 몇 개와 넓이가 같나요?","options":[{"t":"4개","correct":true},{"t":"2개","mis":"M6-2-u5-X11"},{"t":"3개","mis":"M6-2-u5-X10"},{"t":"8개","mis":"M6-2-u5-X11"}],"explanation":["원 밖 정사각형의 한 변은 지름 — 반지름의 2배예요.","가로로 2개, 세로로 2개 들어가요.","그래서 정사각형 4개와 넓이가 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L05_basic#3','math',6,2,'u5','L05','tb_g6_2_math_u5_L05_basic','lesson_basic','M6-2-u5-C5',1,'mc','auto','반지름을 한 변으로 하는 정사각형의 넓이는 어떻게 구하나요?',ARRAY['M6-2-u5-X02','M6-2-u5-X13','M6-2-u5-X14']::text[],true,'{"seq":3,"concept":"M6-2-u5-C5","difficulty":1,"kind":"mc","stem":"반지름을 한 변으로 하는 정사각형의 넓이는 어떻게 구하나요?","options":[{"t":"(반지름) × (반지름)","correct":true},{"t":"(반지름) × 4","mis":"M6-2-u5-X02"},{"t":"(지름) × (지름)","mis":"M6-2-u5-X13"},{"t":"(반지름) × 2","mis":"M6-2-u5-X14"}],"explanation":["정사각형의 넓이는 (한 변) × (한 변)이에요.","한 변이 반지름이에요.","그래서 (반지름) × (반지름)이에요."],"variant_rule":{"alt":[{"stem":"반지름이 5 cm인 원이 있어요. 반지름을 한 변으로 하는 정사각형의 넓이는 몇 cm²인가요?","options":[{"t":"25 cm²","correct":true},{"t":"10 cm²","mis":"M6-2-u5-X14"},{"t":"100 cm²","mis":"M6-2-u5-X13"},{"t":"20 cm²","mis":"M6-2-u5-X02"}],"explanation":["한 변이 5 cm인 정사각형이에요.","5 × 5를 계산해요.","5 × 5 = 25 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L05_basic#4','math',6,2,'u5','L05','tb_g6_2_math_u5_L05_basic','lesson_basic','M6-2-u5-C5',1,'mc','auto','반지름이 10 cm인 원의 넓이를 가장 가깝게 어림한 것은 어느 것인가요?',ARRAY['M6-2-u5-X14','M6-2-u5-X10','M6-2-u5-X11']::text[],true,'{"seq":4,"concept":"M6-2-u5-C5","difficulty":1,"kind":"mc","stem":"반지름이 10 cm인 원의 넓이를 가장 가깝게 어림한 것은 어느 것인가요?","options":[{"t":"300 cm²","correct":true},{"t":"30 cm²","mis":"M6-2-u5-X14"},{"t":"900 cm²","mis":"M6-2-u5-X10"},{"t":"100 cm²","mis":"M6-2-u5-X11"}],"explanation":["원의 넓이는 (반지름) × (반지름)의 2배보다 넓고 4배보다 좁아요.","10 × 10 = 100이니 넓이는 200 cm²보다 넓고 400 cm²보다 좁아요.","보기 가운데 그 사이에 있는 것은 300 cm²예요."],"variant_rule":{"alt":[{"stem":"반지름이 5 cm인 원의 넓이를 가장 가깝게 어림한 것은 어느 것인가요?","options":[{"t":"80 cm²","correct":true},{"t":"25 cm²","mis":"M6-2-u5-X11"},{"t":"140 cm²","mis":"M6-2-u5-X10"},{"t":"50 cm²","mis":"M6-2-u5-X10"}],"explanation":["원의 넓이는 (반지름) × (반지름)의 2배보다 넓고 4배보다 좁아요.","5 × 5 = 25니 넓이는 50 cm²보다 넓고 100 cm²보다 좁아요.","보기 가운데 그 사이에 있는 것은 80 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L05_basic#5','math',6,2,'u5','L05','tb_g6_2_math_u5_L05_basic','lesson_basic','M6-2-u5-C5',2,'sa','auto','반지름이 10 cm인 원 안에 꼭 맞는 정사각형이 있어요. 이 정사각형은 두 대각선이 모두 20 cm예요. 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":5,"concept":"M6-2-u5-C5","difficulty":2,"kind":"sa","stem":"반지름이 10 cm인 원 안에 꼭 맞는 정사각형이 있어요. 이 정사각형은 두 대각선이 모두 20 cm예요. 넓이는 몇 cm²인가요?","answer":["200"],"explanation":["마름모·정사각형의 넓이는 (한 대각선) × (다른 대각선) ÷ 2예요.","20 × 20 ÷ 2 = 200이에요.","반지름을 한 변으로 하는 정사각형 2개와 넓이가 같아요."],"variant_rule":{"alt":[{"stem":"반지름이 7 cm인 원 안에 꼭 맞는 정사각형이 있어요. 이 정사각형은 두 대각선이 모두 14 cm예요. 넓이는 몇 cm²인가요?","answer":["98"],"explanation":["마름모·정사각형의 넓이는 (한 대각선) × (다른 대각선) ÷ 2예요.","14 × 14 ÷ 2 = 98이에요.","반지름을 한 변으로 하는 정사각형 2개와 넓이가 같아요."]},{"stem":"반지름이 6 cm인 원 안에 꼭 맞는 정사각형이 있어요. 이 정사각형은 두 대각선이 모두 12 cm예요. 넓이는 몇 cm²인가요?","answer":["72"],"explanation":["마름모·정사각형의 넓이는 (한 대각선) × (다른 대각선) ÷ 2예요.","12 × 12 ÷ 2 = 72예요.","반지름을 한 변으로 하는 정사각형 2개와 넓이가 같아요."]}]},"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"O":[60,60],"A":[10,10],"B":[110,10],"C":[110,110],"D":[10,110],"T":[60,10],"Rt":[110,60],"Bt":[60,110],"Lf":[10,60]},"show":[],"poly":[["A","B","C","D"],["T","Rt","Bt","Lf"]],"circle":[["O",50]],"dash":[["O","T"],["O","Rt"]],"right":[["T","O","Rt"]]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L05_basic#6','math',6,2,'u5','L05','tb_g6_2_math_u5_L05_basic','lesson_basic','M6-2-u5-C5',2,'sa','auto','반지름이 10 cm인 원 밖에 꼭 맞는 정사각형이 있어요. 이 정사각형의 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":6,"concept":"M6-2-u5-C5","difficulty":2,"kind":"sa","stem":"반지름이 10 cm인 원 밖에 꼭 맞는 정사각형이 있어요. 이 정사각형의 넓이는 몇 cm²인가요?","answer":["400"],"explanation":["원 밖 정사각형의 한 변은 지름 20 cm예요.","20 × 20 = 400이에요.","반지름을 한 변으로 하는 정사각형 4개와 넓이가 같아요."],"variant_rule":{"alt":[{"stem":"반지름이 7 cm인 원 밖에 꼭 맞는 정사각형이 있어요. 이 정사각형의 넓이는 몇 cm²인가요?","answer":["196"],"explanation":["원 밖 정사각형의 한 변은 지름 14 cm예요.","14 × 14 = 196이에요.","반지름을 한 변으로 하는 정사각형 4개와 넓이가 같아요."]},{"stem":"반지름이 6 cm인 원 밖에 꼭 맞는 정사각형이 있어요. 이 정사각형의 넓이는 몇 cm²인가요?","answer":["144"],"explanation":["원 밖 정사각형의 한 변은 지름 12 cm예요.","12 × 12 = 144예요.","반지름을 한 변으로 하는 정사각형 4개와 넓이가 같아요."]}]},"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"O":[60,60],"A":[10,10],"B":[110,10],"C":[110,110],"D":[10,110],"T":[60,10],"Rt":[110,60],"Bt":[60,110],"Lf":[10,60]},"show":[],"poly":[["A","B","C","D"],["T","Rt","Bt","Lf"]],"circle":[["O",50]],"dash":[["O","T"],["O","Rt"]],"right":[["T","O","Rt"]]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L05_basic#7','math',6,2,'u5','L05','tb_g6_2_math_u5_L05_basic','lesson_basic','M6-2-u5-C5',2,'mc','auto','지름이 20 cm인 원의 넓이를 원 안과 밖에 꼭 맞는 정사각형으로 어림했어요. 알맞은 범위는 어느 것인가요?',ARRAY['M6-2-u5-X11','M6-2-u5-X01','M6-2-u5-X12']::text[],true,'{"seq":7,"concept":"M6-2-u5-C5","difficulty":2,"kind":"mc","stem":"지름이 20 cm인 원의 넓이를 원 안과 밖에 꼭 맞는 정사각형으로 어림했어요. 알맞은 범위는 어느 것인가요?","options":[{"t":"200 cm²보다 넓고 400 cm²보다 좁아요","correct":true},{"t":"100 cm²보다 넓고 200 cm²보다 좁아요","mis":"M6-2-u5-X11"},{"t":"400 cm²보다 넓고 800 cm²보다 좁아요","mis":"M6-2-u5-X01"},{"t":"20 cm²보다 넓고 40 cm²보다 좁아요","mis":"M6-2-u5-X12"}],"explanation":["반지름은 10 cm예요.","원 안 정사각형은 10 × 10 × 2 = 200 cm², 원 밖 정사각형은 10 × 10 × 4 = 400 cm²예요.","원의 넓이는 그 사이 — 200 cm²보다 넓고 400 cm²보다 좁아요."],"variant_rule":{"alt":[{"stem":"지름이 14 cm인 원의 넓이를 원 안과 밖에 꼭 맞는 정사각형으로 어림했어요. 알맞은 범위는 어느 것인가요?","options":[{"t":"98 cm²보다 넓고 196 cm²보다 좁아요","correct":true},{"t":"49 cm²보다 넓고 98 cm²보다 좁아요","mis":"M6-2-u5-X11"},{"t":"196 cm²보다 넓고 392 cm²보다 좁아요","mis":"M6-2-u5-X01"},{"t":"14 cm²보다 넓고 28 cm²보다 좁아요","mis":"M6-2-u5-X12"}],"explanation":["반지름은 7 cm예요.","원 안 정사각형은 7 × 7 × 2 = 98 cm², 원 밖 정사각형은 7 × 7 × 4 = 196 cm²예요.","원의 넓이는 그 사이 — 98 cm²보다 넓고 196 cm²보다 좁아요."]},{"stem":"지름이 12 cm인 원의 넓이를 원 안과 밖에 꼭 맞는 정사각형으로 어림했어요. 알맞은 범위는 어느 것인가요?","options":[{"t":"72 cm²보다 넓고 144 cm²보다 좁아요","correct":true},{"t":"36 cm²보다 넓고 72 cm²보다 좁아요","mis":"M6-2-u5-X11"},{"t":"144 cm²보다 넓고 288 cm²보다 좁아요","mis":"M6-2-u5-X01"},{"t":"12 cm²보다 넓고 24 cm²보다 좁아요","mis":"M6-2-u5-X12"}],"explanation":["반지름은 6 cm예요.","원 안 정사각형은 6 × 6 × 2 = 72 cm², 원 밖 정사각형은 6 × 6 × 4 = 144 cm²예요.","원의 넓이는 그 사이 — 72 cm²보다 넓고 144 cm²보다 좁아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L05_basic#8','math',6,2,'u5','L05','tb_g6_2_math_u5_L05_basic','lesson_basic','M6-2-u5-C5',2,'ox','auto','원의 넓이는 (반지름) × (반지름)의 2배보다 넓고 4배보다 좁아요.',ARRAY['M6-2-u5-X11']::text[],true,'{"seq":8,"concept":"M6-2-u5-C5","difficulty":2,"kind":"ox","stem":"원의 넓이는 (반지름) × (반지름)의 2배보다 넓고 4배보다 좁아요.","answer":"O","reason_options":[{"t":"원 안 정사각형은 2배, 원 밖 정사각형은 4배와 넓이가 같기 때문에","correct":true},{"t":"원의 넓이는 반지름의 4배와 정확히 같기 때문에","mis":"M6-2-u5-X11"}],"mis":"M6-2-u5-X11","explanation":["원 안 정사각형은 반지름 정사각형 2개, 원 밖 정사각형은 4개와 넓이가 같아요.","원의 넓이는 그 사이에 있어요.","어림은 정확한 값이 아니라 범위를 찾는 일이에요."],"variant_rule":{"alt":[{"stem":"원 밖에 꼭 맞는 정사각형의 넓이는 (반지름) × (반지름)의 2배예요.","answer":"X","reason_options":[{"t":"원 밖 정사각형의 한 변은 지름이라 반지름 정사각형 4개와 같기 때문에","correct":true},{"t":"원 밖 정사각형의 한 변이 반지름이기 때문에","mis":"M6-2-u5-X11"}],"explanation":["원 안 정사각형은 반지름 정사각형 2개, 원 밖 정사각형은 4개와 넓이가 같아요.","원의 넓이는 그 사이에 있어요.","어림은 정확한 값이 아니라 범위를 찾는 일이에요."]},{"stem":"모눈으로 어림한 넓이는 원의 정확한 넓이예요.","answer":"X","reason_options":[{"t":"어림은 넓이가 들어갈 범위를 찾는 것이기 때문에","correct":true},{"t":"칸을 빠짐없이 셌으니 정확하기 때문에","mis":"M6-2-u5-X10"}],"explanation":["원 안 정사각형은 반지름 정사각형 2개, 원 밖 정사각형은 4개와 넓이가 같아요.","원의 넓이는 그 사이에 있어요.","어림은 정확한 값이 아니라 범위를 찾는 일이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L05_basic#9','math',6,2,'u5','L05','tb_g6_2_math_u5_L05_basic','lesson_basic','M6-2-u5-C5',2,'sa','auto','한 칸이 1 cm²인 모눈 위에 반지름이 5 cm인 원을 그렸어요. 원을 똑같이 4로 나눈 한 부분에서 원 안에 완전히 들어간 칸은 15칸이에요. 원 전체에서 원 안에 완전히 들어간 칸은 모두 몇 칸인가요?','{}'::text[],true,'{"seq":9,"concept":"M6-2-u5-C5","difficulty":2,"kind":"sa","stem":"한 칸이 1 cm²인 모눈 위에 반지름이 5 cm인 원을 그렸어요. 원을 똑같이 4로 나눈 한 부분에서 원 안에 완전히 들어간 칸은 15칸이에요. 원 전체에서 원 안에 완전히 들어간 칸은 모두 몇 칸인가요?","answer":["60"],"explanation":["원은 똑같이 4로 나뉘어 네 부분의 모양이 같아요.","한 부분에 15칸이 있어요.","15 × 4 = 60칸 — 하나씩 세는 것보다 빨라요."],"variant_rule":{"alt":[{"stem":"한 칸이 1 cm²인 모눈 위에 반지름이 5 cm인 원을 그렸어요. 원을 똑같이 4로 나눈 한 부분에서 원에 걸친 칸까지 세면 22칸이에요. 원 전체에서 걸친 칸까지 세면 모두 몇 칸인가요?","answer":["88"],"explanation":["네 부분의 모양이 같아요.","한 부분에 22칸이 있어요.","22 × 4 = 88칸이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L05_basic#10','math',6,2,'u5','L05','tb_g6_2_math_u5_L05_basic','lesson_basic','M6-2-u5-C5',3,'mc','auto','반지름이 5 cm인 원의 넓이를 모눈으로 세었더니 60 cm²보다 넓고 88 cm²보다 좁았고, 정사각형으로 어림했더니 50 cm²보다 넓고 100 cm²보다 좁았어요. 범위를 더 좁게 어림한 방법은 어느 것인가요?',ARRAY['M6-2-u5-X10','M6-2-u5-X19']::text[],false,'{"seq":10,"concept":"M6-2-u5-C5","difficulty":3,"kind":"mc","stem":"반지름이 5 cm인 원의 넓이를 모눈으로 세었더니 60 cm²보다 넓고 88 cm²보다 좁았고, 정사각형으로 어림했더니 50 cm²보다 넓고 100 cm²보다 좁았어요. 범위를 더 좁게 어림한 방법은 어느 것인가요?","options":[{"t":"모눈 칸 세기","correct":true},{"t":"정사각형으로 어림하기","mis":"M6-2-u5-X10"},{"t":"두 방법의 범위가 같아요","mis":"M6-2-u5-X10"},{"t":"알 수 없어요","mis":"M6-2-u5-X19"}],"explanation":["모눈으로 얻은 범위의 폭은 88 − 60 = 28 cm²예요.","정사각형으로 얻은 범위의 폭은 100 − 50 = 50 cm²예요.","폭이 좁은 모눈 칸 세기가 더 좁게 어림한 방법이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L05_challenge#1','math',6,2,'u5','L05','tb_g6_2_math_u5_L05_challenge','lesson_challenge','M6-2-u5-C5',2,'error','auto','반지름이 5 cm인 원의 넓이를 어림하며 친구들이 말했어요. 잘못 말한 것은 어느 것인가요?',ARRAY['M6-2-u5-X11','M6-2-u5-X19']::text[],true,'{"seq":1,"concept":"M6-2-u5-C5","difficulty":2,"kind":"error","stem":"반지름이 5 cm인 원의 넓이를 어림하며 친구들이 말했어요. 잘못 말한 것은 어느 것인가요?","options":[{"t":"㉠ 「원의 넓이는 100 cm²보다 넓어.」","correct":true,"mis_target":"M6-2-u5-X11"},{"t":"㉡ 「원 안 정사각형의 넓이는 50 cm²야.」","mis":"M6-2-u5-X19"},{"t":"㉢ 「원 밖 정사각형의 넓이는 100 cm²야.」","mis":"M6-2-u5-X19"},{"t":"㉣ 「원의 넓이는 약 75 cm²쯤이야.」","mis":"M6-2-u5-X19"}],"explanation":["원 안 정사각형은 50 cm², 원 밖 정사각형은 100 cm²예요.","원은 원 밖 정사각형 안에 들어 있어요.","그래서 원이 100 cm²보다 넓다는 ㉠의 말이 잘못되었어요."],"variant_rule":{"alt":[{"stem":"반지름이 10 cm인 원의 넓이를 어림하며 친구들이 말했어요. 잘못 말한 것은 어느 것인가요?","options":[{"t":"㉠ 「원의 넓이는 400 cm²보다 넓어.」","correct":true,"mis_target":"M6-2-u5-X11"},{"t":"㉡ 「원 안 정사각형의 넓이는 200 cm²야.」","mis":"M6-2-u5-X19"},{"t":"㉢ 「원 밖 정사각형의 넓이는 400 cm²야.」","mis":"M6-2-u5-X19"},{"t":"㉣ 「원의 넓이는 약 300 cm²쯤이야.」","mis":"M6-2-u5-X19"}],"explanation":["원 안 정사각형은 200 cm², 원 밖 정사각형은 400 cm²예요.","원은 원 밖 정사각형 안에 들어 있어요.","그래서 원이 400 cm²보다 넓다는 ㉠의 말이 잘못되었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L05_challenge#2','math',6,2,'u5','L05','tb_g6_2_math_u5_L05_challenge','lesson_challenge','M6-2-u5-C5',2,'sa','auto','어떤 원 밖에 꼭 맞는 정사각형의 넓이가 400 cm²예요. 같은 원 안에 꼭 맞는 정사각형의 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":2,"concept":"M6-2-u5-C5","difficulty":2,"kind":"sa","stem":"어떤 원 밖에 꼭 맞는 정사각형의 넓이가 400 cm²예요. 같은 원 안에 꼭 맞는 정사각형의 넓이는 몇 cm²인가요?","answer":["200"],"explanation":["원 밖 정사각형은 반지름 정사각형 4개, 원 안 정사각형은 2개와 넓이가 같아요.","그래서 원 안 정사각형은 원 밖 정사각형의 반이에요.","400 ÷ 2 = 200 cm²예요."],"variant_rule":{"alt":[{"stem":"어떤 원 밖에 꼭 맞는 정사각형의 넓이가 196 cm²예요. 같은 원 안에 꼭 맞는 정사각형의 넓이는 몇 cm²인가요?","answer":["98"],"explanation":["원 밖 정사각형은 반지름 정사각형 4개, 원 안 정사각형은 2개와 넓이가 같아요.","그래서 원 안 정사각형은 원 밖 정사각형의 반이에요.","196 ÷ 2 = 98 cm²예요."]},{"stem":"어떤 원 밖에 꼭 맞는 정사각형의 넓이가 144 cm²예요. 같은 원 안에 꼭 맞는 정사각형의 넓이는 몇 cm²인가요?","answer":["72"],"explanation":["원 밖 정사각형은 반지름 정사각형 4개, 원 안 정사각형은 2개와 넓이가 같아요.","그래서 원 안 정사각형은 원 밖 정사각형의 반이에요.","144 ÷ 2 = 72 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L05_challenge#3','math',6,2,'u5','L05','tb_g6_2_math_u5_L05_challenge','lesson_challenge','M6-2-u5-C5',3,'match','auto','원의 넓이를 정사각형으로 어림한 범위끼리 이으세요.','{}'::text[],true,'{"seq":3,"concept":"M6-2-u5-C5","difficulty":3,"kind":"match","stem":"원의 넓이를 정사각형으로 어림한 범위끼리 이으세요.","pairs":[{"l":"반지름 3 cm","r":"18 cm²보다 넓고 36 cm²보다 좁아요"},{"l":"반지름 4 cm","r":"32 cm²보다 넓고 64 cm²보다 좁아요"},{"l":"반지름 6 cm","r":"72 cm²보다 넓고 144 cm²보다 좁아요"}],"mis":"M6-2-u5-X11","explanation":["원 안 정사각형은 (반지름) × (반지름) × 2예요.","원 밖 정사각형은 (반지름) × (반지름) × 4예요.","원의 넓이는 그 사이에 있어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 원의 넓이를 정사각형으로 어림한 범위끼리 이으세요.","pairs":[{"l":"반지름 2 cm","r":"8 cm²보다 넓고 16 cm²보다 좁아요"},{"l":"반지름 5 cm","r":"50 cm²보다 넓고 100 cm²보다 좁아요"},{"l":"반지름 7 cm","r":"98 cm²보다 넓고 196 cm²보다 좁아요"}],"explanation":["원 안 정사각형은 (반지름) × (반지름) × 2예요.","원 밖 정사각형은 (반지름) × (반지름) × 4예요.","원의 넓이는 그 사이에 있어요."]},{"stem":"이번에는 다른 보기예요. 원의 넓이를 정사각형으로 어림한 범위끼리 이으세요.","pairs":[{"l":"반지름 1 cm","r":"2 cm²보다 넓고 4 cm²보다 좁아요"},{"l":"반지름 8 cm","r":"128 cm²보다 넓고 256 cm²보다 좁아요"},{"l":"반지름 10 cm","r":"200 cm²보다 넓고 400 cm²보다 좁아요"}],"explanation":["원 안 정사각형은 (반지름) × (반지름) × 2예요.","원 밖 정사각형은 (반지름) × (반지름) × 4예요.","원의 넓이는 그 사이에 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L05_challenge#4','math',6,2,'u5','L05','tb_g6_2_math_u5_L05_challenge','lesson_challenge','M6-2-u5-C5',3,'mc','auto','반지름이 5 cm인 원의 넓이가 될 수 있는 것은 어느 것인가요?',ARRAY['M6-2-u5-X10','M6-2-u5-X11']::text[],true,'{"seq":4,"concept":"M6-2-u5-C5","difficulty":3,"kind":"mc","stem":"반지름이 5 cm인 원의 넓이가 될 수 있는 것은 어느 것인가요?","options":[{"t":"78.5 cm²","correct":true},{"t":"48 cm²","mis":"M6-2-u5-X10"},{"t":"106 cm²","mis":"M6-2-u5-X10"},{"t":"25 cm²","mis":"M6-2-u5-X11"}],"explanation":["원의 넓이는 5 × 5 × 2 = 50 cm²보다 넓어요.","또 5 × 5 × 4 = 100 cm²보다 좁아요.","그 사이에 있는 것은 78.5 cm²뿐이에요."],"variant_rule":{"alt":[{"stem":"반지름이 10 cm인 원의 넓이가 될 수 있는 것은 어느 것인가요?","options":[{"t":"314 cm²","correct":true},{"t":"198 cm²","mis":"M6-2-u5-X10"},{"t":"406 cm²","mis":"M6-2-u5-X10"},{"t":"100 cm²","mis":"M6-2-u5-X11"}],"explanation":["원의 넓이는 10 × 10 × 2 = 200 cm²보다 넓어요.","또 10 × 10 × 4 = 400 cm²보다 좁아요.","그 사이에 있는 것은 314 cm²뿐이에요."]},{"stem":"반지름이 7 cm인 원의 넓이가 될 수 있는 것은 어느 것인가요?","options":[{"t":"153.86 cm²","correct":true},{"t":"96 cm²","mis":"M6-2-u5-X10"},{"t":"202 cm²","mis":"M6-2-u5-X10"},{"t":"49 cm²","mis":"M6-2-u5-X11"}],"explanation":["원의 넓이는 7 × 7 × 2 = 98 cm²보다 넓어요.","또 7 × 7 × 4 = 196 cm²보다 좁아요.","그 사이에 있는 것은 153.86 cm²뿐이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L05_challenge#5','math',6,2,'u5','L05','tb_g6_2_math_u5_L05_challenge','lesson_challenge','M6-2-u5-C5',3,'mc','auto','원의 넓이는 반지름을 한 변으로 하는 정사각형 몇 개의 넓이와 가장 비슷한가요?',ARRAY['M6-2-u5-X11','M6-2-u5-X10']::text[],false,'{"seq":5,"concept":"M6-2-u5-C5","difficulty":3,"kind":"mc","stem":"원의 넓이는 반지름을 한 변으로 하는 정사각형 몇 개의 넓이와 가장 비슷한가요?","options":[{"t":"약 3개","correct":true},{"t":"약 1개","mis":"M6-2-u5-X11"},{"t":"약 6개","mis":"M6-2-u5-X10"},{"t":"약 5개","mis":"M6-2-u5-X10"}],"explanation":["원의 넓이는 반지름 정사각형 2개보다 넓어요.","또 4개보다 좁아요.","그 한가운데쯤인 약 3개와 비슷해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L05_challenge#6','math',6,2,'u5','L05','tb_g6_2_math_u5_L05_challenge','lesson_challenge','M6-2-u5-C5',3,'ox','auto','원의 넓이는 원 밖에 꼭 맞는 정사각형 넓이의 반보다 넓어요.',ARRAY['M6-2-u5-X11']::text[],true,'{"seq":6,"concept":"M6-2-u5-C5","difficulty":3,"kind":"ox","stem":"원의 넓이는 원 밖에 꼭 맞는 정사각형 넓이의 반보다 넓어요.","answer":"O","reason_options":[{"t":"원 안 정사각형이 원 밖 정사각형의 반이고 원은 그보다 넓기 때문에","correct":true},{"t":"원이 원 밖 정사각형보다 넓기 때문에","mis":"M6-2-u5-X11"}],"mis":"M6-2-u5-X11","explanation":["원 안 정사각형은 반지름 정사각형 2개, 원 밖 정사각형은 4개와 넓이가 같아요.","원의 넓이는 그 사이에 있어요.","어림은 정확한 값이 아니라 범위를 찾는 일이에요."],"variant_rule":{"alt":[{"stem":"원 안에 꼭 맞는 정사각형의 넓이는 원 밖에 꼭 맞는 정사각형 넓이의 반이에요.","answer":"O","reason_options":[{"t":"반지름 정사각형 2개와 4개이기 때문에","correct":true},{"t":"두 정사각형의 넓이가 같기 때문에","mis":"M6-2-u5-X11"}],"explanation":["원 안 정사각형은 반지름 정사각형 2개, 원 밖 정사각형은 4개와 넓이가 같아요.","원의 넓이는 그 사이에 있어요.","어림은 정확한 값이 아니라 범위를 찾는 일이에요."]},{"stem":"원의 넓이는 원 안에 꼭 맞는 정사각형보다 좁아요.","answer":"X","reason_options":[{"t":"정사각형이 원 안에 들어 있으니 원이 더 넓기 때문에","correct":true},{"t":"정사각형은 모서리가 있어 더 넓기 때문에","mis":"M6-2-u5-X10"}],"explanation":["원 안 정사각형은 반지름 정사각형 2개, 원 밖 정사각형은 4개와 넓이가 같아요.","원의 넓이는 그 사이에 있어요.","어림은 정확한 값이 아니라 범위를 찾는 일이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L05_challenge#7','math',6,2,'u5','L05','tb_g6_2_math_u5_L05_challenge','lesson_challenge','M6-2-u5-C5',3,'mc','auto','지름이 10 cm인 원의 넓이를 원 안과 밖에 꼭 맞는 정사각형으로 어림했어요. 알맞은 범위는 어느 것인가요?',ARRAY['M6-2-u5-X11','M6-2-u5-X01','M6-2-u5-X12']::text[],true,'{"seq":7,"concept":"M6-2-u5-C5","difficulty":3,"kind":"mc","stem":"지름이 10 cm인 원의 넓이를 원 안과 밖에 꼭 맞는 정사각형으로 어림했어요. 알맞은 범위는 어느 것인가요?","options":[{"t":"50 cm²보다 넓고 100 cm²보다 좁아요","correct":true},{"t":"25 cm²보다 넓고 50 cm²보다 좁아요","mis":"M6-2-u5-X11"},{"t":"100 cm²보다 넓고 200 cm²보다 좁아요","mis":"M6-2-u5-X01"},{"t":"10 cm²보다 넓고 20 cm²보다 좁아요","mis":"M6-2-u5-X12"}],"explanation":["반지름은 5 cm예요.","원 안 정사각형은 5 × 5 × 2 = 50 cm², 원 밖 정사각형은 5 × 5 × 4 = 100 cm²예요.","원의 넓이는 그 사이 — 50 cm²보다 넓고 100 cm²보다 좁아요."],"variant_rule":{"alt":[{"stem":"지름이 18 cm인 원의 넓이를 원 안과 밖에 꼭 맞는 정사각형으로 어림했어요. 알맞은 범위는 어느 것인가요?","options":[{"t":"162 cm²보다 넓고 324 cm²보다 좁아요","correct":true},{"t":"81 cm²보다 넓고 162 cm²보다 좁아요","mis":"M6-2-u5-X11"},{"t":"324 cm²보다 넓고 648 cm²보다 좁아요","mis":"M6-2-u5-X01"},{"t":"18 cm²보다 넓고 36 cm²보다 좁아요","mis":"M6-2-u5-X12"}],"explanation":["반지름은 9 cm예요.","원 안 정사각형은 9 × 9 × 2 = 162 cm², 원 밖 정사각형은 9 × 9 × 4 = 324 cm²예요.","원의 넓이는 그 사이 — 162 cm²보다 넓고 324 cm²보다 좁아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L05_challenge#8','math',6,2,'u5','L05','tb_g6_2_math_u5_L05_challenge','lesson_challenge','M6-2-u5-C5',4,'sa','auto','반지름이 10 cm인 원의 넓이는 원 안에 꼭 맞는 정사각형보다 넓고 원 밖에 꼭 맞는 정사각형보다 좁아요. 두 정사각형의 넓이의 차는 몇 cm²인가요?','{}'::text[],true,'{"seq":8,"concept":"M6-2-u5-C5","difficulty":4,"kind":"sa","stem":"반지름이 10 cm인 원의 넓이는 원 안에 꼭 맞는 정사각형보다 넓고 원 밖에 꼭 맞는 정사각형보다 좁아요. 두 정사각형의 넓이의 차는 몇 cm²인가요?","answer":["200"],"explanation":["원 안 정사각형은 두 대각선이 20 cm — 20 × 20 ÷ 2 = 200 cm²예요.","원 밖 정사각형은 한 변이 20 cm — 20 × 20 = 400 cm²예요.","400 − 200 = 200 cm²예요."],"variant_rule":{"alt":[{"stem":"반지름이 7 cm인 원의 넓이를 어림하려고 원 안의 마름모와 원 밖의 정사각형을 그렸어요. 두 도형의 넓이의 차는 몇 cm²인가요?","answer":["98"],"explanation":["마름모는 두 대각선이 14 cm — 14 × 14 ÷ 2 = 98 cm²예요.","정사각형은 14 × 14 = 196 cm²예요.","196 − 98 = 98 cm²예요."]},{"stem":"반지름이 6 cm인 원의 넓이를 어림하려고 원 안의 마름모와 원 밖의 정사각형을 그렸어요. 두 도형의 넓이의 차는 몇 cm²인가요?","answer":["72"],"explanation":["마름모는 두 대각선이 12 cm — 12 × 12 ÷ 2 = 72 cm²예요.","정사각형은 12 × 12 = 144 cm²예요.","144 − 72 = 72 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L05_challenge#9','math',6,2,'u5','L05','tb_g6_2_math_u5_L05_challenge','lesson_challenge','M6-2-u5-C5',4,'essay','teacher','한 칸이 1 cm²인 모눈 위에 반지름이 5 cm인 원을 그렸어요. 원 안에 완전히 들어간 칸은 60칸, 원에 걸친 칸까지 세면 88칸이에요. 이것으로 원의 넓이를 어림하고, 그렇게 어림한 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M6-2-u5-C5","difficulty":4,"kind":"essay","stem":"한 칸이 1 cm²인 모눈 위에 반지름이 5 cm인 원을 그렸어요. 원 안에 완전히 들어간 칸은 60칸, 원에 걸친 칸까지 세면 88칸이에요. 이것으로 원의 넓이를 어림하고, 그렇게 어림한 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 원의 넓이는 60 cm²보다 넓고 88 cm²보다 좁다. 원 안에 완전히 들어간 60칸은 모두 원 안에 있으니 원은 그보다 넓고, 걸친 칸까지 센 88칸은 원을 다 덮으니 원은 그보다 좁다.","scoring_points":["60 cm²보다 넓고 88 cm²보다 좁다고 어림했는가","60칸이 원 안에 있어 원이 더 넓은 까닭을 썼는가","88칸이 원을 다 덮어 원이 더 좁은 까닭을 썼는가"]},"explanation":["원 안에 완전히 들어간 칸 60칸 — 원은 60 cm²보다 넓어요.","걸친 칸까지 88칸 — 원은 88 cm²보다 좁아요.","그래서 60 cm² < (원의 넓이) < 88 cm²예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L05_challenge#10','math',6,2,'u5','L05','tb_g6_2_math_u5_L05_challenge','lesson_challenge','M6-2-u5-C5',4,'essay','teacher','반지름이 10 cm인 원 안의 마름모와 원 밖의 정사각형으로 원의 넓이를 어림하려고 해요. 두 도형의 넓이를 구하고, 원의 넓이가 (반지름) × (반지름)의 몇 배쯤인지 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u5-C5","difficulty":4,"kind":"essay","stem":"반지름이 10 cm인 원 안의 마름모와 원 밖의 정사각형으로 원의 넓이를 어림하려고 해요. 두 도형의 넓이를 구하고, 원의 넓이가 (반지름) × (반지름)의 몇 배쯤인지 설명해 보세요.","answer_guide":{"answer":"예: 마름모의 두 대각선은 지름 20 cm와 같아 넓이는 20 × 20 ÷ 2 = 200 cm², 정사각형의 한 변은 지름과 같아 넓이는 20 × 20 = 400 cm²이다. (반지름) × (반지름) = 100이므로 원의 넓이는 100의 2배보다 넓고 4배보다 좁아 약 3배쯤이다.","scoring_points":["마름모 200 cm²를 구했는가","정사각형 400 cm²를 구했는가","(반지름) × (반지름)의 2배와 4배 사이, 약 3배라고 썼는가"]},"explanation":["마름모는 20 × 20 ÷ 2 = 200 cm²예요.","정사각형은 20 × 20 = 400 cm²예요.","원의 넓이는 100 cm²의 2배와 4배 사이 — 약 3배예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L06_basic#1','math',6,2,'u5','L06','tb_g6_2_math_u5_L06_basic','lesson_basic','M6-2-u5-C6',1,'mc','auto','원을 한없이 잘라서 이어 붙이면 직사각형이 돼요. 이 직사각형의 가로는 원의 무엇과 같나요?',ARRAY['M6-2-u5-X15']::text[],true,'{"seq":1,"concept":"M6-2-u5-C6","difficulty":1,"kind":"mc","stem":"원을 한없이 잘라서 이어 붙이면 직사각형이 돼요. 이 직사각형의 가로는 원의 무엇과 같나요?","options":[{"t":"원주의 반","correct":true},{"t":"원주","mis":"M6-2-u5-X15"},{"t":"지름","mis":"M6-2-u5-X15"},{"t":"반지름","mis":"M6-2-u5-X15"}],"explanation":["잘라 낸 부채꼴이 위아래로 번갈아 놓여요.","원주의 반은 위쪽에, 나머지 반은 아래쪽에 놓여요.","그래서 가로는 원주의 반이에요."],"variant_rule":{"alt":[{"stem":"원을 한없이 잘라서 이어 붙여 만든 직사각형에서 세로는 원의 무엇과 같나요?","options":[{"t":"반지름","correct":true},{"t":"지름","mis":"M6-2-u5-X15"},{"t":"원주","mis":"M6-2-u5-X15"},{"t":"원주의 반","mis":"M6-2-u5-X15"}],"explanation":["부채꼴 한 조각의 길이가 반지름이에요.","조각을 세워 이어 붙이니 높이가 반지름이 돼요.","그래서 세로는 반지름이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L06_basic#2','math',6,2,'u5','L06','tb_g6_2_math_u5_L06_basic','lesson_basic','M6-2-u5-C6',1,'mc','auto','원의 넓이를 구하는 식으로 알맞은 것은 어느 것인가요?',ARRAY['M6-2-u5-X12','M6-2-u5-X13','M6-2-u5-X14']::text[],true,'{"seq":2,"concept":"M6-2-u5-C6","difficulty":1,"kind":"mc","stem":"원의 넓이를 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"(반지름) × (반지름) × (원주율)","correct":true},{"t":"(지름) × (원주율)","mis":"M6-2-u5-X12"},{"t":"(지름) × (지름) × (원주율)","mis":"M6-2-u5-X13"},{"t":"(반지름) × (원주율)","mis":"M6-2-u5-X14"}],"explanation":["직사각형의 넓이는 (가로) × (세로)예요.","가로는 원주의 반 — (반지름) × (원주율), 세로는 반지름이에요.","그래서 (원의 넓이) = (반지름) × (반지름) × (원주율)이에요."],"variant_rule":{"alt":[{"stem":"(원의 넓이) = (반지름) × (지름) × (원주율) × ⟨1/2⟩ = ( ㉠ ) × ( ㉡ ) × (원주율)이에요. ㉠과 ㉡에 알맞은 말은 어느 것인가요?","options":[{"t":"반지름, 반지름","correct":true},{"t":"지름, 지름","mis":"M6-2-u5-X13"},{"t":"반지름, 지름","mis":"M6-2-u5-X15"},{"t":"지름, 원주율","mis":"M6-2-u5-X12"}],"explanation":["(지름) × ⟨1/2⟩은 반지름이에요.","그래서 (반지름) × (지름) × ⟨1/2⟩ = (반지름) × (반지름)이에요.","(원의 넓이) = (반지름) × (반지름) × (원주율)이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L06_basic#3','math',6,2,'u5','L06','tb_g6_2_math_u5_L06_basic','lesson_basic','M6-2-u5-C6',1,'mc','auto','반지름이 3 cm인 원의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X12','M6-2-u5-X14','M6-2-u5-X13']::text[],true,'{"seq":3,"concept":"M6-2-u5-C6","difficulty":1,"kind":"mc","stem":"반지름이 3 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"28.26 cm²","correct":true},{"t":"18.84 cm²","mis":"M6-2-u5-X12"},{"t":"9.42 cm²","mis":"M6-2-u5-X14"},{"t":"113.04 cm²","mis":"M6-2-u5-X13"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","3 × 3 × 3.14를 계산해요.","3 × 3 × 3.14 = 28.26 — 넓이는 28.26 cm²예요."],"variant_rule":{"alt":[{"stem":"반지름이 5 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"78.5 cm²","correct":true},{"t":"31.4 cm²","mis":"M6-2-u5-X12"},{"t":"15.7 cm²","mis":"M6-2-u5-X14"},{"t":"314 cm²","mis":"M6-2-u5-X13"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","5 × 5 × 3.14를 계산해요.","5 × 5 × 3.14 = 78.5 — 넓이는 78.5 cm²예요."]},{"stem":"반지름이 2 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"12.56 cm²","correct":true},{"t":"6.28 cm²","mis":"M6-2-u5-X14"},{"t":"50.24 cm²","mis":"M6-2-u5-X13"},{"t":"4 cm²","mis":"M6-2-u5-X20"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","2 × 2 × 3.14를 계산해요.","2 × 2 × 3.14 = 12.56 — 넓이는 12.56 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L06_basic#4','math',6,2,'u5','L06','tb_g6_2_math_u5_L06_basic','lesson_basic','M6-2-u5-C6',1,'mc','auto','지름이 12 cm인 원의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X13','M6-2-u5-X12','M6-2-u5-X14']::text[],true,'{"seq":4,"concept":"M6-2-u5-C6","difficulty":1,"kind":"mc","stem":"지름이 12 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"113.04 cm²","correct":true},{"t":"452.16 cm²","mis":"M6-2-u5-X13"},{"t":"37.68 cm²","mis":"M6-2-u5-X12"},{"t":"18.84 cm²","mis":"M6-2-u5-X14"}],"explanation":["넓이는 반지름으로 구해요 — 반지름은 12 ÷ 2 = 6 cm예요.","6 × 6 × 3.14를 계산해요.","6 × 6 × 3.14 = 113.04 — 넓이는 113.04 cm²예요."],"variant_rule":{"alt":[{"stem":"지름이 8 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"50.24 cm²","correct":true},{"t":"200.96 cm²","mis":"M6-2-u5-X13"},{"t":"25.12 cm²","mis":"M6-2-u5-X12"},{"t":"12.56 cm²","mis":"M6-2-u5-X14"}],"explanation":["넓이는 반지름으로 구해요 — 반지름은 8 ÷ 2 = 4 cm예요.","4 × 4 × 3.14를 계산해요.","4 × 4 × 3.14 = 50.24 — 넓이는 50.24 cm²예요."]},{"stem":"지름이 20 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"314 cm²","correct":true},{"t":"1256 cm²","mis":"M6-2-u5-X13"},{"t":"62.8 cm²","mis":"M6-2-u5-X12"},{"t":"31.4 cm²","mis":"M6-2-u5-X14"}],"explanation":["넓이는 반지름으로 구해요 — 반지름은 20 ÷ 2 = 10 cm예요.","10 × 10 × 3.14를 계산해요.","10 × 10 × 3.14 = 314 — 넓이는 314 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L06_basic#5','math',6,2,'u5','L06','tb_g6_2_math_u5_L06_basic','lesson_basic','M6-2-u5-C6',2,'mc','auto','원의 넓이를 구하는 방법을 식으로 잘못 나타낸 것은 어느 것인가요?',ARRAY['M6-2-u5-X19']::text[],true,'{"seq":5,"concept":"M6-2-u5-C6","difficulty":2,"kind":"mc","stem":"원의 넓이를 구하는 방법을 식으로 잘못 나타낸 것은 어느 것인가요?","options":[{"t":"(지름) × (원주율)","correct":true},{"t":"(반지름) × (원주) × ⟨1/2⟩","mis":"M6-2-u5-X19"},{"t":"(반지름) × (반지름) × (원주율)","mis":"M6-2-u5-X19"},{"t":"(반지름) × (지름) × (원주율) × ⟨1/2⟩","mis":"M6-2-u5-X19"}],"explanation":["(원의 넓이) = (반지름) × (원주) × ⟨1/2⟩이에요.","원주 대신 (지름) × (원주율)을 넣고 정리하면 (반지름) × (반지름) × (원주율)이에요.","(지름) × (원주율)은 넓이를 구하는 식이 아니에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 원의 넓이를 구하는 방법을 식으로 잘못 나타낸 것은 어느 것인가요?","options":[{"t":"(반지름) × 2 × (원주율)","correct":true},{"t":"(반지름) × (원주) × ⟨1/2⟩","mis":"M6-2-u5-X19"},{"t":"(반지름) × (반지름) × (원주율)","mis":"M6-2-u5-X19"},{"t":"(반지름) × (지름) × (원주율) × ⟨1/2⟩","mis":"M6-2-u5-X19"}],"explanation":["(원의 넓이) = (반지름) × (원주) × ⟨1/2⟩이에요.","원주 대신 (지름) × (원주율)을 넣고 정리하면 (반지름) × (반지름) × (원주율)이에요.","(반지름) × 2 × (원주율)은 넓이를 구하는 식이 아니에요."]},{"stem":"이번에는 다른 보기예요. 원의 넓이를 구하는 방법을 식으로 잘못 나타낸 것은 어느 것인가요?","options":[{"t":"(지름) × (지름) × (원주율)","correct":true},{"t":"(반지름) × (원주) × ⟨1/2⟩","mis":"M6-2-u5-X19"},{"t":"(반지름) × (반지름) × (원주율)","mis":"M6-2-u5-X19"},{"t":"(반지름) × (지름) × (원주율) × ⟨1/2⟩","mis":"M6-2-u5-X19"}],"explanation":["(원의 넓이) = (반지름) × (원주) × ⟨1/2⟩이에요.","원주 대신 (지름) × (원주율)을 넣고 정리하면 (반지름) × (반지름) × (원주율)이에요.","(지름) × (지름) × (원주율)은 넓이를 구하는 식이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L06_basic#6','math',6,2,'u5','L06','tb_g6_2_math_u5_L06_basic','lesson_basic','M6-2-u5-C6',2,'mc','auto','반지름이 6 cm인 원을 한없이 잘라 이어 붙여 직사각형을 만들었어요. 이 직사각형의 가로와 세로로 알맞은 것은 어느 것인가요?',ARRAY['M6-2-u5-X15']::text[],true,'{"seq":6,"concept":"M6-2-u5-C6","difficulty":2,"kind":"mc","stem":"반지름이 6 cm인 원을 한없이 잘라 이어 붙여 직사각형을 만들었어요. 이 직사각형의 가로와 세로로 알맞은 것은 어느 것인가요?","options":[{"t":"가로 18.84 cm, 세로 6 cm","correct":true},{"t":"가로 37.68 cm, 세로 6 cm","mis":"M6-2-u5-X15"},{"t":"가로 18.84 cm, 세로 12 cm","mis":"M6-2-u5-X15"},{"t":"가로 37.68 cm, 세로 12 cm","mis":"M6-2-u5-X15"}],"explanation":["원주는 12 × 3.14 = 37.68 cm예요.","가로는 원주의 반 — 18.84 cm예요.","세로는 반지름 — 6 cm예요."],"variant_rule":{"alt":[{"stem":"반지름이 3 cm인 원을 한없이 잘라 이어 붙여 직사각형을 만들었어요. 이 직사각형의 가로와 세로로 알맞은 것은 어느 것인가요?","options":[{"t":"가로 9.42 cm, 세로 3 cm","correct":true},{"t":"가로 18.84 cm, 세로 3 cm","mis":"M6-2-u5-X15"},{"t":"가로 9.42 cm, 세로 6 cm","mis":"M6-2-u5-X15"},{"t":"가로 18.84 cm, 세로 6 cm","mis":"M6-2-u5-X15"}],"explanation":["원주는 6 × 3.14 = 18.84 cm예요.","가로는 원주의 반 — 9.42 cm예요.","세로는 반지름 — 3 cm예요."]},{"stem":"반지름이 10 cm인 원을 한없이 잘라 이어 붙여 직사각형을 만들었어요. 이 직사각형의 가로와 세로로 알맞은 것은 어느 것인가요?","options":[{"t":"가로 31.4 cm, 세로 10 cm","correct":true},{"t":"가로 62.8 cm, 세로 10 cm","mis":"M6-2-u5-X15"},{"t":"가로 31.4 cm, 세로 20 cm","mis":"M6-2-u5-X15"},{"t":"가로 62.8 cm, 세로 20 cm","mis":"M6-2-u5-X15"}],"explanation":["원주는 20 × 3.14 = 62.8 cm예요.","가로는 원주의 반 — 31.4 cm예요.","세로는 반지름 — 10 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L06_basic#7','math',6,2,'u5','L06','tb_g6_2_math_u5_L06_basic','lesson_basic','M6-2-u5-C6',2,'mc','auto','반지름이 30 cm인 원 모양 거울과 가로 70 cm, 세로 40 cm인 직사각형 모양 거울이 있어요. 넓이가 더 넓은 거울은 어느 것인가요?',ARRAY['M6-2-u5-X20','M6-2-u5-X19']::text[],false,'{"seq":7,"concept":"M6-2-u5-C6","difficulty":2,"kind":"mc","stem":"반지름이 30 cm인 원 모양 거울과 가로 70 cm, 세로 40 cm인 직사각형 모양 거울이 있어요. 넓이가 더 넓은 거울은 어느 것인가요?","options":[{"t":"원 모양 거울","correct":true},{"t":"직사각형 모양 거울","mis":"M6-2-u5-X20"},{"t":"두 거울의 넓이가 같다","mis":"M6-2-u5-X20"},{"t":"넓이를 비교할 수 없다","mis":"M6-2-u5-X19"}],"explanation":["원 모양 거울은 30 × 30 × 3.14 = 2826 cm²예요.","직사각형 모양 거울은 70 × 40 = 2800 cm²예요.","그래서 원 모양 거울이 더 넓어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L06_basic#8','math',6,2,'u5','L06','tb_g6_2_math_u5_L06_basic','lesson_basic','M6-2-u5-C6',2,'mc','auto','원을 한없이 잘라 이어 붙여 만든 직사각형의 넓이는 처음 원의 넓이와 견주어 어떤가요?',ARRAY['M6-2-u5-X17','M6-2-u5-X15']::text[],true,'{"seq":8,"concept":"M6-2-u5-C6","difficulty":2,"kind":"mc","stem":"원을 한없이 잘라 이어 붙여 만든 직사각형의 넓이는 처음 원의 넓이와 견주어 어떤가요?","options":[{"t":"같아요","correct":true},{"t":"더 넓어요","mis":"M6-2-u5-X17"},{"t":"더 좁아요","mis":"M6-2-u5-X17"},{"t":"두 배예요","mis":"M6-2-u5-X15"}],"explanation":["원을 자르고 이어 붙였을 뿐이에요.","조각을 더하거나 덜어 내지 않았어요.","그래서 직사각형의 넓이는 원의 넓이와 같아요."],"variant_rule":{"alt":[{"stem":"부채꼴 조각을 번갈아 뒤집어 이어 붙였어요. 처음 원과 견주어 넓이는 어떻게 되나요?","options":[{"t":"변하지 않아요","correct":true},{"t":"넓어져요","mis":"M6-2-u5-X17"},{"t":"좁아져요","mis":"M6-2-u5-X17"},{"t":"두 배가 돼요","mis":"M6-2-u5-X17"}],"explanation":["조각을 더하지도 덜어 내지도 않았어요.","자리만 옮기면 모양은 변해도 넓이는 그대로예요.","5학년 때 평행사변형을 직사각형으로 바꾼 것과 같은 방법이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L06_basic#9','math',6,2,'u5','L06','tb_g6_2_math_u5_L06_basic','lesson_basic','M6-2-u5-C6',2,'mc','auto','원을 8등분, 16등분, 32등분, 64등분하여 잘라 이어 붙였어요. 원을 더 많이 잘라서 이어 붙일수록 이어 붙인 모양은 어떤 도형에 가까워지나요?',ARRAY['M6-2-u5-X22']::text[],true,'{"seq":9,"concept":"M6-2-u5-C6","difficulty":2,"kind":"mc","stem":"원을 8등분, 16등분, 32등분, 64등분하여 잘라 이어 붙였어요. 원을 더 많이 잘라서 이어 붙일수록 이어 붙인 모양은 어떤 도형에 가까워지나요?","options":[{"t":"직사각형","correct":true},{"t":"삼각형","mis":"M6-2-u5-X22"},{"t":"원","mis":"M6-2-u5-X22"},{"t":"정사각형","mis":"M6-2-u5-X22"}],"explanation":["잘게 자를수록 조각의 굽은 부분이 작아져요.","이어 붙인 모양의 위아래가 점점 곧아져요.","원을 한없이 잘라 이어 붙이면 직사각형이 돼요."],"variant_rule":{"alt":[{"stem":"원을 8등분하여 잘라 이어 붙인 모양에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"직사각형과 비슷하지만 위아래가 굽어 있어 아직 직사각형은 아니에요","correct":true},{"t":"이미 완전한 직사각형이에요","mis":"M6-2-u5-X22"},{"t":"넓이가 원보다 넓어졌어요","mis":"M6-2-u5-X17"},{"t":"넓이가 원보다 좁아졌어요","mis":"M6-2-u5-X17"}],"explanation":["8등분한 조각을 이어 붙이면 위아래가 우툴두툴해요.","더 잘게 자를수록 직사각형에 가까워지고, 한없이 자르면 직사각형이 돼요.","자르고 이어 붙였을 뿐이니 넓이는 원과 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L06_basic#10','math',6,2,'u5','L06','tb_g6_2_math_u5_L06_basic','lesson_basic','M6-2-u5-C6',3,'mc','auto','두 원이 맞닿아 있어요. 큰 원의 중심에서 작은 원의 중심까지의 거리는 14 cm이고, 작은 원의 반지름은 6 cm예요. 큰 원의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X01','M6-2-u5-X09']::text[],true,'{"seq":10,"concept":"M6-2-u5-C6","difficulty":3,"kind":"mc","stem":"두 원이 맞닿아 있어요. 큰 원의 중심에서 작은 원의 중심까지의 거리는 14 cm이고, 작은 원의 반지름은 6 cm예요. 큰 원의 넓이는 몇 cm²인가요?","options":[{"t":"200.96 cm²","correct":true},{"t":"615.44 cm²","mis":"M6-2-u5-X01"},{"t":"153.86 cm²","mis":"M6-2-u5-X09"},{"t":"1256 cm²","mis":"M6-2-u5-X01"}],"explanation":["두 중심 사이 14 cm는 큰 원의 반지름과 작은 원의 반지름을 이은 길이예요.","큰 원의 반지름은 14 − 6 = 8 cm예요.","8 × 8 × 3.14 = 200.96 cm²예요."],"variant_rule":{"alt":[{"stem":"원 모양 시계가 있어요. 시계의 지름이 32 cm일 때 시계의 넓이는 몇 cm²인가요?","options":[{"t":"803.84 cm²","correct":true},{"t":"3215.36 cm²","mis":"M6-2-u5-X13"},{"t":"100.48 cm²","mis":"M6-2-u5-X12"},{"t":"50.24 cm²","mis":"M6-2-u5-X14"}],"explanation":["넓이는 반지름으로 구해요 — 반지름은 32 ÷ 2 = 16 cm예요.","16 × 16 × 3.14를 계산해요.","16 × 16 × 3.14 = 803.84 — 넓이는 803.84 cm²예요."]},{"stem":"원주가 87.92 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"615.44 cm²","correct":true},{"t":"2461.76 cm²","mis":"M6-2-u5-X13"},{"t":"87.92 cm²","mis":"M6-2-u5-X12"},{"t":"43.96 cm²","mis":"M6-2-u5-X14"}],"explanation":["지름은 87.92 ÷ 3.14 = 28 cm, 반지름은 14 cm예요.","넓이는 14 × 14 × 3.14예요.","14 × 14 × 3.14 = 615.44 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L06_challenge#1','math',6,2,'u5','L06','tb_g6_2_math_u5_L06_challenge','lesson_challenge','M6-2-u5-C6',2,'error','auto','반지름이 3 cm인 원의 넓이를 구했어요. 잘못 구한 것은 어느 것인가요?',ARRAY['M6-2-u5-X13','M6-2-u5-X19']::text[],true,'{"seq":1,"concept":"M6-2-u5-C6","difficulty":2,"kind":"error","stem":"반지름이 3 cm인 원의 넓이를 구했어요. 잘못 구한 것은 어느 것인가요?","options":[{"t":"㉠ 「6 × 6 × 3.14 = 113.04야.」","correct":true,"mis_target":"M6-2-u5-X13"},{"t":"㉡ 「3 × 3 × 3.14 = 28.26이야.」","mis":"M6-2-u5-X19"},{"t":"㉢ 「9.42 × 3 = 28.26이야.」","mis":"M6-2-u5-X19"},{"t":"㉣ 「넓이는 28.26 cm²야.」","mis":"M6-2-u5-X19"}],"explanation":["넓이는 반지름을 두 번 곱해요.","㉠의 말은 지름 6 cm를 두 번 곱한 거예요.","바른 넓이는 3 × 3 × 3.14 = 28.26 cm²예요."],"variant_rule":{"alt":[{"stem":"반지름이 6 cm인 원의 넓이를 구했어요. 잘못 구한 것은 어느 것인가요?","options":[{"t":"㉠ 「12 × 12 × 3.14 = 452.16이야.」","correct":true,"mis_target":"M6-2-u5-X13"},{"t":"㉡ 「6 × 6 × 3.14 = 113.04야.」","mis":"M6-2-u5-X19"},{"t":"㉢ 「18.84 × 6 = 113.04야.」","mis":"M6-2-u5-X19"},{"t":"㉣ 「넓이는 113.04 cm²야.」","mis":"M6-2-u5-X19"}],"explanation":["넓이는 반지름을 두 번 곱해요.","㉠의 말은 지름 12 cm를 두 번 곱한 거예요.","바른 넓이는 6 × 6 × 3.14 = 113.04 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L06_challenge#2','math',6,2,'u5','L06','tb_g6_2_math_u5_L06_challenge','lesson_challenge','M6-2-u5-C6',2,'ox','auto','원의 넓이는 (반지름) × (원주) × ⟨1/2⟩로도 구할 수 있어요.',ARRAY['M6-2-u5-X15']::text[],true,'{"seq":2,"concept":"M6-2-u5-C6","difficulty":2,"kind":"ox","stem":"원의 넓이는 (반지름) × (원주) × ⟨1/2⟩로도 구할 수 있어요.","answer":"O","reason_options":[{"t":"이어 붙인 직사각형의 가로가 원주의 반, 세로가 반지름이기 때문에","correct":true},{"t":"원주의 반이 넓이이기 때문에","mis":"M6-2-u5-X15"}],"mis":"M6-2-u5-X15","explanation":["원을 잘라 이어 붙인 직사각형은 가로가 원주의 반, 세로가 반지름이에요.","그래서 넓이는 (반지름) × (원주) × ⟨1/2⟩ = (반지름) × (반지름) × (원주율)이에요.","(지름) × (원주율)은 원주예요."],"variant_rule":{"alt":[{"stem":"원의 넓이는 (지름) × (원주율)로 구해요.","answer":"X","reason_options":[{"t":"(지름) × (원주율)은 원주를 구하는 식이기 때문에","correct":true},{"t":"넓이도 둘레처럼 지름에 원주율을 곱하기 때문에","mis":"M6-2-u5-X12"}],"explanation":["원을 잘라 이어 붙인 직사각형은 가로가 원주의 반, 세로가 반지름이에요.","그래서 넓이는 (반지름) × (원주) × ⟨1/2⟩ = (반지름) × (반지름) × (원주율)이에요.","(지름) × (원주율)은 원주예요."]},{"stem":"반지름이 5 cm인 원의 넓이는 5 × 3.14로 구해요.","answer":"X","reason_options":[{"t":"반지름을 두 번 곱해 5 × 5 × 3.14로 구해야 하기 때문에","correct":true},{"t":"반지름에 원주율을 한 번 곱하면 넓이이기 때문에","mis":"M6-2-u5-X14"}],"explanation":["원을 잘라 이어 붙인 직사각형은 가로가 원주의 반, 세로가 반지름이에요.","그래서 넓이는 (반지름) × (원주) × ⟨1/2⟩ = (반지름) × (반지름) × (원주율)이에요.","(지름) × (원주율)은 원주예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L06_challenge#3','math',6,2,'u5','L06','tb_g6_2_math_u5_L06_challenge','lesson_challenge','M6-2-u5-C6',3,'mc','auto','원주가 87.92 cm인 원의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X13','M6-2-u5-X12','M6-2-u5-X14']::text[],true,'{"seq":3,"concept":"M6-2-u5-C6","difficulty":3,"kind":"mc","stem":"원주가 87.92 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"615.44 cm²","correct":true},{"t":"2461.76 cm²","mis":"M6-2-u5-X13"},{"t":"87.92 cm²","mis":"M6-2-u5-X12"},{"t":"43.96 cm²","mis":"M6-2-u5-X14"}],"explanation":["지름은 87.92 ÷ 3.14 = 28 cm, 반지름은 14 cm예요.","넓이는 14 × 14 × 3.14예요.","14 × 14 × 3.14 = 615.44 cm²예요."],"variant_rule":{"alt":[{"stem":"원주가 75.36 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"452.16 cm²","correct":true},{"t":"1808.64 cm²","mis":"M6-2-u5-X13"},{"t":"75.36 cm²","mis":"M6-2-u5-X12"},{"t":"37.68 cm²","mis":"M6-2-u5-X14"}],"explanation":["지름은 75.36 ÷ 3.14 = 24 cm, 반지름은 12 cm예요.","넓이는 12 × 12 × 3.14예요.","12 × 12 × 3.14 = 452.16 cm²예요."]},{"stem":"원주가 31.4 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"78.5 cm²","correct":true},{"t":"314 cm²","mis":"M6-2-u5-X13"},{"t":"31.4 cm²","mis":"M6-2-u5-X12"},{"t":"15.7 cm²","mis":"M6-2-u5-X14"}],"explanation":["지름은 31.4 ÷ 3.14 = 10 cm, 반지름은 5 cm예요.","넓이는 5 × 5 × 3.14예요.","5 × 5 × 3.14 = 78.5 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L06_challenge#4','math',6,2,'u5','L06','tb_g6_2_math_u5_L06_challenge','lesson_challenge','M6-2-u5-C6',3,'sa','auto','넓이가 452.16 cm²인 원이 있어요. 이 원의 반지름은 몇 cm인가요?','{}'::text[],true,'{"seq":4,"concept":"M6-2-u5-C6","difficulty":3,"kind":"sa","stem":"넓이가 452.16 cm²인 원이 있어요. 이 원의 반지름은 몇 cm인가요?","answer":["12"],"explanation":["(반지름) × (반지름) × 3.14 = 452.16이에요.","452.16 ÷ 3.14 = 144니 (반지름) × (반지름) = 144예요.","같은 수를 두 번 곱해 144가 되는 수는 12 — 반지름은 12 cm예요."],"variant_rule":{"alt":[{"stem":"넓이가 314 cm²인 원이 있어요. 이 원의 반지름은 몇 cm인가요?","answer":["10"],"explanation":["(반지름) × (반지름) × 3.14 = 314예요.","314 ÷ 3.14 = 100이니 (반지름) × (반지름) = 100이에요.","같은 수를 두 번 곱해 100이 되는 수는 10 — 반지름은 10 cm예요."]},{"stem":"넓이가 78.5 cm²인 원이 있어요. 이 원의 반지름은 몇 cm인가요?","answer":["5"],"explanation":["(반지름) × (반지름) × 3.14 = 78.5예요.","78.5 ÷ 3.14 = 25니 (반지름) × (반지름) = 25예요.","같은 수를 두 번 곱해 25가 되는 수는 5 — 반지름은 5 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L06_challenge#5','math',6,2,'u5','L06','tb_g6_2_math_u5_L06_challenge','lesson_challenge','M6-2-u5-C6',3,'mc','auto','넓이가 넓은 원부터 차례로 놓으려고 해요. ㉠ 반지름이 10 cm인 원 · ㉡ 넓이가 615.44 cm²인 원 · ㉢ 원주가 75.36 cm인 원 — 바르게 놓은 것은 어느 것인가요?',ARRAY['M6-2-u5-X19','M6-2-u5-X13']::text[],true,'{"seq":5,"concept":"M6-2-u5-C6","difficulty":3,"kind":"mc","stem":"넓이가 넓은 원부터 차례로 놓으려고 해요. ㉠ 반지름이 10 cm인 원 · ㉡ 넓이가 615.44 cm²인 원 · ㉢ 원주가 75.36 cm인 원 — 바르게 놓은 것은 어느 것인가요?","options":[{"t":"㉡, ㉢, ㉠","correct":true},{"t":"㉠, ㉢, ㉡","mis":"M6-2-u5-X19"},{"t":"㉠, ㉡, ㉢","mis":"M6-2-u5-X13"},{"t":"㉢, ㉡, ㉠","mis":"M6-2-u5-X13"}],"explanation":["세 원의 넓이를 모두 구해 견주어요.","㉠ 314 cm² · ㉡ 615.44 cm² · ㉢ 452.16 cm²예요.","넓은 원부터 놓으면 ㉡, ㉢, ㉠이에요."],"variant_rule":{"alt":[{"stem":"넓이가 넓은 원부터 차례로 놓으려고 해요. ㉠ 지름이 22 cm인 원 · ㉡ 반지름이 9 cm인 원 · ㉢ 넓이가 452.16 cm²인 원 — 바르게 놓은 것은 어느 것인가요?","options":[{"t":"㉢, ㉠, ㉡","correct":true},{"t":"㉡, ㉠, ㉢","mis":"M6-2-u5-X19"},{"t":"㉠, ㉡, ㉢","mis":"M6-2-u5-X13"},{"t":"㉡, ㉢, ㉠","mis":"M6-2-u5-X13"}],"explanation":["세 원의 넓이를 모두 구해 견주어요.","㉠ 379.94 cm² · ㉡ 254.34 cm² · ㉢ 452.16 cm²예요.","넓은 원부터 놓으면 ㉢, ㉠, ㉡이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L06_challenge#6','math',6,2,'u5','L06','tb_g6_2_math_u5_L06_challenge','lesson_challenge','M6-2-u5-C6',3,'mc','auto','가로가 20 cm, 세로가 14 cm인 직사각형 종이를 잘라 만들 수 있는 가장 큰 원의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X21','M6-2-u5-X13','M6-2-u5-X12']::text[],true,'{"seq":6,"concept":"M6-2-u5-C6","difficulty":3,"kind":"mc","stem":"가로가 20 cm, 세로가 14 cm인 직사각형 종이를 잘라 만들 수 있는 가장 큰 원의 넓이는 몇 cm²인가요?","options":[{"t":"153.86 cm²","correct":true},{"t":"314 cm²","mis":"M6-2-u5-X21"},{"t":"615.44 cm²","mis":"M6-2-u5-X13"},{"t":"43.96 cm²","mis":"M6-2-u5-X12"}],"explanation":["가장 큰 원의 지름은 짧은 변 14 cm를 넘을 수 없어요.","반지름은 7 cm예요.","7 × 7 × 3.14 = 153.86 cm²예요."],"variant_rule":{"alt":[{"stem":"가로가 12 cm, 세로가 15 cm인 직사각형 종이를 잘라 만들 수 있는 가장 큰 원의 넓이는 몇 cm²인가요?","options":[{"t":"113.04 cm²","correct":true},{"t":"176.625 cm²","mis":"M6-2-u5-X21"},{"t":"452.16 cm²","mis":"M6-2-u5-X13"},{"t":"37.68 cm²","mis":"M6-2-u5-X12"}],"explanation":["가장 큰 원의 지름은 짧은 변 12 cm를 넘을 수 없어요.","반지름은 6 cm예요.","6 × 6 × 3.14 = 113.04 cm²예요."]}]},"asset":{"type":"geo","items":[{"w":120,"h":84,"pts":{"O":[60,42],"A":[0,0],"B":[120,0],"C":[120,84],"D":[0,84]},"show":[],"poly":[["A","B","C","D"]],"circle":[["O",42],["O",2]],"right":[["B","A","D"]]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L06_challenge#7','math',6,2,'u5','L06','tb_g6_2_math_u5_L06_challenge','lesson_challenge','M6-2-u5-C6',3,'match','auto','반지름과 원의 넓이를 이으세요.','{}'::text[],true,'{"seq":7,"concept":"M6-2-u5-C6","difficulty":3,"kind":"match","stem":"반지름과 원의 넓이를 이으세요.","pairs":[{"l":"반지름 1 cm","r":"3.14 cm²"},{"l":"반지름 2 cm","r":"12.56 cm²"},{"l":"반지름 5 cm","r":"78.5 cm²"}],"mis":"M6-2-u5-X14","explanation":["(원의 넓이) = (반지름) × (반지름) × 3.14예요.","1 × 1 × 3.14 = 3.14 · 2 × 2 × 3.14 = 12.56이에요.","5 × 5 × 3.14 = 78.5예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 반지름과 원의 넓이를 이으세요.","pairs":[{"l":"반지름 3 cm","r":"28.26 cm²"},{"l":"반지름 4 cm","r":"50.24 cm²"},{"l":"반지름 10 cm","r":"314 cm²"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × 3.14예요.","3 × 3 × 3.14 = 28.26 · 4 × 4 × 3.14 = 50.24예요.","10 × 10 × 3.14 = 314예요."]},{"stem":"이번에는 다른 보기예요. 반지름과 원의 넓이를 이으세요.","pairs":[{"l":"반지름 6 cm","r":"113.04 cm²"},{"l":"반지름 7 cm","r":"153.86 cm²"},{"l":"반지름 8 cm","r":"200.96 cm²"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × 3.14예요.","6 × 6 × 3.14 = 113.04 · 7 × 7 × 3.14 = 153.86이에요.","8 × 8 × 3.14 = 200.96이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L06_challenge#8','math',6,2,'u5','L06','tb_g6_2_math_u5_L06_challenge','lesson_challenge','M6-2-u5-C6',4,'mc','auto','고대 이집트 사람들은 지름이 9인 원의 넓이를 지름에서 1을 뺀 8을 한 변으로 하는 정사각형의 넓이와 같다고 생각했어요. 원주율을 3.14로 할 때, 지름이 9 m인 원의 넓이와 한 변이 8 m인 정사각형의 넓이의 차는 몇 m²인가요?',ARRAY['M6-2-u5-X13','M6-2-u5-X12','M6-2-u5-X19']::text[],false,'{"seq":8,"concept":"M6-2-u5-C6","difficulty":4,"kind":"mc","stem":"고대 이집트 사람들은 지름이 9인 원의 넓이를 지름에서 1을 뺀 8을 한 변으로 하는 정사각형의 넓이와 같다고 생각했어요. 원주율을 3.14로 할 때, 지름이 9 m인 원의 넓이와 한 변이 8 m인 정사각형의 넓이의 차는 몇 m²인가요?","options":[{"t":"0.415 m²","correct":true},{"t":"190.34 m²","mis":"M6-2-u5-X13"},{"t":"35.74 m²","mis":"M6-2-u5-X12"},{"t":"1 m²","mis":"M6-2-u5-X19"}],"explanation":["지름이 9 m인 원의 반지름은 4.5 m — 넓이는 4.5 × 4.5 × 3.14 = 63.585 m²예요.","정사각형의 넓이는 8 × 8 = 64 m²예요.","64 − 63.585 = 0.415 m² — 원주율을 몰랐던 옛사람들의 어림이 꽤 가까웠어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L06_challenge#9','math',6,2,'u5','L06','tb_g6_2_math_u5_L06_challenge','lesson_challenge','M6-2-u5-C6',4,'essay','teacher','원을 한없이 잘라서 이어 붙이면 직사각형이 돼요. 이 직사각형의 가로와 세로가 원의 무엇과 같은지 쓰고, 원의 넓이를 구하는 식을 이끌어 내는 과정을 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M6-2-u5-C6","difficulty":4,"kind":"essay","stem":"원을 한없이 잘라서 이어 붙이면 직사각형이 돼요. 이 직사각형의 가로와 세로가 원의 무엇과 같은지 쓰고, 원의 넓이를 구하는 식을 이끌어 내는 과정을 설명해 보세요.","answer_guide":{"answer":"예: 가로는 원주의 반 (원주) × ⟨1/2⟩이고, 세로는 반지름이다. (원의 넓이) = (반지름) × (원주) × ⟨1/2⟩ = (반지름) × (지름) × (원주율) × ⟨1/2⟩이고, (지름) × ⟨1/2⟩ = (반지름)이므로 (반지름) × (반지름) × (원주율)이다.","scoring_points":["가로 = 원주의 반, 세로 = 반지름을 썼는가","(원주) = (지름) × (원주율)을 넣었는가","(반지름) × (반지름) × (원주율)을 이끌어 냈는가"]},"explanation":["가로는 원주의 반, 세로는 반지름이에요.","원주에 (지름) × (원주율)을 넣어요.","(지름)의 반은 반지름 — (반지름) × (반지름) × (원주율)이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L06_challenge#10','math',6,2,'u5','L06','tb_g6_2_math_u5_L06_challenge','lesson_challenge','M6-2-u5-C6',4,'essay','teacher','가로 70 cm, 세로 40 cm인 직사각형 모양 거울과 지름이 60 cm인 원 모양 거울이 있어요. 눈으로 보면 넓이가 비슷해 보여요. 어느 거울이 더 넓은지 식을 세워 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u5-C6","difficulty":4,"kind":"essay","stem":"가로 70 cm, 세로 40 cm인 직사각형 모양 거울과 지름이 60 cm인 원 모양 거울이 있어요. 눈으로 보면 넓이가 비슷해 보여요. 어느 거울이 더 넓은지 식을 세워 설명해 보세요.","answer_guide":{"answer":"예: 직사각형 모양 거울은 70 × 40 = 2800 cm²이다. 원 모양 거울은 반지름이 30 cm이므로 30 × 30 × 3.14 = 2826 cm²이다. 따라서 원 모양 거울이 26 cm² 더 넓다.","scoring_points":["직사각형 2800 cm²를 구했는가","반지름 30 cm로 원 2826 cm²를 구했는가","원 모양 거울이 더 넓다고 썼는가"]},"explanation":["직사각형 거울은 70 × 40 = 2800 cm²예요.","원 거울은 30 × 30 × 3.14 = 2826 cm²예요.","원 모양 거울이 더 넓어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L07_basic#1','math',6,2,'u5','L07','tb_g6_2_math_u5_L07_basic','lesson_basic','M6-2-u5-C7',1,'mc','auto','중심이 같은 원을 겹겹이 그린 작품에서 가장 안쪽 가 부분은 반지름이 1 cm인 원이에요. 가 부분의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X12','M6-2-u5-X13','M6-2-u5-X17']::text[],true,'{"seq":1,"concept":"M6-2-u5-C7","difficulty":1,"kind":"mc","stem":"중심이 같은 원을 겹겹이 그린 작품에서 가장 안쪽 가 부분은 반지름이 1 cm인 원이에요. 가 부분의 넓이는 몇 cm²인가요?","options":[{"t":"3.14 cm²","correct":true},{"t":"6.28 cm²","mis":"M6-2-u5-X12"},{"t":"12.56 cm²","mis":"M6-2-u5-X13"},{"t":"1.57 cm²","mis":"M6-2-u5-X17"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","1 × 1 × 3.14를 계산해요.","1 × 1 × 3.14 = 3.14 — 넓이는 3.14 cm²예요."],"variant_rule":{"alt":[{"stem":"반지름이 5 cm인 원 모양 색종이의 넓이는 몇 cm²인가요?","options":[{"t":"78.5 cm²","correct":true},{"t":"31.4 cm²","mis":"M6-2-u5-X12"},{"t":"15.7 cm²","mis":"M6-2-u5-X14"},{"t":"314 cm²","mis":"M6-2-u5-X13"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","5 × 5 × 3.14를 계산해요.","5 × 5 × 3.14 = 78.5 — 넓이는 78.5 cm²예요."]}]},"asset":{"type":"geo","items":[{"w":140,"h":140,"pts":{"O":[70,70],"E":[130,70]},"show":[],"circle":[["O",6],["O",24],["O",42],["O",60]],"seg":[["O","E"]],"lab":[[[70,58],"가"],[[85,52],"나"],[[103,52],"다"],[[121,52],"라"]]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L07_basic#2','math',6,2,'u5','L07','tb_g6_2_math_u5_L07_basic','lesson_basic','M6-2-u5-C7',1,'mc','auto','나 부분은 반지름이 4 cm인 원에서 반지름이 1 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X16','M6-2-u5-X20']::text[],true,'{"seq":2,"concept":"M6-2-u5-C7","difficulty":1,"kind":"mc","stem":"나 부분은 반지름이 4 cm인 원에서 반지름이 1 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?","options":[{"t":"47.1 cm²","correct":true},{"t":"50.24 cm²","mis":"M6-2-u5-X16"},{"t":"28.26 cm²","mis":"M6-2-u5-X16"},{"t":"53.38 cm²","mis":"M6-2-u5-X20"}],"explanation":["큰 원의 넓이는 4 × 4 × 3.14 = 50.24 cm²예요.","작은 원의 넓이는 1 × 1 × 3.14 = 3.14 cm²예요.","50.24 − 3.14 = 47.1 cm²예요."],"variant_rule":{"alt":[{"stem":"다 부분은 반지름이 7 cm인 원에서 반지름이 4 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?","options":[{"t":"103.62 cm²","correct":true},{"t":"153.86 cm²","mis":"M6-2-u5-X16"},{"t":"28.26 cm²","mis":"M6-2-u5-X16"},{"t":"204.1 cm²","mis":"M6-2-u5-X20"}],"explanation":["큰 원의 넓이는 7 × 7 × 3.14 = 153.86 cm²예요.","작은 원의 넓이는 4 × 4 × 3.14 = 50.24 cm²예요.","153.86 − 50.24 = 103.62 cm²예요."]},{"stem":"라 부분은 반지름이 10 cm인 원에서 반지름이 7 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?","options":[{"t":"160.14 cm²","correct":true},{"t":"314 cm²","mis":"M6-2-u5-X16"},{"t":"28.26 cm²","mis":"M6-2-u5-X16"},{"t":"467.86 cm²","mis":"M6-2-u5-X20"}],"explanation":["큰 원의 넓이는 10 × 10 × 3.14 = 314 cm²예요.","작은 원의 넓이는 7 × 7 × 3.14 = 153.86 cm²예요.","314 − 153.86 = 160.14 cm²예요."]}]},"asset":{"type":"geo","items":[{"w":140,"h":140,"pts":{"O":[70,70],"E":[130,70]},"show":[],"circle":[["O",6],["O",24],["O",42],["O",60]],"seg":[["O","E"]],"lab":[[[70,58],"가"],[[85,52],"나"],[[103,52],"다"],[[121,52],"라"]]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L07_basic#3','math',6,2,'u5','L07','tb_g6_2_math_u5_L07_basic','lesson_basic','M6-2-u5-C7',1,'sa','auto','아랫부분이 반원만큼 패이고 윗부분이 반원만큼 볼록한 모양이 있어요. 아랫부분의 반원을 윗부분으로 옮겼더니 가로 10 cm, 세로 5 cm인 직사각형이 되었어요. 처음 모양의 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":3,"concept":"M6-2-u5-C7","difficulty":1,"kind":"sa","stem":"아랫부분이 반원만큼 패이고 윗부분이 반원만큼 볼록한 모양이 있어요. 아랫부분의 반원을 윗부분으로 옮겼더니 가로 10 cm, 세로 5 cm인 직사각형이 되었어요. 처음 모양의 넓이는 몇 cm²인가요?","answer":["50"],"explanation":["조각을 더하지도 덜지도 않고 자리만 옮겼어요.","그래서 넓이는 직사각형과 같아요.","10 × 5 = 50 cm²예요."],"variant_rule":{"alt":[{"stem":"꽃밭은 가로 20 m, 세로 10 m인 직사각형의 위쪽에 반원만큼 볼록하고 아래쪽은 같은 크기의 반원만큼 패여 있어요. 볼록한 반원을 패인 곳으로 옮기면 직사각형이 돼요. 꽃밭의 넓이는 몇 m²인가요?","answer":["200"],"explanation":["볼록한 반원과 패인 반원은 크기가 같아요.","옮기면 가로 20 m, 세로 10 m인 직사각형이 돼요.","20 × 10 = 200 m²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L07_basic#4','math',6,2,'u5','L07','tb_g6_2_math_u5_L07_basic','lesson_basic','M6-2-u5-C7',1,'mc','auto','원의 일부를 잘라서 다른 자리로 옮겨 붙이면 넓이는 어떻게 되나요?',ARRAY['M6-2-u5-X17']::text[],true,'{"seq":4,"concept":"M6-2-u5-C7","difficulty":1,"kind":"mc","stem":"원의 일부를 잘라서 다른 자리로 옮겨 붙이면 넓이는 어떻게 되나요?","options":[{"t":"변하지 않아요","correct":true},{"t":"넓어져요","mis":"M6-2-u5-X17"},{"t":"좁아져요","mis":"M6-2-u5-X17"},{"t":"두 배가 돼요","mis":"M6-2-u5-X17"}],"explanation":["조각을 더하지도 덜어 내지도 않았어요.","자리만 옮기면 모양은 변해도 넓이는 그대로예요.","5학년 때 평행사변형을 직사각형으로 바꾼 것과 같은 방법이에요."],"variant_rule":{"alt":[{"stem":"반원 하나를 잘라 반대쪽에 붙여 새 모양을 만들었어요. 처음 모양과 견주어 넓이는 어떻게 되나요?","options":[{"t":"변하지 않아요","correct":true},{"t":"넓어져요","mis":"M6-2-u5-X17"},{"t":"좁아져요","mis":"M6-2-u5-X17"},{"t":"두 배가 돼요","mis":"M6-2-u5-X17"}],"explanation":["조각을 더하지도 덜어 내지도 않았어요.","자리만 옮기면 모양은 변해도 넓이는 그대로예요.","5학년 때 평행사변형을 직사각형으로 바꾼 것과 같은 방법이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L07_basic#5','math',6,2,'u5','L07','tb_g6_2_math_u5_L07_basic','lesson_basic','M6-2-u5-C7',2,'mc','auto','세호는 지름이 24 cm인 원 모양 피자를 똑같이 8조각으로 나눈 것 가운데 한 조각을 먹었어요. 세호가 먹은 피자의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X17','M6-2-u5-X13']::text[],true,'{"seq":5,"concept":"M6-2-u5-C7","difficulty":2,"kind":"mc","stem":"세호는 지름이 24 cm인 원 모양 피자를 똑같이 8조각으로 나눈 것 가운데 한 조각을 먹었어요. 세호가 먹은 피자의 넓이는 몇 cm²인가요?","options":[{"t":"56.52 cm²","correct":true},{"t":"452.16 cm²","mis":"M6-2-u5-X17"},{"t":"226.08 cm²","mis":"M6-2-u5-X13"},{"t":"113.04 cm²","mis":"M6-2-u5-X17"}],"explanation":["반지름은 24 ÷ 2 = 12 cm예요.","피자 전체는 12 × 12 × 3.14 = 452.16 cm²예요.","8조각 중 한 조각은 452.16 ÷ 8 = 56.52 cm²예요."],"variant_rule":{"alt":[{"stem":"반지름이 4 m인 반원의 넓이는 몇 m²인가요?","options":[{"t":"25.12 m²","correct":true},{"t":"50.24 m²","mis":"M6-2-u5-X17"},{"t":"12.56 m²","mis":"M6-2-u5-X17"},{"t":"100.48 m²","mis":"M6-2-u5-X13"}],"explanation":["반원은 원을 똑같이 2로 나눈 것 가운데 하나예요.","원의 넓이는 4 × 4 × 3.14 = 50.24 m²예요.","50.24 ÷ 2 = 25.12 m²예요."]},{"stem":"반지름이 6 cm인 사분원의 넓이는 몇 cm²인가요?","options":[{"t":"28.26 cm²","correct":true},{"t":"113.04 cm²","mis":"M6-2-u5-X17"},{"t":"56.52 cm²","mis":"M6-2-u5-X17"},{"t":"9.42 cm²","mis":"M6-2-u5-X12"}],"explanation":["사분원은 원을 똑같이 4로 나눈 것 가운데 하나예요.","원의 넓이는 6 × 6 × 3.14 = 113.04 cm²예요.","113.04 ÷ 4 = 28.26 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L07_basic#6','math',6,2,'u5','L07','tb_g6_2_math_u5_L07_basic','lesson_basic','M6-2-u5-C7',2,'mc','auto','꽃밭 가는 반지름이 4 m인 원 모양이고, 꽃밭 나는 반지름이 8 m인 원의 사분원 모양이에요. 두 꽃밭의 넓이를 바르게 비교한 것은 어느 것인가요?',ARRAY['M6-2-u5-X17','M6-2-u5-X18','M6-2-u5-X19']::text[],false,'{"seq":6,"concept":"M6-2-u5-C7","difficulty":2,"kind":"mc","stem":"꽃밭 가는 반지름이 4 m인 원 모양이고, 꽃밭 나는 반지름이 8 m인 원의 사분원 모양이에요. 두 꽃밭의 넓이를 바르게 비교한 것은 어느 것인가요?","options":[{"t":"가와 나의 넓이가 같아요","correct":true},{"t":"가가 나보다 넓어요","mis":"M6-2-u5-X17"},{"t":"나가 가보다 넓어요","mis":"M6-2-u5-X18"},{"t":"넓이를 비교할 수 없어요","mis":"M6-2-u5-X19"}],"explanation":["가는 4 × 4 × 3.14 = 50.24 m²예요.","나는 8 × 8 × 3.14 ÷ 4 = 50.24 m²예요.","두 꽃밭의 넓이는 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L07_basic#7','math',6,2,'u5','L07','tb_g6_2_math_u5_L07_basic','lesson_basic','M6-2-u5-C7',2,'mc','auto','한 변이 8 cm인 정사각형 안에 원이 꼭 맞게 들어 있어요. 정사각형에서 원을 뺀 부분의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X17','M6-2-u5-X12']::text[],true,'{"seq":7,"concept":"M6-2-u5-C7","difficulty":2,"kind":"mc","stem":"한 변이 8 cm인 정사각형 안에 원이 꼭 맞게 들어 있어요. 정사각형에서 원을 뺀 부분의 넓이는 몇 cm²인가요?","options":[{"t":"13.76 cm²","correct":true},{"t":"50.24 cm²","mis":"M6-2-u5-X17"},{"t":"38.88 cm²","mis":"M6-2-u5-X12"},{"t":"64 cm²","mis":"M6-2-u5-X17"}],"explanation":["정사각형의 넓이는 8 × 8 = 64 cm²예요.","원의 지름은 8 cm, 반지름은 4 cm — 넓이는 4 × 4 × 3.14 = 50.24 cm²예요.","64 − 50.24 = 13.76 cm²예요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"O":[60,60],"A":[10,10],"B":[110,10],"C":[110,110],"D":[10,110]},"show":[],"poly":[["A","B","C","D"]],"circle":[["O",50],["O",2]],"right":[["B","A","D"]]}]},"variant_rule":{"alt":[{"stem":"한 변이 20 cm인 정사각형 안에 원이 꼭 맞게 들어 있어요. 정사각형에서 원을 뺀 부분의 넓이는 몇 cm²인가요?","options":[{"t":"86 cm²","correct":true},{"t":"314 cm²","mis":"M6-2-u5-X17"},{"t":"337.2 cm²","mis":"M6-2-u5-X12"},{"t":"400 cm²","mis":"M6-2-u5-X17"}],"explanation":["정사각형의 넓이는 20 × 20 = 400 cm²예요.","원의 지름은 20 cm, 반지름은 10 cm — 넓이는 10 × 10 × 3.14 = 314 cm²예요.","400 − 314 = 86 cm²예요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"O":[60,60],"A":[10,10],"B":[110,10],"C":[110,110],"D":[10,110]},"show":[],"poly":[["A","B","C","D"]],"circle":[["O",50],["O",2]],"right":[["B","A","D"]]}]}},{"stem":"한 변이 10 cm인 정사각형 안에 원이 꼭 맞게 들어 있어요. 정사각형에서 원을 뺀 부분의 넓이는 몇 cm²인가요?","options":[{"t":"21.5 cm²","correct":true},{"t":"78.5 cm²","mis":"M6-2-u5-X17"},{"t":"68.6 cm²","mis":"M6-2-u5-X12"},{"t":"100 cm²","mis":"M6-2-u5-X17"}],"explanation":["정사각형의 넓이는 10 × 10 = 100 cm²예요.","원의 지름은 10 cm, 반지름은 5 cm — 넓이는 5 × 5 × 3.14 = 78.5 cm²예요.","100 − 78.5 = 21.5 cm²예요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"O":[60,60],"A":[10,10],"B":[110,10],"C":[110,110],"D":[10,110]},"show":[],"poly":[["A","B","C","D"]],"circle":[["O",50],["O",2]],"right":[["B","A","D"]]}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L07_basic#8','math',6,2,'u5','L07','tb_g6_2_math_u5_L07_basic','lesson_basic','M6-2-u5-C7',2,'mc','auto','지름이 8 cm인 반원이 있어요. 반원의 지름 위 한쪽에는 지름이 4 cm인 반원이 볼록하게 붙어 있고, 다른 쪽은 같은 크기의 반원만큼 패여 있어요. 이 모양의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X17']::text[],true,'{"seq":8,"concept":"M6-2-u5-C7","difficulty":2,"kind":"mc","stem":"지름이 8 cm인 반원이 있어요. 반원의 지름 위 한쪽에는 지름이 4 cm인 반원이 볼록하게 붙어 있고, 다른 쪽은 같은 크기의 반원만큼 패여 있어요. 이 모양의 넓이는 몇 cm²인가요?","options":[{"t":"25.12 cm²","correct":true},{"t":"31.4 cm²","mis":"M6-2-u5-X17"},{"t":"18.84 cm²","mis":"M6-2-u5-X17"},{"t":"50.24 cm²","mis":"M6-2-u5-X17"}],"explanation":["볼록한 반원과 패인 반원은 크기가 같아요.","볼록한 반원을 떼어 패인 곳에 옮기면 반지름 4 cm인 반원 하나가 돼요.","4 × 4 × 3.14 ÷ 2 = 25.12 cm²예요."],"variant_rule":{"alt":[{"stem":"지름이 12 cm인 반원이 있어요. 반원의 지름 위 한쪽에는 지름이 6 cm인 반원이 볼록하게 붙어 있고, 다른 쪽은 같은 크기의 반원만큼 패여 있어요. 이 모양의 넓이는 몇 cm²인가요?","options":[{"t":"56.52 cm²","correct":true},{"t":"70.65 cm²","mis":"M6-2-u5-X17"},{"t":"42.39 cm²","mis":"M6-2-u5-X17"},{"t":"113.04 cm²","mis":"M6-2-u5-X17"}],"explanation":["볼록한 반원과 패인 반원은 크기가 같아요.","볼록한 반원을 떼어 패인 곳에 옮기면 반지름 6 cm인 반원 하나가 돼요.","6 × 6 × 3.14 ÷ 2 = 56.52 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L07_basic#9','math',6,2,'u5','L07','tb_g6_2_math_u5_L07_basic','lesson_basic','M6-2-u5-C7',2,'mc','auto','가로 35 cm, 세로 20 cm인 직사각형의 양쪽 세로 변에 반원을 하나씩 붙인 운동장 모양이 있어요. 전체 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X17','M6-2-u5-X13']::text[],true,'{"seq":9,"concept":"M6-2-u5-C7","difficulty":2,"kind":"mc","stem":"가로 35 cm, 세로 20 cm인 직사각형의 양쪽 세로 변에 반원을 하나씩 붙인 운동장 모양이 있어요. 전체 넓이는 몇 cm²인가요?","options":[{"t":"1014 cm²","correct":true},{"t":"857 cm²","mis":"M6-2-u5-X17"},{"t":"1328 cm²","mis":"M6-2-u5-X17"},{"t":"1956 cm²","mis":"M6-2-u5-X13"}],"explanation":["직사각형은 35 × 20 = 700 cm²예요.","양쪽 반원 두 개를 모으면 반지름 10 cm인 원 하나 — 10 × 10 × 3.14 = 314 cm²예요.","700 + 314 = 1014 cm²예요."],"asset":{"type":"geo","items":[{"w":160,"h":80,"pts":{"A":[40,10],"B":[120,10],"C":[120,70],"D":[40,70],"O1":[40,40],"O2":[120,40]},"show":[],"poly":[["A","B","C","D"]],"circle":[["O1",30],["O2",30]],"right":[["B","A","D"],["A","B","C"]]}]},"variant_rule":{"alt":[{"stem":"가로 60 m, 세로 50 m인 직사각형의 양쪽 세로 변에 반원을 하나씩 붙인 운동장 모양이 있어요. 전체 넓이는 몇 m²인가요?","options":[{"t":"4962.5 m²","correct":true},{"t":"3981.25 m²","mis":"M6-2-u5-X17"},{"t":"6925 m²","mis":"M6-2-u5-X17"},{"t":"10850 m²","mis":"M6-2-u5-X13"}],"explanation":["직사각형은 60 × 50 = 3000 m²예요.","양쪽 반원 두 개를 모으면 반지름 25 m인 원 하나 — 25 × 25 × 3.14 = 1962.5 m²예요.","3000 + 1962.5 = 4962.5 m²예요."],"asset":{"type":"geo","items":[{"w":160,"h":80,"pts":{"A":[40,10],"B":[120,10],"C":[120,70],"D":[40,70],"O1":[40,40],"O2":[120,40]},"show":[],"poly":[["A","B","C","D"]],"circle":[["O1",30],["O2",30]],"right":[["B","A","D"],["A","B","C"]]}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L07_basic#10','math',6,2,'u5','L07','tb_g6_2_math_u5_L07_basic','lesson_basic','M6-2-u5-C7',3,'mc','auto','반지름이 12 cm인 큰 원 안에 반지름이 6 cm인 원 두 개가 들어 있어요. 큰 원에서 작은 원 두 개를 뺀 부분의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X17','M6-2-u5-X16','M6-2-u5-X19']::text[],true,'{"seq":10,"concept":"M6-2-u5-C7","difficulty":3,"kind":"mc","stem":"반지름이 12 cm인 큰 원 안에 반지름이 6 cm인 원 두 개가 들어 있어요. 큰 원에서 작은 원 두 개를 뺀 부분의 넓이는 몇 cm²인가요?","options":[{"t":"226.08 cm²","correct":true},{"t":"339.12 cm²","mis":"M6-2-u5-X17"},{"t":"452.16 cm²","mis":"M6-2-u5-X16"},{"t":"113.04 cm²","mis":"M6-2-u5-X19"}],"explanation":["큰 원은 12 × 12 × 3.14 = 452.16 cm²예요.","작은 원 하나는 6 × 6 × 3.14 = 113.04 cm², 두 개는 226.08 cm²예요.","452.16 − 226.08 = 226.08 cm²예요."],"variant_rule":{"alt":[{"stem":"반지름이 10 cm인 큰 원 안에 반지름이 5 cm인 원 두 개가 들어 있어요. 큰 원에서 작은 원 두 개를 뺀 부분의 넓이는 몇 cm²인가요?","options":[{"t":"157 cm²","correct":true},{"t":"235.5 cm²","mis":"M6-2-u5-X17"},{"t":"314 cm²","mis":"M6-2-u5-X16"},{"t":"78.5 cm²","mis":"M6-2-u5-X19"}],"explanation":["큰 원은 10 × 10 × 3.14 = 314 cm²예요.","작은 원 하나는 5 × 5 × 3.14 = 78.5 cm², 두 개는 157 cm²예요.","314 − 157 = 157 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L07_challenge#1','math',6,2,'u5','L07','tb_g6_2_math_u5_L07_challenge','lesson_challenge','M6-2-u5-C7',2,'error','auto','반지름이 4 cm인 원에서 반지름이 1 cm인 원을 뺀 고리 모양의 넓이를 구했어요. 잘못 구한 것은 어느 것인가요?',ARRAY['M6-2-u5-X16','M6-2-u5-X19']::text[],true,'{"seq":1,"concept":"M6-2-u5-C7","difficulty":2,"kind":"error","stem":"반지름이 4 cm인 원에서 반지름이 1 cm인 원을 뺀 고리 모양의 넓이를 구했어요. 잘못 구한 것은 어느 것인가요?","options":[{"t":"㉠ 「4 − 1 = 3이니 3 × 3 × 3.14 = 28.26이야.」","correct":true,"mis_target":"M6-2-u5-X16"},{"t":"㉡ 「50.24 − 3.14 = 47.1이야.」","mis":"M6-2-u5-X19"},{"t":"㉢ 「(4 × 4 − 1 × 1) × 3.14 = 47.1이야.」","mis":"M6-2-u5-X19"},{"t":"㉣ 「넓이는 47.1 cm²야.」","mis":"M6-2-u5-X19"}],"explanation":["고리의 넓이는 큰 원의 넓이에서 작은 원의 넓이를 빼요.","반지름의 차로 원을 그리면 고리와 넓이가 달라요.","바른 넓이는 47.1 cm² — ㉠의 방법이 잘못되었어요."],"variant_rule":{"alt":[{"stem":"반지름이 7 cm인 원에서 반지름이 4 cm인 원을 뺀 고리 모양의 넓이를 구했어요. 잘못 구한 것은 어느 것인가요?","options":[{"t":"㉠ 「7 − 4 = 3이니 3 × 3 × 3.14 = 28.26이야.」","correct":true,"mis_target":"M6-2-u5-X16"},{"t":"㉡ 「153.86 − 50.24 = 103.62야.」","mis":"M6-2-u5-X19"},{"t":"㉢ 「(7 × 7 − 4 × 4) × 3.14 = 103.62야.」","mis":"M6-2-u5-X19"},{"t":"㉣ 「넓이는 103.62 cm²야.」","mis":"M6-2-u5-X19"}],"explanation":["고리의 넓이는 큰 원의 넓이에서 작은 원의 넓이를 빼요.","반지름의 차로 원을 그리면 고리와 넓이가 달라요.","바른 넓이는 103.62 cm² — ㉠의 방법이 잘못되었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L07_challenge#2','math',6,2,'u5','L07','tb_g6_2_math_u5_L07_challenge','lesson_challenge','M6-2-u5-C7',2,'ox','auto','반지름이 4 m인 원과 반지름이 8 m인 사분원은 넓이가 같아요.',ARRAY['M6-2-u5-X17']::text[],true,'{"seq":2,"concept":"M6-2-u5-C7","difficulty":2,"kind":"ox","stem":"반지름이 4 m인 원과 반지름이 8 m인 사분원은 넓이가 같아요.","answer":"O","reason_options":[{"t":"8 × 8 × 3.14 ÷ 4 = 4 × 4 × 3.14이기 때문에","correct":true},{"t":"사분원은 원의 반이기 때문에","mis":"M6-2-u5-X17"}],"mis":"M6-2-u5-X17","explanation":["고리 모양은 큰 원에서 작은 원을 빼요.","반원·사분원은 원의 넓이를 2·4로 나누어요.","자리만 옮기면 넓이는 그대로예요."],"variant_rule":{"alt":[{"stem":"고리 모양의 넓이는 두 반지름의 차를 반지름으로 하는 원의 넓이와 같아요.","answer":"X","reason_options":[{"t":"큰 원의 넓이에서 작은 원의 넓이를 빼야 하기 때문에","correct":true},{"t":"고리의 폭이 반지름의 차이기 때문에","mis":"M6-2-u5-X16"}],"explanation":["고리 모양은 큰 원에서 작은 원을 빼요.","반원·사분원은 원의 넓이를 2·4로 나누어요.","자리만 옮기면 넓이는 그대로예요."]},{"stem":"원을 잘라 다른 자리에 옮겨 붙이면 넓이가 넓어져요.","answer":"X","reason_options":[{"t":"조각을 더하거나 덜지 않고 자리만 옮겼기 때문에","correct":true},{"t":"모양이 바뀌면 넓이도 바뀌기 때문에","mis":"M6-2-u5-X17"}],"explanation":["고리 모양은 큰 원에서 작은 원을 빼요.","반원·사분원은 원의 넓이를 2·4로 나누어요.","자리만 옮기면 넓이는 그대로예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L07_challenge#3','math',6,2,'u5','L07','tb_g6_2_math_u5_L07_challenge','lesson_challenge','M6-2-u5-C7',3,'match','auto','반지름이 2 cm인 도형과 넓이를 이으세요.','{}'::text[],true,'{"seq":3,"concept":"M6-2-u5-C7","difficulty":3,"kind":"match","stem":"반지름이 2 cm인 도형과 넓이를 이으세요.","pairs":[{"l":"원","r":"12.56 cm²"},{"l":"반원","r":"6.28 cm²"},{"l":"사분원","r":"3.14 cm²"}],"mis":"M6-2-u5-X17","explanation":["원의 넓이는 2 × 2 × 3.14 = 12.56 cm²예요.","반원은 그 반 — 6.28 cm²예요.","사분원은 4로 나눈 하나 — 3.14 cm²예요."],"variant_rule":{"alt":[{"stem":"반지름이 4 cm인 도형과 넓이를 이으세요.","pairs":[{"l":"원","r":"50.24 cm²"},{"l":"반원","r":"25.12 cm²"},{"l":"사분원","r":"12.56 cm²"}],"explanation":["원의 넓이는 4 × 4 × 3.14 = 50.24 cm²예요.","반원은 그 반 — 25.12 cm²예요.","사분원은 4로 나눈 하나 — 12.56 cm²예요."]},{"stem":"반지름이 10 cm인 도형과 넓이를 이으세요.","pairs":[{"l":"원","r":"314 cm²"},{"l":"반원","r":"157 cm²"},{"l":"사분원","r":"78.5 cm²"}],"explanation":["원의 넓이는 10 × 10 × 3.14 = 314 cm²예요.","반원은 그 반 — 157 cm²예요.","사분원은 4로 나눈 하나 — 78.5 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L07_challenge#4','math',6,2,'u5','L07','tb_g6_2_math_u5_L07_challenge','lesson_challenge','M6-2-u5-C7',3,'mc','auto','지름이 20 cm인 원 안에 지름이 10 cm인 반원 두 개가 지름 위 양쪽에 하나는 위로, 하나는 아래로 그려져 있어요. 큰 원에서 두 반원을 뺀 부분의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X17','M6-2-u5-X16']::text[],true,'{"seq":4,"concept":"M6-2-u5-C7","difficulty":3,"kind":"mc","stem":"지름이 20 cm인 원 안에 지름이 10 cm인 반원 두 개가 지름 위 양쪽에 하나는 위로, 하나는 아래로 그려져 있어요. 큰 원에서 두 반원을 뺀 부분의 넓이는 몇 cm²인가요?","options":[{"t":"235.5 cm²","correct":true},{"t":"274.75 cm²","mis":"M6-2-u5-X17"},{"t":"157 cm²","mis":"M6-2-u5-X17"},{"t":"314 cm²","mis":"M6-2-u5-X16"}],"explanation":["큰 원은 반지름 10 cm — 10 × 10 × 3.14 = 314 cm²예요.","반원 두 개를 모으면 반지름 5 cm인 원 하나 — 5 × 5 × 3.14 = 78.5 cm²예요.","314 − 78.5 = 235.5 cm²예요."],"variant_rule":{"alt":[{"stem":"한 변이 16 cm인 정사각형 안에 지름이 16 cm인 반원 두 개가 위아래 변에 붙어 마주 보고 있어요. 두 반원의 넓이의 합은 몇 cm²인가요?","options":[{"t":"200.96 cm²","correct":true},{"t":"100.48 cm²","mis":"M6-2-u5-X17"},{"t":"803.84 cm²","mis":"M6-2-u5-X13"},{"t":"55.04 cm²","mis":"M6-2-u5-X17"}],"explanation":["반원 하나는 반지름 8 cm인 원의 반이에요.","반원 두 개를 모으면 원 하나 — 8 × 8 × 3.14 = 200.96 cm²예요.","두 반원의 넓이의 합은 200.96 cm²예요."]},{"stem":"한 변이 10 cm인 정사각형의 오른쪽 변을 지름으로 하는 반원이 정사각형 안쪽으로 그려져 있어요. 정사각형에서 반원을 뺀 부분의 넓이는 몇 cm²인가요?","options":[{"t":"60.75 cm²","correct":true},{"t":"21.5 cm²","mis":"M6-2-u5-X17"},{"t":"39.25 cm²","mis":"M6-2-u5-X17"},{"t":"84.3 cm²","mis":"M6-2-u5-X12"}],"explanation":["정사각형은 10 × 10 = 100 cm²예요.","반원은 반지름 5 cm — 5 × 5 × 3.14 ÷ 2 = 39.25 cm²예요.","100 − 39.25 = 60.75 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L07_challenge#5','math',6,2,'u5','L07','tb_g6_2_math_u5_L07_challenge','lesson_challenge','M6-2-u5-C7',3,'mc','auto','한 변이 8 cm인 정사각형 안에 위쪽 변의 가운데에서 지름 8 cm인 반원 아래로 삼각형이 붙은 모양이 있어요. 삼각형은 밑변이 8 cm, 높이가 4 cm예요. 반원과 삼각형을 합한 모양의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X17','M6-2-u5-X20','M6-2-u5-X13']::text[],false,'{"seq":5,"concept":"M6-2-u5-C7","difficulty":3,"kind":"mc","stem":"한 변이 8 cm인 정사각형 안에 위쪽 변의 가운데에서 지름 8 cm인 반원 아래로 삼각형이 붙은 모양이 있어요. 삼각형은 밑변이 8 cm, 높이가 4 cm예요. 반원과 삼각형을 합한 모양의 넓이는 몇 cm²인가요?","options":[{"t":"41.12 cm²","correct":true},{"t":"66.24 cm²","mis":"M6-2-u5-X17"},{"t":"57.12 cm²","mis":"M6-2-u5-X20"},{"t":"116.48 cm²","mis":"M6-2-u5-X13"}],"explanation":["반원은 반지름 4 cm — 4 × 4 × 3.14 ÷ 2 = 25.12 cm²예요.","삼각형은 8 × 4 ÷ 2 = 16 cm²예요.","25.12 + 16 = 41.12 cm²예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L07_challenge#6','math',6,2,'u5','L07','tb_g6_2_math_u5_L07_challenge','lesson_challenge','M6-2-u5-C7',3,'mc','auto','지름이 30 cm인 큰 원 안에 지름이 20 cm인 원과 지름이 10 cm인 원이 지름 위에 나란히 꼭 맞게 들어 있어요. 큰 원에서 두 원을 뺀 부분의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X17','M6-2-u5-X13']::text[],false,'{"seq":6,"concept":"M6-2-u5-C7","difficulty":3,"kind":"mc","stem":"지름이 30 cm인 큰 원 안에 지름이 20 cm인 원과 지름이 10 cm인 원이 지름 위에 나란히 꼭 맞게 들어 있어요. 큰 원에서 두 원을 뺀 부분의 넓이는 몇 cm²인가요?","options":[{"t":"314 cm²","correct":true},{"t":"392.5 cm²","mis":"M6-2-u5-X17"},{"t":"628 cm²","mis":"M6-2-u5-X17"},{"t":"1256 cm²","mis":"M6-2-u5-X13"}],"explanation":["큰 원은 15 × 15 × 3.14 = 706.5 cm²예요.","두 원은 10 × 10 × 3.14 = 314 cm², 5 × 5 × 3.14 = 78.5 cm²예요.","706.5 − 314 − 78.5 = 314 cm²예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L07_challenge#7','math',6,2,'u5','L07','tb_g6_2_math_u5_L07_challenge','lesson_challenge','M6-2-u5-C7',3,'sa','auto','한 변이 20 cm인 정사각형의 네 꼭짓점을 중심으로 반지름이 10 cm인 사분원을 하나씩 그렸어요. 정사각형에서 사분원 4개를 뺀 가운데 부분의 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":7,"concept":"M6-2-u5-C7","difficulty":3,"kind":"sa","stem":"한 변이 20 cm인 정사각형의 네 꼭짓점을 중심으로 반지름이 10 cm인 사분원을 하나씩 그렸어요. 정사각형에서 사분원 4개를 뺀 가운데 부분의 넓이는 몇 cm²인가요?","answer":["86"],"explanation":["사분원 4개를 모으면 반지름 10 cm인 원 하나예요.","원은 10 × 10 × 3.14 = 314 cm², 정사각형은 20 × 20 = 400 cm²예요.","400 − 314 = 86 cm²예요."],"variant_rule":{"alt":[{"stem":"한 변이 20 cm인 정사각형의 네 꼭짓점을 중심으로 반지름이 10 cm인 사분원을 하나씩 그렸어요. 사분원 4개의 넓이의 합은 몇 cm²인가요?","answer":["314"],"explanation":["사분원은 원을 똑같이 4로 나눈 하나예요.","사분원 4개를 모으면 반지름 10 cm인 원 하나예요.","10 × 10 × 3.14 = 314 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L07_challenge#8','math',6,2,'u5','L07','tb_g6_2_math_u5_L07_challenge','lesson_challenge','M6-2-u5-C7',4,'essay','teacher','중심이 같은 원 두 개가 있어요. 큰 원의 반지름은 10 cm, 작은 원의 반지름은 7 cm예요. 두 원 사이의 고리 모양(라 부분)의 넓이를 반지름의 차 3 cm로 원을 그려 3 × 3 × 3.14로 구한 친구가 있어요. 무엇이 잘못되었는지 쓰고 바르게 구해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M6-2-u5-C7","difficulty":4,"kind":"essay","stem":"중심이 같은 원 두 개가 있어요. 큰 원의 반지름은 10 cm, 작은 원의 반지름은 7 cm예요. 두 원 사이의 고리 모양(라 부분)의 넓이를 반지름의 차 3 cm로 원을 그려 3 × 3 × 3.14로 구한 친구가 있어요. 무엇이 잘못되었는지 쓰고 바르게 구해 보세요.","answer_guide":{"answer":"예: 고리 모양은 반지름이 3 cm인 원과 넓이가 다르다. 큰 원의 넓이에서 작은 원의 넓이를 빼야 하므로 10 × 10 × 3.14 − 7 × 7 × 3.14 = 314 − 153.86 = 160.14 cm²이다.","scoring_points":["반지름의 차로 구한 것이 잘못임을 밝혔는가","큰 원 − 작은 원으로 식을 세웠는가","160.14 cm²를 구했는가"]},"explanation":["고리는 큰 원에서 작은 원을 뺀 모양이에요.","314 − 153.86 = 160.14예요.","라 부분의 넓이는 160.14 cm²예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L07_challenge#9','math',6,2,'u5','L07','tb_g6_2_math_u5_L07_challenge','lesson_challenge','M6-2-u5-C7',4,'essay','teacher','가로 35 cm, 세로 20 cm인 직사각형의 양쪽에 반원을 붙인 모양의 넓이를 구하려고 해요. 넓이를 구하기 쉬운 모양으로 나누어 구하는 과정을 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M6-2-u5-C7","difficulty":4,"kind":"essay","stem":"가로 35 cm, 세로 20 cm인 직사각형의 양쪽에 반원을 붙인 모양의 넓이를 구하려고 해요. 넓이를 구하기 쉬운 모양으로 나누어 구하는 과정을 써 보세요.","answer_guide":{"answer":"예: 직사각형과 양쪽 반원 두 개로 나눈다. 직사각형은 35 × 20 = 700 cm²이다. 반원 두 개를 모으면 지름 20 cm, 반지름 10 cm인 원이 되어 10 × 10 × 3.14 = 314 cm²이다. 따라서 700 + 314 = 1014 cm²이다.","scoring_points":["직사각형 700 cm²를 구했는가","반원 두 개를 원 하나 314 cm²로 모았는가","1014 cm²를 구했는가"]},"explanation":["직사각형은 35 × 20 = 700 cm²예요.","반원 두 개 = 반지름 10 cm인 원 = 314 cm²예요.","700 + 314 = 1014 cm²예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L07_challenge#10','math',6,2,'u5','L07','tb_g6_2_math_u5_L07_challenge','lesson_challenge','M6-2-u5-C7',4,'mc','auto','가로 60 m, 세로 50 m인 직사각형의 양쪽 세로 변에 반원을 하나씩 붙인 학교 운동장 모양이 있어요. 전체 넓이는 몇 m²인가요?',ARRAY['M6-2-u5-X17','M6-2-u5-X13']::text[],true,'{"seq":10,"concept":"M6-2-u5-C7","difficulty":4,"kind":"mc","stem":"가로 60 m, 세로 50 m인 직사각형의 양쪽 세로 변에 반원을 하나씩 붙인 학교 운동장 모양이 있어요. 전체 넓이는 몇 m²인가요?","options":[{"t":"4962.5 m²","correct":true},{"t":"3981.25 m²","mis":"M6-2-u5-X17"},{"t":"6925 m²","mis":"M6-2-u5-X17"},{"t":"10850 m²","mis":"M6-2-u5-X13"}],"explanation":["직사각형은 60 × 50 = 3000 m²예요.","양쪽 반원 두 개를 모으면 반지름 25 m인 원 하나 — 25 × 25 × 3.14 = 1962.5 m²예요.","3000 + 1962.5 = 4962.5 m²예요."],"asset":{"type":"geo","items":[{"w":160,"h":80,"pts":{"A":[40,10],"B":[120,10],"C":[120,70],"D":[40,70],"O1":[40,40],"O2":[120,40]},"show":[],"poly":[["A","B","C","D"]],"circle":[["O1",30],["O2",30]],"right":[["B","A","D"],["A","B","C"]]}]},"variant_rule":{"alt":[{"stem":"가로 35 cm, 세로 20 cm인 직사각형의 양쪽 세로 변에 반원을 하나씩 붙인 운동장 모양이 있어요. 전체 넓이는 몇 cm²인가요?","options":[{"t":"1014 cm²","correct":true},{"t":"857 cm²","mis":"M6-2-u5-X17"},{"t":"1328 cm²","mis":"M6-2-u5-X17"},{"t":"1956 cm²","mis":"M6-2-u5-X13"}],"explanation":["직사각형은 35 × 20 = 700 cm²예요.","양쪽 반원 두 개를 모으면 반지름 10 cm인 원 하나 — 10 × 10 × 3.14 = 314 cm²예요.","700 + 314 = 1014 cm²예요."],"asset":{"type":"geo","items":[{"w":160,"h":80,"pts":{"A":[40,10],"B":[120,10],"C":[120,70],"D":[40,70],"O1":[40,40],"O2":[120,40]},"show":[],"poly":[["A","B","C","D"]],"circle":[["O1",30],["O2",30]],"right":[["B","A","D"],["A","B","C"]]}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L08_basic#1','math',6,2,'u5','L08','tb_g6_2_math_u5_L08_basic','lesson_basic','M6-2-u5-C8',1,'sa','auto','동물 보호소에 작은 동물들을 위한 반지름이 10 cm인 원 모양 방석이 있어요. 이 방석의 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":1,"concept":"M6-2-u5-C8","difficulty":1,"kind":"sa","stem":"동물 보호소에 작은 동물들을 위한 반지름이 10 cm인 원 모양 방석이 있어요. 이 방석의 넓이는 몇 cm²인가요?","answer":["314"],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","10 × 10 × 3.14를 계산해요.","10 × 10 × 3.14 = 314 cm²예요."],"variant_rule":{"alt":[{"stem":"동물 보호소에 더 큰 동물들을 위한 반지름이 20 cm인 원 모양 방석이 있어요. 이 방석의 넓이는 몇 cm²인가요?","answer":["1256"],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","20 × 20 × 3.14를 계산해요.","20 × 20 × 3.14 = 1256 cm²예요."]},{"stem":"동물 보호소에 반지름이 30 cm인 원 모양 방석이 있어요. 이 방석의 넓이는 몇 cm²인가요?","answer":["2826"],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","30 × 30 × 3.14를 계산해요.","30 × 30 × 3.14 = 2826 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L08_basic#2','math',6,2,'u5','L08','tb_g6_2_math_u5_L08_basic','lesson_basic','M6-2-u5-C8',1,'sa','auto','반지름이 10 cm인 방석의 넓이는 314 cm², 반지름이 20 cm인 방석의 넓이는 1256 cm²예요. 반지름이 2배가 되면 넓이는 몇 배가 되나요?','{}'::text[],true,'{"seq":2,"concept":"M6-2-u5-C8","difficulty":1,"kind":"sa","stem":"반지름이 10 cm인 방석의 넓이는 314 cm², 반지름이 20 cm인 방석의 넓이는 1256 cm²예요. 반지름이 2배가 되면 넓이는 몇 배가 되나요?","answer":["4"],"explanation":["1256 ÷ 314 = 4예요.","반지름이 2배가 되니 넓이는 2 × 2 = 4배가 되었어요.","넓이를 구할 때 반지름을 두 번 곱하기 때문이에요."],"variant_rule":{"alt":[{"stem":"반지름이 10 cm인 방석의 넓이는 314 cm², 반지름이 30 cm인 방석의 넓이는 2826 cm²예요. 반지름이 3배가 되면 넓이는 몇 배가 되나요?","answer":["9"],"explanation":["2826 ÷ 314 = 9예요.","반지름이 3배가 되니 넓이는 3 × 3 = 9배가 되었어요.","넓이를 구할 때 반지름을 두 번 곱하기 때문이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L08_basic#3','math',6,2,'u5','L08','tb_g6_2_math_u5_L08_basic','lesson_basic','M6-2-u5-C8',1,'sa','auto','원의 반지름이 2배가 되면 원의 넓이는 몇 배가 되나요?','{}'::text[],true,'{"seq":3,"concept":"M6-2-u5-C8","difficulty":1,"kind":"sa","stem":"원의 반지름이 2배가 되면 원의 넓이는 몇 배가 되나요?","answer":["4"],"explanation":["넓이는 (반지름) × (반지름) × (원주율)이에요.","반지름이 2배면 두 번 곱하는 반지름이 모두 2배예요.","2 × 2 = 4배가 돼요."],"variant_rule":{"alt":[{"stem":"원의 반지름이 3배가 되면 원의 넓이는 몇 배가 되나요?","answer":["9"],"explanation":["넓이는 (반지름) × (반지름) × (원주율)이에요.","반지름이 3배면 두 번 곱하는 반지름이 모두 3배예요.","3 × 3 = 9배가 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L08_basic#4','math',6,2,'u5','L08','tb_g6_2_math_u5_L08_basic','lesson_basic','M6-2-u5-C8',1,'mc','auto','반지름이 24 cm인 원의 넓이는 반지름이 12 cm인 원의 넓이의 몇 배인가요?',ARRAY['M6-2-u5-X18','M6-2-u5-X20']::text[],true,'{"seq":4,"concept":"M6-2-u5-C8","difficulty":1,"kind":"mc","stem":"반지름이 24 cm인 원의 넓이는 반지름이 12 cm인 원의 넓이의 몇 배인가요?","options":[{"t":"4배","correct":true},{"t":"2배","mis":"M6-2-u5-X18"},{"t":"8배","mis":"M6-2-u5-X20"},{"t":"24배","mis":"M6-2-u5-X20"}],"explanation":["반지름이 24 ÷ 12 = 2배예요.","넓이는 반지름을 두 번 곱하니 2 × 2 = 4배예요.","계산해 봐도 1808.64 ÷ 452.16 = 4예요."],"variant_rule":{"alt":[{"stem":"반지름이 36 cm인 원의 넓이는 반지름이 12 cm인 원의 넓이의 몇 배인가요?","options":[{"t":"9배","correct":true},{"t":"3배","mis":"M6-2-u5-X18"},{"t":"6배","mis":"M6-2-u5-X18"},{"t":"27배","mis":"M6-2-u5-X20"}],"explanation":["반지름이 36 ÷ 12 = 3배예요.","넓이는 반지름을 두 번 곱하니 3 × 3 = 9배예요.","계산해 봐도 4069.44 ÷ 452.16 = 9예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L08_basic#5','math',6,2,'u5','L08','tb_g6_2_math_u5_L08_basic','lesson_basic','M6-2-u5-C8',2,'mc','auto','반지름이 2배가 될 때 원의 넓이가 4배가 되는 까닭은 무엇인가요?',ARRAY['M6-2-u5-X18','M6-2-u5-X05','M6-2-u5-X01']::text[],true,'{"seq":5,"concept":"M6-2-u5-C8","difficulty":2,"kind":"mc","stem":"반지름이 2배가 될 때 원의 넓이가 4배가 되는 까닭은 무엇인가요?","options":[{"t":"넓이를 구할 때 반지름을 두 번 곱하므로 2 × 2 = 4배가 되어서","correct":true},{"t":"반지름에 2를 더하기 때문에","mis":"M6-2-u5-X18"},{"t":"원주율이 2배가 되기 때문에","mis":"M6-2-u5-X05"},{"t":"지름이 4배가 되기 때문에","mis":"M6-2-u5-X01"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","반지름이 2배면 곱하는 두 반지름이 모두 2배예요.","그래서 넓이는 2 × 2 = 4배예요."],"variant_rule":{"alt":[{"stem":"반지름이 3배가 될 때 원의 넓이가 9배가 되는 까닭은 무엇인가요?","options":[{"t":"넓이를 구할 때 반지름을 두 번 곱하므로 3 × 3 = 9배가 되어서","correct":true},{"t":"반지름에 3을 더하기 때문에","mis":"M6-2-u5-X18"},{"t":"원주율이 3배가 되기 때문에","mis":"M6-2-u5-X05"},{"t":"지름이 9배가 되기 때문에","mis":"M6-2-u5-X01"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","반지름이 3배면 곱하는 두 반지름이 모두 3배예요.","그래서 넓이는 3 × 3 = 9배예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L08_basic#6','math',6,2,'u5','L08','tb_g6_2_math_u5_L08_basic','lesson_basic','M6-2-u5-C8',2,'error','auto','반지름이 2배일 때 원의 넓이가 4배였어요. 반지름이 3배일 때를 두고 친구들이 말했어요. 잘못 말한 것은 어느 것인가요?',ARRAY['M6-2-u5-X18','M6-2-u5-X19']::text[],true,'{"seq":6,"concept":"M6-2-u5-C8","difficulty":2,"kind":"error","stem":"반지름이 2배일 때 원의 넓이가 4배였어요. 반지름이 3배일 때를 두고 친구들이 말했어요. 잘못 말한 것은 어느 것인가요?","options":[{"t":"㉠ 「2배일 때 4배였으니 3배면 6배일 거야.」","correct":true,"mis_target":"M6-2-u5-X18"},{"t":"㉡ 「반지름을 두 번 곱하니 3 × 3 = 9배야.」","mis":"M6-2-u5-X19"},{"t":"㉢ 「계산해 보면 넓이가 9배로 나와.」","mis":"M6-2-u5-X19"},{"t":"㉣ 「반지름이 몇 배든 그 수를 두 번 곱한 만큼 넓어져.」","mis":"M6-2-u5-X19"}],"explanation":["넓이는 반지름을 두 번 곱해요.","반지름이 3배면 넓이는 3 × 3 = 9배예요.","㉠의 말은 2배씩 늘린다고 생각한 거예요 — 6배가 아니에요."],"variant_rule":{"alt":[{"stem":"반지름이 2배일 때 원의 넓이가 4배였어요. 반지름이 2배일 때를 두고 친구들이 말했어요. 잘못 말한 것은 어느 것인가요?","options":[{"t":"㉠ 「2배일 때 4배였으니 2배면 4배일 거야.」","correct":true,"mis_target":"M6-2-u5-X18"},{"t":"㉡ 「반지름을 두 번 곱하니 2 × 2 = 4배야.」","mis":"M6-2-u5-X19"},{"t":"㉢ 「계산해 보면 넓이가 4배로 나와.」","mis":"M6-2-u5-X19"},{"t":"㉣ 「반지름이 몇 배든 그 수를 두 번 곱한 만큼 넓어져.」","mis":"M6-2-u5-X19"}],"explanation":["넓이는 반지름을 두 번 곱해요.","반지름이 2배면 넓이는 2 × 2 = 4배예요.","㉠의 말은 2배씩 늘린다고 생각한 거예요 — 4배가 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L08_basic#7','math',6,2,'u5','L08','tb_g6_2_math_u5_L08_basic','lesson_basic','M6-2-u5-C8',2,'mc','auto','반지름이 12 cm인 원의 넓이는 452.16 cm²예요. 반지름이 24 cm인 원의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X18','M6-2-u5-X12']::text[],true,'{"seq":7,"concept":"M6-2-u5-C8","difficulty":2,"kind":"mc","stem":"반지름이 12 cm인 원의 넓이는 452.16 cm²예요. 반지름이 24 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"1808.64 cm²","correct":true},{"t":"904.32 cm²","mis":"M6-2-u5-X18"},{"t":"1356.48 cm²","mis":"M6-2-u5-X18"},{"t":"150.72 cm²","mis":"M6-2-u5-X12"}],"explanation":["반지름이 24 ÷ 12 = 2배예요.","넓이는 2 × 2 = 4배 — 452.16 × 4 = 1808.64 cm²예요.","24 × 24 × 3.14 = 1808.64로 계산해도 같아요."],"variant_rule":{"alt":[{"stem":"반지름이 12 cm인 원의 넓이는 452.16 cm²예요. 반지름이 36 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"4069.44 cm²","correct":true},{"t":"1356.48 cm²","mis":"M6-2-u5-X18"},{"t":"2712.96 cm²","mis":"M6-2-u5-X18"},{"t":"226.08 cm²","mis":"M6-2-u5-X12"}],"explanation":["반지름이 36 ÷ 12 = 3배예요.","넓이는 3 × 3 = 9배 — 452.16 × 9 = 4069.44 cm²예요.","36 × 36 × 3.14 = 4069.44로 계산해도 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L08_basic#8','math',6,2,'u5','L08','tb_g6_2_math_u5_L08_basic','lesson_basic','M6-2-u5-C8',2,'mc','auto','원의 반지름이 2배가 되면 원주와 넓이는 각각 몇 배가 되나요?',ARRAY['M6-2-u5-X18']::text[],true,'{"seq":8,"concept":"M6-2-u5-C8","difficulty":2,"kind":"mc","stem":"원의 반지름이 2배가 되면 원주와 넓이는 각각 몇 배가 되나요?","options":[{"t":"원주는 2배, 넓이는 4배","correct":true},{"t":"원주는 2배, 넓이는 2배","mis":"M6-2-u5-X18"},{"t":"원주는 4배, 넓이는 4배","mis":"M6-2-u5-X18"},{"t":"원주는 4배, 넓이는 2배","mis":"M6-2-u5-X18"}],"explanation":["원주는 (지름) × (원주율) — 길이를 한 번 곱해요.","그래서 원주는 2배예요.","넓이는 반지름을 두 번 곱하니 2 × 2 = 4배예요."],"variant_rule":{"alt":[{"stem":"원의 반지름이 3배가 되면 원주와 넓이는 각각 몇 배가 되나요?","options":[{"t":"원주는 3배, 넓이는 9배","correct":true},{"t":"원주는 3배, 넓이는 3배","mis":"M6-2-u5-X18"},{"t":"원주는 9배, 넓이는 9배","mis":"M6-2-u5-X18"},{"t":"원주는 9배, 넓이는 3배","mis":"M6-2-u5-X18"}],"explanation":["원주는 (지름) × (원주율) — 길이를 한 번 곱해요.","그래서 원주는 3배예요.","넓이는 반지름을 두 번 곱하니 3 × 3 = 9배예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L08_basic#9','math',6,2,'u5','L08','tb_g6_2_math_u5_L08_basic','lesson_basic','M6-2-u5-C8',2,'sa','auto','원의 넓이가 9배가 되었어요. 반지름은 몇 배가 되었나요?','{}'::text[],true,'{"seq":9,"concept":"M6-2-u5-C8","difficulty":2,"kind":"sa","stem":"원의 넓이가 9배가 되었어요. 반지름은 몇 배가 되었나요?","answer":["3"],"explanation":["반지름이 □배면 넓이는 □ × □배예요.","□ × □ = 9인 수를 찾아요.","3 × 3 = 9 — 반지름은 3배예요."],"variant_rule":{"alt":[{"stem":"원의 넓이가 4배가 되었어요. 반지름은 몇 배가 되었나요?","answer":["2"],"explanation":["반지름이 □배면 넓이는 □ × □배예요.","□ × □ = 4인 수를 찾아요.","2 × 2 = 4 — 반지름은 2배예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L08_basic#10','math',6,2,'u5','L08','tb_g6_2_math_u5_L08_basic','lesson_basic','M6-2-u5-C8',3,'mc','auto','반지름이 30 cm인 큰 방석 한 개를 만드는 천으로, 반지름이 10 cm인 작은 방석을 몇 개 만들 수 있을까요? (자투리 없이 쓴다고 생각해요.)',ARRAY['M6-2-u5-X18','M6-2-u5-X20']::text[],true,'{"seq":10,"concept":"M6-2-u5-C8","difficulty":3,"kind":"mc","stem":"반지름이 30 cm인 큰 방석 한 개를 만드는 천으로, 반지름이 10 cm인 작은 방석을 몇 개 만들 수 있을까요? (자투리 없이 쓴다고 생각해요.)","options":[{"t":"9개","correct":true},{"t":"3개","mis":"M6-2-u5-X18"},{"t":"6개","mis":"M6-2-u5-X18"},{"t":"18개","mis":"M6-2-u5-X20"}],"explanation":["반지름이 3배인 방석이에요.","넓이는 3 × 3 = 9배예요.","그래서 작은 방석 9개를 만들 수 있어요."],"variant_rule":{"alt":[{"stem":"반지름이 20 cm인 큰 방석 한 개를 만드는 천으로, 반지름이 10 cm인 작은 방석을 몇 개 만들 수 있을까요? (자투리 없이 쓴다고 생각해요.)","options":[{"t":"4개","correct":true},{"t":"2개","mis":"M6-2-u5-X18"},{"t":"8개","mis":"M6-2-u5-X20"},{"t":"6개","mis":"M6-2-u5-X18"}],"explanation":["반지름이 2배인 방석이에요.","넓이는 2 × 2 = 4배예요.","그래서 작은 방석 4개를 만들 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L08_challenge#1','math',6,2,'u5','L08','tb_g6_2_math_u5_L08_challenge','lesson_challenge','M6-2-u5-C8',2,'ox','auto','반지름이 3배가 되면 원주는 9배가 돼요.',ARRAY['M6-2-u5-X18']::text[],true,'{"seq":1,"concept":"M6-2-u5-C8","difficulty":2,"kind":"ox","stem":"반지름이 3배가 되면 원주는 9배가 돼요.","answer":"X","reason_options":[{"t":"원주는 길이를 한 번 곱하므로 3배가 되기 때문에","correct":true},{"t":"넓이처럼 원주도 3 × 3배가 되기 때문에","mis":"M6-2-u5-X18"}],"mis":"M6-2-u5-X18","explanation":["원주는 (지름) × (원주율) — 길이를 한 번 곱해요.","넓이는 (반지름) × (반지름) × (원주율) — 두 번 곱해요.","그래서 반지름이 □배면 원주는 □배, 넓이는 □ × □배예요."],"variant_rule":{"alt":[{"stem":"반지름이 2배가 되면 원의 넓이는 4배가 돼요.","answer":"O","reason_options":[{"t":"넓이를 구할 때 반지름을 두 번 곱하기 때문에","correct":true},{"t":"반지름에 2를 두 번 더하기 때문에","mis":"M6-2-u5-X18"}],"explanation":["원주는 (지름) × (원주율) — 길이를 한 번 곱해요.","넓이는 (반지름) × (반지름) × (원주율) — 두 번 곱해요.","그래서 반지름이 □배면 원주는 □배, 넓이는 □ × □배예요."]},{"stem":"지름이 2배가 되면 원의 넓이도 2배가 돼요.","answer":"X","reason_options":[{"t":"지름이 2배면 반지름도 2배라 넓이는 2 × 2 = 4배이기 때문에","correct":true},{"t":"지름과 넓이는 같은 배수로 늘기 때문에","mis":"M6-2-u5-X18"}],"explanation":["원주는 (지름) × (원주율) — 길이를 한 번 곱해요.","넓이는 (반지름) × (반지름) × (원주율) — 두 번 곱해요.","그래서 반지름이 □배면 원주는 □배, 넓이는 □ × □배예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L08_challenge#2','math',6,2,'u5','L08','tb_g6_2_math_u5_L08_challenge','lesson_challenge','M6-2-u5-C8',2,'mc','auto','원의 지름이 2배가 되면 원의 넓이는 몇 배가 되나요?',ARRAY['M6-2-u5-X18','M6-2-u5-X01','M6-2-u5-X20']::text[],true,'{"seq":2,"concept":"M6-2-u5-C8","difficulty":2,"kind":"mc","stem":"원의 지름이 2배가 되면 원의 넓이는 몇 배가 되나요?","options":[{"t":"4배","correct":true},{"t":"2배","mis":"M6-2-u5-X18"},{"t":"16배","mis":"M6-2-u5-X01"},{"t":"8배","mis":"M6-2-u5-X20"}],"explanation":["지름이 2배면 반지름도 2배예요.","넓이는 반지름을 두 번 곱해요.","2 × 2 = 4배예요."],"variant_rule":{"alt":[{"stem":"원의 지름이 3배가 되면 원의 넓이는 몇 배가 되나요?","options":[{"t":"9배","correct":true},{"t":"3배","mis":"M6-2-u5-X18"},{"t":"6배","mis":"M6-2-u5-X18"},{"t":"36배","mis":"M6-2-u5-X01"}],"explanation":["지름이 3배면 반지름도 3배예요.","넓이는 반지름을 두 번 곱해요.","3 × 3 = 9배예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L08_challenge#3','math',6,2,'u5','L08','tb_g6_2_math_u5_L08_challenge','lesson_challenge','M6-2-u5-C8',3,'match','auto','반지름이 늘어난 배수와 넓이가 늘어난 배수를 이으세요.','{}'::text[],true,'{"seq":3,"concept":"M6-2-u5-C8","difficulty":3,"kind":"match","stem":"반지름이 늘어난 배수와 넓이가 늘어난 배수를 이으세요.","pairs":[{"l":"반지름 2배","r":"넓이 4배"},{"l":"반지름 3배","r":"넓이 9배"},{"l":"반지름 4배","r":"넓이 16배"}],"mis":"M6-2-u5-X18","explanation":["넓이는 반지름을 두 번 곱해요.","반지름이 □배면 넓이는 □ × □배예요.","2 × 2 = 4 · 3 × 3 = 9 · 4 × 4 = 16이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 반지름이 늘어난 배수와 넓이가 늘어난 배수를 이으세요.","pairs":[{"l":"반지름 3배","r":"넓이 9배"},{"l":"반지름 5배","r":"넓이 25배"},{"l":"반지름 6배","r":"넓이 36배"}],"explanation":["넓이는 반지름을 두 번 곱해요.","반지름이 □배면 넓이는 □ × □배예요.","3 × 3 = 9 · 5 × 5 = 25 · 6 × 6 = 36이에요."]},{"stem":"이번에는 다른 보기예요. 반지름이 늘어난 배수와 넓이가 늘어난 배수를 이으세요.","pairs":[{"l":"반지름 2배","r":"넓이 4배"},{"l":"반지름 4배","r":"넓이 16배"},{"l":"반지름 10배","r":"넓이 100배"}],"explanation":["넓이는 반지름을 두 번 곱해요.","반지름이 □배면 넓이는 □ × □배예요.","2 × 2 = 4 · 4 × 4 = 16 · 10 × 10 = 100이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L08_challenge#4','math',6,2,'u5','L08','tb_g6_2_math_u5_L08_challenge','lesson_challenge','M6-2-u5-C8',3,'mc','auto','반지름이 10 cm인 방석과 반지름이 20 cm인 방석이 있어요. 큰 방석은 작은 방석보다 몇 cm² 더 넓은가요?',ARRAY['M6-2-u5-X18','M6-2-u5-X19','M6-2-u5-X20']::text[],true,'{"seq":4,"concept":"M6-2-u5-C8","difficulty":3,"kind":"mc","stem":"반지름이 10 cm인 방석과 반지름이 20 cm인 방석이 있어요. 큰 방석은 작은 방석보다 몇 cm² 더 넓은가요?","options":[{"t":"942 cm²","correct":true},{"t":"314 cm²","mis":"M6-2-u5-X18"},{"t":"1256 cm²","mis":"M6-2-u5-X19"},{"t":"1570 cm²","mis":"M6-2-u5-X20"}],"explanation":["작은 방석은 10 × 10 × 3.14 = 314 cm²예요.","큰 방석은 반지름이 2배라 넓이가 4배 — 1256 cm²예요.","1256 − 314 = 942 cm²예요."],"variant_rule":{"alt":[{"stem":"반지름이 10 cm인 방석과 반지름이 30 cm인 방석이 있어요. 큰 방석은 작은 방석보다 몇 cm² 더 넓은가요?","options":[{"t":"2512 cm²","correct":true},{"t":"628 cm²","mis":"M6-2-u5-X18"},{"t":"1256 cm²","mis":"M6-2-u5-X16"},{"t":"2826 cm²","mis":"M6-2-u5-X19"}],"explanation":["작은 방석은 10 × 10 × 3.14 = 314 cm²예요.","큰 방석은 반지름이 3배라 넓이가 9배 — 2826 cm²예요.","2826 − 314 = 2512 cm²예요."]},{"stem":"반지름이 12 cm인 방석과 반지름이 24 cm인 방석이 있어요. 큰 방석은 작은 방석보다 몇 cm² 더 넓은가요?","options":[{"t":"1356.48 cm²","correct":true},{"t":"452.16 cm²","mis":"M6-2-u5-X18"},{"t":"1808.64 cm²","mis":"M6-2-u5-X19"},{"t":"2260.8 cm²","mis":"M6-2-u5-X20"}],"explanation":["작은 방석은 12 × 12 × 3.14 = 452.16 cm²예요.","큰 방석은 반지름이 2배라 넓이가 4배 — 1808.64 cm²예요.","1808.64 − 452.16 = 1356.48 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L08_challenge#5','math',6,2,'u5','L08','tb_g6_2_math_u5_L08_challenge','lesson_challenge','M6-2-u5-C8',3,'sa','auto','반지름이 10 cm인 원 모양 방석보다 넓이가 4배인 원 모양 방석을 만들려고 해요. 새 방석의 반지름은 몇 cm로 하면 되나요?','{}'::text[],true,'{"seq":5,"concept":"M6-2-u5-C8","difficulty":3,"kind":"sa","stem":"반지름이 10 cm인 원 모양 방석보다 넓이가 4배인 원 모양 방석을 만들려고 해요. 새 방석의 반지름은 몇 cm로 하면 되나요?","answer":["20"],"explanation":["넓이가 4배가 되려면 반지름은 □ × □ = 4인 □배예요.","□ = 2예요.","10 × 2 = 20 — 반지름을 20 cm로 해요."],"variant_rule":{"alt":[{"stem":"반지름이 10 cm인 원 모양 방석보다 넓이가 9배인 원 모양 방석을 만들려고 해요. 새 방석의 반지름은 몇 cm로 하면 되나요?","answer":["30"],"explanation":["넓이가 9배가 되려면 반지름은 □ × □ = 9인 □배예요.","□ = 3이에요.","10 × 3 = 30 — 반지름을 30 cm로 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L08_challenge#6','math',6,2,'u5','L08','tb_g6_2_math_u5_L08_challenge','lesson_challenge','M6-2-u5-C8',3,'mc','auto','반지름이 9 cm인 원의 넓이는 반지름이 3 cm인 원의 넓이의 몇 배인가요?',ARRAY['M6-2-u5-X18','M6-2-u5-X20']::text[],true,'{"seq":6,"concept":"M6-2-u5-C8","difficulty":3,"kind":"mc","stem":"반지름이 9 cm인 원의 넓이는 반지름이 3 cm인 원의 넓이의 몇 배인가요?","options":[{"t":"9배","correct":true},{"t":"3배","mis":"M6-2-u5-X18"},{"t":"6배","mis":"M6-2-u5-X18"},{"t":"27배","mis":"M6-2-u5-X20"}],"explanation":["반지름이 9 ÷ 3 = 3배예요.","넓이는 반지름을 두 번 곱하니 3 × 3 = 9배예요.","계산해 봐도 254.34 ÷ 28.26 = 9예요."],"variant_rule":{"alt":[{"stem":"반지름이 30 cm인 원의 넓이는 반지름이 10 cm인 원의 넓이의 몇 배인가요?","options":[{"t":"9배","correct":true},{"t":"3배","mis":"M6-2-u5-X18"},{"t":"6배","mis":"M6-2-u5-X18"},{"t":"27배","mis":"M6-2-u5-X20"}],"explanation":["반지름이 30 ÷ 10 = 3배예요.","넓이는 반지름을 두 번 곱하니 3 × 3 = 9배예요.","계산해 봐도 2826 ÷ 314 = 9예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L08_challenge#7','math',6,2,'u5','L08','tb_g6_2_math_u5_L08_challenge','lesson_challenge','M6-2-u5-C8',3,'sa','auto','원의 넓이가 16배가 되었어요. 반지름은 몇 배가 되었나요?','{}'::text[],true,'{"seq":7,"concept":"M6-2-u5-C8","difficulty":3,"kind":"sa","stem":"원의 넓이가 16배가 되었어요. 반지름은 몇 배가 되었나요?","answer":["4"],"explanation":["반지름이 □배면 넓이는 □ × □배예요.","□ × □ = 16인 수를 찾아요.","4 × 4 = 16 — 반지름은 4배예요."],"variant_rule":{"alt":[{"stem":"원의 넓이가 25배가 되었어요. 반지름은 몇 배가 되었나요?","answer":["5"],"explanation":["반지름이 □배면 넓이는 □ × □배예요.","□ × □ = 25인 수를 찾아요.","5 × 5 = 25 — 반지름은 5배예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L08_challenge#8','math',6,2,'u5','L08','tb_g6_2_math_u5_L08_challenge','lesson_challenge','M6-2-u5-C8',4,'essay','teacher','반지름이 10 cm인 방석의 넓이는 314 cm², 반지름이 20 cm인 방석의 넓이는 1256 cm²예요. 어떤 친구가 「반지름이 2배일 때 넓이가 4배였으니 반지름이 3배면 6배일 거야.」라고 예상했어요. 반지름이 30 cm인 방석의 넓이를 구해 예상이 맞는지 확인하고 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M6-2-u5-C8","difficulty":4,"kind":"essay","stem":"반지름이 10 cm인 방석의 넓이는 314 cm², 반지름이 20 cm인 방석의 넓이는 1256 cm²예요. 어떤 친구가 「반지름이 2배일 때 넓이가 4배였으니 반지름이 3배면 6배일 거야.」라고 예상했어요. 반지름이 30 cm인 방석의 넓이를 구해 예상이 맞는지 확인하고 설명해 보세요.","answer_guide":{"answer":"예: 반지름이 30 cm인 방석의 넓이는 30 × 30 × 3.14 = 2826 cm²이고 2826 ÷ 314 = 9이므로 6배가 아니라 9배이다. 넓이를 구할 때 반지름을 두 번 곱하므로 반지름이 3배면 넓이는 3 × 3 = 9배가 된다.","scoring_points":["2826 cm²를 구했는가","9배임을 보여 예상이 틀렸다고 썼는가","반지름을 두 번 곱하는 까닭을 썼는가"]},"explanation":["30 × 30 × 3.14 = 2826 cm²예요.","2826 ÷ 314 = 9 — 9배예요.","반지름을 두 번 곱하니 3 × 3 = 9배예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L08_challenge#9','math',6,2,'u5','L08','tb_g6_2_math_u5_L08_challenge','lesson_challenge','M6-2-u5-C8',4,'essay','teacher','반지름이 12 cm인 원의 넓이는 452.16 cm²예요. 반지름이 각각 24 cm, 36 cm인 원의 넓이를 구하고, 반지름이 12 cm인 원의 넓이와 비교하여 알게 된 점을 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M6-2-u5-C8","difficulty":4,"kind":"essay","stem":"반지름이 12 cm인 원의 넓이는 452.16 cm²예요. 반지름이 각각 24 cm, 36 cm인 원의 넓이를 구하고, 반지름이 12 cm인 원의 넓이와 비교하여 알게 된 점을 써 보세요.","answer_guide":{"answer":"예: 24 × 24 × 3.14 = 1808.64 cm²이고 1808.64 ÷ 452.16 = 4, 36 × 36 × 3.14 = 4069.44 cm²이고 4069.44 ÷ 452.16 = 9이다. 반지름이 2배, 3배가 되면 원의 넓이는 4배, 9배가 된다.","scoring_points":["1808.64 cm²와 4배를 구했는가","4069.44 cm²와 9배를 구했는가","반지름이 2배·3배면 넓이가 4배·9배라고 썼는가"]},"explanation":["1808.64 ÷ 452.16 = 4예요.","4069.44 ÷ 452.16 = 9예요.","반지름 2배·3배 → 넓이 4배·9배예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_L08_challenge#10','math',6,2,'u5','L08','tb_g6_2_math_u5_L08_challenge','lesson_challenge','M6-2-u5-C8',4,'mc','auto','반지름이 10 cm, 20 cm, 30 cm인 원 모양 방석의 넓이는 314 cm², 1256 cm², 2826 cm²예요. 세 방석의 넓이의 비를 가장 간단한 자연수의 비로 나타낸 것은 어느 것인가요?',ARRAY['M6-2-u5-X18']::text[],false,'{"seq":10,"concept":"M6-2-u5-C8","difficulty":4,"kind":"mc","stem":"반지름이 10 cm, 20 cm, 30 cm인 원 모양 방석의 넓이는 314 cm², 1256 cm², 2826 cm²예요. 세 방석의 넓이의 비를 가장 간단한 자연수의 비로 나타낸 것은 어느 것인가요?","options":[{"t":"1 : 4 : 9","correct":true},{"t":"1 : 2 : 3","mis":"M6-2-u5-X18"},{"t":"1 : 3 : 6","mis":"M6-2-u5-X18"},{"t":"1 : 4 : 6","mis":"M6-2-u5-X18"}],"explanation":["1256 ÷ 314 = 4, 2826 ÷ 314 = 9예요.","세 넓이를 모두 314로 나누면 1 : 4 : 9예요.","반지름의 비 1 : 2 : 3을 두 번 곱한 1 × 1 : 2 × 2 : 3 × 3이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_a#1','math',6,2,'u5','','tb_g6_2_math_u5_review_a','unit_review','M6-2-u5-C1',1,'mc','auto','원주, 원주율 중에서 알맞은 말을 골라요. 원의 둘레를 ( ㉠ )(이)라고 하고, 원의 지름에 대한 원주의 비율을 ( ㉡ )(이)라고 해요. ㉠과 ㉡을 차례로 쓴 것은 어느 것인가요?',ARRAY['M6-2-u5-X04','M6-2-u5-X02']::text[],true,'{"seq":1,"concept":"M6-2-u5-C1","difficulty":1,"kind":"mc","stem":"원주, 원주율 중에서 알맞은 말을 골라요. 원의 둘레를 ( ㉠ )(이)라고 하고, 원의 지름에 대한 원주의 비율을 ( ㉡ )(이)라고 해요. ㉠과 ㉡을 차례로 쓴 것은 어느 것인가요?","options":[{"t":"원주, 원주율","correct":true},{"t":"원주율, 원주","mis":"M6-2-u5-X04"},{"t":"원주, 원주","mis":"M6-2-u5-X02"},{"t":"원주율, 원주율","mis":"M6-2-u5-X02"}],"explanation":["원의 둘레를 원주라고 해요.","원의 지름에 대한 원주의 비율을 원주율이라고 해요.","㉠ 원주, ㉡ 원주율이에요."],"variant_rule":{"alt":[{"stem":"원의 지름에 대한 원주의 비율을 무엇이라고 하나요?","options":[{"t":"원주율","correct":true},{"t":"원주","mis":"M6-2-u5-X02"},{"t":"반지름","mis":"M6-2-u5-X01"},{"t":"지름","mis":"M6-2-u5-X01"}],"explanation":["원의 둘레가 원주예요.","모든 원에서 지름에 대한 원주의 비율은 일정해요.","그 비율을 원주율이라고 해요."]},{"stem":"(원주율) = ( □ ) ÷ (지름)에서 □에 알맞은 말은 어느 것인가요?","options":[{"t":"원주","correct":true},{"t":"반지름","mis":"M6-2-u5-X04"},{"t":"원주율","mis":"M6-2-u5-X02"},{"t":"원의 넓이","mis":"M6-2-u5-X12"}],"explanation":["원주율은 원의 지름에 대한 원주의 비율이에요.","비교하는 양이 원주, 기준량이 지름이에요.","그래서 (원주율) = (원주) ÷ (지름)이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_a#2','math',6,2,'u5','','tb_g6_2_math_u5_review_a','unit_review','M6-2-u5-C3',1,'mc','auto','지름이 6 cm인 원의 원주는 몇 cm인가요?',ARRAY['M6-2-u5-X01','M6-2-u5-X12']::text[],true,'{"seq":2,"concept":"M6-2-u5-C3","difficulty":1,"kind":"mc","stem":"지름이 6 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"18.84 cm","correct":true},{"t":"9.42 cm","mis":"M6-2-u5-X01"},{"t":"37.68 cm","mis":"M6-2-u5-X01"},{"t":"28.26 cm","mis":"M6-2-u5-X12"}],"explanation":["(원주) = (지름) × (원주율)이에요.","6 × 3.14를 계산해요.","6 × 3.14 = 18.84 — 원주는 18.84 cm예요."],"variant_rule":{"alt":[{"stem":"지름이 14 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"43.96 cm","correct":true},{"t":"21.98 cm","mis":"M6-2-u5-X01"},{"t":"87.92 cm","mis":"M6-2-u5-X01"},{"t":"153.86 cm","mis":"M6-2-u5-X12"}],"explanation":["(원주) = (지름) × (원주율)이에요.","14 × 3.14를 계산해요.","14 × 3.14 = 43.96 — 원주는 43.96 cm예요."]},{"stem":"지름이 7 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"21.98 cm","correct":true},{"t":"10.99 cm","mis":"M6-2-u5-X01"},{"t":"43.96 cm","mis":"M6-2-u5-X01"},{"t":"38.465 cm","mis":"M6-2-u5-X12"}],"explanation":["(원주) = (지름) × (원주율)이에요.","7 × 3.14를 계산해요.","7 × 3.14 = 21.98 — 원주는 21.98 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_a#3','math',6,2,'u5','','tb_g6_2_math_u5_review_a','unit_review','M6-2-u5-C3',1,'mc','auto','반지름이 5.5 cm인 원의 원주는 몇 cm인가요?',ARRAY['M6-2-u5-X07','M6-2-u5-X12','M6-2-u5-X01']::text[],true,'{"seq":3,"concept":"M6-2-u5-C3","difficulty":1,"kind":"mc","stem":"반지름이 5.5 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"34.54 cm","correct":true},{"t":"17.27 cm","mis":"M6-2-u5-X07"},{"t":"94.985 cm","mis":"M6-2-u5-X12"},{"t":"69.08 cm","mis":"M6-2-u5-X01"}],"explanation":["반지름에 바로 원주율을 곱하면 안 돼요.","반지름 5.5 cm에 2를 곱해 지름 11 cm를 먼저 만들어요.","11 × 3.14 = 34.54 — 원주는 34.54 cm예요."],"variant_rule":{"alt":[{"stem":"반지름이 9 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"56.52 cm","correct":true},{"t":"28.26 cm","mis":"M6-2-u5-X07"},{"t":"254.34 cm","mis":"M6-2-u5-X12"},{"t":"113.04 cm","mis":"M6-2-u5-X01"}],"explanation":["반지름에 바로 원주율을 곱하면 안 돼요.","반지름 9 cm에 2를 곱해 지름 18 cm를 먼저 만들어요.","18 × 3.14 = 56.52 — 원주는 56.52 cm예요."]},{"stem":"반지름이 6 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"37.68 cm","correct":true},{"t":"18.84 cm","mis":"M6-2-u5-X07"},{"t":"113.04 cm","mis":"M6-2-u5-X12"},{"t":"75.36 cm","mis":"M6-2-u5-X01"}],"explanation":["반지름에 바로 원주율을 곱하면 안 돼요.","반지름 6 cm에 2를 곱해 지름 12 cm를 먼저 만들어요.","12 × 3.14 = 37.68 — 원주는 37.68 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_a#4','math',6,2,'u5','','tb_g6_2_math_u5_review_a','unit_review','M6-2-u5-C6',1,'mc','auto','반지름이 11 cm인 원의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X12','M6-2-u5-X14','M6-2-u5-X13']::text[],true,'{"seq":4,"concept":"M6-2-u5-C6","difficulty":1,"kind":"mc","stem":"반지름이 11 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"379.94 cm²","correct":true},{"t":"69.08 cm²","mis":"M6-2-u5-X12"},{"t":"34.54 cm²","mis":"M6-2-u5-X14"},{"t":"1519.76 cm²","mis":"M6-2-u5-X13"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","11 × 11 × 3.14를 계산해요.","11 × 11 × 3.14 = 379.94 — 넓이는 379.94 cm²예요."],"variant_rule":{"alt":[{"stem":"반지름이 5 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"78.5 cm²","correct":true},{"t":"31.4 cm²","mis":"M6-2-u5-X12"},{"t":"15.7 cm²","mis":"M6-2-u5-X14"},{"t":"314 cm²","mis":"M6-2-u5-X13"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","5 × 5 × 3.14를 계산해요.","5 × 5 × 3.14 = 78.5 — 넓이는 78.5 cm²예요."]},{"stem":"반지름이 3 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"28.26 cm²","correct":true},{"t":"18.84 cm²","mis":"M6-2-u5-X12"},{"t":"9.42 cm²","mis":"M6-2-u5-X14"},{"t":"113.04 cm²","mis":"M6-2-u5-X13"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","3 × 3 × 3.14를 계산해요.","3 × 3 × 3.14 = 28.26 — 넓이는 28.26 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_a#5','math',6,2,'u5','','tb_g6_2_math_u5_review_a','unit_review','M6-2-u5-C6',1,'mc','auto','지름이 8 cm인 원의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X13','M6-2-u5-X12','M6-2-u5-X14']::text[],true,'{"seq":5,"concept":"M6-2-u5-C6","difficulty":1,"kind":"mc","stem":"지름이 8 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"50.24 cm²","correct":true},{"t":"200.96 cm²","mis":"M6-2-u5-X13"},{"t":"25.12 cm²","mis":"M6-2-u5-X12"},{"t":"12.56 cm²","mis":"M6-2-u5-X14"}],"explanation":["넓이는 반지름으로 구해요 — 반지름은 8 ÷ 2 = 4 cm예요.","4 × 4 × 3.14를 계산해요.","4 × 4 × 3.14 = 50.24 — 넓이는 50.24 cm²예요."],"variant_rule":{"alt":[{"stem":"지름이 20 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"314 cm²","correct":true},{"t":"1256 cm²","mis":"M6-2-u5-X13"},{"t":"62.8 cm²","mis":"M6-2-u5-X12"},{"t":"31.4 cm²","mis":"M6-2-u5-X14"}],"explanation":["넓이는 반지름으로 구해요 — 반지름은 20 ÷ 2 = 10 cm예요.","10 × 10 × 3.14를 계산해요.","10 × 10 × 3.14 = 314 — 넓이는 314 cm²예요."]},{"stem":"지름이 12 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"113.04 cm²","correct":true},{"t":"452.16 cm²","mis":"M6-2-u5-X13"},{"t":"37.68 cm²","mis":"M6-2-u5-X12"},{"t":"18.84 cm²","mis":"M6-2-u5-X14"}],"explanation":["넓이는 반지름으로 구해요 — 반지름은 12 ÷ 2 = 6 cm예요.","6 × 6 × 3.14를 계산해요.","6 × 6 × 3.14 = 113.04 — 넓이는 113.04 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_a#6','math',6,2,'u5','','tb_g6_2_math_u5_review_a','unit_review','M6-2-u5-C4',1,'sa','auto','길이가 78.5 cm인 종이띠를 겹치지 않게 붙여 원을 만들었어요. 만든 원의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":6,"concept":"M6-2-u5-C4","difficulty":1,"kind":"sa","stem":"길이가 78.5 cm인 종이띠를 겹치지 않게 붙여 원을 만들었어요. 만든 원의 지름은 몇 cm인가요?","answer":["25"],"explanation":["(지름) = (원주) ÷ (원주율)이에요.","78.5 ÷ 3.14를 계산해요.","78.5 ÷ 3.14 = 25예요."],"variant_rule":{"alt":[{"stem":"원 모양 호수의 둘레가 157 m예요. 호수의 중심을 지나는 다리의 길이는 몇 m인가요?","answer":["50"],"explanation":["(지름) = (원주) ÷ (원주율)이에요.","157 ÷ 3.14를 계산해요.","157 ÷ 3.14 = 50이에요."]},{"stem":"원 모양 접시의 원주를 재었더니 31.4 cm였어요. 이 접시의 지름은 몇 cm인가요?","answer":["10"],"explanation":["(지름) = (원주) ÷ (원주율)이에요.","31.4 ÷ 3.14를 계산해요.","31.4 ÷ 3.14 = 10이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_a#7','math',6,2,'u5','','tb_g6_2_math_u5_review_a','unit_review','M6-2-u5-C2',1,'mc','auto','원주율에 대한 설명으로 잘못된 문장은 어느 것인가요?',ARRAY['M6-2-u5-X19']::text[],true,'{"seq":7,"concept":"M6-2-u5-C2","difficulty":1,"kind":"mc","stem":"원주율에 대한 설명으로 잘못된 문장은 어느 것인가요?","options":[{"t":"원이 커지면 원주율도 커집니다.","correct":true},{"t":"지름이 길어지면 원주도 길어집니다.","mis":"M6-2-u5-X19"},{"t":"원주는 지름의 약 3.14배입니다.","mis":"M6-2-u5-X19"},{"t":"원주율을 소수로 나타내면 끝없이 계속됩니다.","mis":"M6-2-u5-X19"}],"explanation":["보기를 하나씩 원주율의 뜻과 견주어 봐요.","원이 커져도 원주와 지름이 함께 늘어 원주율은 그대로예요.","나머지 세 문장은 모두 바른 설명이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 원주율에 대한 설명으로 잘못된 문장은 어느 것인가요?","options":[{"t":"원주에 대한 원의 지름의 비율을 원주율이라고 합니다.","correct":true},{"t":"원의 크기가 달라져도 원주율은 일정합니다.","mis":"M6-2-u5-X19"},{"t":"반지름이 길어지면 원주도 길어집니다.","mis":"M6-2-u5-X19"},{"t":"원주율을 소수로 나타내면 끝없이 계속됩니다.","mis":"M6-2-u5-X19"}],"explanation":["보기를 하나씩 원주율의 뜻과 견주어 봐요.","원주율은 지름에 대한 원주의 비율 — 기준량이 지름이에요.","나머지 세 문장은 모두 바른 설명이에요."]},{"stem":"이번에는 다른 보기예요. 원주율에 대한 설명으로 잘못된 문장은 어느 것인가요?","options":[{"t":"원주율은 정확히 3.14입니다.","correct":true},{"t":"원주율은 원의 크기와 상관없이 일정합니다.","mis":"M6-2-u5-X19"},{"t":"원주율은 (원주) ÷ (지름)으로 구합니다.","mis":"M6-2-u5-X19"},{"t":"원주는 지름의 3배보다 길고 4배보다 짧습니다.","mis":"M6-2-u5-X19"}],"explanation":["보기를 하나씩 원주율의 뜻과 견주어 봐요.","3.14는 끝없이 이어지는 원주율을 어림한 값이에요.","나머지 세 문장은 모두 바른 설명이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_a#8','math',6,2,'u5','','tb_g6_2_math_u5_review_a','unit_review','M6-2-u5-C2',1,'mc','auto','지름이 10 cm인 원의 원주는 31.4 cm예요. 원주는 지름의 약 몇 배인가요?',ARRAY['M6-2-u5-X04','M6-2-u5-X02']::text[],true,'{"seq":8,"concept":"M6-2-u5-C2","difficulty":1,"kind":"mc","stem":"지름이 10 cm인 원의 원주는 31.4 cm예요. 원주는 지름의 약 몇 배인가요?","options":[{"t":"약 3.14배","correct":true},{"t":"약 6.28배","mis":"M6-2-u5-X04"},{"t":"약 0.32배","mis":"M6-2-u5-X04"},{"t":"약 4배","mis":"M6-2-u5-X02"}],"explanation":["(원주) ÷ (지름)을 계산해요.","31.4 ÷ 10 = 3.14예요.","원주는 지름의 약 3.14배 — 이 값이 원주율이에요."],"variant_rule":{"alt":[{"stem":"지름이 20 cm인 원의 원주는 62.8 cm예요. 원주는 지름의 약 몇 배인가요?","options":[{"t":"약 3.14배","correct":true},{"t":"약 6.28배","mis":"M6-2-u5-X04"},{"t":"약 0.32배","mis":"M6-2-u5-X04"},{"t":"약 4배","mis":"M6-2-u5-X02"}],"explanation":["(원주) ÷ (지름)을 계산해요.","62.8 ÷ 20 = 3.14예요.","원주는 지름의 약 3.14배 — 이 값이 원주율이에요."]},{"stem":"지름이 15 cm인 원의 원주는 47.1 cm예요. 원주는 지름의 약 몇 배인가요?","options":[{"t":"약 3.14배","correct":true},{"t":"약 6.28배","mis":"M6-2-u5-X04"},{"t":"약 0.32배","mis":"M6-2-u5-X04"},{"t":"약 4배","mis":"M6-2-u5-X02"}],"explanation":["(원주) ÷ (지름)을 계산해요.","47.1 ÷ 15 = 3.14예요.","원주는 지름의 약 3.14배 — 이 값이 원주율이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_a#9','math',6,2,'u5','','tb_g6_2_math_u5_review_a','unit_review','M6-2-u5-C7',2,'sa','auto','한 변이 20 cm인 정사각형의 네 꼭짓점을 중심으로 반지름이 10 cm인 사분원을 하나씩 그려 노란색으로 칠했어요. 노란색 부분의 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":9,"concept":"M6-2-u5-C7","difficulty":2,"kind":"sa","stem":"한 변이 20 cm인 정사각형의 네 꼭짓점을 중심으로 반지름이 10 cm인 사분원을 하나씩 그려 노란색으로 칠했어요. 노란색 부분의 넓이는 몇 cm²인가요?","answer":["314"],"explanation":["노란색 사분원 4개를 꼭짓점 쪽을 모아 붙이면 원 하나가 돼요.","그 원의 반지름은 10 cm예요.","10 × 10 × 3.14 = 314 cm²예요."],"variant_rule":{"alt":[{"stem":"한 변이 20 cm인 정사각형의 네 꼭짓점을 중심으로 반지름이 10 cm인 사분원을 그렸어요. 사분원 4개를 뺀 가운데 초록색 부분의 넓이는 몇 cm²인가요?","answer":["86"],"explanation":["정사각형의 넓이는 20 × 20 = 400 cm²예요.","사분원 4개는 반지름 10 cm인 원 하나 — 314 cm²예요.","400 − 314 = 86 cm²예요."]},{"stem":"꽃밭은 가로 20 m, 세로 10 m인 직사각형의 위쪽에 반원만큼 볼록하고 아래쪽은 같은 크기의 반원만큼 패여 있어요. 꽃밭의 넓이는 몇 m²인가요?","answer":["200"],"explanation":["볼록한 반원을 패인 곳으로 옮겨요.","그러면 가로 20 m, 세로 10 m인 직사각형이 돼요.","20 × 10 = 200 m²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_a#10','math',6,2,'u5','','tb_g6_2_math_u5_review_a','unit_review','M6-2-u5-C6',2,'mc','auto','가로가 20 cm, 세로가 14 cm인 직사각형 종이를 잘라 만들 수 있는 가장 큰 원의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X21','M6-2-u5-X13','M6-2-u5-X12']::text[],true,'{"seq":10,"concept":"M6-2-u5-C6","difficulty":2,"kind":"mc","stem":"가로가 20 cm, 세로가 14 cm인 직사각형 종이를 잘라 만들 수 있는 가장 큰 원의 넓이는 몇 cm²인가요?","options":[{"t":"153.86 cm²","correct":true},{"t":"314 cm²","mis":"M6-2-u5-X21"},{"t":"615.44 cm²","mis":"M6-2-u5-X13"},{"t":"43.96 cm²","mis":"M6-2-u5-X12"}],"explanation":["가장 큰 원의 지름은 짧은 변 14 cm를 넘을 수 없어요.","반지름은 7 cm예요.","7 × 7 × 3.14 = 153.86 cm²예요."],"variant_rule":{"alt":[{"stem":"가로가 12 cm, 세로가 15 cm인 직사각형 종이를 잘라 만들 수 있는 가장 큰 원의 넓이는 몇 cm²인가요?","options":[{"t":"113.04 cm²","correct":true},{"t":"176.625 cm²","mis":"M6-2-u5-X21"},{"t":"452.16 cm²","mis":"M6-2-u5-X13"},{"t":"37.68 cm²","mis":"M6-2-u5-X12"}],"explanation":["가장 큰 원의 지름은 짧은 변 12 cm를 넘을 수 없어요.","반지름은 6 cm예요.","6 × 6 × 3.14 = 113.04 cm²예요."]},{"stem":"가로가 14 cm, 세로가 20 cm인 직사각형 종이를 잘라 만들 수 있는 가장 큰 원의 넓이는 몇 cm²인가요?","options":[{"t":"153.86 cm²","correct":true},{"t":"314 cm²","mis":"M6-2-u5-X21"},{"t":"615.44 cm²","mis":"M6-2-u5-X13"},{"t":"43.96 cm²","mis":"M6-2-u5-X12"}],"explanation":["가장 큰 원의 지름은 짧은 변 14 cm를 넘을 수 없어요.","반지름은 7 cm예요.","7 × 7 × 3.14 = 153.86 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_a#11','math',6,2,'u5','','tb_g6_2_math_u5_review_a','unit_review','M6-2-u5-C3',2,'mc','auto','바깥쪽 원의 지름이 48 cm인 굴렁쇠를 5바퀴 굴렸어요. 이 굴렁쇠가 굴러간 거리는 몇 m인가요?',ARRAY['M6-2-u5-X20','M6-2-u5-X19','M6-2-u5-X07']::text[],true,'{"seq":11,"concept":"M6-2-u5-C3","difficulty":2,"kind":"mc","stem":"바깥쪽 원의 지름이 48 cm인 굴렁쇠를 5바퀴 굴렸어요. 이 굴렁쇠가 굴러간 거리는 몇 m인가요?","options":[{"t":"7.536 m","correct":true},{"t":"753.6 m","mis":"M6-2-u5-X20"},{"t":"1.5072 m","mis":"M6-2-u5-X19"},{"t":"3.768 m","mis":"M6-2-u5-X07"}],"explanation":["한 바퀴 굴러간 거리는 48 × 3.14 = 150.72 cm예요.","5바퀴면 150.72 × 5 = 753.6 cm예요.","100 cm = 1 m니 7.536 m예요."],"variant_rule":{"alt":[{"stem":"바깥쪽 원의 지름이 40 cm인 굴렁쇠를 3바퀴 굴렸어요. 이 굴렁쇠가 굴러간 거리는 몇 m인가요?","options":[{"t":"3.768 m","correct":true},{"t":"376.8 m","mis":"M6-2-u5-X20"},{"t":"1.256 m","mis":"M6-2-u5-X19"},{"t":"1.884 m","mis":"M6-2-u5-X07"}],"explanation":["한 바퀴 굴러간 거리는 40 × 3.14 = 125.6 cm예요.","3바퀴면 125.6 × 3 = 376.8 cm예요.","100 cm = 1 m니 3.768 m예요."]},{"stem":"바깥쪽 원의 지름이 20 cm인 원판을 10바퀴 굴렸어요. 이 원판이 굴러간 거리는 몇 m인가요?","options":[{"t":"6.28 m","correct":true},{"t":"628 m","mis":"M6-2-u5-X20"},{"t":"0.628 m","mis":"M6-2-u5-X19"},{"t":"3.14 m","mis":"M6-2-u5-X07"}],"explanation":["한 바퀴 굴러간 거리는 20 × 3.14 = 62.8 cm예요.","10바퀴면 62.8 × 10 = 628 cm예요.","100 cm = 1 m니 6.28 m예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_a#12','math',6,2,'u5','','tb_g6_2_math_u5_review_a','unit_review','M6-2-u5-C2',2,'mc','auto','「알지오매스 키즈」로 반지름이 5 cm인 원 안쪽에 맞닿는 정사각형을 그렸더니 둘레가 28.28 cm였어요. (정사각형의 둘레) ÷ (지름)은 얼마인가요?',ARRAY['M6-2-u5-X04','M6-2-u5-X23','M6-2-u5-X20']::text[],true,'{"seq":12,"concept":"M6-2-u5-C2","difficulty":2,"kind":"mc","stem":"「알지오매스 키즈」로 반지름이 5 cm인 원 안쪽에 맞닿는 정사각형을 그렸더니 둘레가 28.28 cm였어요. (정사각형의 둘레) ÷ (지름)은 얼마인가요?","options":[{"t":"2.828","correct":true},{"t":"5.656","mis":"M6-2-u5-X04"},{"t":"3.14","mis":"M6-2-u5-X23"},{"t":"0.2828","mis":"M6-2-u5-X20"}],"explanation":["원의 반지름이 5 cm니 지름은 10 cm예요.","28.28 ÷ 10 = 2.828이에요.","원 안쪽 다각형의 둘레는 원주보다 짧아서 이 값은 원주율 3.14보다 작아요."],"variant_rule":{"alt":[{"stem":"「알지오매스 키즈」로 반지름이 5 cm인 원 안쪽에 맞닿는 정육각형을 그렸더니 둘레가 30 cm였어요. (정육각형의 둘레) ÷ (지름)은 얼마인가요?","options":[{"t":"3","correct":true},{"t":"6","mis":"M6-2-u5-X04"},{"t":"3.14","mis":"M6-2-u5-X23"},{"t":"0.3","mis":"M6-2-u5-X20"}],"explanation":["원의 반지름이 5 cm니 지름은 10 cm예요.","30 ÷ 10 = 3이에요.","원 안쪽 다각형의 둘레는 원주보다 짧아서 이 값은 원주율 3.14보다 작아요."]},{"stem":"「알지오매스 키즈」로 반지름이 5 cm인 원 안쪽에 맞닿는 정십이각형을 그렸더니 둘레가 31.08 cm였어요. (정십이각형의 둘레) ÷ (지름)은 얼마인가요?","options":[{"t":"3.108","correct":true},{"t":"6.216","mis":"M6-2-u5-X04"},{"t":"3.14","mis":"M6-2-u5-X23"},{"t":"0.3108","mis":"M6-2-u5-X20"}],"explanation":["원의 반지름이 5 cm니 지름은 10 cm예요.","31.08 ÷ 10 = 3.108이에요.","원 안쪽 다각형의 둘레는 원주보다 짧아서 이 값은 원주율 3.14보다 작아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_a#13','math',6,2,'u5','','tb_g6_2_math_u5_review_a','unit_review','M6-2-u5-C2',2,'mc','auto','「알지오매스 키즈」로 원 안쪽에 맞닿는 정사각형, 정육각형, 정십이각형, 정이십이각형을 차례로 그렸어요. 정다각형의 변의 수가 늘어날수록 정다각형은 어떤 모양에 가까워지나요?',ARRAY['M6-2-u5-X23']::text[],true,'{"seq":13,"concept":"M6-2-u5-C2","difficulty":2,"kind":"mc","stem":"「알지오매스 키즈」로 원 안쪽에 맞닿는 정사각형, 정육각형, 정십이각형, 정이십이각형을 차례로 그렸어요. 정다각형의 변의 수가 늘어날수록 정다각형은 어떤 모양에 가까워지나요?","options":[{"t":"원","correct":true},{"t":"정사각형","mis":"M6-2-u5-X23"},{"t":"삼각형","mis":"M6-2-u5-X23"},{"t":"직사각형","mis":"M6-2-u5-X23"}],"explanation":["변의 수가 늘어날수록 꼭짓점이 원 위에 촘촘히 놓여요.","변이 짧아지고 원과 정다각형 사이의 틈이 줄어요.","그래서 정다각형은 원에 가까워져요."],"variant_rule":{"alt":[{"stem":"원 안쪽에 맞닿는 정다각형의 변의 수가 늘어날수록 (정다각형의 둘레) ÷ (지름)은 어떻게 되나요?","options":[{"t":"원주율 3.14에 가까워져요","correct":true},{"t":"점점 작아져요","mis":"M6-2-u5-X23"},{"t":"변하지 않아요","mis":"M6-2-u5-X23"},{"t":"원주율보다 커져요","mis":"M6-2-u5-X23"}],"explanation":["반지름 5 cm인 원에서 2.828 → 3 → 3.108 → 3.124로 커졌어요.","정다각형이 원에 가까워지니 둘레도 원주에 가까워져요.","그래서 (둘레) ÷ (지름)은 원주율 3.14에 가까워져요."]},{"stem":"반지름이 5 cm인 원 안쪽에 맞닿는 정이십이각형의 (둘레) ÷ (지름)은 3.124예요. 원주율과 견주면 어떤가요?","options":[{"t":"원주율보다 조금 작아요","correct":true},{"t":"원주율과 똑같아요","mis":"M6-2-u5-X23"},{"t":"원주율보다 커요","mis":"M6-2-u5-X23"},{"t":"원주율의 2배쯤이에요","mis":"M6-2-u5-X04"}],"explanation":["정이십이각형은 원 안쪽에 맞닿아 있어요.","원 안쪽 다각형의 둘레는 원주보다 조금 짧아요.","그래서 3.124는 원주율 3.14보다 조금 작아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_a#14','math',6,2,'u5','','tb_g6_2_math_u5_review_a','unit_review','M6-2-u5-C4',2,'mc','auto','지름이 15 cm인 원과 원주가 43.96 cm인 원이 있어요. 크기가 더 큰 원은 어느 것인가요?',ARRAY['M6-2-u5-X08','M6-2-u5-X20','M6-2-u5-X19']::text[],true,'{"seq":14,"concept":"M6-2-u5-C4","difficulty":2,"kind":"mc","stem":"지름이 15 cm인 원과 원주가 43.96 cm인 원이 있어요. 크기가 더 큰 원은 어느 것인가요?","options":[{"t":"지름이 15 cm인 원","correct":true},{"t":"원주가 43.96 cm인 원","mis":"M6-2-u5-X08"},{"t":"두 원의 크기가 같아요","mis":"M6-2-u5-X20"},{"t":"견줄 수 없어요","mis":"M6-2-u5-X19"}],"explanation":["같은 것끼리 견주려고 원주를 지름으로 바꾸어요.","43.96 ÷ 3.14 = 14 — 원주가 43.96 cm인 원의 지름은 14 cm예요.","지름 15 cm와 14 cm를 견주면 지름이 15 cm인 원이 더 커요."],"variant_rule":{"alt":[{"stem":"지름이 22 cm인 원과 원주가 81.64 cm인 원이 있어요. 크기가 더 큰 원은 어느 것인가요?","options":[{"t":"원주가 81.64 cm인 원","correct":true},{"t":"지름이 22 cm인 원","mis":"M6-2-u5-X08"},{"t":"두 원의 크기가 같아요","mis":"M6-2-u5-X20"},{"t":"견줄 수 없어요","mis":"M6-2-u5-X19"}],"explanation":["같은 것끼리 견주려고 원주를 지름으로 바꾸어요.","81.64 ÷ 3.14 = 26 — 원주가 81.64 cm인 원의 지름은 26 cm예요.","지름 22 cm와 26 cm를 견주면 원주가 81.64 cm인 원이 더 커요."]},{"stem":"지름이 10 cm인 원과 원주가 37.68 cm인 원이 있어요. 크기가 더 큰 원은 어느 것인가요?","options":[{"t":"원주가 37.68 cm인 원","correct":true},{"t":"지름이 10 cm인 원","mis":"M6-2-u5-X08"},{"t":"두 원의 크기가 같아요","mis":"M6-2-u5-X20"},{"t":"견줄 수 없어요","mis":"M6-2-u5-X19"}],"explanation":["같은 것끼리 견주려고 원주를 지름으로 바꾸어요.","37.68 ÷ 3.14 = 12 — 원주가 37.68 cm인 원의 지름은 12 cm예요.","지름 10 cm와 12 cm를 견주면 원주가 37.68 cm인 원이 더 커요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_a#15','math',6,2,'u5','','tb_g6_2_math_u5_review_a','unit_review','M6-2-u5-C5',2,'mc','auto','지름이 14 cm인 원의 넓이를 원 안과 밖에 꼭 맞는 정사각형으로 어림했어요. 알맞은 범위는 어느 것인가요?',ARRAY['M6-2-u5-X11','M6-2-u5-X01','M6-2-u5-X12']::text[],true,'{"seq":15,"concept":"M6-2-u5-C5","difficulty":2,"kind":"mc","stem":"지름이 14 cm인 원의 넓이를 원 안과 밖에 꼭 맞는 정사각형으로 어림했어요. 알맞은 범위는 어느 것인가요?","options":[{"t":"98 cm²보다 넓고 196 cm²보다 좁아요","correct":true},{"t":"49 cm²보다 넓고 98 cm²보다 좁아요","mis":"M6-2-u5-X11"},{"t":"196 cm²보다 넓고 392 cm²보다 좁아요","mis":"M6-2-u5-X01"},{"t":"14 cm²보다 넓고 28 cm²보다 좁아요","mis":"M6-2-u5-X12"}],"explanation":["반지름은 7 cm예요.","원 안 정사각형은 7 × 7 × 2 = 98 cm², 원 밖 정사각형은 7 × 7 × 4 = 196 cm²예요.","원의 넓이는 그 사이 — 98 cm²보다 넓고 196 cm²보다 좁아요."],"variant_rule":{"alt":[{"stem":"지름이 12 cm인 원의 넓이를 원 안과 밖에 꼭 맞는 정사각형으로 어림했어요. 알맞은 범위는 어느 것인가요?","options":[{"t":"72 cm²보다 넓고 144 cm²보다 좁아요","correct":true},{"t":"36 cm²보다 넓고 72 cm²보다 좁아요","mis":"M6-2-u5-X11"},{"t":"144 cm²보다 넓고 288 cm²보다 좁아요","mis":"M6-2-u5-X01"},{"t":"12 cm²보다 넓고 24 cm²보다 좁아요","mis":"M6-2-u5-X12"}],"explanation":["반지름은 6 cm예요.","원 안 정사각형은 6 × 6 × 2 = 72 cm², 원 밖 정사각형은 6 × 6 × 4 = 144 cm²예요.","원의 넓이는 그 사이 — 72 cm²보다 넓고 144 cm²보다 좁아요."]},{"stem":"지름이 20 cm인 원의 넓이를 원 안과 밖에 꼭 맞는 정사각형으로 어림했어요. 알맞은 범위는 어느 것인가요?","options":[{"t":"200 cm²보다 넓고 400 cm²보다 좁아요","correct":true},{"t":"100 cm²보다 넓고 200 cm²보다 좁아요","mis":"M6-2-u5-X11"},{"t":"400 cm²보다 넓고 800 cm²보다 좁아요","mis":"M6-2-u5-X01"},{"t":"20 cm²보다 넓고 40 cm²보다 좁아요","mis":"M6-2-u5-X12"}],"explanation":["반지름은 10 cm예요.","원 안 정사각형은 10 × 10 × 2 = 200 cm², 원 밖 정사각형은 10 × 10 × 4 = 400 cm²예요.","원의 넓이는 그 사이 — 200 cm²보다 넓고 400 cm²보다 좁아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_a#16','math',6,2,'u5','','tb_g6_2_math_u5_review_a','unit_review','M6-2-u5-C7',2,'mc','auto','반지름이 4 cm인 원에서 반지름이 1 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X16','M6-2-u5-X20']::text[],true,'{"seq":16,"concept":"M6-2-u5-C7","difficulty":2,"kind":"mc","stem":"반지름이 4 cm인 원에서 반지름이 1 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?","options":[{"t":"47.1 cm²","correct":true},{"t":"50.24 cm²","mis":"M6-2-u5-X16"},{"t":"28.26 cm²","mis":"M6-2-u5-X16"},{"t":"53.38 cm²","mis":"M6-2-u5-X20"}],"explanation":["큰 원의 넓이는 4 × 4 × 3.14 = 50.24 cm²예요.","작은 원의 넓이는 1 × 1 × 3.14 = 3.14 cm²예요.","50.24 − 3.14 = 47.1 cm²예요."],"variant_rule":{"alt":[{"stem":"반지름이 7 cm인 원에서 반지름이 4 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?","options":[{"t":"103.62 cm²","correct":true},{"t":"153.86 cm²","mis":"M6-2-u5-X16"},{"t":"28.26 cm²","mis":"M6-2-u5-X16"},{"t":"204.1 cm²","mis":"M6-2-u5-X20"}],"explanation":["큰 원의 넓이는 7 × 7 × 3.14 = 153.86 cm²예요.","작은 원의 넓이는 4 × 4 × 3.14 = 50.24 cm²예요.","153.86 − 50.24 = 103.62 cm²예요."]},{"stem":"반지름이 10 cm인 원에서 반지름이 7 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?","options":[{"t":"160.14 cm²","correct":true},{"t":"314 cm²","mis":"M6-2-u5-X16"},{"t":"28.26 cm²","mis":"M6-2-u5-X16"},{"t":"467.86 cm²","mis":"M6-2-u5-X20"}],"explanation":["큰 원의 넓이는 10 × 10 × 3.14 = 314 cm²예요.","작은 원의 넓이는 7 × 7 × 3.14 = 153.86 cm²예요.","314 − 153.86 = 160.14 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_a#17','math',6,2,'u5','','tb_g6_2_math_u5_review_a','unit_review','M6-2-u5-C6',3,'mc','auto','원주가 87.92 cm인 원의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X13','M6-2-u5-X12','M6-2-u5-X14']::text[],true,'{"seq":17,"concept":"M6-2-u5-C6","difficulty":3,"kind":"mc","stem":"원주가 87.92 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"615.44 cm²","correct":true},{"t":"2461.76 cm²","mis":"M6-2-u5-X13"},{"t":"87.92 cm²","mis":"M6-2-u5-X12"},{"t":"43.96 cm²","mis":"M6-2-u5-X14"}],"explanation":["지름은 87.92 ÷ 3.14 = 28 cm, 반지름은 14 cm예요.","넓이는 14 × 14 × 3.14예요.","14 × 14 × 3.14 = 615.44 cm²예요."],"variant_rule":{"alt":[{"stem":"원주가 75.36 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"452.16 cm²","correct":true},{"t":"1808.64 cm²","mis":"M6-2-u5-X13"},{"t":"75.36 cm²","mis":"M6-2-u5-X12"},{"t":"37.68 cm²","mis":"M6-2-u5-X14"}],"explanation":["지름은 75.36 ÷ 3.14 = 24 cm, 반지름은 12 cm예요.","넓이는 12 × 12 × 3.14예요.","12 × 12 × 3.14 = 452.16 cm²예요."]},{"stem":"원주가 31.4 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"78.5 cm²","correct":true},{"t":"314 cm²","mis":"M6-2-u5-X13"},{"t":"31.4 cm²","mis":"M6-2-u5-X12"},{"t":"15.7 cm²","mis":"M6-2-u5-X14"}],"explanation":["지름은 31.4 ÷ 3.14 = 10 cm, 반지름은 5 cm예요.","넓이는 5 × 5 × 3.14예요.","5 × 5 × 3.14 = 78.5 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_a#18','math',6,2,'u5','','tb_g6_2_math_u5_review_a','unit_review','M6-2-u5-C6',3,'mc','auto','넓이가 넓은 원부터 차례로 놓으려고 해요. ㉠ 반지름이 10 cm인 원 · ㉡ 넓이가 615.44 cm²인 원 · ㉢ 원주가 75.36 cm인 원 — 바르게 놓은 것은 어느 것인가요?',ARRAY['M6-2-u5-X19','M6-2-u5-X13']::text[],true,'{"seq":18,"concept":"M6-2-u5-C6","difficulty":3,"kind":"mc","stem":"넓이가 넓은 원부터 차례로 놓으려고 해요. ㉠ 반지름이 10 cm인 원 · ㉡ 넓이가 615.44 cm²인 원 · ㉢ 원주가 75.36 cm인 원 — 바르게 놓은 것은 어느 것인가요?","options":[{"t":"㉡, ㉢, ㉠","correct":true},{"t":"㉠, ㉢, ㉡","mis":"M6-2-u5-X19"},{"t":"㉠, ㉡, ㉢","mis":"M6-2-u5-X13"},{"t":"㉢, ㉡, ㉠","mis":"M6-2-u5-X13"}],"explanation":["세 원의 넓이를 모두 구해 견주어요.","㉠ 314 cm² · ㉡ 615.44 cm² · ㉢ 452.16 cm²예요.","넓은 원부터 놓으면 ㉡, ㉢, ㉠이에요."],"variant_rule":{"alt":[{"stem":"넓이가 넓은 원부터 차례로 놓으려고 해요. ㉠ 지름이 22 cm인 원 · ㉡ 반지름이 9 cm인 원 · ㉢ 넓이가 452.16 cm²인 원 — 바르게 놓은 것은 어느 것인가요?","options":[{"t":"㉢, ㉠, ㉡","correct":true},{"t":"㉡, ㉠, ㉢","mis":"M6-2-u5-X19"},{"t":"㉠, ㉡, ㉢","mis":"M6-2-u5-X13"},{"t":"㉡, ㉢, ㉠","mis":"M6-2-u5-X13"}],"explanation":["세 원의 넓이를 모두 구해 견주어요.","㉠ 379.94 cm² · ㉡ 254.34 cm² · ㉢ 452.16 cm²예요.","넓은 원부터 놓으면 ㉢, ㉠, ㉡이에요."]},{"stem":"넓이가 넓은 원부터 차례로 놓으려고 해요. ㉠ 지름이 20 cm인 원 · ㉡ 반지름이 9 cm인 원 · ㉢ 원주가 75.36 cm인 원 — 바르게 놓은 것은 어느 것인가요?","options":[{"t":"㉢, ㉠, ㉡","correct":true},{"t":"㉡, ㉠, ㉢","mis":"M6-2-u5-X19"},{"t":"㉠, ㉡, ㉢","mis":"M6-2-u5-X13"},{"t":"㉡, ㉢, ㉠","mis":"M6-2-u5-X13"}],"explanation":["세 원의 넓이를 모두 구해 견주어요.","㉠ 314 cm² · ㉡ 254.34 cm² · ㉢ 452.16 cm²예요.","넓은 원부터 놓으면 ㉢, ㉠, ㉡이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_a#19','math',6,2,'u5','','tb_g6_2_math_u5_review_a','unit_review','M6-2-u5-C7',3,'mc','auto','지름이 20 cm인 원 안에 지름이 10 cm인 반원 두 개가 하나는 위로, 하나는 아래로 그려져 있어요. 큰 원에서 두 반원을 뺀 부분의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X17','M6-2-u5-X16']::text[],true,'{"seq":19,"concept":"M6-2-u5-C7","difficulty":3,"kind":"mc","stem":"지름이 20 cm인 원 안에 지름이 10 cm인 반원 두 개가 하나는 위로, 하나는 아래로 그려져 있어요. 큰 원에서 두 반원을 뺀 부분의 넓이는 몇 cm²인가요?","options":[{"t":"235.5 cm²","correct":true},{"t":"274.75 cm²","mis":"M6-2-u5-X17"},{"t":"157 cm²","mis":"M6-2-u5-X17"},{"t":"314 cm²","mis":"M6-2-u5-X16"}],"explanation":["큰 원은 10 × 10 × 3.14 = 314 cm²예요.","반원 두 개를 모으면 반지름 5 cm인 원 — 5 × 5 × 3.14 = 78.5 cm²예요.","314 − 78.5 = 235.5 cm²예요."],"variant_rule":{"alt":[{"stem":"지름이 30 cm인 큰 원 안에 지름이 20 cm인 원과 지름이 10 cm인 원이 나란히 꼭 맞게 들어 있어요. 큰 원에서 두 원을 뺀 부분의 넓이는 몇 cm²인가요?","options":[{"t":"314 cm²","correct":true},{"t":"392.5 cm²","mis":"M6-2-u5-X17"},{"t":"628 cm²","mis":"M6-2-u5-X17"},{"t":"1256 cm²","mis":"M6-2-u5-X13"}],"explanation":["큰 원은 15 × 15 × 3.14 = 706.5 cm²예요.","두 원은 314 cm²와 78.5 cm²예요.","706.5 − 314 − 78.5 = 314 cm²예요."]},{"stem":"반지름이 12 cm인 큰 원 안에 반지름이 6 cm인 원 두 개가 들어 있어요. 큰 원에서 작은 원 두 개를 뺀 부분의 넓이는 몇 cm²인가요?","options":[{"t":"226.08 cm²","correct":true},{"t":"339.12 cm²","mis":"M6-2-u5-X17"},{"t":"452.16 cm²","mis":"M6-2-u5-X16"},{"t":"113.04 cm²","mis":"M6-2-u5-X19"}],"explanation":["큰 원은 12 × 12 × 3.14 = 452.16 cm²예요.","작은 원 하나는 6 × 6 × 3.14 = 113.04 cm², 두 개는 226.08 cm²예요.","452.16 − 226.08 = 226.08 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_a#20','math',6,2,'u5','','tb_g6_2_math_u5_review_a','unit_review','M6-2-u5-C6',3,'sa','auto','넓이가 452.16 cm²인 원이 있어요. 이 원의 반지름은 몇 cm인가요?','{}'::text[],true,'{"seq":20,"concept":"M6-2-u5-C6","difficulty":3,"kind":"sa","stem":"넓이가 452.16 cm²인 원이 있어요. 이 원의 반지름은 몇 cm인가요?","answer":["12"],"explanation":["(반지름) × (반지름) × 3.14 = 452.16이에요.","452.16 ÷ 3.14 = 144니 (반지름) × (반지름) = 144예요.","같은 수를 두 번 곱해 144가 되는 수는 12 — 반지름은 12 cm예요."],"variant_rule":{"alt":[{"stem":"넓이가 314 cm²인 원이 있어요. 이 원의 반지름은 몇 cm인가요?","answer":["10"],"explanation":["(반지름) × (반지름) × 3.14 = 314예요.","314 ÷ 3.14 = 100이니 (반지름) × (반지름) = 100이에요.","같은 수를 두 번 곱해 100이 되는 수는 10 — 반지름은 10 cm예요."]},{"stem":"넓이가 78.5 cm²인 원이 있어요. 이 원의 반지름은 몇 cm인가요?","answer":["5"],"explanation":["(반지름) × (반지름) × 3.14 = 78.5예요.","78.5 ÷ 3.14 = 25니 (반지름) × (반지름) = 25예요.","같은 수를 두 번 곱해 25가 되는 수는 5 — 반지름은 5 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_a#21','math',6,2,'u5','','tb_g6_2_math_u5_review_a','unit_review','M6-2-u5-C8',3,'mc','auto','반지름이 9 cm인 원의 넓이는 반지름이 3 cm인 원의 넓이의 몇 배인가요?',ARRAY['M6-2-u5-X18','M6-2-u5-X20']::text[],true,'{"seq":21,"concept":"M6-2-u5-C8","difficulty":3,"kind":"mc","stem":"반지름이 9 cm인 원의 넓이는 반지름이 3 cm인 원의 넓이의 몇 배인가요?","options":[{"t":"9배","correct":true},{"t":"3배","mis":"M6-2-u5-X18"},{"t":"6배","mis":"M6-2-u5-X18"},{"t":"27배","mis":"M6-2-u5-X20"}],"explanation":["반지름이 9 ÷ 3 = 3배예요.","넓이는 반지름을 두 번 곱하니 3 × 3 = 9배예요.","계산해 봐도 254.34 ÷ 28.26 = 9예요."],"variant_rule":{"alt":[{"stem":"반지름이 20 cm인 원의 넓이는 반지름이 10 cm인 원의 넓이의 몇 배인가요?","options":[{"t":"4배","correct":true},{"t":"2배","mis":"M6-2-u5-X18"},{"t":"8배","mis":"M6-2-u5-X20"},{"t":"20배","mis":"M6-2-u5-X20"}],"explanation":["반지름이 20 ÷ 10 = 2배예요.","넓이는 반지름을 두 번 곱하니 2 × 2 = 4배예요.","계산해 봐도 1256 ÷ 314 = 4예요."]},{"stem":"반지름이 30 cm인 원의 넓이는 반지름이 10 cm인 원의 넓이의 몇 배인가요?","options":[{"t":"9배","correct":true},{"t":"3배","mis":"M6-2-u5-X18"},{"t":"6배","mis":"M6-2-u5-X18"},{"t":"27배","mis":"M6-2-u5-X20"}],"explanation":["반지름이 30 ÷ 10 = 3배예요.","넓이는 반지름을 두 번 곱하니 3 × 3 = 9배예요.","계산해 봐도 2826 ÷ 314 = 9예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_a#22','math',6,2,'u5','','tb_g6_2_math_u5_review_a','unit_review','M6-2-u5-C4',3,'mc','auto','반지름이 15 cm인 원판을 몇 바퀴 굴렸더니 471 cm만큼 굴러갔어요. 원판이 굴러간 바퀴 수는 몇 바퀴인가요?',ARRAY['M6-2-u5-X07','M6-2-u5-X01','M6-2-u5-X20']::text[],true,'{"seq":22,"concept":"M6-2-u5-C4","difficulty":3,"kind":"mc","stem":"반지름이 15 cm인 원판을 몇 바퀴 굴렸더니 471 cm만큼 굴러갔어요. 원판이 굴러간 바퀴 수는 몇 바퀴인가요?","options":[{"t":"5바퀴","correct":true},{"t":"10바퀴","mis":"M6-2-u5-X07"},{"t":"2.5바퀴","mis":"M6-2-u5-X01"},{"t":"15바퀴","mis":"M6-2-u5-X20"}],"explanation":["한 바퀴 굴러간 거리는 원판의 원주예요.","지름 30 cm — 원주는 30 × 3.14 = 94.2 cm예요.","471 ÷ 94.2 = 5 — 5바퀴예요."],"variant_rule":{"alt":[{"stem":"지름이 20 cm인 원판을 몇 바퀴 굴렸더니 628 cm만큼 굴러갔어요. 원판이 굴러간 바퀴 수는 몇 바퀴인가요?","options":[{"t":"10바퀴","correct":true},{"t":"20바퀴","mis":"M6-2-u5-X07"},{"t":"5바퀴","mis":"M6-2-u5-X01"},{"t":"30바퀴","mis":"M6-2-u5-X20"}],"explanation":["한 바퀴 굴러간 거리는 원판의 원주예요.","지름 20 cm — 원주는 20 × 3.14 = 62.8 cm예요.","628 ÷ 62.8 = 10 — 10바퀴예요."]},{"stem":"지름이 40 cm인 원판을 몇 바퀴 굴렸더니 376.8 cm만큼 굴러갔어요. 원판이 굴러간 바퀴 수는 몇 바퀴인가요?","options":[{"t":"3바퀴","correct":true},{"t":"6바퀴","mis":"M6-2-u5-X07"},{"t":"1.5바퀴","mis":"M6-2-u5-X01"},{"t":"9바퀴","mis":"M6-2-u5-X20"}],"explanation":["한 바퀴 굴러간 거리는 원판의 원주예요.","지름 40 cm — 원주는 40 × 3.14 = 125.6 cm예요.","376.8 ÷ 125.6 = 3 — 3바퀴예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_a#23','math',6,2,'u5','','tb_g6_2_math_u5_review_a','unit_review','M6-2-u5-C2',4,'essay','teacher','잘못된 문장을 찾고, 바르게 고쳐 써 보세요. ㉠ 지름이 길어지면 원주도 길어집니다. ㉡ 원이 커지면 원주율도 커집니다. ㉢ 원주는 지름의 약 3.14배입니다. ㉣ 원주율을 소수로 나타내면 3.141592…와 같이 끝없이 계속됩니다.','{}'::text[],true,'{"seq":23,"concept":"M6-2-u5-C2","difficulty":4,"kind":"essay","stem":"잘못된 문장을 찾고, 바르게 고쳐 써 보세요. ㉠ 지름이 길어지면 원주도 길어집니다. ㉡ 원이 커지면 원주율도 커집니다. ㉢ 원주는 지름의 약 3.14배입니다. ㉣ 원주율을 소수로 나타내면 3.141592…와 같이 끝없이 계속됩니다.","answer_guide":{"answer":"예: ㉡ — 바른 문장: 원주율은 원의 크기에 상관없이 일정합니다.","scoring_points":["잘못된 문장(㉡)을 찾았는가","바른 문장으로 고쳐 썼는가","고친 까닭(원이 커지면 원주와 지름이 함께 늘어나 비율은 그대로)을 알고 있는가"]},"explanation":["문장마다 원주·원주율의 뜻과 견주어 봐요.","잘못된 문장은 ㉡이에요.","바르게 고치면 「원주율은 원의 크기에 상관없이 일정합니다.」예요."],"variant_rule":{"alt":[{"stem":"잘못된 문장을 찾고, 바르게 고쳐 써 보세요. ㉠ 지름이 길어지면 원주도 길어집니다. ㉡ 원의 지름에 대한 원주의 비율은 지름마다 다릅니다. ㉢ 원주는 지름의 약 3.14배입니다.","answer_guide":{"answer":"예: ㉡ — 바른 문장: 원의 지름에 대한 원주의 비율은 일정합니다.","scoring_points":["잘못된 문장(㉡)을 찾았는가","바른 문장으로 고쳐 썼는가","고친 까닭(어떤 원을 재어도 (원주) ÷ (지름)은 약 3.14)을 알고 있는가"]},"explanation":["문장마다 원주·원주율의 뜻과 견주어 봐요.","잘못된 문장은 ㉡이에요.","바르게 고치면 「원의 지름에 대한 원주의 비율은 일정합니다.」예요."]},{"stem":"잘못된 문장을 찾고, 바르게 고쳐 써 보세요. ㉠ (원주율) = (지름) ÷ (원주)입니다. ㉡ 원주율은 원의 지름에 대한 원주의 비율입니다. ㉢ 원주율을 소수로 나타내면 끝없이 계속됩니다.","answer_guide":{"answer":"예: ㉠ — 바른 문장: (원주율) = (원주) ÷ (지름)입니다.","scoring_points":["잘못된 문장(㉠)을 찾았는가","바른 문장으로 고쳐 썼는가","고친 까닭(원주율은 지름이 기준량이라 원주를 지름으로 나눔)을 알고 있는가"]},"explanation":["문장마다 원주·원주율의 뜻과 견주어 봐요.","잘못된 문장은 ㉠이에요.","바르게 고치면 「(원주율) = (원주) ÷ (지름)입니다.」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_a#24','math',6,2,'u5','','tb_g6_2_math_u5_review_a','unit_review','M6-2-u5-C6',4,'essay','teacher','가로 12 cm, 세로 15 cm인 직사각형 안에 그릴 수 있는 가장 큰 원의 넓이는 몇 cm²인지 풀이 과정을 쓰고 답을 구해 보세요.','{}'::text[],true,'{"seq":24,"concept":"M6-2-u5-C6","difficulty":4,"kind":"essay","stem":"가로 12 cm, 세로 15 cm인 직사각형 안에 그릴 수 있는 가장 큰 원의 넓이는 몇 cm²인지 풀이 과정을 쓰고 답을 구해 보세요.","answer_guide":{"answer":"예: 직사각형 안에 그릴 수 있는 가장 큰 원의 지름은 짧은 변의 길이인 12 cm이다. 반지름은 6 cm이므로 넓이는 6 × 6 × 3.14 = 113.04 cm²이다.","scoring_points":["가장 큰 원의 지름이 짧은 변 12 cm라고 썼는가","반지름 6 cm로 식을 세웠는가","113.04 cm²를 구했는가"]},"explanation":["가장 큰 원의 지름은 짧은 변 12 cm예요.","반지름은 6 cm예요.","6 × 6 × 3.14 = 113.04 cm²예요."],"variant_rule":{"alt":[{"stem":"가는 반지름이 9 cm인 원, 나는 반지름이 3 cm인 원이에요. 가의 넓이는 나의 넓이의 몇 배인지 풀이 과정을 쓰고 답을 구해 보세요.","answer_guide":{"answer":"예: 가의 넓이는 9 × 9 × 3.14 = 254.34 cm², 나의 넓이는 3 × 3 × 3.14 = 28.26 cm²이다. 254.34 ÷ 28.26 = 9이므로 9배이다. (반지름이 3배이니 3 × 3 = 9배로 구해도 된다.)","scoring_points":["두 넓이 254.34 cm²·28.26 cm²를 구했는가","나눗셈으로 9배를 구했는가","반지름 3배 → 넓이 9배를 설명했는가"]},"explanation":["가는 254.34 cm², 나는 28.26 cm²예요.","254.34 ÷ 28.26 = 9예요.","반지름이 3배라 넓이는 3 × 3 = 9배예요."]},{"stem":"바깥쪽 원의 지름이 48 cm인 굴렁쇠를 5바퀴 굴렸어요. 굴렁쇠가 굴러간 거리는 몇 m인지 풀이 과정을 쓰고 답을 구해 보세요.","answer_guide":{"answer":"예: 한 바퀴 굴러간 거리는 굴렁쇠의 원주이므로 48 × 3.14 = 150.72 cm이다. 5바퀴면 150.72 × 5 = 753.6 cm이고, 1 cm = 0.01 m이므로 7.536 m이다.","scoring_points":["한 바퀴 거리가 원주임을 밝혔는가","753.6 cm를 구했는가","m로 바꾸어 7.536 m를 구했는가"]},"explanation":["원주는 48 × 3.14 = 150.72 cm예요.","150.72 × 5 = 753.6 cm예요.","753.6 cm는 7.536 m예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_a#25','math',6,2,'u5','','tb_g6_2_math_u5_review_a','unit_review','M6-2-u5-C2',4,'essay','teacher','반지름이 5 cm인 원 안쪽에 맞닿는 정사각형, 정육각형, 정십이각형, 정이십이각형의 둘레는 28.28 cm, 30 cm, 31.08 cm, 31.24 cm예요. (둘레) ÷ (지름)을 구하고 원주율과 견주어 알게 된 점을 써 보세요.','{}'::text[],true,'{"seq":25,"concept":"M6-2-u5-C2","difficulty":4,"kind":"essay","stem":"반지름이 5 cm인 원 안쪽에 맞닿는 정사각형, 정육각형, 정십이각형, 정이십이각형의 둘레는 28.28 cm, 30 cm, 31.08 cm, 31.24 cm예요. (둘레) ÷ (지름)을 구하고 원주율과 견주어 알게 된 점을 써 보세요.","answer_guide":{"answer":"예: 2.828, 3, 3.108, 3.124이다. 정다각형의 변의 수가 늘어날수록 원에 가까워지고 (둘레) ÷ (지름)은 원주율 3.14에 가까워진다.","scoring_points":["네 값을 구했는가","변의 수가 늘수록 원에 가까워진다고 썼는가","값이 원주율 3.14에 가까워진다고 썼는가"]},"explanation":["지름은 10 cm예요.","2.828 → 3 → 3.108 → 3.124예요.","변이 늘수록 3.14에 가까워져요."],"variant_rule":{"alt":[{"stem":"반지름이 3배가 되면 원주와 원의 넓이는 각각 몇 배가 되는지 쓰고, 두 배수가 다른 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 원주는 3배, 넓이는 9배가 된다. 원주는 (지름) × (원주율)로 길이를 한 번 곱하지만 넓이는 반지름을 두 번 곱하므로 3 × 3 = 9배가 된다.","scoring_points":["원주 3배를 썼는가","넓이 9배를 썼는가","한 번·두 번 곱하는 차이로 설명했는가"]},"explanation":["원주는 3배예요.","넓이는 3 × 3 = 9배예요.","넓이는 반지름을 두 번 곱해요."]},{"stem":"학교 운동장은 가로 60 m, 세로 50 m인 직사각형의 양쪽에 반원을 붙인 모양이에요. 운동장의 넓이는 몇 m²인지 풀이 과정을 쓰고 답을 구해 보세요.","answer_guide":{"answer":"예: 직사각형은 60 × 50 = 3000 m²이다. 양쪽 반원 두 개를 모으면 지름 50 m, 반지름 25 m인 원이 되어 25 × 25 × 3.14 = 1962.5 m²이다. 따라서 3000 + 1962.5 = 4962.5 m²이다.","scoring_points":["직사각형 3000 m²를 구했는가","반원 두 개를 원 1962.5 m²로 모았는가","4962.5 m²를 구했는가"]},"explanation":["직사각형은 60 × 50 = 3000 m²예요.","반원 두 개 = 25 × 25 × 3.14 = 1962.5 m²예요.","3000 + 1962.5 = 4962.5 m²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_b#1','math',6,2,'u5','','tb_g6_2_math_u5_review_b','unit_review','M6-2-u5-C2',1,'mc','auto','원의 지름에 대한 원주의 비율을 무엇이라고 하나요?',ARRAY['M6-2-u5-X02','M6-2-u5-X01']::text[],true,'{"seq":1,"concept":"M6-2-u5-C2","difficulty":1,"kind":"mc","stem":"원의 지름에 대한 원주의 비율을 무엇이라고 하나요?","options":[{"t":"원주율","correct":true},{"t":"원주","mis":"M6-2-u5-X02"},{"t":"반지름","mis":"M6-2-u5-X01"},{"t":"지름","mis":"M6-2-u5-X01"}],"explanation":["원의 둘레가 원주예요.","모든 원에서 지름에 대한 원주의 비율은 일정해요.","그 비율을 원주율이라고 해요."],"variant_rule":{"alt":[{"stem":"(원주율) = ( □ ) ÷ (지름)에서 □에 알맞은 말은 어느 것인가요?","options":[{"t":"원주","correct":true},{"t":"반지름","mis":"M6-2-u5-X04"},{"t":"원주율","mis":"M6-2-u5-X02"},{"t":"원의 넓이","mis":"M6-2-u5-X12"}],"explanation":["원주율은 원의 지름에 대한 원주의 비율이에요.","비교하는 양이 원주, 기준량이 지름이에요.","그래서 (원주율) = (원주) ÷ (지름)이에요."]},{"stem":"원의 둘레를 무엇이라고 하나요?","options":[{"t":"원주","correct":true},{"t":"반지름","mis":"M6-2-u5-X02"},{"t":"지름","mis":"M6-2-u5-X02"},{"t":"원의 중심","mis":"M6-2-u5-X02"}],"explanation":["원의 둘레를 원주라고 해요.","원의 중심과 원 위의 한 점을 이으면 반지름, 중심을 지나 원 위의 두 점을 이으면 지름이에요.","원주는 원의 둘레의 길이를 말하기도 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_b#2','math',6,2,'u5','','tb_g6_2_math_u5_review_b','unit_review','M6-2-u5-C3',1,'mc','auto','지름이 14 cm인 원의 원주는 몇 cm인가요?',ARRAY['M6-2-u5-X01','M6-2-u5-X12']::text[],true,'{"seq":2,"concept":"M6-2-u5-C3","difficulty":1,"kind":"mc","stem":"지름이 14 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"43.96 cm","correct":true},{"t":"21.98 cm","mis":"M6-2-u5-X01"},{"t":"87.92 cm","mis":"M6-2-u5-X01"},{"t":"153.86 cm","mis":"M6-2-u5-X12"}],"explanation":["(원주) = (지름) × (원주율)이에요.","14 × 3.14를 계산해요.","14 × 3.14 = 43.96 — 원주는 43.96 cm예요."],"variant_rule":{"alt":[{"stem":"지름이 7 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"21.98 cm","correct":true},{"t":"10.99 cm","mis":"M6-2-u5-X01"},{"t":"43.96 cm","mis":"M6-2-u5-X01"},{"t":"38.465 cm","mis":"M6-2-u5-X12"}],"explanation":["(원주) = (지름) × (원주율)이에요.","7 × 3.14를 계산해요.","7 × 3.14 = 21.98 — 원주는 21.98 cm예요."]},{"stem":"지름이 4 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"12.56 cm","correct":true},{"t":"6.28 cm","mis":"M6-2-u5-X01"},{"t":"25.12 cm","mis":"M6-2-u5-X01"},{"t":"7.14 cm","mis":"M6-2-u5-X08"}],"explanation":["(원주) = (지름) × (원주율)이에요.","4 × 3.14를 계산해요.","4 × 3.14 = 12.56 — 원주는 12.56 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_b#3','math',6,2,'u5','','tb_g6_2_math_u5_review_b','unit_review','M6-2-u5-C3',1,'mc','auto','반지름이 9 cm인 원의 원주는 몇 cm인가요?',ARRAY['M6-2-u5-X07','M6-2-u5-X12','M6-2-u5-X01']::text[],true,'{"seq":3,"concept":"M6-2-u5-C3","difficulty":1,"kind":"mc","stem":"반지름이 9 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"56.52 cm","correct":true},{"t":"28.26 cm","mis":"M6-2-u5-X07"},{"t":"254.34 cm","mis":"M6-2-u5-X12"},{"t":"113.04 cm","mis":"M6-2-u5-X01"}],"explanation":["반지름에 바로 원주율을 곱하면 안 돼요.","반지름 9 cm에 2를 곱해 지름 18 cm를 먼저 만들어요.","18 × 3.14 = 56.52 — 원주는 56.52 cm예요."],"variant_rule":{"alt":[{"stem":"반지름이 6 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"37.68 cm","correct":true},{"t":"18.84 cm","mis":"M6-2-u5-X07"},{"t":"113.04 cm","mis":"M6-2-u5-X12"},{"t":"75.36 cm","mis":"M6-2-u5-X01"}],"explanation":["반지름에 바로 원주율을 곱하면 안 돼요.","반지름 6 cm에 2를 곱해 지름 12 cm를 먼저 만들어요.","12 × 3.14 = 37.68 — 원주는 37.68 cm예요."]},{"stem":"반지름이 2 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"12.56 cm","correct":true},{"t":"6.28 cm","mis":"M6-2-u5-X07"},{"t":"25.12 cm","mis":"M6-2-u5-X01"},{"t":"3.14 cm","mis":"M6-2-u5-X07"}],"explanation":["반지름에 바로 원주율을 곱하면 안 돼요.","반지름 2 cm에 2를 곱해 지름 4 cm를 먼저 만들어요.","4 × 3.14 = 12.56 — 원주는 12.56 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_b#4','math',6,2,'u5','','tb_g6_2_math_u5_review_b','unit_review','M6-2-u5-C6',1,'mc','auto','반지름이 5 cm인 원의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X12','M6-2-u5-X14','M6-2-u5-X13']::text[],true,'{"seq":4,"concept":"M6-2-u5-C6","difficulty":1,"kind":"mc","stem":"반지름이 5 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"78.5 cm²","correct":true},{"t":"31.4 cm²","mis":"M6-2-u5-X12"},{"t":"15.7 cm²","mis":"M6-2-u5-X14"},{"t":"314 cm²","mis":"M6-2-u5-X13"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","5 × 5 × 3.14를 계산해요.","5 × 5 × 3.14 = 78.5 — 넓이는 78.5 cm²예요."],"variant_rule":{"alt":[{"stem":"반지름이 3 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"28.26 cm²","correct":true},{"t":"18.84 cm²","mis":"M6-2-u5-X12"},{"t":"9.42 cm²","mis":"M6-2-u5-X14"},{"t":"113.04 cm²","mis":"M6-2-u5-X13"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","3 × 3 × 3.14를 계산해요.","3 × 3 × 3.14 = 28.26 — 넓이는 28.26 cm²예요."]},{"stem":"반지름이 9 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"254.34 cm²","correct":true},{"t":"56.52 cm²","mis":"M6-2-u5-X12"},{"t":"28.26 cm²","mis":"M6-2-u5-X14"},{"t":"1017.36 cm²","mis":"M6-2-u5-X13"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","9 × 9 × 3.14를 계산해요.","9 × 9 × 3.14 = 254.34 — 넓이는 254.34 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_b#5','math',6,2,'u5','','tb_g6_2_math_u5_review_b','unit_review','M6-2-u5-C6',1,'mc','auto','지름이 20 cm인 원의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X13','M6-2-u5-X12','M6-2-u5-X14']::text[],true,'{"seq":5,"concept":"M6-2-u5-C6","difficulty":1,"kind":"mc","stem":"지름이 20 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"314 cm²","correct":true},{"t":"1256 cm²","mis":"M6-2-u5-X13"},{"t":"62.8 cm²","mis":"M6-2-u5-X12"},{"t":"31.4 cm²","mis":"M6-2-u5-X14"}],"explanation":["넓이는 반지름으로 구해요 — 반지름은 20 ÷ 2 = 10 cm예요.","10 × 10 × 3.14를 계산해요.","10 × 10 × 3.14 = 314 — 넓이는 314 cm²예요."],"variant_rule":{"alt":[{"stem":"지름이 12 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"113.04 cm²","correct":true},{"t":"452.16 cm²","mis":"M6-2-u5-X13"},{"t":"37.68 cm²","mis":"M6-2-u5-X12"},{"t":"18.84 cm²","mis":"M6-2-u5-X14"}],"explanation":["넓이는 반지름으로 구해요 — 반지름은 12 ÷ 2 = 6 cm예요.","6 × 6 × 3.14를 계산해요.","6 × 6 × 3.14 = 113.04 — 넓이는 113.04 cm²예요."]},{"stem":"지름이 32 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"803.84 cm²","correct":true},{"t":"3215.36 cm²","mis":"M6-2-u5-X13"},{"t":"100.48 cm²","mis":"M6-2-u5-X12"},{"t":"50.24 cm²","mis":"M6-2-u5-X14"}],"explanation":["넓이는 반지름으로 구해요 — 반지름은 32 ÷ 2 = 16 cm예요.","16 × 16 × 3.14를 계산해요.","16 × 16 × 3.14 = 803.84 — 넓이는 803.84 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_b#6','math',6,2,'u5','','tb_g6_2_math_u5_review_b','unit_review','M6-2-u5-C4',1,'sa','auto','원 모양 호수의 둘레가 157 m예요. 호수의 중심을 지나는 다리의 길이는 몇 m인가요?','{}'::text[],true,'{"seq":6,"concept":"M6-2-u5-C4","difficulty":1,"kind":"sa","stem":"원 모양 호수의 둘레가 157 m예요. 호수의 중심을 지나는 다리의 길이는 몇 m인가요?","answer":["50"],"explanation":["(지름) = (원주) ÷ (원주율)이에요.","157 ÷ 3.14를 계산해요.","157 ÷ 3.14 = 50이에요."],"variant_rule":{"alt":[{"stem":"원 모양 접시의 원주를 재었더니 31.4 cm였어요. 이 접시의 지름은 몇 cm인가요?","answer":["10"],"explanation":["(지름) = (원주) ÷ (원주율)이에요.","31.4 ÷ 3.14를 계산해요.","31.4 ÷ 3.14 = 10이에요."]},{"stem":"원 모양 컵 받침의 둘레가 25.12 cm예요. 컵 받침의 지름은 몇 cm인가요?","answer":["8"],"explanation":["(지름) = (원주) ÷ (원주율)이에요.","25.12 ÷ 3.14를 계산해요.","25.12 ÷ 3.14 = 8이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_b#7','math',6,2,'u5','','tb_g6_2_math_u5_review_b','unit_review','M6-2-u5-C2',1,'mc','auto','원주율에 대한 설명으로 잘못된 문장은 어느 것인가요?',ARRAY['M6-2-u5-X19']::text[],true,'{"seq":7,"concept":"M6-2-u5-C2","difficulty":1,"kind":"mc","stem":"원주율에 대한 설명으로 잘못된 문장은 어느 것인가요?","options":[{"t":"원주에 대한 원의 지름의 비율을 원주율이라고 합니다.","correct":true},{"t":"원의 크기가 달라져도 원주율은 일정합니다.","mis":"M6-2-u5-X19"},{"t":"반지름이 길어지면 원주도 길어집니다.","mis":"M6-2-u5-X19"},{"t":"원주율을 소수로 나타내면 끝없이 계속됩니다.","mis":"M6-2-u5-X19"}],"explanation":["보기를 하나씩 원주율의 뜻과 견주어 봐요.","원주율은 지름에 대한 원주의 비율 — 기준량이 지름이에요.","나머지 세 문장은 모두 바른 설명이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 원주율에 대한 설명으로 잘못된 문장은 어느 것인가요?","options":[{"t":"원주율은 정확히 3.14입니다.","correct":true},{"t":"원주율은 원의 크기와 상관없이 일정합니다.","mis":"M6-2-u5-X19"},{"t":"원주율은 (원주) ÷ (지름)으로 구합니다.","mis":"M6-2-u5-X19"},{"t":"원주는 지름의 3배보다 길고 4배보다 짧습니다.","mis":"M6-2-u5-X19"}],"explanation":["보기를 하나씩 원주율의 뜻과 견주어 봐요.","3.14는 끝없이 이어지는 원주율을 어림한 값이에요.","나머지 세 문장은 모두 바른 설명이에요."]},{"stem":"이번에는 다른 보기예요. 원주율에 대한 설명으로 잘못된 문장은 어느 것인가요?","options":[{"t":"원의 지름에 대한 원주의 비율은 지름마다 다릅니다.","correct":true},{"t":"지름이 길어지면 원주도 길어집니다.","mis":"M6-2-u5-X19"},{"t":"원주는 지름의 약 3.14배입니다.","mis":"M6-2-u5-X19"},{"t":"원주율을 소수로 나타내면 끝없이 계속됩니다.","mis":"M6-2-u5-X19"}],"explanation":["보기를 하나씩 원주율의 뜻과 견주어 봐요.","지름에 대한 원주의 비율(원주율)은 모든 원에서 일정해요.","나머지 세 문장은 모두 바른 설명이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_b#8','math',6,2,'u5','','tb_g6_2_math_u5_review_b','unit_review','M6-2-u5-C2',1,'mc','auto','지름이 20 cm인 원의 원주는 62.8 cm예요. 원주는 지름의 약 몇 배인가요?',ARRAY['M6-2-u5-X04','M6-2-u5-X02']::text[],true,'{"seq":8,"concept":"M6-2-u5-C2","difficulty":1,"kind":"mc","stem":"지름이 20 cm인 원의 원주는 62.8 cm예요. 원주는 지름의 약 몇 배인가요?","options":[{"t":"약 3.14배","correct":true},{"t":"약 6.28배","mis":"M6-2-u5-X04"},{"t":"약 0.32배","mis":"M6-2-u5-X04"},{"t":"약 4배","mis":"M6-2-u5-X02"}],"explanation":["(원주) ÷ (지름)을 계산해요.","62.8 ÷ 20 = 3.14예요.","원주는 지름의 약 3.14배 — 이 값이 원주율이에요."],"variant_rule":{"alt":[{"stem":"지름이 15 cm인 원의 원주는 47.1 cm예요. 원주는 지름의 약 몇 배인가요?","options":[{"t":"약 3.14배","correct":true},{"t":"약 6.28배","mis":"M6-2-u5-X04"},{"t":"약 0.32배","mis":"M6-2-u5-X04"},{"t":"약 4배","mis":"M6-2-u5-X02"}],"explanation":["(원주) ÷ (지름)을 계산해요.","47.1 ÷ 15 = 3.14예요.","원주는 지름의 약 3.14배 — 이 값이 원주율이에요."]},{"stem":"지름이 7 cm인 원의 원주는 21.98 cm예요. 원주는 지름의 약 몇 배인가요?","options":[{"t":"약 3.14배","correct":true},{"t":"약 6.28배","mis":"M6-2-u5-X04"},{"t":"약 0.32배","mis":"M6-2-u5-X04"},{"t":"약 4배","mis":"M6-2-u5-X02"}],"explanation":["(원주) ÷ (지름)을 계산해요.","21.98 ÷ 7 = 3.14예요.","원주는 지름의 약 3.14배 — 이 값이 원주율이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_b#9','math',6,2,'u5','','tb_g6_2_math_u5_review_b','unit_review','M6-2-u5-C7',2,'sa','auto','한 변이 20 cm인 정사각형의 네 꼭짓점을 중심으로 반지름이 10 cm인 사분원을 그렸어요. 사분원 4개를 뺀 가운데 초록색 부분의 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":9,"concept":"M6-2-u5-C7","difficulty":2,"kind":"sa","stem":"한 변이 20 cm인 정사각형의 네 꼭짓점을 중심으로 반지름이 10 cm인 사분원을 그렸어요. 사분원 4개를 뺀 가운데 초록색 부분의 넓이는 몇 cm²인가요?","answer":["86"],"explanation":["정사각형의 넓이는 20 × 20 = 400 cm²예요.","사분원 4개는 반지름 10 cm인 원 하나 — 314 cm²예요.","400 − 314 = 86 cm²예요."],"variant_rule":{"alt":[{"stem":"꽃밭은 가로 20 m, 세로 10 m인 직사각형의 위쪽에 반원만큼 볼록하고 아래쪽은 같은 크기의 반원만큼 패여 있어요. 꽃밭의 넓이는 몇 m²인가요?","answer":["200"],"explanation":["볼록한 반원을 패인 곳으로 옮겨요.","그러면 가로 20 m, 세로 10 m인 직사각형이 돼요.","20 × 10 = 200 m²예요."]},{"stem":"아랫부분이 반원만큼 패이고 윗부분이 반원만큼 볼록한 모양이 있어요. 아랫부분의 반원을 윗부분으로 옮겼더니 가로 10 cm, 세로 5 cm인 직사각형이 되었어요. 처음 모양의 넓이는 몇 cm²인가요?","answer":["50"],"explanation":["조각을 더하지도 덜지도 않고 자리만 옮겼어요.","그래서 넓이는 직사각형과 같아요.","10 × 5 = 50 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_b#10','math',6,2,'u5','','tb_g6_2_math_u5_review_b','unit_review','M6-2-u5-C6',2,'mc','auto','가로가 12 cm, 세로가 15 cm인 직사각형 종이를 잘라 만들 수 있는 가장 큰 원의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X21','M6-2-u5-X13','M6-2-u5-X12']::text[],true,'{"seq":10,"concept":"M6-2-u5-C6","difficulty":2,"kind":"mc","stem":"가로가 12 cm, 세로가 15 cm인 직사각형 종이를 잘라 만들 수 있는 가장 큰 원의 넓이는 몇 cm²인가요?","options":[{"t":"113.04 cm²","correct":true},{"t":"176.625 cm²","mis":"M6-2-u5-X21"},{"t":"452.16 cm²","mis":"M6-2-u5-X13"},{"t":"37.68 cm²","mis":"M6-2-u5-X12"}],"explanation":["가장 큰 원의 지름은 짧은 변 12 cm를 넘을 수 없어요.","반지름은 6 cm예요.","6 × 6 × 3.14 = 113.04 cm²예요."],"variant_rule":{"alt":[{"stem":"가로가 14 cm, 세로가 20 cm인 직사각형 종이를 잘라 만들 수 있는 가장 큰 원의 넓이는 몇 cm²인가요?","options":[{"t":"153.86 cm²","correct":true},{"t":"314 cm²","mis":"M6-2-u5-X21"},{"t":"615.44 cm²","mis":"M6-2-u5-X13"},{"t":"43.96 cm²","mis":"M6-2-u5-X12"}],"explanation":["가장 큰 원의 지름은 짧은 변 14 cm를 넘을 수 없어요.","반지름은 7 cm예요.","7 × 7 × 3.14 = 153.86 cm²예요."]},{"stem":"가로가 15 cm, 세로가 12 cm인 직사각형 종이를 잘라 만들 수 있는 가장 큰 원의 넓이는 몇 cm²인가요?","options":[{"t":"113.04 cm²","correct":true},{"t":"176.625 cm²","mis":"M6-2-u5-X21"},{"t":"452.16 cm²","mis":"M6-2-u5-X13"},{"t":"37.68 cm²","mis":"M6-2-u5-X12"}],"explanation":["가장 큰 원의 지름은 짧은 변 12 cm를 넘을 수 없어요.","반지름은 6 cm예요.","6 × 6 × 3.14 = 113.04 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_b#11','math',6,2,'u5','','tb_g6_2_math_u5_review_b','unit_review','M6-2-u5-C3',2,'mc','auto','바깥쪽 원의 지름이 40 cm인 굴렁쇠를 3바퀴 굴렸어요. 이 굴렁쇠가 굴러간 거리는 몇 m인가요?',ARRAY['M6-2-u5-X20','M6-2-u5-X19','M6-2-u5-X07']::text[],true,'{"seq":11,"concept":"M6-2-u5-C3","difficulty":2,"kind":"mc","stem":"바깥쪽 원의 지름이 40 cm인 굴렁쇠를 3바퀴 굴렸어요. 이 굴렁쇠가 굴러간 거리는 몇 m인가요?","options":[{"t":"3.768 m","correct":true},{"t":"376.8 m","mis":"M6-2-u5-X20"},{"t":"1.256 m","mis":"M6-2-u5-X19"},{"t":"1.884 m","mis":"M6-2-u5-X07"}],"explanation":["한 바퀴 굴러간 거리는 40 × 3.14 = 125.6 cm예요.","3바퀴면 125.6 × 3 = 376.8 cm예요.","100 cm = 1 m니 3.768 m예요."],"variant_rule":{"alt":[{"stem":"바깥쪽 원의 지름이 20 cm인 원판을 10바퀴 굴렸어요. 이 원판이 굴러간 거리는 몇 m인가요?","options":[{"t":"6.28 m","correct":true},{"t":"628 m","mis":"M6-2-u5-X20"},{"t":"0.628 m","mis":"M6-2-u5-X19"},{"t":"3.14 m","mis":"M6-2-u5-X07"}],"explanation":["한 바퀴 굴러간 거리는 20 × 3.14 = 62.8 cm예요.","10바퀴면 62.8 × 10 = 628 cm예요.","100 cm = 1 m니 6.28 m예요."]},{"stem":"바깥쪽 원의 지름이 48 cm인 굴렁쇠를 3바퀴 굴렸어요. 이 굴렁쇠가 굴러간 거리는 몇 m인가요?","options":[{"t":"4.5216 m","correct":true},{"t":"452.16 m","mis":"M6-2-u5-X20"},{"t":"1.5072 m","mis":"M6-2-u5-X19"},{"t":"2.2608 m","mis":"M6-2-u5-X07"}],"explanation":["한 바퀴 굴러간 거리는 48 × 3.14 = 150.72 cm예요.","3바퀴면 150.72 × 3 = 452.16 cm예요.","100 cm = 1 m니 4.5216 m예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_b#12','math',6,2,'u5','','tb_g6_2_math_u5_review_b','unit_review','M6-2-u5-C2',2,'mc','auto','「알지오매스 키즈」로 반지름이 5 cm인 원 안쪽에 맞닿는 정육각형을 그렸더니 둘레가 30 cm였어요. (정육각형의 둘레) ÷ (지름)은 얼마인가요?',ARRAY['M6-2-u5-X04','M6-2-u5-X23','M6-2-u5-X20']::text[],true,'{"seq":12,"concept":"M6-2-u5-C2","difficulty":2,"kind":"mc","stem":"「알지오매스 키즈」로 반지름이 5 cm인 원 안쪽에 맞닿는 정육각형을 그렸더니 둘레가 30 cm였어요. (정육각형의 둘레) ÷ (지름)은 얼마인가요?","options":[{"t":"3","correct":true},{"t":"6","mis":"M6-2-u5-X04"},{"t":"3.14","mis":"M6-2-u5-X23"},{"t":"0.3","mis":"M6-2-u5-X20"}],"explanation":["원의 반지름이 5 cm니 지름은 10 cm예요.","30 ÷ 10 = 3이에요.","원 안쪽 다각형의 둘레는 원주보다 짧아서 이 값은 원주율 3.14보다 작아요."],"variant_rule":{"alt":[{"stem":"「알지오매스 키즈」로 반지름이 5 cm인 원 안쪽에 맞닿는 정십이각형을 그렸더니 둘레가 31.08 cm였어요. (정십이각형의 둘레) ÷ (지름)은 얼마인가요?","options":[{"t":"3.108","correct":true},{"t":"6.216","mis":"M6-2-u5-X04"},{"t":"3.14","mis":"M6-2-u5-X23"},{"t":"0.3108","mis":"M6-2-u5-X20"}],"explanation":["원의 반지름이 5 cm니 지름은 10 cm예요.","31.08 ÷ 10 = 3.108이에요.","원 안쪽 다각형의 둘레는 원주보다 짧아서 이 값은 원주율 3.14보다 작아요."]},{"stem":"「알지오매스 키즈」로 반지름이 5 cm인 원 안쪽에 맞닿는 정이십이각형을 그렸더니 둘레가 31.24 cm였어요. (정이십이각형의 둘레) ÷ (지름)은 얼마인가요?","options":[{"t":"3.124","correct":true},{"t":"6.248","mis":"M6-2-u5-X04"},{"t":"3.14","mis":"M6-2-u5-X23"},{"t":"0.3124","mis":"M6-2-u5-X20"}],"explanation":["원의 반지름이 5 cm니 지름은 10 cm예요.","31.24 ÷ 10 = 3.124예요.","원 안쪽 다각형의 둘레는 원주보다 짧아서 이 값은 원주율 3.14보다 작아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_b#13','math',6,2,'u5','','tb_g6_2_math_u5_review_b','unit_review','M6-2-u5-C2',2,'mc','auto','원 안쪽에 맞닿는 정다각형의 변의 수가 늘어날수록 (정다각형의 둘레) ÷ (지름)은 어떻게 되나요?',ARRAY['M6-2-u5-X23']::text[],true,'{"seq":13,"concept":"M6-2-u5-C2","difficulty":2,"kind":"mc","stem":"원 안쪽에 맞닿는 정다각형의 변의 수가 늘어날수록 (정다각형의 둘레) ÷ (지름)은 어떻게 되나요?","options":[{"t":"원주율 3.14에 가까워져요","correct":true},{"t":"점점 작아져요","mis":"M6-2-u5-X23"},{"t":"변하지 않아요","mis":"M6-2-u5-X23"},{"t":"원주율보다 커져요","mis":"M6-2-u5-X23"}],"explanation":["반지름 5 cm인 원에서 2.828 → 3 → 3.108 → 3.124로 커졌어요.","정다각형이 원에 가까워지니 둘레도 원주에 가까워져요.","그래서 (둘레) ÷ (지름)은 원주율 3.14에 가까워져요."],"variant_rule":{"alt":[{"stem":"반지름이 5 cm인 원 안쪽에 맞닿는 정이십이각형의 (둘레) ÷ (지름)은 3.124예요. 원주율과 견주면 어떤가요?","options":[{"t":"원주율보다 조금 작아요","correct":true},{"t":"원주율과 똑같아요","mis":"M6-2-u5-X23"},{"t":"원주율보다 커요","mis":"M6-2-u5-X23"},{"t":"원주율의 2배쯤이에요","mis":"M6-2-u5-X04"}],"explanation":["정이십이각형은 원 안쪽에 맞닿아 있어요.","원 안쪽 다각형의 둘레는 원주보다 조금 짧아요.","그래서 3.124는 원주율 3.14보다 조금 작아요."]},{"stem":"반지름이 5 cm인 원 안쪽에 맞닿는 정십이각형과 정이십이각형의 (둘레) ÷ (지름)은 3.108과 3.124예요. 원주율에 더 가까운 것은 어느 것인가요?","options":[{"t":"정이십이각형","correct":true},{"t":"정십이각형","mis":"M6-2-u5-X23"},{"t":"두 값이 똑같이 가까워요","mis":"M6-2-u5-X23"},{"t":"알 수 없어요","mis":"M6-2-u5-X19"}],"explanation":["3.14 − 3.108 = 0.032예요.","3.14 − 3.124 = 0.016이에요.","변의 수가 더 많은 정이십이각형이 원주율에 더 가까워요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_b#14','math',6,2,'u5','','tb_g6_2_math_u5_review_b','unit_review','M6-2-u5-C4',2,'mc','auto','지름이 22 cm인 원과 원주가 81.64 cm인 원이 있어요. 크기가 더 큰 원은 어느 것인가요?',ARRAY['M6-2-u5-X08','M6-2-u5-X20','M6-2-u5-X19']::text[],true,'{"seq":14,"concept":"M6-2-u5-C4","difficulty":2,"kind":"mc","stem":"지름이 22 cm인 원과 원주가 81.64 cm인 원이 있어요. 크기가 더 큰 원은 어느 것인가요?","options":[{"t":"원주가 81.64 cm인 원","correct":true},{"t":"지름이 22 cm인 원","mis":"M6-2-u5-X08"},{"t":"두 원의 크기가 같아요","mis":"M6-2-u5-X20"},{"t":"견줄 수 없어요","mis":"M6-2-u5-X19"}],"explanation":["같은 것끼리 견주려고 원주를 지름으로 바꾸어요.","81.64 ÷ 3.14 = 26 — 원주가 81.64 cm인 원의 지름은 26 cm예요.","지름 22 cm와 26 cm를 견주면 원주가 81.64 cm인 원이 더 커요."],"variant_rule":{"alt":[{"stem":"지름이 10 cm인 원과 원주가 37.68 cm인 원이 있어요. 크기가 더 큰 원은 어느 것인가요?","options":[{"t":"원주가 37.68 cm인 원","correct":true},{"t":"지름이 10 cm인 원","mis":"M6-2-u5-X08"},{"t":"두 원의 크기가 같아요","mis":"M6-2-u5-X20"},{"t":"견줄 수 없어요","mis":"M6-2-u5-X19"}],"explanation":["같은 것끼리 견주려고 원주를 지름으로 바꾸어요.","37.68 ÷ 3.14 = 12 — 원주가 37.68 cm인 원의 지름은 12 cm예요.","지름 10 cm와 12 cm를 견주면 원주가 37.68 cm인 원이 더 커요."]},{"stem":"지름이 8 cm인 원과 원주가 31.4 cm인 원이 있어요. 크기가 더 큰 원은 어느 것인가요?","options":[{"t":"원주가 31.4 cm인 원","correct":true},{"t":"지름이 8 cm인 원","mis":"M6-2-u5-X08"},{"t":"두 원의 크기가 같아요","mis":"M6-2-u5-X20"},{"t":"견줄 수 없어요","mis":"M6-2-u5-X19"}],"explanation":["같은 것끼리 견주려고 원주를 지름으로 바꾸어요.","31.4 ÷ 3.14 = 10 — 원주가 31.4 cm인 원의 지름은 10 cm예요.","지름 8 cm와 10 cm를 견주면 원주가 31.4 cm인 원이 더 커요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_b#15','math',6,2,'u5','','tb_g6_2_math_u5_review_b','unit_review','M6-2-u5-C5',2,'mc','auto','지름이 12 cm인 원의 넓이를 원 안과 밖에 꼭 맞는 정사각형으로 어림했어요. 알맞은 범위는 어느 것인가요?',ARRAY['M6-2-u5-X11','M6-2-u5-X01','M6-2-u5-X12']::text[],true,'{"seq":15,"concept":"M6-2-u5-C5","difficulty":2,"kind":"mc","stem":"지름이 12 cm인 원의 넓이를 원 안과 밖에 꼭 맞는 정사각형으로 어림했어요. 알맞은 범위는 어느 것인가요?","options":[{"t":"72 cm²보다 넓고 144 cm²보다 좁아요","correct":true},{"t":"36 cm²보다 넓고 72 cm²보다 좁아요","mis":"M6-2-u5-X11"},{"t":"144 cm²보다 넓고 288 cm²보다 좁아요","mis":"M6-2-u5-X01"},{"t":"12 cm²보다 넓고 24 cm²보다 좁아요","mis":"M6-2-u5-X12"}],"explanation":["반지름은 6 cm예요.","원 안 정사각형은 6 × 6 × 2 = 72 cm², 원 밖 정사각형은 6 × 6 × 4 = 144 cm²예요.","원의 넓이는 그 사이 — 72 cm²보다 넓고 144 cm²보다 좁아요."],"variant_rule":{"alt":[{"stem":"지름이 20 cm인 원의 넓이를 원 안과 밖에 꼭 맞는 정사각형으로 어림했어요. 알맞은 범위는 어느 것인가요?","options":[{"t":"200 cm²보다 넓고 400 cm²보다 좁아요","correct":true},{"t":"100 cm²보다 넓고 200 cm²보다 좁아요","mis":"M6-2-u5-X11"},{"t":"400 cm²보다 넓고 800 cm²보다 좁아요","mis":"M6-2-u5-X01"},{"t":"20 cm²보다 넓고 40 cm²보다 좁아요","mis":"M6-2-u5-X12"}],"explanation":["반지름은 10 cm예요.","원 안 정사각형은 10 × 10 × 2 = 200 cm², 원 밖 정사각형은 10 × 10 × 4 = 400 cm²예요.","원의 넓이는 그 사이 — 200 cm²보다 넓고 400 cm²보다 좁아요."]},{"stem":"지름이 10 cm인 원의 넓이를 원 안과 밖에 꼭 맞는 정사각형으로 어림했어요. 알맞은 범위는 어느 것인가요?","options":[{"t":"50 cm²보다 넓고 100 cm²보다 좁아요","correct":true},{"t":"25 cm²보다 넓고 50 cm²보다 좁아요","mis":"M6-2-u5-X11"},{"t":"100 cm²보다 넓고 200 cm²보다 좁아요","mis":"M6-2-u5-X01"},{"t":"10 cm²보다 넓고 20 cm²보다 좁아요","mis":"M6-2-u5-X12"}],"explanation":["반지름은 5 cm예요.","원 안 정사각형은 5 × 5 × 2 = 50 cm², 원 밖 정사각형은 5 × 5 × 4 = 100 cm²예요.","원의 넓이는 그 사이 — 50 cm²보다 넓고 100 cm²보다 좁아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_b#16','math',6,2,'u5','','tb_g6_2_math_u5_review_b','unit_review','M6-2-u5-C7',2,'mc','auto','반지름이 7 cm인 원에서 반지름이 4 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X16','M6-2-u5-X20']::text[],true,'{"seq":16,"concept":"M6-2-u5-C7","difficulty":2,"kind":"mc","stem":"반지름이 7 cm인 원에서 반지름이 4 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?","options":[{"t":"103.62 cm²","correct":true},{"t":"153.86 cm²","mis":"M6-2-u5-X16"},{"t":"28.26 cm²","mis":"M6-2-u5-X16"},{"t":"204.1 cm²","mis":"M6-2-u5-X20"}],"explanation":["큰 원의 넓이는 7 × 7 × 3.14 = 153.86 cm²예요.","작은 원의 넓이는 4 × 4 × 3.14 = 50.24 cm²예요.","153.86 − 50.24 = 103.62 cm²예요."],"variant_rule":{"alt":[{"stem":"반지름이 10 cm인 원에서 반지름이 7 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?","options":[{"t":"160.14 cm²","correct":true},{"t":"314 cm²","mis":"M6-2-u5-X16"},{"t":"28.26 cm²","mis":"M6-2-u5-X16"},{"t":"467.86 cm²","mis":"M6-2-u5-X20"}],"explanation":["큰 원의 넓이는 10 × 10 × 3.14 = 314 cm²예요.","작은 원의 넓이는 7 × 7 × 3.14 = 153.86 cm²예요.","314 − 153.86 = 160.14 cm²예요."]},{"stem":"반지름이 12 cm인 원에서 반지름이 6 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?","options":[{"t":"339.12 cm²","correct":true},{"t":"452.16 cm²","mis":"M6-2-u5-X16"},{"t":"113.04 cm²","mis":"M6-2-u5-X16"},{"t":"565.2 cm²","mis":"M6-2-u5-X20"}],"explanation":["큰 원의 넓이는 12 × 12 × 3.14 = 452.16 cm²예요.","작은 원의 넓이는 6 × 6 × 3.14 = 113.04 cm²예요.","452.16 − 113.04 = 339.12 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_b#17','math',6,2,'u5','','tb_g6_2_math_u5_review_b','unit_review','M6-2-u5-C6',3,'mc','auto','원주가 75.36 cm인 원의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X13','M6-2-u5-X12','M6-2-u5-X14']::text[],true,'{"seq":17,"concept":"M6-2-u5-C6","difficulty":3,"kind":"mc","stem":"원주가 75.36 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"452.16 cm²","correct":true},{"t":"1808.64 cm²","mis":"M6-2-u5-X13"},{"t":"75.36 cm²","mis":"M6-2-u5-X12"},{"t":"37.68 cm²","mis":"M6-2-u5-X14"}],"explanation":["지름은 75.36 ÷ 3.14 = 24 cm, 반지름은 12 cm예요.","넓이는 12 × 12 × 3.14예요.","12 × 12 × 3.14 = 452.16 cm²예요."],"variant_rule":{"alt":[{"stem":"원주가 31.4 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"78.5 cm²","correct":true},{"t":"314 cm²","mis":"M6-2-u5-X13"},{"t":"31.4 cm²","mis":"M6-2-u5-X12"},{"t":"15.7 cm²","mis":"M6-2-u5-X14"}],"explanation":["지름은 31.4 ÷ 3.14 = 10 cm, 반지름은 5 cm예요.","넓이는 5 × 5 × 3.14예요.","5 × 5 × 3.14 = 78.5 cm²예요."]},{"stem":"원주가 43.96 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"153.86 cm²","correct":true},{"t":"615.44 cm²","mis":"M6-2-u5-X13"},{"t":"43.96 cm²","mis":"M6-2-u5-X12"},{"t":"21.98 cm²","mis":"M6-2-u5-X14"}],"explanation":["지름은 43.96 ÷ 3.14 = 14 cm, 반지름은 7 cm예요.","넓이는 7 × 7 × 3.14예요.","7 × 7 × 3.14 = 153.86 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_b#18','math',6,2,'u5','','tb_g6_2_math_u5_review_b','unit_review','M6-2-u5-C6',3,'mc','auto','넓이가 넓은 원부터 차례로 놓으려고 해요. ㉠ 지름이 22 cm인 원 · ㉡ 반지름이 9 cm인 원 · ㉢ 넓이가 452.16 cm²인 원 — 바르게 놓은 것은 어느 것인가요?',ARRAY['M6-2-u5-X19','M6-2-u5-X13']::text[],true,'{"seq":18,"concept":"M6-2-u5-C6","difficulty":3,"kind":"mc","stem":"넓이가 넓은 원부터 차례로 놓으려고 해요. ㉠ 지름이 22 cm인 원 · ㉡ 반지름이 9 cm인 원 · ㉢ 넓이가 452.16 cm²인 원 — 바르게 놓은 것은 어느 것인가요?","options":[{"t":"㉢, ㉠, ㉡","correct":true},{"t":"㉡, ㉠, ㉢","mis":"M6-2-u5-X19"},{"t":"㉠, ㉡, ㉢","mis":"M6-2-u5-X13"},{"t":"㉡, ㉢, ㉠","mis":"M6-2-u5-X13"}],"explanation":["세 원의 넓이를 모두 구해 견주어요.","㉠ 379.94 cm² · ㉡ 254.34 cm² · ㉢ 452.16 cm²예요.","넓은 원부터 놓으면 ㉢, ㉠, ㉡이에요."],"variant_rule":{"alt":[{"stem":"넓이가 넓은 원부터 차례로 놓으려고 해요. ㉠ 지름이 20 cm인 원 · ㉡ 반지름이 9 cm인 원 · ㉢ 원주가 75.36 cm인 원 — 바르게 놓은 것은 어느 것인가요?","options":[{"t":"㉢, ㉠, ㉡","correct":true},{"t":"㉡, ㉠, ㉢","mis":"M6-2-u5-X19"},{"t":"㉠, ㉡, ㉢","mis":"M6-2-u5-X13"},{"t":"㉡, ㉢, ㉠","mis":"M6-2-u5-X13"}],"explanation":["세 원의 넓이를 모두 구해 견주어요.","㉠ 314 cm² · ㉡ 254.34 cm² · ㉢ 452.16 cm²예요.","넓은 원부터 놓으면 ㉢, ㉠, ㉡이에요."]},{"stem":"넓이가 넓은 원부터 차례로 놓으려고 해요. ㉠ 반지름이 8 cm인 원 · ㉡ 지름이 14 cm인 원 · ㉢ 넓이가 314 cm²인 원 — 바르게 놓은 것은 어느 것인가요?","options":[{"t":"㉢, ㉠, ㉡","correct":true},{"t":"㉢, ㉡, ㉠","mis":"M6-2-u5-X01"},{"t":"㉡, ㉠, ㉢","mis":"M6-2-u5-X19"},{"t":"㉠, ㉡, ㉢","mis":"M6-2-u5-X13"}],"explanation":["세 원의 넓이를 모두 구해 견주어요.","㉠ 200.96 cm² · ㉡ 153.86 cm² · ㉢ 314 cm²예요.","넓은 원부터 놓으면 ㉢, ㉠, ㉡이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_b#19','math',6,2,'u5','','tb_g6_2_math_u5_review_b','unit_review','M6-2-u5-C7',3,'mc','auto','지름이 30 cm인 큰 원 안에 지름이 20 cm인 원과 지름이 10 cm인 원이 나란히 꼭 맞게 들어 있어요. 큰 원에서 두 원을 뺀 부분의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X17','M6-2-u5-X13']::text[],true,'{"seq":19,"concept":"M6-2-u5-C7","difficulty":3,"kind":"mc","stem":"지름이 30 cm인 큰 원 안에 지름이 20 cm인 원과 지름이 10 cm인 원이 나란히 꼭 맞게 들어 있어요. 큰 원에서 두 원을 뺀 부분의 넓이는 몇 cm²인가요?","options":[{"t":"314 cm²","correct":true},{"t":"392.5 cm²","mis":"M6-2-u5-X17"},{"t":"628 cm²","mis":"M6-2-u5-X17"},{"t":"1256 cm²","mis":"M6-2-u5-X13"}],"explanation":["큰 원은 15 × 15 × 3.14 = 706.5 cm²예요.","두 원은 314 cm²와 78.5 cm²예요.","706.5 − 314 − 78.5 = 314 cm²예요."],"variant_rule":{"alt":[{"stem":"반지름이 12 cm인 큰 원 안에 반지름이 6 cm인 원 두 개가 들어 있어요. 큰 원에서 작은 원 두 개를 뺀 부분의 넓이는 몇 cm²인가요?","options":[{"t":"226.08 cm²","correct":true},{"t":"339.12 cm²","mis":"M6-2-u5-X17"},{"t":"452.16 cm²","mis":"M6-2-u5-X16"},{"t":"113.04 cm²","mis":"M6-2-u5-X19"}],"explanation":["큰 원은 12 × 12 × 3.14 = 452.16 cm²예요.","작은 원 하나는 6 × 6 × 3.14 = 113.04 cm², 두 개는 226.08 cm²예요.","452.16 − 226.08 = 226.08 cm²예요."]},{"stem":"지름이 12 cm인 반원이 있어요. 반원의 지름 위 한쪽에는 지름이 6 cm인 반원이 볼록하게 붙어 있고, 다른 쪽은 같은 크기의 반원만큼 패여 있어요. 이 모양의 넓이는 몇 cm²인가요?","options":[{"t":"56.52 cm²","correct":true},{"t":"70.65 cm²","mis":"M6-2-u5-X17"},{"t":"42.39 cm²","mis":"M6-2-u5-X17"},{"t":"113.04 cm²","mis":"M6-2-u5-X17"}],"explanation":["볼록한 반원과 패인 반원은 크기가 같아요.","볼록한 반원을 떼어 패인 곳에 옮기면 반지름 6 cm인 반원 하나가 돼요.","6 × 6 × 3.14 ÷ 2 = 56.52 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_b#20','math',6,2,'u5','','tb_g6_2_math_u5_review_b','unit_review','M6-2-u5-C6',3,'sa','auto','넓이가 314 cm²인 원이 있어요. 이 원의 반지름은 몇 cm인가요?','{}'::text[],true,'{"seq":20,"concept":"M6-2-u5-C6","difficulty":3,"kind":"sa","stem":"넓이가 314 cm²인 원이 있어요. 이 원의 반지름은 몇 cm인가요?","answer":["10"],"explanation":["(반지름) × (반지름) × 3.14 = 314예요.","314 ÷ 3.14 = 100이니 (반지름) × (반지름) = 100이에요.","같은 수를 두 번 곱해 100이 되는 수는 10 — 반지름은 10 cm예요."],"variant_rule":{"alt":[{"stem":"넓이가 78.5 cm²인 원이 있어요. 이 원의 반지름은 몇 cm인가요?","answer":["5"],"explanation":["(반지름) × (반지름) × 3.14 = 78.5예요.","78.5 ÷ 3.14 = 25니 (반지름) × (반지름) = 25예요.","같은 수를 두 번 곱해 25가 되는 수는 5 — 반지름은 5 cm예요."]},{"stem":"넓이가 28.26 cm²인 원이 있어요. 이 원의 반지름은 몇 cm인가요?","answer":["3"],"explanation":["(반지름) × (반지름) × 3.14 = 28.26이에요.","28.26 ÷ 3.14 = 9니 (반지름) × (반지름) = 9예요.","같은 수를 두 번 곱해 9가 되는 수는 3 — 반지름은 3 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_b#21','math',6,2,'u5','','tb_g6_2_math_u5_review_b','unit_review','M6-2-u5-C8',3,'mc','auto','반지름이 20 cm인 원의 넓이는 반지름이 10 cm인 원의 넓이의 몇 배인가요?',ARRAY['M6-2-u5-X18','M6-2-u5-X20']::text[],true,'{"seq":21,"concept":"M6-2-u5-C8","difficulty":3,"kind":"mc","stem":"반지름이 20 cm인 원의 넓이는 반지름이 10 cm인 원의 넓이의 몇 배인가요?","options":[{"t":"4배","correct":true},{"t":"2배","mis":"M6-2-u5-X18"},{"t":"8배","mis":"M6-2-u5-X20"},{"t":"20배","mis":"M6-2-u5-X20"}],"explanation":["반지름이 20 ÷ 10 = 2배예요.","넓이는 반지름을 두 번 곱하니 2 × 2 = 4배예요.","계산해 봐도 1256 ÷ 314 = 4예요."],"variant_rule":{"alt":[{"stem":"반지름이 30 cm인 원의 넓이는 반지름이 10 cm인 원의 넓이의 몇 배인가요?","options":[{"t":"9배","correct":true},{"t":"3배","mis":"M6-2-u5-X18"},{"t":"6배","mis":"M6-2-u5-X18"},{"t":"27배","mis":"M6-2-u5-X20"}],"explanation":["반지름이 30 ÷ 10 = 3배예요.","넓이는 반지름을 두 번 곱하니 3 × 3 = 9배예요.","계산해 봐도 2826 ÷ 314 = 9예요."]},{"stem":"반지름이 24 cm인 원의 넓이는 반지름이 12 cm인 원의 넓이의 몇 배인가요?","options":[{"t":"4배","correct":true},{"t":"2배","mis":"M6-2-u5-X18"},{"t":"8배","mis":"M6-2-u5-X20"},{"t":"24배","mis":"M6-2-u5-X20"}],"explanation":["반지름이 24 ÷ 12 = 2배예요.","넓이는 반지름을 두 번 곱하니 2 × 2 = 4배예요.","계산해 봐도 1808.64 ÷ 452.16 = 4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_b#22','math',6,2,'u5','','tb_g6_2_math_u5_review_b','unit_review','M6-2-u5-C4',3,'mc','auto','지름이 20 cm인 원판을 몇 바퀴 굴렸더니 628 cm만큼 굴러갔어요. 원판이 굴러간 바퀴 수는 몇 바퀴인가요?',ARRAY['M6-2-u5-X07','M6-2-u5-X01','M6-2-u5-X20']::text[],true,'{"seq":22,"concept":"M6-2-u5-C4","difficulty":3,"kind":"mc","stem":"지름이 20 cm인 원판을 몇 바퀴 굴렸더니 628 cm만큼 굴러갔어요. 원판이 굴러간 바퀴 수는 몇 바퀴인가요?","options":[{"t":"10바퀴","correct":true},{"t":"20바퀴","mis":"M6-2-u5-X07"},{"t":"5바퀴","mis":"M6-2-u5-X01"},{"t":"30바퀴","mis":"M6-2-u5-X20"}],"explanation":["한 바퀴 굴러간 거리는 원판의 원주예요.","지름 20 cm — 원주는 20 × 3.14 = 62.8 cm예요.","628 ÷ 62.8 = 10 — 10바퀴예요."],"variant_rule":{"alt":[{"stem":"지름이 40 cm인 원판을 몇 바퀴 굴렸더니 376.8 cm만큼 굴러갔어요. 원판이 굴러간 바퀴 수는 몇 바퀴인가요?","options":[{"t":"3바퀴","correct":true},{"t":"6바퀴","mis":"M6-2-u5-X07"},{"t":"1.5바퀴","mis":"M6-2-u5-X01"},{"t":"9바퀴","mis":"M6-2-u5-X20"}],"explanation":["한 바퀴 굴러간 거리는 원판의 원주예요.","지름 40 cm — 원주는 40 × 3.14 = 125.6 cm예요.","376.8 ÷ 125.6 = 3 — 3바퀴예요."]},{"stem":"지름이 48 cm인 원판을 몇 바퀴 굴렸더니 753.6 cm만큼 굴러갔어요. 원판이 굴러간 바퀴 수는 몇 바퀴인가요?","options":[{"t":"5바퀴","correct":true},{"t":"10바퀴","mis":"M6-2-u5-X07"},{"t":"2.5바퀴","mis":"M6-2-u5-X01"},{"t":"15바퀴","mis":"M6-2-u5-X20"}],"explanation":["한 바퀴 굴러간 거리는 원판의 원주예요.","지름 48 cm — 원주는 48 × 3.14 = 150.72 cm예요.","753.6 ÷ 150.72 = 5 — 5바퀴예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_b#23','math',6,2,'u5','','tb_g6_2_math_u5_review_b','unit_review','M6-2-u5-C2',4,'essay','teacher','잘못된 문장을 찾고, 바르게 고쳐 써 보세요. ㉠ 지름이 길어지면 원주도 길어집니다. ㉡ 원의 지름에 대한 원주의 비율은 지름마다 다릅니다. ㉢ 원주는 지름의 약 3.14배입니다.','{}'::text[],true,'{"seq":23,"concept":"M6-2-u5-C2","difficulty":4,"kind":"essay","stem":"잘못된 문장을 찾고, 바르게 고쳐 써 보세요. ㉠ 지름이 길어지면 원주도 길어집니다. ㉡ 원의 지름에 대한 원주의 비율은 지름마다 다릅니다. ㉢ 원주는 지름의 약 3.14배입니다.","answer_guide":{"answer":"예: ㉡ — 바른 문장: 원의 지름에 대한 원주의 비율은 일정합니다.","scoring_points":["잘못된 문장(㉡)을 찾았는가","바른 문장으로 고쳐 썼는가","고친 까닭(어떤 원을 재어도 (원주) ÷ (지름)은 약 3.14)을 알고 있는가"]},"explanation":["문장마다 원주·원주율의 뜻과 견주어 봐요.","잘못된 문장은 ㉡이에요.","바르게 고치면 「원의 지름에 대한 원주의 비율은 일정합니다.」예요."],"variant_rule":{"alt":[{"stem":"잘못된 문장을 찾고, 바르게 고쳐 써 보세요. ㉠ (원주율) = (지름) ÷ (원주)입니다. ㉡ 원주율은 원의 지름에 대한 원주의 비율입니다. ㉢ 원주율을 소수로 나타내면 끝없이 계속됩니다.","answer_guide":{"answer":"예: ㉠ — 바른 문장: (원주율) = (원주) ÷ (지름)입니다.","scoring_points":["잘못된 문장(㉠)을 찾았는가","바른 문장으로 고쳐 썼는가","고친 까닭(원주율은 지름이 기준량이라 원주를 지름으로 나눔)을 알고 있는가"]},"explanation":["문장마다 원주·원주율의 뜻과 견주어 봐요.","잘못된 문장은 ㉠이에요.","바르게 고치면 「(원주율) = (원주) ÷ (지름)입니다.」예요."]},{"stem":"잘못된 문장을 찾고, 바르게 고쳐 써 보세요. ㉠ 원의 크기가 달라져도 원주율은 일정합니다. ㉡ 반지름이 길어지면 원주도 길어집니다. ㉢ 원주에 대한 원의 지름의 비율을 원주율이라고 합니다.","answer_guide":{"answer":"예: ㉢ — 바른 문장: 원의 지름에 대한 원주의 비율을 원주율이라고 합니다.","scoring_points":["잘못된 문장(㉢)을 찾았는가","바른 문장으로 고쳐 썼는가","고친 까닭(원주율은 지름에 대한 원주의 비율(기준량 = 지름))을 알고 있는가"]},"explanation":["문장마다 원주·원주율의 뜻과 견주어 봐요.","잘못된 문장은 ㉢이에요.","바르게 고치면 「원의 지름에 대한 원주의 비율을 원주율이라고 합니다.」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_b#24','math',6,2,'u5','','tb_g6_2_math_u5_review_b','unit_review','M6-2-u5-C8',4,'essay','teacher','가는 반지름이 9 cm인 원, 나는 반지름이 3 cm인 원이에요. 가의 넓이는 나의 넓이의 몇 배인지 풀이 과정을 쓰고 답을 구해 보세요.','{}'::text[],true,'{"seq":24,"concept":"M6-2-u5-C8","difficulty":4,"kind":"essay","stem":"가는 반지름이 9 cm인 원, 나는 반지름이 3 cm인 원이에요. 가의 넓이는 나의 넓이의 몇 배인지 풀이 과정을 쓰고 답을 구해 보세요.","answer_guide":{"answer":"예: 가의 넓이는 9 × 9 × 3.14 = 254.34 cm², 나의 넓이는 3 × 3 × 3.14 = 28.26 cm²이다. 254.34 ÷ 28.26 = 9이므로 9배이다. (반지름이 3배이니 3 × 3 = 9배로 구해도 된다.)","scoring_points":["두 넓이 254.34 cm²·28.26 cm²를 구했는가","나눗셈으로 9배를 구했는가","반지름 3배 → 넓이 9배를 설명했는가"]},"explanation":["가는 254.34 cm², 나는 28.26 cm²예요.","254.34 ÷ 28.26 = 9예요.","반지름이 3배라 넓이는 3 × 3 = 9배예요."],"variant_rule":{"alt":[{"stem":"바깥쪽 원의 지름이 48 cm인 굴렁쇠를 5바퀴 굴렸어요. 굴렁쇠가 굴러간 거리는 몇 m인지 풀이 과정을 쓰고 답을 구해 보세요.","answer_guide":{"answer":"예: 한 바퀴 굴러간 거리는 굴렁쇠의 원주이므로 48 × 3.14 = 150.72 cm이다. 5바퀴면 150.72 × 5 = 753.6 cm이고, 1 cm = 0.01 m이므로 7.536 m이다.","scoring_points":["한 바퀴 거리가 원주임을 밝혔는가","753.6 cm를 구했는가","m로 바꾸어 7.536 m를 구했는가"]},"explanation":["원주는 48 × 3.14 = 150.72 cm예요.","150.72 × 5 = 753.6 cm예요.","753.6 cm는 7.536 m예요."]},{"stem":"한 변이 20 cm인 정사각형의 네 꼭짓점을 중심으로 반지름이 10 cm인 사분원을 그렸어요. 노란색 사분원 4개와 가운데 초록색 부분의 넓이를 각각 구하는 과정을 써 보세요.","answer_guide":{"answer":"예: 노란색 사분원 4개를 직각인 꼭짓점을 중심으로 모으면 반지름 10 cm인 원이 되어 10 × 10 × 3.14 = 314 cm²이다. 초록색 부분은 정사각형에서 노란색 부분을 빼어 20 × 20 − 314 = 86 cm²이다.","scoring_points":["사분원 4개를 원 하나로 모았는가","노란색 314 cm²를 구했는가","초록색 86 cm²를 구했는가"]},"explanation":["사분원 4개 = 반지름 10 cm인 원이에요.","노란색은 314 cm²예요.","초록색은 400 − 314 = 86 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_b#25','math',6,2,'u5','','tb_g6_2_math_u5_review_b','unit_review','M6-2-u5-C8',4,'essay','teacher','반지름이 3배가 되면 원주와 원의 넓이는 각각 몇 배가 되는지 쓰고, 두 배수가 다른 까닭을 설명해 보세요.','{}'::text[],true,'{"seq":25,"concept":"M6-2-u5-C8","difficulty":4,"kind":"essay","stem":"반지름이 3배가 되면 원주와 원의 넓이는 각각 몇 배가 되는지 쓰고, 두 배수가 다른 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 원주는 3배, 넓이는 9배가 된다. 원주는 (지름) × (원주율)로 길이를 한 번 곱하지만 넓이는 반지름을 두 번 곱하므로 3 × 3 = 9배가 된다.","scoring_points":["원주 3배를 썼는가","넓이 9배를 썼는가","한 번·두 번 곱하는 차이로 설명했는가"]},"explanation":["원주는 3배예요.","넓이는 3 × 3 = 9배예요.","넓이는 반지름을 두 번 곱해요."],"variant_rule":{"alt":[{"stem":"학교 운동장은 가로 60 m, 세로 50 m인 직사각형의 양쪽에 반원을 붙인 모양이에요. 운동장의 넓이는 몇 m²인지 풀이 과정을 쓰고 답을 구해 보세요.","answer_guide":{"answer":"예: 직사각형은 60 × 50 = 3000 m²이다. 양쪽 반원 두 개를 모으면 지름 50 m, 반지름 25 m인 원이 되어 25 × 25 × 3.14 = 1962.5 m²이다. 따라서 3000 + 1962.5 = 4962.5 m²이다.","scoring_points":["직사각형 3000 m²를 구했는가","반원 두 개를 원 1962.5 m²로 모았는가","4962.5 m²를 구했는가"]},"explanation":["직사각형은 60 × 50 = 3000 m²예요.","반원 두 개 = 25 × 25 × 3.14 = 1962.5 m²예요.","3000 + 1962.5 = 4962.5 m²예요."]},{"stem":"고대 이집트 사람들은 지름이 9인 원의 넓이를 한 변이 8인 정사각형의 넓이와 같다고 생각했어요. 원주율을 3.14로 하여 지름이 9 m인 원의 넓이를 구하고, 이 생각이 얼마나 맞는지 설명해 보세요.","answer_guide":{"answer":"예: 반지름이 4.5 m이므로 원의 넓이는 4.5 × 4.5 × 3.14 = 63.585 m²이다. 한 변이 8 m인 정사각형의 넓이는 8 × 8 = 64 m²이다. 차가 0.415 m²로 매우 작아 꽤 비슷하게 어림했다.","scoring_points":["원의 넓이 63.585 m²를 구했는가","정사각형 64 m²를 구했는가","두 넓이가 비슷하다고 견주었는가"]},"explanation":["반지름은 4.5 m예요.","4.5 × 4.5 × 3.14 = 63.585 m², 8 × 8 = 64 m²예요.","차가 0.415 m² — 꽤 가까워요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_c#1','math',6,2,'u5','','tb_g6_2_math_u5_review_c','unit_review','M6-2-u5-C2',1,'mc','auto','(원주율) = ( □ ) ÷ (지름)에서 □에 알맞은 말은 어느 것인가요?',ARRAY['M6-2-u5-X04','M6-2-u5-X02','M6-2-u5-X12']::text[],true,'{"seq":1,"concept":"M6-2-u5-C2","difficulty":1,"kind":"mc","stem":"(원주율) = ( □ ) ÷ (지름)에서 □에 알맞은 말은 어느 것인가요?","options":[{"t":"원주","correct":true},{"t":"반지름","mis":"M6-2-u5-X04"},{"t":"원주율","mis":"M6-2-u5-X02"},{"t":"원의 넓이","mis":"M6-2-u5-X12"}],"explanation":["원주율은 원의 지름에 대한 원주의 비율이에요.","비교하는 양이 원주, 기준량이 지름이에요.","그래서 (원주율) = (원주) ÷ (지름)이에요."],"variant_rule":{"alt":[{"stem":"원의 둘레를 무엇이라고 하나요?","options":[{"t":"원주","correct":true},{"t":"반지름","mis":"M6-2-u5-X02"},{"t":"지름","mis":"M6-2-u5-X02"},{"t":"원의 중심","mis":"M6-2-u5-X02"}],"explanation":["원의 둘레를 원주라고 해요.","원의 중심과 원 위의 한 점을 이으면 반지름, 중심을 지나 원 위의 두 점을 이으면 지름이에요.","원주는 원의 둘레의 길이를 말하기도 해요."]},{"stem":"원주, 원주율 중에서 알맞은 말을 골라요. 원의 둘레를 ( ㉠ )(이)라고 하고, 원의 지름에 대한 원주의 비율을 ( ㉡ )(이)라고 해요. ㉠과 ㉡을 차례로 쓴 것은 어느 것인가요?","options":[{"t":"원주, 원주율","correct":true},{"t":"원주율, 원주","mis":"M6-2-u5-X04"},{"t":"원주, 원주","mis":"M6-2-u5-X02"},{"t":"원주율, 원주율","mis":"M6-2-u5-X02"}],"explanation":["원의 둘레를 원주라고 해요.","원의 지름에 대한 원주의 비율을 원주율이라고 해요.","㉠ 원주, ㉡ 원주율이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_c#2','math',6,2,'u5','','tb_g6_2_math_u5_review_c','unit_review','M6-2-u5-C3',1,'mc','auto','지름이 7 cm인 원의 원주는 몇 cm인가요?',ARRAY['M6-2-u5-X01','M6-2-u5-X12']::text[],true,'{"seq":2,"concept":"M6-2-u5-C3","difficulty":1,"kind":"mc","stem":"지름이 7 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"21.98 cm","correct":true},{"t":"10.99 cm","mis":"M6-2-u5-X01"},{"t":"43.96 cm","mis":"M6-2-u5-X01"},{"t":"38.465 cm","mis":"M6-2-u5-X12"}],"explanation":["(원주) = (지름) × (원주율)이에요.","7 × 3.14를 계산해요.","7 × 3.14 = 21.98 — 원주는 21.98 cm예요."],"variant_rule":{"alt":[{"stem":"지름이 4 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"12.56 cm","correct":true},{"t":"6.28 cm","mis":"M6-2-u5-X01"},{"t":"25.12 cm","mis":"M6-2-u5-X01"},{"t":"7.14 cm","mis":"M6-2-u5-X08"}],"explanation":["(원주) = (지름) × (원주율)이에요.","4 × 3.14를 계산해요.","4 × 3.14 = 12.56 — 원주는 12.56 cm예요."]},{"stem":"지름이 6 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"18.84 cm","correct":true},{"t":"9.42 cm","mis":"M6-2-u5-X01"},{"t":"37.68 cm","mis":"M6-2-u5-X01"},{"t":"28.26 cm","mis":"M6-2-u5-X12"}],"explanation":["(원주) = (지름) × (원주율)이에요.","6 × 3.14를 계산해요.","6 × 3.14 = 18.84 — 원주는 18.84 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_c#3','math',6,2,'u5','','tb_g6_2_math_u5_review_c','unit_review','M6-2-u5-C3',1,'mc','auto','반지름이 6 cm인 원의 원주는 몇 cm인가요?',ARRAY['M6-2-u5-X07','M6-2-u5-X12','M6-2-u5-X01']::text[],true,'{"seq":3,"concept":"M6-2-u5-C3","difficulty":1,"kind":"mc","stem":"반지름이 6 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"37.68 cm","correct":true},{"t":"18.84 cm","mis":"M6-2-u5-X07"},{"t":"113.04 cm","mis":"M6-2-u5-X12"},{"t":"75.36 cm","mis":"M6-2-u5-X01"}],"explanation":["반지름에 바로 원주율을 곱하면 안 돼요.","반지름 6 cm에 2를 곱해 지름 12 cm를 먼저 만들어요.","12 × 3.14 = 37.68 — 원주는 37.68 cm예요."],"variant_rule":{"alt":[{"stem":"반지름이 2 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"12.56 cm","correct":true},{"t":"6.28 cm","mis":"M6-2-u5-X07"},{"t":"25.12 cm","mis":"M6-2-u5-X01"},{"t":"3.14 cm","mis":"M6-2-u5-X07"}],"explanation":["반지름에 바로 원주율을 곱하면 안 돼요.","반지름 2 cm에 2를 곱해 지름 4 cm를 먼저 만들어요.","4 × 3.14 = 12.56 — 원주는 12.56 cm예요."]},{"stem":"반지름이 5.5 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"34.54 cm","correct":true},{"t":"17.27 cm","mis":"M6-2-u5-X07"},{"t":"94.985 cm","mis":"M6-2-u5-X12"},{"t":"69.08 cm","mis":"M6-2-u5-X01"}],"explanation":["반지름에 바로 원주율을 곱하면 안 돼요.","반지름 5.5 cm에 2를 곱해 지름 11 cm를 먼저 만들어요.","11 × 3.14 = 34.54 — 원주는 34.54 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_c#4','math',6,2,'u5','','tb_g6_2_math_u5_review_c','unit_review','M6-2-u5-C6',1,'mc','auto','반지름이 3 cm인 원의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X12','M6-2-u5-X14','M6-2-u5-X13']::text[],true,'{"seq":4,"concept":"M6-2-u5-C6","difficulty":1,"kind":"mc","stem":"반지름이 3 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"28.26 cm²","correct":true},{"t":"18.84 cm²","mis":"M6-2-u5-X12"},{"t":"9.42 cm²","mis":"M6-2-u5-X14"},{"t":"113.04 cm²","mis":"M6-2-u5-X13"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","3 × 3 × 3.14를 계산해요.","3 × 3 × 3.14 = 28.26 — 넓이는 28.26 cm²예요."],"variant_rule":{"alt":[{"stem":"반지름이 9 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"254.34 cm²","correct":true},{"t":"56.52 cm²","mis":"M6-2-u5-X12"},{"t":"28.26 cm²","mis":"M6-2-u5-X14"},{"t":"1017.36 cm²","mis":"M6-2-u5-X13"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","9 × 9 × 3.14를 계산해요.","9 × 9 × 3.14 = 254.34 — 넓이는 254.34 cm²예요."]},{"stem":"반지름이 11 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"379.94 cm²","correct":true},{"t":"69.08 cm²","mis":"M6-2-u5-X12"},{"t":"34.54 cm²","mis":"M6-2-u5-X14"},{"t":"1519.76 cm²","mis":"M6-2-u5-X13"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","11 × 11 × 3.14를 계산해요.","11 × 11 × 3.14 = 379.94 — 넓이는 379.94 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_c#5','math',6,2,'u5','','tb_g6_2_math_u5_review_c','unit_review','M6-2-u5-C6',1,'mc','auto','지름이 12 cm인 원의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X13','M6-2-u5-X12','M6-2-u5-X14']::text[],true,'{"seq":5,"concept":"M6-2-u5-C6","difficulty":1,"kind":"mc","stem":"지름이 12 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"113.04 cm²","correct":true},{"t":"452.16 cm²","mis":"M6-2-u5-X13"},{"t":"37.68 cm²","mis":"M6-2-u5-X12"},{"t":"18.84 cm²","mis":"M6-2-u5-X14"}],"explanation":["넓이는 반지름으로 구해요 — 반지름은 12 ÷ 2 = 6 cm예요.","6 × 6 × 3.14를 계산해요.","6 × 6 × 3.14 = 113.04 — 넓이는 113.04 cm²예요."],"variant_rule":{"alt":[{"stem":"지름이 32 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"803.84 cm²","correct":true},{"t":"3215.36 cm²","mis":"M6-2-u5-X13"},{"t":"100.48 cm²","mis":"M6-2-u5-X12"},{"t":"50.24 cm²","mis":"M6-2-u5-X14"}],"explanation":["넓이는 반지름으로 구해요 — 반지름은 32 ÷ 2 = 16 cm예요.","16 × 16 × 3.14를 계산해요.","16 × 16 × 3.14 = 803.84 — 넓이는 803.84 cm²예요."]},{"stem":"지름이 8 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"50.24 cm²","correct":true},{"t":"200.96 cm²","mis":"M6-2-u5-X13"},{"t":"25.12 cm²","mis":"M6-2-u5-X12"},{"t":"12.56 cm²","mis":"M6-2-u5-X14"}],"explanation":["넓이는 반지름으로 구해요 — 반지름은 8 ÷ 2 = 4 cm예요.","4 × 4 × 3.14를 계산해요.","4 × 4 × 3.14 = 50.24 — 넓이는 50.24 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_c#6','math',6,2,'u5','','tb_g6_2_math_u5_review_c','unit_review','M6-2-u5-C4',1,'sa','auto','원 모양 접시의 원주를 재었더니 31.4 cm였어요. 이 접시의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":6,"concept":"M6-2-u5-C4","difficulty":1,"kind":"sa","stem":"원 모양 접시의 원주를 재었더니 31.4 cm였어요. 이 접시의 지름은 몇 cm인가요?","answer":["10"],"explanation":["(지름) = (원주) ÷ (원주율)이에요.","31.4 ÷ 3.14를 계산해요.","31.4 ÷ 3.14 = 10이에요."],"variant_rule":{"alt":[{"stem":"원 모양 컵 받침의 둘레가 25.12 cm예요. 컵 받침의 지름은 몇 cm인가요?","answer":["8"],"explanation":["(지름) = (원주) ÷ (원주율)이에요.","25.12 ÷ 3.14를 계산해요.","25.12 ÷ 3.14 = 8이에요."]},{"stem":"길이가 78.5 cm인 종이띠를 겹치지 않게 붙여 원을 만들었어요. 만든 원의 지름은 몇 cm인가요?","answer":["25"],"explanation":["(지름) = (원주) ÷ (원주율)이에요.","78.5 ÷ 3.14를 계산해요.","78.5 ÷ 3.14 = 25예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_c#7','math',6,2,'u5','','tb_g6_2_math_u5_review_c','unit_review','M6-2-u5-C2',1,'mc','auto','원주율에 대한 설명으로 잘못된 문장은 어느 것인가요?',ARRAY['M6-2-u5-X19']::text[],true,'{"seq":7,"concept":"M6-2-u5-C2","difficulty":1,"kind":"mc","stem":"원주율에 대한 설명으로 잘못된 문장은 어느 것인가요?","options":[{"t":"원주율은 정확히 3.14입니다.","correct":true},{"t":"원주율은 원의 크기와 상관없이 일정합니다.","mis":"M6-2-u5-X19"},{"t":"원주율은 (원주) ÷ (지름)으로 구합니다.","mis":"M6-2-u5-X19"},{"t":"원주는 지름의 3배보다 길고 4배보다 짧습니다.","mis":"M6-2-u5-X19"}],"explanation":["보기를 하나씩 원주율의 뜻과 견주어 봐요.","3.14는 끝없이 이어지는 원주율을 어림한 값이에요.","나머지 세 문장은 모두 바른 설명이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 원주율에 대한 설명으로 잘못된 문장은 어느 것인가요?","options":[{"t":"원의 지름에 대한 원주의 비율은 지름마다 다릅니다.","correct":true},{"t":"지름이 길어지면 원주도 길어집니다.","mis":"M6-2-u5-X19"},{"t":"원주는 지름의 약 3.14배입니다.","mis":"M6-2-u5-X19"},{"t":"원주율을 소수로 나타내면 끝없이 계속됩니다.","mis":"M6-2-u5-X19"}],"explanation":["보기를 하나씩 원주율의 뜻과 견주어 봐요.","지름에 대한 원주의 비율(원주율)은 모든 원에서 일정해요.","나머지 세 문장은 모두 바른 설명이에요."]},{"stem":"이번에는 다른 보기예요. 원주율에 대한 설명으로 잘못된 문장은 어느 것인가요?","options":[{"t":"원이 커지면 원주율도 커집니다.","correct":true},{"t":"지름이 길어지면 원주도 길어집니다.","mis":"M6-2-u5-X19"},{"t":"원주는 지름의 약 3.14배입니다.","mis":"M6-2-u5-X19"},{"t":"원주율을 소수로 나타내면 끝없이 계속됩니다.","mis":"M6-2-u5-X19"}],"explanation":["보기를 하나씩 원주율의 뜻과 견주어 봐요.","원이 커져도 원주와 지름이 함께 늘어 원주율은 그대로예요.","나머지 세 문장은 모두 바른 설명이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_c#8','math',6,2,'u5','','tb_g6_2_math_u5_review_c','unit_review','M6-2-u5-C2',1,'mc','auto','지름이 15 cm인 원의 원주는 47.1 cm예요. 원주는 지름의 약 몇 배인가요?',ARRAY['M6-2-u5-X04','M6-2-u5-X02']::text[],true,'{"seq":8,"concept":"M6-2-u5-C2","difficulty":1,"kind":"mc","stem":"지름이 15 cm인 원의 원주는 47.1 cm예요. 원주는 지름의 약 몇 배인가요?","options":[{"t":"약 3.14배","correct":true},{"t":"약 6.28배","mis":"M6-2-u5-X04"},{"t":"약 0.32배","mis":"M6-2-u5-X04"},{"t":"약 4배","mis":"M6-2-u5-X02"}],"explanation":["(원주) ÷ (지름)을 계산해요.","47.1 ÷ 15 = 3.14예요.","원주는 지름의 약 3.14배 — 이 값이 원주율이에요."],"variant_rule":{"alt":[{"stem":"지름이 7 cm인 원의 원주는 21.98 cm예요. 원주는 지름의 약 몇 배인가요?","options":[{"t":"약 3.14배","correct":true},{"t":"약 6.28배","mis":"M6-2-u5-X04"},{"t":"약 0.32배","mis":"M6-2-u5-X04"},{"t":"약 4배","mis":"M6-2-u5-X02"}],"explanation":["(원주) ÷ (지름)을 계산해요.","21.98 ÷ 7 = 3.14예요.","원주는 지름의 약 3.14배 — 이 값이 원주율이에요."]},{"stem":"지름이 10 cm인 원의 원주는 31.4 cm예요. 원주는 지름의 약 몇 배인가요?","options":[{"t":"약 3.14배","correct":true},{"t":"약 6.28배","mis":"M6-2-u5-X04"},{"t":"약 0.32배","mis":"M6-2-u5-X04"},{"t":"약 4배","mis":"M6-2-u5-X02"}],"explanation":["(원주) ÷ (지름)을 계산해요.","31.4 ÷ 10 = 3.14예요.","원주는 지름의 약 3.14배 — 이 값이 원주율이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_c#9','math',6,2,'u5','','tb_g6_2_math_u5_review_c','unit_review','M6-2-u5-C7',2,'sa','auto','꽃밭은 가로 20 m, 세로 10 m인 직사각형의 위쪽에 반원만큼 볼록하고 아래쪽은 같은 크기의 반원만큼 패여 있어요. 꽃밭의 넓이는 몇 m²인가요?','{}'::text[],true,'{"seq":9,"concept":"M6-2-u5-C7","difficulty":2,"kind":"sa","stem":"꽃밭은 가로 20 m, 세로 10 m인 직사각형의 위쪽에 반원만큼 볼록하고 아래쪽은 같은 크기의 반원만큼 패여 있어요. 꽃밭의 넓이는 몇 m²인가요?","answer":["200"],"explanation":["볼록한 반원을 패인 곳으로 옮겨요.","그러면 가로 20 m, 세로 10 m인 직사각형이 돼요.","20 × 10 = 200 m²예요."],"variant_rule":{"alt":[{"stem":"아랫부분이 반원만큼 패이고 윗부분이 반원만큼 볼록한 모양이 있어요. 아랫부분의 반원을 윗부분으로 옮겼더니 가로 10 cm, 세로 5 cm인 직사각형이 되었어요. 처음 모양의 넓이는 몇 cm²인가요?","answer":["50"],"explanation":["조각을 더하지도 덜지도 않고 자리만 옮겼어요.","그래서 넓이는 직사각형과 같아요.","10 × 5 = 50 cm²예요."]},{"stem":"한 변이 20 cm인 정사각형의 네 꼭짓점을 중심으로 반지름이 10 cm인 사분원을 하나씩 그려 노란색으로 칠했어요. 노란색 부분의 넓이는 몇 cm²인가요?","answer":["314"],"explanation":["노란색 사분원 4개를 꼭짓점 쪽을 모아 붙이면 원 하나가 돼요.","그 원의 반지름은 10 cm예요.","10 × 10 × 3.14 = 314 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_c#10','math',6,2,'u5','','tb_g6_2_math_u5_review_c','unit_review','M6-2-u5-C6',2,'mc','auto','가로가 14 cm, 세로가 20 cm인 직사각형 종이를 잘라 만들 수 있는 가장 큰 원의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X21','M6-2-u5-X13','M6-2-u5-X12']::text[],true,'{"seq":10,"concept":"M6-2-u5-C6","difficulty":2,"kind":"mc","stem":"가로가 14 cm, 세로가 20 cm인 직사각형 종이를 잘라 만들 수 있는 가장 큰 원의 넓이는 몇 cm²인가요?","options":[{"t":"153.86 cm²","correct":true},{"t":"314 cm²","mis":"M6-2-u5-X21"},{"t":"615.44 cm²","mis":"M6-2-u5-X13"},{"t":"43.96 cm²","mis":"M6-2-u5-X12"}],"explanation":["가장 큰 원의 지름은 짧은 변 14 cm를 넘을 수 없어요.","반지름은 7 cm예요.","7 × 7 × 3.14 = 153.86 cm²예요."],"variant_rule":{"alt":[{"stem":"가로가 15 cm, 세로가 12 cm인 직사각형 종이를 잘라 만들 수 있는 가장 큰 원의 넓이는 몇 cm²인가요?","options":[{"t":"113.04 cm²","correct":true},{"t":"176.625 cm²","mis":"M6-2-u5-X21"},{"t":"452.16 cm²","mis":"M6-2-u5-X13"},{"t":"37.68 cm²","mis":"M6-2-u5-X12"}],"explanation":["가장 큰 원의 지름은 짧은 변 12 cm를 넘을 수 없어요.","반지름은 6 cm예요.","6 × 6 × 3.14 = 113.04 cm²예요."]},{"stem":"가로가 20 cm, 세로가 14 cm인 직사각형 종이를 잘라 만들 수 있는 가장 큰 원의 넓이는 몇 cm²인가요?","options":[{"t":"153.86 cm²","correct":true},{"t":"314 cm²","mis":"M6-2-u5-X21"},{"t":"615.44 cm²","mis":"M6-2-u5-X13"},{"t":"43.96 cm²","mis":"M6-2-u5-X12"}],"explanation":["가장 큰 원의 지름은 짧은 변 14 cm를 넘을 수 없어요.","반지름은 7 cm예요.","7 × 7 × 3.14 = 153.86 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_c#11','math',6,2,'u5','','tb_g6_2_math_u5_review_c','unit_review','M6-2-u5-C3',2,'mc','auto','바깥쪽 원의 지름이 20 cm인 원판을 10바퀴 굴렸어요. 이 원판이 굴러간 거리는 몇 m인가요?',ARRAY['M6-2-u5-X20','M6-2-u5-X19','M6-2-u5-X07']::text[],true,'{"seq":11,"concept":"M6-2-u5-C3","difficulty":2,"kind":"mc","stem":"바깥쪽 원의 지름이 20 cm인 원판을 10바퀴 굴렸어요. 이 원판이 굴러간 거리는 몇 m인가요?","options":[{"t":"6.28 m","correct":true},{"t":"628 m","mis":"M6-2-u5-X20"},{"t":"0.628 m","mis":"M6-2-u5-X19"},{"t":"3.14 m","mis":"M6-2-u5-X07"}],"explanation":["한 바퀴 굴러간 거리는 20 × 3.14 = 62.8 cm예요.","10바퀴면 62.8 × 10 = 628 cm예요.","100 cm = 1 m니 6.28 m예요."],"variant_rule":{"alt":[{"stem":"바깥쪽 원의 지름이 48 cm인 굴렁쇠를 3바퀴 굴렸어요. 이 굴렁쇠가 굴러간 거리는 몇 m인가요?","options":[{"t":"4.5216 m","correct":true},{"t":"452.16 m","mis":"M6-2-u5-X20"},{"t":"1.5072 m","mis":"M6-2-u5-X19"},{"t":"2.2608 m","mis":"M6-2-u5-X07"}],"explanation":["한 바퀴 굴러간 거리는 48 × 3.14 = 150.72 cm예요.","3바퀴면 150.72 × 3 = 452.16 cm예요.","100 cm = 1 m니 4.5216 m예요."]},{"stem":"바깥쪽 원의 지름이 48 cm인 굴렁쇠를 5바퀴 굴렸어요. 이 굴렁쇠가 굴러간 거리는 몇 m인가요?","options":[{"t":"7.536 m","correct":true},{"t":"753.6 m","mis":"M6-2-u5-X20"},{"t":"1.5072 m","mis":"M6-2-u5-X19"},{"t":"3.768 m","mis":"M6-2-u5-X07"}],"explanation":["한 바퀴 굴러간 거리는 48 × 3.14 = 150.72 cm예요.","5바퀴면 150.72 × 5 = 753.6 cm예요.","100 cm = 1 m니 7.536 m예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_c#12','math',6,2,'u5','','tb_g6_2_math_u5_review_c','unit_review','M6-2-u5-C2',2,'mc','auto','「알지오매스 키즈」로 반지름이 5 cm인 원 안쪽에 맞닿는 정십이각형을 그렸더니 둘레가 31.08 cm였어요. (정십이각형의 둘레) ÷ (지름)은 얼마인가요?',ARRAY['M6-2-u5-X04','M6-2-u5-X23','M6-2-u5-X20']::text[],true,'{"seq":12,"concept":"M6-2-u5-C2","difficulty":2,"kind":"mc","stem":"「알지오매스 키즈」로 반지름이 5 cm인 원 안쪽에 맞닿는 정십이각형을 그렸더니 둘레가 31.08 cm였어요. (정십이각형의 둘레) ÷ (지름)은 얼마인가요?","options":[{"t":"3.108","correct":true},{"t":"6.216","mis":"M6-2-u5-X04"},{"t":"3.14","mis":"M6-2-u5-X23"},{"t":"0.3108","mis":"M6-2-u5-X20"}],"explanation":["원의 반지름이 5 cm니 지름은 10 cm예요.","31.08 ÷ 10 = 3.108이에요.","원 안쪽 다각형의 둘레는 원주보다 짧아서 이 값은 원주율 3.14보다 작아요."],"variant_rule":{"alt":[{"stem":"「알지오매스 키즈」로 반지름이 5 cm인 원 안쪽에 맞닿는 정이십이각형을 그렸더니 둘레가 31.24 cm였어요. (정이십이각형의 둘레) ÷ (지름)은 얼마인가요?","options":[{"t":"3.124","correct":true},{"t":"6.248","mis":"M6-2-u5-X04"},{"t":"3.14","mis":"M6-2-u5-X23"},{"t":"0.3124","mis":"M6-2-u5-X20"}],"explanation":["원의 반지름이 5 cm니 지름은 10 cm예요.","31.24 ÷ 10 = 3.124예요.","원 안쪽 다각형의 둘레는 원주보다 짧아서 이 값은 원주율 3.14보다 작아요."]},{"stem":"「알지오매스 키즈」로 반지름이 5 cm인 원 안쪽에 맞닿는 정사각형을 그렸더니 둘레가 28.28 cm였어요. (정사각형의 둘레) ÷ (지름)은 얼마인가요?","options":[{"t":"2.828","correct":true},{"t":"5.656","mis":"M6-2-u5-X04"},{"t":"3.14","mis":"M6-2-u5-X23"},{"t":"0.2828","mis":"M6-2-u5-X20"}],"explanation":["원의 반지름이 5 cm니 지름은 10 cm예요.","28.28 ÷ 10 = 2.828이에요.","원 안쪽 다각형의 둘레는 원주보다 짧아서 이 값은 원주율 3.14보다 작아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_c#13','math',6,2,'u5','','tb_g6_2_math_u5_review_c','unit_review','M6-2-u5-C2',2,'mc','auto','반지름이 5 cm인 원 안쪽에 맞닿는 정이십이각형의 (둘레) ÷ (지름)은 3.124예요. 원주율과 견주면 어떤가요?',ARRAY['M6-2-u5-X23','M6-2-u5-X04']::text[],true,'{"seq":13,"concept":"M6-2-u5-C2","difficulty":2,"kind":"mc","stem":"반지름이 5 cm인 원 안쪽에 맞닿는 정이십이각형의 (둘레) ÷ (지름)은 3.124예요. 원주율과 견주면 어떤가요?","options":[{"t":"원주율보다 조금 작아요","correct":true},{"t":"원주율과 똑같아요","mis":"M6-2-u5-X23"},{"t":"원주율보다 커요","mis":"M6-2-u5-X23"},{"t":"원주율의 2배쯤이에요","mis":"M6-2-u5-X04"}],"explanation":["정이십이각형은 원 안쪽에 맞닿아 있어요.","원 안쪽 다각형의 둘레는 원주보다 조금 짧아요.","그래서 3.124는 원주율 3.14보다 조금 작아요."],"variant_rule":{"alt":[{"stem":"반지름이 5 cm인 원 안쪽에 맞닿는 정십이각형과 정이십이각형의 (둘레) ÷ (지름)은 3.108과 3.124예요. 원주율에 더 가까운 것은 어느 것인가요?","options":[{"t":"정이십이각형","correct":true},{"t":"정십이각형","mis":"M6-2-u5-X23"},{"t":"두 값이 똑같이 가까워요","mis":"M6-2-u5-X23"},{"t":"알 수 없어요","mis":"M6-2-u5-X19"}],"explanation":["3.14 − 3.108 = 0.032예요.","3.14 − 3.124 = 0.016이에요.","변의 수가 더 많은 정이십이각형이 원주율에 더 가까워요."]},{"stem":"「알지오매스 키즈」로 원 안쪽에 맞닿는 정사각형, 정육각형, 정십이각형, 정이십이각형을 차례로 그렸어요. 정다각형의 변의 수가 늘어날수록 정다각형은 어떤 모양에 가까워지나요?","options":[{"t":"원","correct":true},{"t":"정사각형","mis":"M6-2-u5-X23"},{"t":"삼각형","mis":"M6-2-u5-X23"},{"t":"직사각형","mis":"M6-2-u5-X23"}],"explanation":["변의 수가 늘어날수록 꼭짓점이 원 위에 촘촘히 놓여요.","변이 짧아지고 원과 정다각형 사이의 틈이 줄어요.","그래서 정다각형은 원에 가까워져요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_c#14','math',6,2,'u5','','tb_g6_2_math_u5_review_c','unit_review','M6-2-u5-C4',2,'mc','auto','지름이 10 cm인 원과 원주가 37.68 cm인 원이 있어요. 크기가 더 큰 원은 어느 것인가요?',ARRAY['M6-2-u5-X08','M6-2-u5-X20','M6-2-u5-X19']::text[],true,'{"seq":14,"concept":"M6-2-u5-C4","difficulty":2,"kind":"mc","stem":"지름이 10 cm인 원과 원주가 37.68 cm인 원이 있어요. 크기가 더 큰 원은 어느 것인가요?","options":[{"t":"원주가 37.68 cm인 원","correct":true},{"t":"지름이 10 cm인 원","mis":"M6-2-u5-X08"},{"t":"두 원의 크기가 같아요","mis":"M6-2-u5-X20"},{"t":"견줄 수 없어요","mis":"M6-2-u5-X19"}],"explanation":["같은 것끼리 견주려고 원주를 지름으로 바꾸어요.","37.68 ÷ 3.14 = 12 — 원주가 37.68 cm인 원의 지름은 12 cm예요.","지름 10 cm와 12 cm를 견주면 원주가 37.68 cm인 원이 더 커요."],"variant_rule":{"alt":[{"stem":"지름이 8 cm인 원과 원주가 31.4 cm인 원이 있어요. 크기가 더 큰 원은 어느 것인가요?","options":[{"t":"원주가 31.4 cm인 원","correct":true},{"t":"지름이 8 cm인 원","mis":"M6-2-u5-X08"},{"t":"두 원의 크기가 같아요","mis":"M6-2-u5-X20"},{"t":"견줄 수 없어요","mis":"M6-2-u5-X19"}],"explanation":["같은 것끼리 견주려고 원주를 지름으로 바꾸어요.","31.4 ÷ 3.14 = 10 — 원주가 31.4 cm인 원의 지름은 10 cm예요.","지름 8 cm와 10 cm를 견주면 원주가 31.4 cm인 원이 더 커요."]},{"stem":"지름이 15 cm인 원과 원주가 43.96 cm인 원이 있어요. 크기가 더 큰 원은 어느 것인가요?","options":[{"t":"지름이 15 cm인 원","correct":true},{"t":"원주가 43.96 cm인 원","mis":"M6-2-u5-X08"},{"t":"두 원의 크기가 같아요","mis":"M6-2-u5-X20"},{"t":"견줄 수 없어요","mis":"M6-2-u5-X19"}],"explanation":["같은 것끼리 견주려고 원주를 지름으로 바꾸어요.","43.96 ÷ 3.14 = 14 — 원주가 43.96 cm인 원의 지름은 14 cm예요.","지름 15 cm와 14 cm를 견주면 지름이 15 cm인 원이 더 커요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_c#15','math',6,2,'u5','','tb_g6_2_math_u5_review_c','unit_review','M6-2-u5-C5',2,'mc','auto','지름이 20 cm인 원의 넓이를 원 안과 밖에 꼭 맞는 정사각형으로 어림했어요. 알맞은 범위는 어느 것인가요?',ARRAY['M6-2-u5-X11','M6-2-u5-X01','M6-2-u5-X12']::text[],true,'{"seq":15,"concept":"M6-2-u5-C5","difficulty":2,"kind":"mc","stem":"지름이 20 cm인 원의 넓이를 원 안과 밖에 꼭 맞는 정사각형으로 어림했어요. 알맞은 범위는 어느 것인가요?","options":[{"t":"200 cm²보다 넓고 400 cm²보다 좁아요","correct":true},{"t":"100 cm²보다 넓고 200 cm²보다 좁아요","mis":"M6-2-u5-X11"},{"t":"400 cm²보다 넓고 800 cm²보다 좁아요","mis":"M6-2-u5-X01"},{"t":"20 cm²보다 넓고 40 cm²보다 좁아요","mis":"M6-2-u5-X12"}],"explanation":["반지름은 10 cm예요.","원 안 정사각형은 10 × 10 × 2 = 200 cm², 원 밖 정사각형은 10 × 10 × 4 = 400 cm²예요.","원의 넓이는 그 사이 — 200 cm²보다 넓고 400 cm²보다 좁아요."],"variant_rule":{"alt":[{"stem":"지름이 10 cm인 원의 넓이를 원 안과 밖에 꼭 맞는 정사각형으로 어림했어요. 알맞은 범위는 어느 것인가요?","options":[{"t":"50 cm²보다 넓고 100 cm²보다 좁아요","correct":true},{"t":"25 cm²보다 넓고 50 cm²보다 좁아요","mis":"M6-2-u5-X11"},{"t":"100 cm²보다 넓고 200 cm²보다 좁아요","mis":"M6-2-u5-X01"},{"t":"10 cm²보다 넓고 20 cm²보다 좁아요","mis":"M6-2-u5-X12"}],"explanation":["반지름은 5 cm예요.","원 안 정사각형은 5 × 5 × 2 = 50 cm², 원 밖 정사각형은 5 × 5 × 4 = 100 cm²예요.","원의 넓이는 그 사이 — 50 cm²보다 넓고 100 cm²보다 좁아요."]},{"stem":"지름이 14 cm인 원의 넓이를 원 안과 밖에 꼭 맞는 정사각형으로 어림했어요. 알맞은 범위는 어느 것인가요?","options":[{"t":"98 cm²보다 넓고 196 cm²보다 좁아요","correct":true},{"t":"49 cm²보다 넓고 98 cm²보다 좁아요","mis":"M6-2-u5-X11"},{"t":"196 cm²보다 넓고 392 cm²보다 좁아요","mis":"M6-2-u5-X01"},{"t":"14 cm²보다 넓고 28 cm²보다 좁아요","mis":"M6-2-u5-X12"}],"explanation":["반지름은 7 cm예요.","원 안 정사각형은 7 × 7 × 2 = 98 cm², 원 밖 정사각형은 7 × 7 × 4 = 196 cm²예요.","원의 넓이는 그 사이 — 98 cm²보다 넓고 196 cm²보다 좁아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_c#16','math',6,2,'u5','','tb_g6_2_math_u5_review_c','unit_review','M6-2-u5-C7',2,'mc','auto','반지름이 10 cm인 원에서 반지름이 7 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X16','M6-2-u5-X20']::text[],true,'{"seq":16,"concept":"M6-2-u5-C7","difficulty":2,"kind":"mc","stem":"반지름이 10 cm인 원에서 반지름이 7 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?","options":[{"t":"160.14 cm²","correct":true},{"t":"314 cm²","mis":"M6-2-u5-X16"},{"t":"28.26 cm²","mis":"M6-2-u5-X16"},{"t":"467.86 cm²","mis":"M6-2-u5-X20"}],"explanation":["큰 원의 넓이는 10 × 10 × 3.14 = 314 cm²예요.","작은 원의 넓이는 7 × 7 × 3.14 = 153.86 cm²예요.","314 − 153.86 = 160.14 cm²예요."],"variant_rule":{"alt":[{"stem":"반지름이 12 cm인 원에서 반지름이 6 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?","options":[{"t":"339.12 cm²","correct":true},{"t":"452.16 cm²","mis":"M6-2-u5-X16"},{"t":"113.04 cm²","mis":"M6-2-u5-X16"},{"t":"565.2 cm²","mis":"M6-2-u5-X20"}],"explanation":["큰 원의 넓이는 12 × 12 × 3.14 = 452.16 cm²예요.","작은 원의 넓이는 6 × 6 × 3.14 = 113.04 cm²예요.","452.16 − 113.04 = 339.12 cm²예요."]},{"stem":"반지름이 4 cm인 원에서 반지름이 1 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?","options":[{"t":"47.1 cm²","correct":true},{"t":"50.24 cm²","mis":"M6-2-u5-X16"},{"t":"28.26 cm²","mis":"M6-2-u5-X16"},{"t":"53.38 cm²","mis":"M6-2-u5-X20"}],"explanation":["큰 원의 넓이는 4 × 4 × 3.14 = 50.24 cm²예요.","작은 원의 넓이는 1 × 1 × 3.14 = 3.14 cm²예요.","50.24 − 3.14 = 47.1 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_c#17','math',6,2,'u5','','tb_g6_2_math_u5_review_c','unit_review','M6-2-u5-C6',3,'mc','auto','원주가 31.4 cm인 원의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X13','M6-2-u5-X12','M6-2-u5-X14']::text[],true,'{"seq":17,"concept":"M6-2-u5-C6","difficulty":3,"kind":"mc","stem":"원주가 31.4 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"78.5 cm²","correct":true},{"t":"314 cm²","mis":"M6-2-u5-X13"},{"t":"31.4 cm²","mis":"M6-2-u5-X12"},{"t":"15.7 cm²","mis":"M6-2-u5-X14"}],"explanation":["지름은 31.4 ÷ 3.14 = 10 cm, 반지름은 5 cm예요.","넓이는 5 × 5 × 3.14예요.","5 × 5 × 3.14 = 78.5 cm²예요."],"variant_rule":{"alt":[{"stem":"원주가 43.96 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"153.86 cm²","correct":true},{"t":"615.44 cm²","mis":"M6-2-u5-X13"},{"t":"43.96 cm²","mis":"M6-2-u5-X12"},{"t":"21.98 cm²","mis":"M6-2-u5-X14"}],"explanation":["지름은 43.96 ÷ 3.14 = 14 cm, 반지름은 7 cm예요.","넓이는 7 × 7 × 3.14예요.","7 × 7 × 3.14 = 153.86 cm²예요."]},{"stem":"원주가 87.92 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"615.44 cm²","correct":true},{"t":"2461.76 cm²","mis":"M6-2-u5-X13"},{"t":"87.92 cm²","mis":"M6-2-u5-X12"},{"t":"43.96 cm²","mis":"M6-2-u5-X14"}],"explanation":["지름은 87.92 ÷ 3.14 = 28 cm, 반지름은 14 cm예요.","넓이는 14 × 14 × 3.14예요.","14 × 14 × 3.14 = 615.44 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_c#18','math',6,2,'u5','','tb_g6_2_math_u5_review_c','unit_review','M6-2-u5-C6',3,'mc','auto','넓이가 넓은 원부터 차례로 놓으려고 해요. ㉠ 지름이 20 cm인 원 · ㉡ 반지름이 9 cm인 원 · ㉢ 원주가 75.36 cm인 원 — 바르게 놓은 것은 어느 것인가요?',ARRAY['M6-2-u5-X19','M6-2-u5-X13']::text[],true,'{"seq":18,"concept":"M6-2-u5-C6","difficulty":3,"kind":"mc","stem":"넓이가 넓은 원부터 차례로 놓으려고 해요. ㉠ 지름이 20 cm인 원 · ㉡ 반지름이 9 cm인 원 · ㉢ 원주가 75.36 cm인 원 — 바르게 놓은 것은 어느 것인가요?","options":[{"t":"㉢, ㉠, ㉡","correct":true},{"t":"㉡, ㉠, ㉢","mis":"M6-2-u5-X19"},{"t":"㉠, ㉡, ㉢","mis":"M6-2-u5-X13"},{"t":"㉡, ㉢, ㉠","mis":"M6-2-u5-X13"}],"explanation":["세 원의 넓이를 모두 구해 견주어요.","㉠ 314 cm² · ㉡ 254.34 cm² · ㉢ 452.16 cm²예요.","넓은 원부터 놓으면 ㉢, ㉠, ㉡이에요."],"variant_rule":{"alt":[{"stem":"넓이가 넓은 원부터 차례로 놓으려고 해요. ㉠ 반지름이 8 cm인 원 · ㉡ 지름이 14 cm인 원 · ㉢ 넓이가 314 cm²인 원 — 바르게 놓은 것은 어느 것인가요?","options":[{"t":"㉢, ㉠, ㉡","correct":true},{"t":"㉢, ㉡, ㉠","mis":"M6-2-u5-X01"},{"t":"㉡, ㉠, ㉢","mis":"M6-2-u5-X19"},{"t":"㉠, ㉡, ㉢","mis":"M6-2-u5-X13"}],"explanation":["세 원의 넓이를 모두 구해 견주어요.","㉠ 200.96 cm² · ㉡ 153.86 cm² · ㉢ 314 cm²예요.","넓은 원부터 놓으면 ㉢, ㉠, ㉡이에요."]},{"stem":"넓이가 넓은 원부터 차례로 놓으려고 해요. ㉠ 반지름이 10 cm인 원 · ㉡ 넓이가 615.44 cm²인 원 · ㉢ 원주가 75.36 cm인 원 — 바르게 놓은 것은 어느 것인가요?","options":[{"t":"㉡, ㉢, ㉠","correct":true},{"t":"㉠, ㉢, ㉡","mis":"M6-2-u5-X19"},{"t":"㉠, ㉡, ㉢","mis":"M6-2-u5-X13"},{"t":"㉢, ㉡, ㉠","mis":"M6-2-u5-X13"}],"explanation":["세 원의 넓이를 모두 구해 견주어요.","㉠ 314 cm² · ㉡ 615.44 cm² · ㉢ 452.16 cm²예요.","넓은 원부터 놓으면 ㉡, ㉢, ㉠이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_c#19','math',6,2,'u5','','tb_g6_2_math_u5_review_c','unit_review','M6-2-u5-C7',3,'mc','auto','반지름이 12 cm인 큰 원 안에 반지름이 6 cm인 원 두 개가 들어 있어요. 큰 원에서 작은 원 두 개를 뺀 부분의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X17','M6-2-u5-X16','M6-2-u5-X19']::text[],true,'{"seq":19,"concept":"M6-2-u5-C7","difficulty":3,"kind":"mc","stem":"반지름이 12 cm인 큰 원 안에 반지름이 6 cm인 원 두 개가 들어 있어요. 큰 원에서 작은 원 두 개를 뺀 부분의 넓이는 몇 cm²인가요?","options":[{"t":"226.08 cm²","correct":true},{"t":"339.12 cm²","mis":"M6-2-u5-X17"},{"t":"452.16 cm²","mis":"M6-2-u5-X16"},{"t":"113.04 cm²","mis":"M6-2-u5-X19"}],"explanation":["큰 원은 12 × 12 × 3.14 = 452.16 cm²예요.","작은 원 하나는 6 × 6 × 3.14 = 113.04 cm², 두 개는 226.08 cm²예요.","452.16 − 226.08 = 226.08 cm²예요."],"variant_rule":{"alt":[{"stem":"지름이 12 cm인 반원이 있어요. 반원의 지름 위 한쪽에는 지름이 6 cm인 반원이 볼록하게 붙어 있고, 다른 쪽은 같은 크기의 반원만큼 패여 있어요. 이 모양의 넓이는 몇 cm²인가요?","options":[{"t":"56.52 cm²","correct":true},{"t":"70.65 cm²","mis":"M6-2-u5-X17"},{"t":"42.39 cm²","mis":"M6-2-u5-X17"},{"t":"113.04 cm²","mis":"M6-2-u5-X17"}],"explanation":["볼록한 반원과 패인 반원은 크기가 같아요.","볼록한 반원을 떼어 패인 곳에 옮기면 반지름 6 cm인 반원 하나가 돼요.","6 × 6 × 3.14 ÷ 2 = 56.52 cm²예요."]},{"stem":"지름이 20 cm인 원 안에 지름이 10 cm인 반원 두 개가 하나는 위로, 하나는 아래로 그려져 있어요. 큰 원에서 두 반원을 뺀 부분의 넓이는 몇 cm²인가요?","options":[{"t":"235.5 cm²","correct":true},{"t":"274.75 cm²","mis":"M6-2-u5-X17"},{"t":"157 cm²","mis":"M6-2-u5-X17"},{"t":"314 cm²","mis":"M6-2-u5-X16"}],"explanation":["큰 원은 10 × 10 × 3.14 = 314 cm²예요.","반원 두 개를 모으면 반지름 5 cm인 원 — 5 × 5 × 3.14 = 78.5 cm²예요.","314 − 78.5 = 235.5 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_c#20','math',6,2,'u5','','tb_g6_2_math_u5_review_c','unit_review','M6-2-u5-C6',3,'sa','auto','넓이가 78.5 cm²인 원이 있어요. 이 원의 반지름은 몇 cm인가요?','{}'::text[],true,'{"seq":20,"concept":"M6-2-u5-C6","difficulty":3,"kind":"sa","stem":"넓이가 78.5 cm²인 원이 있어요. 이 원의 반지름은 몇 cm인가요?","answer":["5"],"explanation":["(반지름) × (반지름) × 3.14 = 78.5예요.","78.5 ÷ 3.14 = 25니 (반지름) × (반지름) = 25예요.","같은 수를 두 번 곱해 25가 되는 수는 5 — 반지름은 5 cm예요."],"variant_rule":{"alt":[{"stem":"넓이가 28.26 cm²인 원이 있어요. 이 원의 반지름은 몇 cm인가요?","answer":["3"],"explanation":["(반지름) × (반지름) × 3.14 = 28.26이에요.","28.26 ÷ 3.14 = 9니 (반지름) × (반지름) = 9예요.","같은 수를 두 번 곱해 9가 되는 수는 3 — 반지름은 3 cm예요."]},{"stem":"넓이가 452.16 cm²인 원이 있어요. 이 원의 반지름은 몇 cm인가요?","answer":["12"],"explanation":["(반지름) × (반지름) × 3.14 = 452.16이에요.","452.16 ÷ 3.14 = 144니 (반지름) × (반지름) = 144예요.","같은 수를 두 번 곱해 144가 되는 수는 12 — 반지름은 12 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_c#21','math',6,2,'u5','','tb_g6_2_math_u5_review_c','unit_review','M6-2-u5-C8',3,'mc','auto','반지름이 30 cm인 원의 넓이는 반지름이 10 cm인 원의 넓이의 몇 배인가요?',ARRAY['M6-2-u5-X18','M6-2-u5-X20']::text[],true,'{"seq":21,"concept":"M6-2-u5-C8","difficulty":3,"kind":"mc","stem":"반지름이 30 cm인 원의 넓이는 반지름이 10 cm인 원의 넓이의 몇 배인가요?","options":[{"t":"9배","correct":true},{"t":"3배","mis":"M6-2-u5-X18"},{"t":"6배","mis":"M6-2-u5-X18"},{"t":"27배","mis":"M6-2-u5-X20"}],"explanation":["반지름이 30 ÷ 10 = 3배예요.","넓이는 반지름을 두 번 곱하니 3 × 3 = 9배예요.","계산해 봐도 2826 ÷ 314 = 9예요."],"variant_rule":{"alt":[{"stem":"반지름이 24 cm인 원의 넓이는 반지름이 12 cm인 원의 넓이의 몇 배인가요?","options":[{"t":"4배","correct":true},{"t":"2배","mis":"M6-2-u5-X18"},{"t":"8배","mis":"M6-2-u5-X20"},{"t":"24배","mis":"M6-2-u5-X20"}],"explanation":["반지름이 24 ÷ 12 = 2배예요.","넓이는 반지름을 두 번 곱하니 2 × 2 = 4배예요.","계산해 봐도 1808.64 ÷ 452.16 = 4예요."]},{"stem":"반지름이 9 cm인 원의 넓이는 반지름이 3 cm인 원의 넓이의 몇 배인가요?","options":[{"t":"9배","correct":true},{"t":"3배","mis":"M6-2-u5-X18"},{"t":"6배","mis":"M6-2-u5-X18"},{"t":"27배","mis":"M6-2-u5-X20"}],"explanation":["반지름이 9 ÷ 3 = 3배예요.","넓이는 반지름을 두 번 곱하니 3 × 3 = 9배예요.","계산해 봐도 254.34 ÷ 28.26 = 9예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_c#22','math',6,2,'u5','','tb_g6_2_math_u5_review_c','unit_review','M6-2-u5-C4',3,'mc','auto','지름이 40 cm인 원판을 몇 바퀴 굴렸더니 376.8 cm만큼 굴러갔어요. 원판이 굴러간 바퀴 수는 몇 바퀴인가요?',ARRAY['M6-2-u5-X07','M6-2-u5-X01','M6-2-u5-X20']::text[],true,'{"seq":22,"concept":"M6-2-u5-C4","difficulty":3,"kind":"mc","stem":"지름이 40 cm인 원판을 몇 바퀴 굴렸더니 376.8 cm만큼 굴러갔어요. 원판이 굴러간 바퀴 수는 몇 바퀴인가요?","options":[{"t":"3바퀴","correct":true},{"t":"6바퀴","mis":"M6-2-u5-X07"},{"t":"1.5바퀴","mis":"M6-2-u5-X01"},{"t":"9바퀴","mis":"M6-2-u5-X20"}],"explanation":["한 바퀴 굴러간 거리는 원판의 원주예요.","지름 40 cm — 원주는 40 × 3.14 = 125.6 cm예요.","376.8 ÷ 125.6 = 3 — 3바퀴예요."],"variant_rule":{"alt":[{"stem":"지름이 48 cm인 원판을 몇 바퀴 굴렸더니 753.6 cm만큼 굴러갔어요. 원판이 굴러간 바퀴 수는 몇 바퀴인가요?","options":[{"t":"5바퀴","correct":true},{"t":"10바퀴","mis":"M6-2-u5-X07"},{"t":"2.5바퀴","mis":"M6-2-u5-X01"},{"t":"15바퀴","mis":"M6-2-u5-X20"}],"explanation":["한 바퀴 굴러간 거리는 원판의 원주예요.","지름 48 cm — 원주는 48 × 3.14 = 150.72 cm예요.","753.6 ÷ 150.72 = 5 — 5바퀴예요."]},{"stem":"반지름이 15 cm인 원판을 몇 바퀴 굴렸더니 471 cm만큼 굴러갔어요. 원판이 굴러간 바퀴 수는 몇 바퀴인가요?","options":[{"t":"5바퀴","correct":true},{"t":"10바퀴","mis":"M6-2-u5-X07"},{"t":"2.5바퀴","mis":"M6-2-u5-X01"},{"t":"15바퀴","mis":"M6-2-u5-X20"}],"explanation":["한 바퀴 굴러간 거리는 원판의 원주예요.","지름 30 cm — 원주는 30 × 3.14 = 94.2 cm예요.","471 ÷ 94.2 = 5 — 5바퀴예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_c#23','math',6,2,'u5','','tb_g6_2_math_u5_review_c','unit_review','M6-2-u5-C2',4,'essay','teacher','잘못된 문장을 찾고, 바르게 고쳐 써 보세요. ㉠ (원주율) = (지름) ÷ (원주)입니다. ㉡ 원주율은 원의 지름에 대한 원주의 비율입니다. ㉢ 원주율을 소수로 나타내면 끝없이 계속됩니다.','{}'::text[],true,'{"seq":23,"concept":"M6-2-u5-C2","difficulty":4,"kind":"essay","stem":"잘못된 문장을 찾고, 바르게 고쳐 써 보세요. ㉠ (원주율) = (지름) ÷ (원주)입니다. ㉡ 원주율은 원의 지름에 대한 원주의 비율입니다. ㉢ 원주율을 소수로 나타내면 끝없이 계속됩니다.","answer_guide":{"answer":"예: ㉠ — 바른 문장: (원주율) = (원주) ÷ (지름)입니다.","scoring_points":["잘못된 문장(㉠)을 찾았는가","바른 문장으로 고쳐 썼는가","고친 까닭(원주율은 지름이 기준량이라 원주를 지름으로 나눔)을 알고 있는가"]},"explanation":["문장마다 원주·원주율의 뜻과 견주어 봐요.","잘못된 문장은 ㉠이에요.","바르게 고치면 「(원주율) = (원주) ÷ (지름)입니다.」예요."],"variant_rule":{"alt":[{"stem":"잘못된 문장을 찾고, 바르게 고쳐 써 보세요. ㉠ 원의 크기가 달라져도 원주율은 일정합니다. ㉡ 반지름이 길어지면 원주도 길어집니다. ㉢ 원주에 대한 원의 지름의 비율을 원주율이라고 합니다.","answer_guide":{"answer":"예: ㉢ — 바른 문장: 원의 지름에 대한 원주의 비율을 원주율이라고 합니다.","scoring_points":["잘못된 문장(㉢)을 찾았는가","바른 문장으로 고쳐 썼는가","고친 까닭(원주율은 지름에 대한 원주의 비율(기준량 = 지름))을 알고 있는가"]},"explanation":["문장마다 원주·원주율의 뜻과 견주어 봐요.","잘못된 문장은 ㉢이에요.","바르게 고치면 「원의 지름에 대한 원주의 비율을 원주율이라고 합니다.」예요."]},{"stem":"잘못된 문장을 찾고, 바르게 고쳐 써 보세요. ㉠ 지름이 길어지면 원주도 길어집니다. ㉡ 원이 커지면 원주율도 커집니다. ㉢ 원주는 지름의 약 3.14배입니다. ㉣ 원주율을 소수로 나타내면 3.141592…와 같이 끝없이 계속됩니다.","answer_guide":{"answer":"예: ㉡ — 바른 문장: 원주율은 원의 크기에 상관없이 일정합니다.","scoring_points":["잘못된 문장(㉡)을 찾았는가","바른 문장으로 고쳐 썼는가","고친 까닭(원이 커지면 원주와 지름이 함께 늘어나 비율은 그대로)을 알고 있는가"]},"explanation":["문장마다 원주·원주율의 뜻과 견주어 봐요.","잘못된 문장은 ㉡이에요.","바르게 고치면 「원주율은 원의 크기에 상관없이 일정합니다.」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_c#24','math',6,2,'u5','','tb_g6_2_math_u5_review_c','unit_review','M6-2-u5-C3',4,'essay','teacher','바깥쪽 원의 지름이 48 cm인 굴렁쇠를 5바퀴 굴렸어요. 굴렁쇠가 굴러간 거리는 몇 m인지 풀이 과정을 쓰고 답을 구해 보세요.','{}'::text[],true,'{"seq":24,"concept":"M6-2-u5-C3","difficulty":4,"kind":"essay","stem":"바깥쪽 원의 지름이 48 cm인 굴렁쇠를 5바퀴 굴렸어요. 굴렁쇠가 굴러간 거리는 몇 m인지 풀이 과정을 쓰고 답을 구해 보세요.","answer_guide":{"answer":"예: 한 바퀴 굴러간 거리는 굴렁쇠의 원주이므로 48 × 3.14 = 150.72 cm이다. 5바퀴면 150.72 × 5 = 753.6 cm이고, 1 cm = 0.01 m이므로 7.536 m이다.","scoring_points":["한 바퀴 거리가 원주임을 밝혔는가","753.6 cm를 구했는가","m로 바꾸어 7.536 m를 구했는가"]},"explanation":["원주는 48 × 3.14 = 150.72 cm예요.","150.72 × 5 = 753.6 cm예요.","753.6 cm는 7.536 m예요."],"variant_rule":{"alt":[{"stem":"한 변이 20 cm인 정사각형의 네 꼭짓점을 중심으로 반지름이 10 cm인 사분원을 그렸어요. 노란색 사분원 4개와 가운데 초록색 부분의 넓이를 각각 구하는 과정을 써 보세요.","answer_guide":{"answer":"예: 노란색 사분원 4개를 직각인 꼭짓점을 중심으로 모으면 반지름 10 cm인 원이 되어 10 × 10 × 3.14 = 314 cm²이다. 초록색 부분은 정사각형에서 노란색 부분을 빼어 20 × 20 − 314 = 86 cm²이다.","scoring_points":["사분원 4개를 원 하나로 모았는가","노란색 314 cm²를 구했는가","초록색 86 cm²를 구했는가"]},"explanation":["사분원 4개 = 반지름 10 cm인 원이에요.","노란색은 314 cm²예요.","초록색은 400 − 314 = 86 cm²예요."]},{"stem":"가로 12 cm, 세로 15 cm인 직사각형 안에 그릴 수 있는 가장 큰 원의 넓이는 몇 cm²인지 풀이 과정을 쓰고 답을 구해 보세요.","answer_guide":{"answer":"예: 직사각형 안에 그릴 수 있는 가장 큰 원의 지름은 짧은 변의 길이인 12 cm이다. 반지름은 6 cm이므로 넓이는 6 × 6 × 3.14 = 113.04 cm²이다.","scoring_points":["가장 큰 원의 지름이 짧은 변 12 cm라고 썼는가","반지름 6 cm로 식을 세웠는가","113.04 cm²를 구했는가"]},"explanation":["가장 큰 원의 지름은 짧은 변 12 cm예요.","반지름은 6 cm예요.","6 × 6 × 3.14 = 113.04 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_c#25','math',6,2,'u5','','tb_g6_2_math_u5_review_c','unit_review','M6-2-u5-C7',4,'essay','teacher','학교 운동장은 가로 60 m, 세로 50 m인 직사각형의 양쪽에 반원을 붙인 모양이에요. 운동장의 넓이는 몇 m²인지 풀이 과정을 쓰고 답을 구해 보세요.','{}'::text[],true,'{"seq":25,"concept":"M6-2-u5-C7","difficulty":4,"kind":"essay","stem":"학교 운동장은 가로 60 m, 세로 50 m인 직사각형의 양쪽에 반원을 붙인 모양이에요. 운동장의 넓이는 몇 m²인지 풀이 과정을 쓰고 답을 구해 보세요.","answer_guide":{"answer":"예: 직사각형은 60 × 50 = 3000 m²이다. 양쪽 반원 두 개를 모으면 지름 50 m, 반지름 25 m인 원이 되어 25 × 25 × 3.14 = 1962.5 m²이다. 따라서 3000 + 1962.5 = 4962.5 m²이다.","scoring_points":["직사각형 3000 m²를 구했는가","반원 두 개를 원 1962.5 m²로 모았는가","4962.5 m²를 구했는가"]},"explanation":["직사각형은 60 × 50 = 3000 m²예요.","반원 두 개 = 25 × 25 × 3.14 = 1962.5 m²예요.","3000 + 1962.5 = 4962.5 m²예요."],"variant_rule":{"alt":[{"stem":"고대 이집트 사람들은 지름이 9인 원의 넓이를 한 변이 8인 정사각형의 넓이와 같다고 생각했어요. 원주율을 3.14로 하여 지름이 9 m인 원의 넓이를 구하고, 이 생각이 얼마나 맞는지 설명해 보세요.","answer_guide":{"answer":"예: 반지름이 4.5 m이므로 원의 넓이는 4.5 × 4.5 × 3.14 = 63.585 m²이다. 한 변이 8 m인 정사각형의 넓이는 8 × 8 = 64 m²이다. 차가 0.415 m²로 매우 작아 꽤 비슷하게 어림했다.","scoring_points":["원의 넓이 63.585 m²를 구했는가","정사각형 64 m²를 구했는가","두 넓이가 비슷하다고 견주었는가"]},"explanation":["반지름은 4.5 m예요.","4.5 × 4.5 × 3.14 = 63.585 m², 8 × 8 = 64 m²예요.","차가 0.415 m² — 꽤 가까워요."]},{"stem":"반지름이 5 cm인 원 안쪽에 맞닿는 정사각형, 정육각형, 정십이각형, 정이십이각형의 둘레는 28.28 cm, 30 cm, 31.08 cm, 31.24 cm예요. (둘레) ÷ (지름)을 구하고 원주율과 견주어 알게 된 점을 써 보세요.","answer_guide":{"answer":"예: 2.828, 3, 3.108, 3.124이다. 정다각형의 변의 수가 늘어날수록 원에 가까워지고 (둘레) ÷ (지름)은 원주율 3.14에 가까워진다.","scoring_points":["네 값을 구했는가","변의 수가 늘수록 원에 가까워진다고 썼는가","값이 원주율 3.14에 가까워진다고 썼는가"]},"explanation":["지름은 10 cm예요.","2.828 → 3 → 3.108 → 3.124예요.","변이 늘수록 3.14에 가까워져요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_d#1','math',6,2,'u5','','tb_g6_2_math_u5_review_d','unit_review','M6-2-u5-C1',1,'mc','auto','원의 둘레를 무엇이라고 하나요?',ARRAY['M6-2-u5-X02']::text[],true,'{"seq":1,"concept":"M6-2-u5-C1","difficulty":1,"kind":"mc","stem":"원의 둘레를 무엇이라고 하나요?","options":[{"t":"원주","correct":true},{"t":"반지름","mis":"M6-2-u5-X02"},{"t":"지름","mis":"M6-2-u5-X02"},{"t":"원의 중심","mis":"M6-2-u5-X02"}],"explanation":["원의 둘레를 원주라고 해요.","원의 중심과 원 위의 한 점을 이으면 반지름, 중심을 지나 원 위의 두 점을 이으면 지름이에요.","원주는 원의 둘레의 길이를 말하기도 해요."],"variant_rule":{"alt":[{"stem":"원주, 원주율 중에서 알맞은 말을 골라요. 원의 둘레를 ( ㉠ )(이)라고 하고, 원의 지름에 대한 원주의 비율을 ( ㉡ )(이)라고 해요. ㉠과 ㉡을 차례로 쓴 것은 어느 것인가요?","options":[{"t":"원주, 원주율","correct":true},{"t":"원주율, 원주","mis":"M6-2-u5-X04"},{"t":"원주, 원주","mis":"M6-2-u5-X02"},{"t":"원주율, 원주율","mis":"M6-2-u5-X02"}],"explanation":["원의 둘레를 원주라고 해요.","원의 지름에 대한 원주의 비율을 원주율이라고 해요.","㉠ 원주, ㉡ 원주율이에요."]},{"stem":"원의 지름에 대한 원주의 비율을 무엇이라고 하나요?","options":[{"t":"원주율","correct":true},{"t":"원주","mis":"M6-2-u5-X02"},{"t":"반지름","mis":"M6-2-u5-X01"},{"t":"지름","mis":"M6-2-u5-X01"}],"explanation":["원의 둘레가 원주예요.","모든 원에서 지름에 대한 원주의 비율은 일정해요.","그 비율을 원주율이라고 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_d#2','math',6,2,'u5','','tb_g6_2_math_u5_review_d','unit_review','M6-2-u5-C3',1,'mc','auto','지름이 4 cm인 원의 원주는 몇 cm인가요?',ARRAY['M6-2-u5-X01','M6-2-u5-X08']::text[],true,'{"seq":2,"concept":"M6-2-u5-C3","difficulty":1,"kind":"mc","stem":"지름이 4 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"12.56 cm","correct":true},{"t":"6.28 cm","mis":"M6-2-u5-X01"},{"t":"25.12 cm","mis":"M6-2-u5-X01"},{"t":"7.14 cm","mis":"M6-2-u5-X08"}],"explanation":["(원주) = (지름) × (원주율)이에요.","4 × 3.14를 계산해요.","4 × 3.14 = 12.56 — 원주는 12.56 cm예요."],"variant_rule":{"alt":[{"stem":"지름이 6 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"18.84 cm","correct":true},{"t":"9.42 cm","mis":"M6-2-u5-X01"},{"t":"37.68 cm","mis":"M6-2-u5-X01"},{"t":"28.26 cm","mis":"M6-2-u5-X12"}],"explanation":["(원주) = (지름) × (원주율)이에요.","6 × 3.14를 계산해요.","6 × 3.14 = 18.84 — 원주는 18.84 cm예요."]},{"stem":"지름이 14 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"43.96 cm","correct":true},{"t":"21.98 cm","mis":"M6-2-u5-X01"},{"t":"87.92 cm","mis":"M6-2-u5-X01"},{"t":"153.86 cm","mis":"M6-2-u5-X12"}],"explanation":["(원주) = (지름) × (원주율)이에요.","14 × 3.14를 계산해요.","14 × 3.14 = 43.96 — 원주는 43.96 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_d#3','math',6,2,'u5','','tb_g6_2_math_u5_review_d','unit_review','M6-2-u5-C3',1,'mc','auto','반지름이 2 cm인 원의 원주는 몇 cm인가요?',ARRAY['M6-2-u5-X07','M6-2-u5-X01']::text[],true,'{"seq":3,"concept":"M6-2-u5-C3","difficulty":1,"kind":"mc","stem":"반지름이 2 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"12.56 cm","correct":true},{"t":"6.28 cm","mis":"M6-2-u5-X07"},{"t":"25.12 cm","mis":"M6-2-u5-X01"},{"t":"3.14 cm","mis":"M6-2-u5-X07"}],"explanation":["반지름에 바로 원주율을 곱하면 안 돼요.","반지름 2 cm에 2를 곱해 지름 4 cm를 먼저 만들어요.","4 × 3.14 = 12.56 — 원주는 12.56 cm예요."],"variant_rule":{"alt":[{"stem":"반지름이 5.5 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"34.54 cm","correct":true},{"t":"17.27 cm","mis":"M6-2-u5-X07"},{"t":"94.985 cm","mis":"M6-2-u5-X12"},{"t":"69.08 cm","mis":"M6-2-u5-X01"}],"explanation":["반지름에 바로 원주율을 곱하면 안 돼요.","반지름 5.5 cm에 2를 곱해 지름 11 cm를 먼저 만들어요.","11 × 3.14 = 34.54 — 원주는 34.54 cm예요."]},{"stem":"반지름이 9 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"56.52 cm","correct":true},{"t":"28.26 cm","mis":"M6-2-u5-X07"},{"t":"254.34 cm","mis":"M6-2-u5-X12"},{"t":"113.04 cm","mis":"M6-2-u5-X01"}],"explanation":["반지름에 바로 원주율을 곱하면 안 돼요.","반지름 9 cm에 2를 곱해 지름 18 cm를 먼저 만들어요.","18 × 3.14 = 56.52 — 원주는 56.52 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_d#4','math',6,2,'u5','','tb_g6_2_math_u5_review_d','unit_review','M6-2-u5-C6',1,'mc','auto','반지름이 9 cm인 원의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X12','M6-2-u5-X14','M6-2-u5-X13']::text[],true,'{"seq":4,"concept":"M6-2-u5-C6","difficulty":1,"kind":"mc","stem":"반지름이 9 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"254.34 cm²","correct":true},{"t":"56.52 cm²","mis":"M6-2-u5-X12"},{"t":"28.26 cm²","mis":"M6-2-u5-X14"},{"t":"1017.36 cm²","mis":"M6-2-u5-X13"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","9 × 9 × 3.14를 계산해요.","9 × 9 × 3.14 = 254.34 — 넓이는 254.34 cm²예요."],"variant_rule":{"alt":[{"stem":"반지름이 11 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"379.94 cm²","correct":true},{"t":"69.08 cm²","mis":"M6-2-u5-X12"},{"t":"34.54 cm²","mis":"M6-2-u5-X14"},{"t":"1519.76 cm²","mis":"M6-2-u5-X13"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","11 × 11 × 3.14를 계산해요.","11 × 11 × 3.14 = 379.94 — 넓이는 379.94 cm²예요."]},{"stem":"반지름이 5 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"78.5 cm²","correct":true},{"t":"31.4 cm²","mis":"M6-2-u5-X12"},{"t":"15.7 cm²","mis":"M6-2-u5-X14"},{"t":"314 cm²","mis":"M6-2-u5-X13"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","5 × 5 × 3.14를 계산해요.","5 × 5 × 3.14 = 78.5 — 넓이는 78.5 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_d#5','math',6,2,'u5','','tb_g6_2_math_u5_review_d','unit_review','M6-2-u5-C6',1,'mc','auto','지름이 32 cm인 원의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X13','M6-2-u5-X12','M6-2-u5-X14']::text[],true,'{"seq":5,"concept":"M6-2-u5-C6","difficulty":1,"kind":"mc","stem":"지름이 32 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"803.84 cm²","correct":true},{"t":"3215.36 cm²","mis":"M6-2-u5-X13"},{"t":"100.48 cm²","mis":"M6-2-u5-X12"},{"t":"50.24 cm²","mis":"M6-2-u5-X14"}],"explanation":["넓이는 반지름으로 구해요 — 반지름은 32 ÷ 2 = 16 cm예요.","16 × 16 × 3.14를 계산해요.","16 × 16 × 3.14 = 803.84 — 넓이는 803.84 cm²예요."],"variant_rule":{"alt":[{"stem":"지름이 8 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"50.24 cm²","correct":true},{"t":"200.96 cm²","mis":"M6-2-u5-X13"},{"t":"25.12 cm²","mis":"M6-2-u5-X12"},{"t":"12.56 cm²","mis":"M6-2-u5-X14"}],"explanation":["넓이는 반지름으로 구해요 — 반지름은 8 ÷ 2 = 4 cm예요.","4 × 4 × 3.14를 계산해요.","4 × 4 × 3.14 = 50.24 — 넓이는 50.24 cm²예요."]},{"stem":"지름이 20 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"314 cm²","correct":true},{"t":"1256 cm²","mis":"M6-2-u5-X13"},{"t":"62.8 cm²","mis":"M6-2-u5-X12"},{"t":"31.4 cm²","mis":"M6-2-u5-X14"}],"explanation":["넓이는 반지름으로 구해요 — 반지름은 20 ÷ 2 = 10 cm예요.","10 × 10 × 3.14를 계산해요.","10 × 10 × 3.14 = 314 — 넓이는 314 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_d#6','math',6,2,'u5','','tb_g6_2_math_u5_review_d','unit_review','M6-2-u5-C4',1,'sa','auto','원 모양 컵 받침의 둘레가 25.12 cm예요. 컵 받침의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":6,"concept":"M6-2-u5-C4","difficulty":1,"kind":"sa","stem":"원 모양 컵 받침의 둘레가 25.12 cm예요. 컵 받침의 지름은 몇 cm인가요?","answer":["8"],"explanation":["(지름) = (원주) ÷ (원주율)이에요.","25.12 ÷ 3.14를 계산해요.","25.12 ÷ 3.14 = 8이에요."],"variant_rule":{"alt":[{"stem":"길이가 78.5 cm인 종이띠를 겹치지 않게 붙여 원을 만들었어요. 만든 원의 지름은 몇 cm인가요?","answer":["25"],"explanation":["(지름) = (원주) ÷ (원주율)이에요.","78.5 ÷ 3.14를 계산해요.","78.5 ÷ 3.14 = 25예요."]},{"stem":"원 모양 호수의 둘레가 157 m예요. 호수의 중심을 지나는 다리의 길이는 몇 m인가요?","answer":["50"],"explanation":["(지름) = (원주) ÷ (원주율)이에요.","157 ÷ 3.14를 계산해요.","157 ÷ 3.14 = 50이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_d#7','math',6,2,'u5','','tb_g6_2_math_u5_review_d','unit_review','M6-2-u5-C2',1,'mc','auto','원주율에 대한 설명으로 잘못된 문장은 어느 것인가요?',ARRAY['M6-2-u5-X19']::text[],true,'{"seq":7,"concept":"M6-2-u5-C2","difficulty":1,"kind":"mc","stem":"원주율에 대한 설명으로 잘못된 문장은 어느 것인가요?","options":[{"t":"원의 지름에 대한 원주의 비율은 지름마다 다릅니다.","correct":true},{"t":"지름이 길어지면 원주도 길어집니다.","mis":"M6-2-u5-X19"},{"t":"원주는 지름의 약 3.14배입니다.","mis":"M6-2-u5-X19"},{"t":"원주율을 소수로 나타내면 끝없이 계속됩니다.","mis":"M6-2-u5-X19"}],"explanation":["보기를 하나씩 원주율의 뜻과 견주어 봐요.","지름에 대한 원주의 비율(원주율)은 모든 원에서 일정해요.","나머지 세 문장은 모두 바른 설명이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 원주율에 대한 설명으로 잘못된 문장은 어느 것인가요?","options":[{"t":"원이 커지면 원주율도 커집니다.","correct":true},{"t":"지름이 길어지면 원주도 길어집니다.","mis":"M6-2-u5-X19"},{"t":"원주는 지름의 약 3.14배입니다.","mis":"M6-2-u5-X19"},{"t":"원주율을 소수로 나타내면 끝없이 계속됩니다.","mis":"M6-2-u5-X19"}],"explanation":["보기를 하나씩 원주율의 뜻과 견주어 봐요.","원이 커져도 원주와 지름이 함께 늘어 원주율은 그대로예요.","나머지 세 문장은 모두 바른 설명이에요."]},{"stem":"이번에는 다른 보기예요. 원주율에 대한 설명으로 잘못된 문장은 어느 것인가요?","options":[{"t":"원주에 대한 원의 지름의 비율을 원주율이라고 합니다.","correct":true},{"t":"원의 크기가 달라져도 원주율은 일정합니다.","mis":"M6-2-u5-X19"},{"t":"반지름이 길어지면 원주도 길어집니다.","mis":"M6-2-u5-X19"},{"t":"원주율을 소수로 나타내면 끝없이 계속됩니다.","mis":"M6-2-u5-X19"}],"explanation":["보기를 하나씩 원주율의 뜻과 견주어 봐요.","원주율은 지름에 대한 원주의 비율 — 기준량이 지름이에요.","나머지 세 문장은 모두 바른 설명이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_d#8','math',6,2,'u5','','tb_g6_2_math_u5_review_d','unit_review','M6-2-u5-C2',1,'mc','auto','지름이 7 cm인 원의 원주는 21.98 cm예요. 원주는 지름의 약 몇 배인가요?',ARRAY['M6-2-u5-X04','M6-2-u5-X02']::text[],true,'{"seq":8,"concept":"M6-2-u5-C2","difficulty":1,"kind":"mc","stem":"지름이 7 cm인 원의 원주는 21.98 cm예요. 원주는 지름의 약 몇 배인가요?","options":[{"t":"약 3.14배","correct":true},{"t":"약 6.28배","mis":"M6-2-u5-X04"},{"t":"약 0.32배","mis":"M6-2-u5-X04"},{"t":"약 4배","mis":"M6-2-u5-X02"}],"explanation":["(원주) ÷ (지름)을 계산해요.","21.98 ÷ 7 = 3.14예요.","원주는 지름의 약 3.14배 — 이 값이 원주율이에요."],"variant_rule":{"alt":[{"stem":"지름이 10 cm인 원의 원주는 31.4 cm예요. 원주는 지름의 약 몇 배인가요?","options":[{"t":"약 3.14배","correct":true},{"t":"약 6.28배","mis":"M6-2-u5-X04"},{"t":"약 0.32배","mis":"M6-2-u5-X04"},{"t":"약 4배","mis":"M6-2-u5-X02"}],"explanation":["(원주) ÷ (지름)을 계산해요.","31.4 ÷ 10 = 3.14예요.","원주는 지름의 약 3.14배 — 이 값이 원주율이에요."]},{"stem":"지름이 20 cm인 원의 원주는 62.8 cm예요. 원주는 지름의 약 몇 배인가요?","options":[{"t":"약 3.14배","correct":true},{"t":"약 6.28배","mis":"M6-2-u5-X04"},{"t":"약 0.32배","mis":"M6-2-u5-X04"},{"t":"약 4배","mis":"M6-2-u5-X02"}],"explanation":["(원주) ÷ (지름)을 계산해요.","62.8 ÷ 20 = 3.14예요.","원주는 지름의 약 3.14배 — 이 값이 원주율이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_d#9','math',6,2,'u5','','tb_g6_2_math_u5_review_d','unit_review','M6-2-u5-C7',2,'sa','auto','아랫부분이 반원만큼 패이고 윗부분이 반원만큼 볼록한 모양이 있어요. 아랫부분의 반원을 윗부분으로 옮겼더니 가로 10 cm, 세로 5 cm인 직사각형이 되었어요. 처음 모양의 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":9,"concept":"M6-2-u5-C7","difficulty":2,"kind":"sa","stem":"아랫부분이 반원만큼 패이고 윗부분이 반원만큼 볼록한 모양이 있어요. 아랫부분의 반원을 윗부분으로 옮겼더니 가로 10 cm, 세로 5 cm인 직사각형이 되었어요. 처음 모양의 넓이는 몇 cm²인가요?","answer":["50"],"explanation":["조각을 더하지도 덜지도 않고 자리만 옮겼어요.","그래서 넓이는 직사각형과 같아요.","10 × 5 = 50 cm²예요."],"variant_rule":{"alt":[{"stem":"한 변이 20 cm인 정사각형의 네 꼭짓점을 중심으로 반지름이 10 cm인 사분원을 하나씩 그려 노란색으로 칠했어요. 노란색 부분의 넓이는 몇 cm²인가요?","answer":["314"],"explanation":["노란색 사분원 4개를 꼭짓점 쪽을 모아 붙이면 원 하나가 돼요.","그 원의 반지름은 10 cm예요.","10 × 10 × 3.14 = 314 cm²예요."]},{"stem":"한 변이 20 cm인 정사각형의 네 꼭짓점을 중심으로 반지름이 10 cm인 사분원을 그렸어요. 사분원 4개를 뺀 가운데 초록색 부분의 넓이는 몇 cm²인가요?","answer":["86"],"explanation":["정사각형의 넓이는 20 × 20 = 400 cm²예요.","사분원 4개는 반지름 10 cm인 원 하나 — 314 cm²예요.","400 − 314 = 86 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_d#10','math',6,2,'u5','','tb_g6_2_math_u5_review_d','unit_review','M6-2-u5-C6',2,'mc','auto','가로가 15 cm, 세로가 12 cm인 직사각형 종이를 잘라 만들 수 있는 가장 큰 원의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X21','M6-2-u5-X13','M6-2-u5-X12']::text[],true,'{"seq":10,"concept":"M6-2-u5-C6","difficulty":2,"kind":"mc","stem":"가로가 15 cm, 세로가 12 cm인 직사각형 종이를 잘라 만들 수 있는 가장 큰 원의 넓이는 몇 cm²인가요?","options":[{"t":"113.04 cm²","correct":true},{"t":"176.625 cm²","mis":"M6-2-u5-X21"},{"t":"452.16 cm²","mis":"M6-2-u5-X13"},{"t":"37.68 cm²","mis":"M6-2-u5-X12"}],"explanation":["가장 큰 원의 지름은 짧은 변 12 cm를 넘을 수 없어요.","반지름은 6 cm예요.","6 × 6 × 3.14 = 113.04 cm²예요."],"variant_rule":{"alt":[{"stem":"가로가 20 cm, 세로가 14 cm인 직사각형 종이를 잘라 만들 수 있는 가장 큰 원의 넓이는 몇 cm²인가요?","options":[{"t":"153.86 cm²","correct":true},{"t":"314 cm²","mis":"M6-2-u5-X21"},{"t":"615.44 cm²","mis":"M6-2-u5-X13"},{"t":"43.96 cm²","mis":"M6-2-u5-X12"}],"explanation":["가장 큰 원의 지름은 짧은 변 14 cm를 넘을 수 없어요.","반지름은 7 cm예요.","7 × 7 × 3.14 = 153.86 cm²예요."]},{"stem":"가로가 12 cm, 세로가 15 cm인 직사각형 종이를 잘라 만들 수 있는 가장 큰 원의 넓이는 몇 cm²인가요?","options":[{"t":"113.04 cm²","correct":true},{"t":"176.625 cm²","mis":"M6-2-u5-X21"},{"t":"452.16 cm²","mis":"M6-2-u5-X13"},{"t":"37.68 cm²","mis":"M6-2-u5-X12"}],"explanation":["가장 큰 원의 지름은 짧은 변 12 cm를 넘을 수 없어요.","반지름은 6 cm예요.","6 × 6 × 3.14 = 113.04 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_d#11','math',6,2,'u5','','tb_g6_2_math_u5_review_d','unit_review','M6-2-u5-C3',2,'mc','auto','바깥쪽 원의 지름이 48 cm인 굴렁쇠를 3바퀴 굴렸어요. 이 굴렁쇠가 굴러간 거리는 몇 m인가요?',ARRAY['M6-2-u5-X20','M6-2-u5-X19','M6-2-u5-X07']::text[],true,'{"seq":11,"concept":"M6-2-u5-C3","difficulty":2,"kind":"mc","stem":"바깥쪽 원의 지름이 48 cm인 굴렁쇠를 3바퀴 굴렸어요. 이 굴렁쇠가 굴러간 거리는 몇 m인가요?","options":[{"t":"4.5216 m","correct":true},{"t":"452.16 m","mis":"M6-2-u5-X20"},{"t":"1.5072 m","mis":"M6-2-u5-X19"},{"t":"2.2608 m","mis":"M6-2-u5-X07"}],"explanation":["한 바퀴 굴러간 거리는 48 × 3.14 = 150.72 cm예요.","3바퀴면 150.72 × 3 = 452.16 cm예요.","100 cm = 1 m니 4.5216 m예요."],"variant_rule":{"alt":[{"stem":"바깥쪽 원의 지름이 48 cm인 굴렁쇠를 5바퀴 굴렸어요. 이 굴렁쇠가 굴러간 거리는 몇 m인가요?","options":[{"t":"7.536 m","correct":true},{"t":"753.6 m","mis":"M6-2-u5-X20"},{"t":"1.5072 m","mis":"M6-2-u5-X19"},{"t":"3.768 m","mis":"M6-2-u5-X07"}],"explanation":["한 바퀴 굴러간 거리는 48 × 3.14 = 150.72 cm예요.","5바퀴면 150.72 × 5 = 753.6 cm예요.","100 cm = 1 m니 7.536 m예요."]},{"stem":"바깥쪽 원의 지름이 40 cm인 굴렁쇠를 3바퀴 굴렸어요. 이 굴렁쇠가 굴러간 거리는 몇 m인가요?","options":[{"t":"3.768 m","correct":true},{"t":"376.8 m","mis":"M6-2-u5-X20"},{"t":"1.256 m","mis":"M6-2-u5-X19"},{"t":"1.884 m","mis":"M6-2-u5-X07"}],"explanation":["한 바퀴 굴러간 거리는 40 × 3.14 = 125.6 cm예요.","3바퀴면 125.6 × 3 = 376.8 cm예요.","100 cm = 1 m니 3.768 m예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_d#12','math',6,2,'u5','','tb_g6_2_math_u5_review_d','unit_review','M6-2-u5-C2',2,'mc','auto','「알지오매스 키즈」로 반지름이 5 cm인 원 안쪽에 맞닿는 정이십이각형을 그렸더니 둘레가 31.24 cm였어요. (정이십이각형의 둘레) ÷ (지름)은 얼마인가요?',ARRAY['M6-2-u5-X04','M6-2-u5-X23','M6-2-u5-X20']::text[],true,'{"seq":12,"concept":"M6-2-u5-C2","difficulty":2,"kind":"mc","stem":"「알지오매스 키즈」로 반지름이 5 cm인 원 안쪽에 맞닿는 정이십이각형을 그렸더니 둘레가 31.24 cm였어요. (정이십이각형의 둘레) ÷ (지름)은 얼마인가요?","options":[{"t":"3.124","correct":true},{"t":"6.248","mis":"M6-2-u5-X04"},{"t":"3.14","mis":"M6-2-u5-X23"},{"t":"0.3124","mis":"M6-2-u5-X20"}],"explanation":["원의 반지름이 5 cm니 지름은 10 cm예요.","31.24 ÷ 10 = 3.124예요.","원 안쪽 다각형의 둘레는 원주보다 짧아서 이 값은 원주율 3.14보다 작아요."],"variant_rule":{"alt":[{"stem":"「알지오매스 키즈」로 반지름이 5 cm인 원 안쪽에 맞닿는 정사각형을 그렸더니 둘레가 28.28 cm였어요. (정사각형의 둘레) ÷ (지름)은 얼마인가요?","options":[{"t":"2.828","correct":true},{"t":"5.656","mis":"M6-2-u5-X04"},{"t":"3.14","mis":"M6-2-u5-X23"},{"t":"0.2828","mis":"M6-2-u5-X20"}],"explanation":["원의 반지름이 5 cm니 지름은 10 cm예요.","28.28 ÷ 10 = 2.828이에요.","원 안쪽 다각형의 둘레는 원주보다 짧아서 이 값은 원주율 3.14보다 작아요."]},{"stem":"「알지오매스 키즈」로 반지름이 5 cm인 원 안쪽에 맞닿는 정육각형을 그렸더니 둘레가 30 cm였어요. (정육각형의 둘레) ÷ (지름)은 얼마인가요?","options":[{"t":"3","correct":true},{"t":"6","mis":"M6-2-u5-X04"},{"t":"3.14","mis":"M6-2-u5-X23"},{"t":"0.3","mis":"M6-2-u5-X20"}],"explanation":["원의 반지름이 5 cm니 지름은 10 cm예요.","30 ÷ 10 = 3이에요.","원 안쪽 다각형의 둘레는 원주보다 짧아서 이 값은 원주율 3.14보다 작아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_d#13','math',6,2,'u5','','tb_g6_2_math_u5_review_d','unit_review','M6-2-u5-C2',2,'mc','auto','반지름이 5 cm인 원 안쪽에 맞닿는 정십이각형과 정이십이각형의 (둘레) ÷ (지름)은 3.108과 3.124예요. 원주율에 더 가까운 것은 어느 것인가요?',ARRAY['M6-2-u5-X23','M6-2-u5-X19']::text[],true,'{"seq":13,"concept":"M6-2-u5-C2","difficulty":2,"kind":"mc","stem":"반지름이 5 cm인 원 안쪽에 맞닿는 정십이각형과 정이십이각형의 (둘레) ÷ (지름)은 3.108과 3.124예요. 원주율에 더 가까운 것은 어느 것인가요?","options":[{"t":"정이십이각형","correct":true},{"t":"정십이각형","mis":"M6-2-u5-X23"},{"t":"두 값이 똑같이 가까워요","mis":"M6-2-u5-X23"},{"t":"알 수 없어요","mis":"M6-2-u5-X19"}],"explanation":["3.14 − 3.108 = 0.032예요.","3.14 − 3.124 = 0.016이에요.","변의 수가 더 많은 정이십이각형이 원주율에 더 가까워요."],"variant_rule":{"alt":[{"stem":"「알지오매스 키즈」로 원 안쪽에 맞닿는 정사각형, 정육각형, 정십이각형, 정이십이각형을 차례로 그렸어요. 정다각형의 변의 수가 늘어날수록 정다각형은 어떤 모양에 가까워지나요?","options":[{"t":"원","correct":true},{"t":"정사각형","mis":"M6-2-u5-X23"},{"t":"삼각형","mis":"M6-2-u5-X23"},{"t":"직사각형","mis":"M6-2-u5-X23"}],"explanation":["변의 수가 늘어날수록 꼭짓점이 원 위에 촘촘히 놓여요.","변이 짧아지고 원과 정다각형 사이의 틈이 줄어요.","그래서 정다각형은 원에 가까워져요."]},{"stem":"원 안쪽에 맞닿는 정다각형의 변의 수가 늘어날수록 (정다각형의 둘레) ÷ (지름)은 어떻게 되나요?","options":[{"t":"원주율 3.14에 가까워져요","correct":true},{"t":"점점 작아져요","mis":"M6-2-u5-X23"},{"t":"변하지 않아요","mis":"M6-2-u5-X23"},{"t":"원주율보다 커져요","mis":"M6-2-u5-X23"}],"explanation":["반지름 5 cm인 원에서 2.828 → 3 → 3.108 → 3.124로 커졌어요.","정다각형이 원에 가까워지니 둘레도 원주에 가까워져요.","그래서 (둘레) ÷ (지름)은 원주율 3.14에 가까워져요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_d#14','math',6,2,'u5','','tb_g6_2_math_u5_review_d','unit_review','M6-2-u5-C4',2,'mc','auto','지름이 8 cm인 원과 원주가 31.4 cm인 원이 있어요. 크기가 더 큰 원은 어느 것인가요?',ARRAY['M6-2-u5-X08','M6-2-u5-X20','M6-2-u5-X19']::text[],true,'{"seq":14,"concept":"M6-2-u5-C4","difficulty":2,"kind":"mc","stem":"지름이 8 cm인 원과 원주가 31.4 cm인 원이 있어요. 크기가 더 큰 원은 어느 것인가요?","options":[{"t":"원주가 31.4 cm인 원","correct":true},{"t":"지름이 8 cm인 원","mis":"M6-2-u5-X08"},{"t":"두 원의 크기가 같아요","mis":"M6-2-u5-X20"},{"t":"견줄 수 없어요","mis":"M6-2-u5-X19"}],"explanation":["같은 것끼리 견주려고 원주를 지름으로 바꾸어요.","31.4 ÷ 3.14 = 10 — 원주가 31.4 cm인 원의 지름은 10 cm예요.","지름 8 cm와 10 cm를 견주면 원주가 31.4 cm인 원이 더 커요."],"variant_rule":{"alt":[{"stem":"지름이 15 cm인 원과 원주가 43.96 cm인 원이 있어요. 크기가 더 큰 원은 어느 것인가요?","options":[{"t":"지름이 15 cm인 원","correct":true},{"t":"원주가 43.96 cm인 원","mis":"M6-2-u5-X08"},{"t":"두 원의 크기가 같아요","mis":"M6-2-u5-X20"},{"t":"견줄 수 없어요","mis":"M6-2-u5-X19"}],"explanation":["같은 것끼리 견주려고 원주를 지름으로 바꾸어요.","43.96 ÷ 3.14 = 14 — 원주가 43.96 cm인 원의 지름은 14 cm예요.","지름 15 cm와 14 cm를 견주면 지름이 15 cm인 원이 더 커요."]},{"stem":"지름이 22 cm인 원과 원주가 81.64 cm인 원이 있어요. 크기가 더 큰 원은 어느 것인가요?","options":[{"t":"원주가 81.64 cm인 원","correct":true},{"t":"지름이 22 cm인 원","mis":"M6-2-u5-X08"},{"t":"두 원의 크기가 같아요","mis":"M6-2-u5-X20"},{"t":"견줄 수 없어요","mis":"M6-2-u5-X19"}],"explanation":["같은 것끼리 견주려고 원주를 지름으로 바꾸어요.","81.64 ÷ 3.14 = 26 — 원주가 81.64 cm인 원의 지름은 26 cm예요.","지름 22 cm와 26 cm를 견주면 원주가 81.64 cm인 원이 더 커요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_d#15','math',6,2,'u5','','tb_g6_2_math_u5_review_d','unit_review','M6-2-u5-C5',2,'mc','auto','지름이 10 cm인 원의 넓이를 원 안과 밖에 꼭 맞는 정사각형으로 어림했어요. 알맞은 범위는 어느 것인가요?',ARRAY['M6-2-u5-X11','M6-2-u5-X01','M6-2-u5-X12']::text[],true,'{"seq":15,"concept":"M6-2-u5-C5","difficulty":2,"kind":"mc","stem":"지름이 10 cm인 원의 넓이를 원 안과 밖에 꼭 맞는 정사각형으로 어림했어요. 알맞은 범위는 어느 것인가요?","options":[{"t":"50 cm²보다 넓고 100 cm²보다 좁아요","correct":true},{"t":"25 cm²보다 넓고 50 cm²보다 좁아요","mis":"M6-2-u5-X11"},{"t":"100 cm²보다 넓고 200 cm²보다 좁아요","mis":"M6-2-u5-X01"},{"t":"10 cm²보다 넓고 20 cm²보다 좁아요","mis":"M6-2-u5-X12"}],"explanation":["반지름은 5 cm예요.","원 안 정사각형은 5 × 5 × 2 = 50 cm², 원 밖 정사각형은 5 × 5 × 4 = 100 cm²예요.","원의 넓이는 그 사이 — 50 cm²보다 넓고 100 cm²보다 좁아요."],"variant_rule":{"alt":[{"stem":"지름이 14 cm인 원의 넓이를 원 안과 밖에 꼭 맞는 정사각형으로 어림했어요. 알맞은 범위는 어느 것인가요?","options":[{"t":"98 cm²보다 넓고 196 cm²보다 좁아요","correct":true},{"t":"49 cm²보다 넓고 98 cm²보다 좁아요","mis":"M6-2-u5-X11"},{"t":"196 cm²보다 넓고 392 cm²보다 좁아요","mis":"M6-2-u5-X01"},{"t":"14 cm²보다 넓고 28 cm²보다 좁아요","mis":"M6-2-u5-X12"}],"explanation":["반지름은 7 cm예요.","원 안 정사각형은 7 × 7 × 2 = 98 cm², 원 밖 정사각형은 7 × 7 × 4 = 196 cm²예요.","원의 넓이는 그 사이 — 98 cm²보다 넓고 196 cm²보다 좁아요."]},{"stem":"지름이 12 cm인 원의 넓이를 원 안과 밖에 꼭 맞는 정사각형으로 어림했어요. 알맞은 범위는 어느 것인가요?","options":[{"t":"72 cm²보다 넓고 144 cm²보다 좁아요","correct":true},{"t":"36 cm²보다 넓고 72 cm²보다 좁아요","mis":"M6-2-u5-X11"},{"t":"144 cm²보다 넓고 288 cm²보다 좁아요","mis":"M6-2-u5-X01"},{"t":"12 cm²보다 넓고 24 cm²보다 좁아요","mis":"M6-2-u5-X12"}],"explanation":["반지름은 6 cm예요.","원 안 정사각형은 6 × 6 × 2 = 72 cm², 원 밖 정사각형은 6 × 6 × 4 = 144 cm²예요.","원의 넓이는 그 사이 — 72 cm²보다 넓고 144 cm²보다 좁아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_d#16','math',6,2,'u5','','tb_g6_2_math_u5_review_d','unit_review','M6-2-u5-C7',2,'mc','auto','반지름이 12 cm인 원에서 반지름이 6 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X16','M6-2-u5-X20']::text[],true,'{"seq":16,"concept":"M6-2-u5-C7","difficulty":2,"kind":"mc","stem":"반지름이 12 cm인 원에서 반지름이 6 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?","options":[{"t":"339.12 cm²","correct":true},{"t":"452.16 cm²","mis":"M6-2-u5-X16"},{"t":"113.04 cm²","mis":"M6-2-u5-X16"},{"t":"565.2 cm²","mis":"M6-2-u5-X20"}],"explanation":["큰 원의 넓이는 12 × 12 × 3.14 = 452.16 cm²예요.","작은 원의 넓이는 6 × 6 × 3.14 = 113.04 cm²예요.","452.16 − 113.04 = 339.12 cm²예요."],"variant_rule":{"alt":[{"stem":"반지름이 4 cm인 원에서 반지름이 1 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?","options":[{"t":"47.1 cm²","correct":true},{"t":"50.24 cm²","mis":"M6-2-u5-X16"},{"t":"28.26 cm²","mis":"M6-2-u5-X16"},{"t":"53.38 cm²","mis":"M6-2-u5-X20"}],"explanation":["큰 원의 넓이는 4 × 4 × 3.14 = 50.24 cm²예요.","작은 원의 넓이는 1 × 1 × 3.14 = 3.14 cm²예요.","50.24 − 3.14 = 47.1 cm²예요."]},{"stem":"반지름이 7 cm인 원에서 반지름이 4 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?","options":[{"t":"103.62 cm²","correct":true},{"t":"153.86 cm²","mis":"M6-2-u5-X16"},{"t":"28.26 cm²","mis":"M6-2-u5-X16"},{"t":"204.1 cm²","mis":"M6-2-u5-X20"}],"explanation":["큰 원의 넓이는 7 × 7 × 3.14 = 153.86 cm²예요.","작은 원의 넓이는 4 × 4 × 3.14 = 50.24 cm²예요.","153.86 − 50.24 = 103.62 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_d#17','math',6,2,'u5','','tb_g6_2_math_u5_review_d','unit_review','M6-2-u5-C6',3,'mc','auto','원주가 43.96 cm인 원의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X13','M6-2-u5-X12','M6-2-u5-X14']::text[],true,'{"seq":17,"concept":"M6-2-u5-C6","difficulty":3,"kind":"mc","stem":"원주가 43.96 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"153.86 cm²","correct":true},{"t":"615.44 cm²","mis":"M6-2-u5-X13"},{"t":"43.96 cm²","mis":"M6-2-u5-X12"},{"t":"21.98 cm²","mis":"M6-2-u5-X14"}],"explanation":["지름은 43.96 ÷ 3.14 = 14 cm, 반지름은 7 cm예요.","넓이는 7 × 7 × 3.14예요.","7 × 7 × 3.14 = 153.86 cm²예요."],"variant_rule":{"alt":[{"stem":"원주가 87.92 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"615.44 cm²","correct":true},{"t":"2461.76 cm²","mis":"M6-2-u5-X13"},{"t":"87.92 cm²","mis":"M6-2-u5-X12"},{"t":"43.96 cm²","mis":"M6-2-u5-X14"}],"explanation":["지름은 87.92 ÷ 3.14 = 28 cm, 반지름은 14 cm예요.","넓이는 14 × 14 × 3.14예요.","14 × 14 × 3.14 = 615.44 cm²예요."]},{"stem":"원주가 75.36 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"452.16 cm²","correct":true},{"t":"1808.64 cm²","mis":"M6-2-u5-X13"},{"t":"75.36 cm²","mis":"M6-2-u5-X12"},{"t":"37.68 cm²","mis":"M6-2-u5-X14"}],"explanation":["지름은 75.36 ÷ 3.14 = 24 cm, 반지름은 12 cm예요.","넓이는 12 × 12 × 3.14예요.","12 × 12 × 3.14 = 452.16 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_d#18','math',6,2,'u5','','tb_g6_2_math_u5_review_d','unit_review','M6-2-u5-C6',3,'mc','auto','넓이가 넓은 원부터 차례로 놓으려고 해요. ㉠ 반지름이 8 cm인 원 · ㉡ 지름이 14 cm인 원 · ㉢ 넓이가 314 cm²인 원 — 바르게 놓은 것은 어느 것인가요?',ARRAY['M6-2-u5-X01','M6-2-u5-X19','M6-2-u5-X13']::text[],true,'{"seq":18,"concept":"M6-2-u5-C6","difficulty":3,"kind":"mc","stem":"넓이가 넓은 원부터 차례로 놓으려고 해요. ㉠ 반지름이 8 cm인 원 · ㉡ 지름이 14 cm인 원 · ㉢ 넓이가 314 cm²인 원 — 바르게 놓은 것은 어느 것인가요?","options":[{"t":"㉢, ㉠, ㉡","correct":true},{"t":"㉢, ㉡, ㉠","mis":"M6-2-u5-X01"},{"t":"㉡, ㉠, ㉢","mis":"M6-2-u5-X19"},{"t":"㉠, ㉡, ㉢","mis":"M6-2-u5-X13"}],"explanation":["세 원의 넓이를 모두 구해 견주어요.","㉠ 200.96 cm² · ㉡ 153.86 cm² · ㉢ 314 cm²예요.","넓은 원부터 놓으면 ㉢, ㉠, ㉡이에요."],"variant_rule":{"alt":[{"stem":"넓이가 넓은 원부터 차례로 놓으려고 해요. ㉠ 반지름이 10 cm인 원 · ㉡ 넓이가 615.44 cm²인 원 · ㉢ 원주가 75.36 cm인 원 — 바르게 놓은 것은 어느 것인가요?","options":[{"t":"㉡, ㉢, ㉠","correct":true},{"t":"㉠, ㉢, ㉡","mis":"M6-2-u5-X19"},{"t":"㉠, ㉡, ㉢","mis":"M6-2-u5-X13"},{"t":"㉢, ㉡, ㉠","mis":"M6-2-u5-X13"}],"explanation":["세 원의 넓이를 모두 구해 견주어요.","㉠ 314 cm² · ㉡ 615.44 cm² · ㉢ 452.16 cm²예요.","넓은 원부터 놓으면 ㉡, ㉢, ㉠이에요."]},{"stem":"넓이가 넓은 원부터 차례로 놓으려고 해요. ㉠ 지름이 22 cm인 원 · ㉡ 반지름이 9 cm인 원 · ㉢ 넓이가 452.16 cm²인 원 — 바르게 놓은 것은 어느 것인가요?","options":[{"t":"㉢, ㉠, ㉡","correct":true},{"t":"㉡, ㉠, ㉢","mis":"M6-2-u5-X19"},{"t":"㉠, ㉡, ㉢","mis":"M6-2-u5-X13"},{"t":"㉡, ㉢, ㉠","mis":"M6-2-u5-X13"}],"explanation":["세 원의 넓이를 모두 구해 견주어요.","㉠ 379.94 cm² · ㉡ 254.34 cm² · ㉢ 452.16 cm²예요.","넓은 원부터 놓으면 ㉢, ㉠, ㉡이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_d#19','math',6,2,'u5','','tb_g6_2_math_u5_review_d','unit_review','M6-2-u5-C7',3,'mc','auto','지름이 12 cm인 반원이 있어요. 반원의 지름 위 한쪽에는 지름이 6 cm인 반원이 볼록하게 붙어 있고, 다른 쪽은 같은 크기의 반원만큼 패여 있어요. 이 모양의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X17']::text[],true,'{"seq":19,"concept":"M6-2-u5-C7","difficulty":3,"kind":"mc","stem":"지름이 12 cm인 반원이 있어요. 반원의 지름 위 한쪽에는 지름이 6 cm인 반원이 볼록하게 붙어 있고, 다른 쪽은 같은 크기의 반원만큼 패여 있어요. 이 모양의 넓이는 몇 cm²인가요?","options":[{"t":"56.52 cm²","correct":true},{"t":"70.65 cm²","mis":"M6-2-u5-X17"},{"t":"42.39 cm²","mis":"M6-2-u5-X17"},{"t":"113.04 cm²","mis":"M6-2-u5-X17"}],"explanation":["볼록한 반원과 패인 반원은 크기가 같아요.","볼록한 반원을 떼어 패인 곳에 옮기면 반지름 6 cm인 반원 하나가 돼요.","6 × 6 × 3.14 ÷ 2 = 56.52 cm²예요."],"variant_rule":{"alt":[{"stem":"지름이 20 cm인 원 안에 지름이 10 cm인 반원 두 개가 하나는 위로, 하나는 아래로 그려져 있어요. 큰 원에서 두 반원을 뺀 부분의 넓이는 몇 cm²인가요?","options":[{"t":"235.5 cm²","correct":true},{"t":"274.75 cm²","mis":"M6-2-u5-X17"},{"t":"157 cm²","mis":"M6-2-u5-X17"},{"t":"314 cm²","mis":"M6-2-u5-X16"}],"explanation":["큰 원은 10 × 10 × 3.14 = 314 cm²예요.","반원 두 개를 모으면 반지름 5 cm인 원 — 5 × 5 × 3.14 = 78.5 cm²예요.","314 − 78.5 = 235.5 cm²예요."]},{"stem":"지름이 30 cm인 큰 원 안에 지름이 20 cm인 원과 지름이 10 cm인 원이 나란히 꼭 맞게 들어 있어요. 큰 원에서 두 원을 뺀 부분의 넓이는 몇 cm²인가요?","options":[{"t":"314 cm²","correct":true},{"t":"392.5 cm²","mis":"M6-2-u5-X17"},{"t":"628 cm²","mis":"M6-2-u5-X17"},{"t":"1256 cm²","mis":"M6-2-u5-X13"}],"explanation":["큰 원은 15 × 15 × 3.14 = 706.5 cm²예요.","두 원은 314 cm²와 78.5 cm²예요.","706.5 − 314 − 78.5 = 314 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_d#20','math',6,2,'u5','','tb_g6_2_math_u5_review_d','unit_review','M6-2-u5-C6',3,'sa','auto','넓이가 28.26 cm²인 원이 있어요. 이 원의 반지름은 몇 cm인가요?','{}'::text[],true,'{"seq":20,"concept":"M6-2-u5-C6","difficulty":3,"kind":"sa","stem":"넓이가 28.26 cm²인 원이 있어요. 이 원의 반지름은 몇 cm인가요?","answer":["3"],"explanation":["(반지름) × (반지름) × 3.14 = 28.26이에요.","28.26 ÷ 3.14 = 9니 (반지름) × (반지름) = 9예요.","같은 수를 두 번 곱해 9가 되는 수는 3 — 반지름은 3 cm예요."],"variant_rule":{"alt":[{"stem":"넓이가 452.16 cm²인 원이 있어요. 이 원의 반지름은 몇 cm인가요?","answer":["12"],"explanation":["(반지름) × (반지름) × 3.14 = 452.16이에요.","452.16 ÷ 3.14 = 144니 (반지름) × (반지름) = 144예요.","같은 수를 두 번 곱해 144가 되는 수는 12 — 반지름은 12 cm예요."]},{"stem":"넓이가 314 cm²인 원이 있어요. 이 원의 반지름은 몇 cm인가요?","answer":["10"],"explanation":["(반지름) × (반지름) × 3.14 = 314예요.","314 ÷ 3.14 = 100이니 (반지름) × (반지름) = 100이에요.","같은 수를 두 번 곱해 100이 되는 수는 10 — 반지름은 10 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_d#21','math',6,2,'u5','','tb_g6_2_math_u5_review_d','unit_review','M6-2-u5-C8',3,'mc','auto','반지름이 24 cm인 원의 넓이는 반지름이 12 cm인 원의 넓이의 몇 배인가요?',ARRAY['M6-2-u5-X18','M6-2-u5-X20']::text[],true,'{"seq":21,"concept":"M6-2-u5-C8","difficulty":3,"kind":"mc","stem":"반지름이 24 cm인 원의 넓이는 반지름이 12 cm인 원의 넓이의 몇 배인가요?","options":[{"t":"4배","correct":true},{"t":"2배","mis":"M6-2-u5-X18"},{"t":"8배","mis":"M6-2-u5-X20"},{"t":"24배","mis":"M6-2-u5-X20"}],"explanation":["반지름이 24 ÷ 12 = 2배예요.","넓이는 반지름을 두 번 곱하니 2 × 2 = 4배예요.","계산해 봐도 1808.64 ÷ 452.16 = 4예요."],"variant_rule":{"alt":[{"stem":"반지름이 9 cm인 원의 넓이는 반지름이 3 cm인 원의 넓이의 몇 배인가요?","options":[{"t":"9배","correct":true},{"t":"3배","mis":"M6-2-u5-X18"},{"t":"6배","mis":"M6-2-u5-X18"},{"t":"27배","mis":"M6-2-u5-X20"}],"explanation":["반지름이 9 ÷ 3 = 3배예요.","넓이는 반지름을 두 번 곱하니 3 × 3 = 9배예요.","계산해 봐도 254.34 ÷ 28.26 = 9예요."]},{"stem":"반지름이 20 cm인 원의 넓이는 반지름이 10 cm인 원의 넓이의 몇 배인가요?","options":[{"t":"4배","correct":true},{"t":"2배","mis":"M6-2-u5-X18"},{"t":"8배","mis":"M6-2-u5-X20"},{"t":"20배","mis":"M6-2-u5-X20"}],"explanation":["반지름이 20 ÷ 10 = 2배예요.","넓이는 반지름을 두 번 곱하니 2 × 2 = 4배예요.","계산해 봐도 1256 ÷ 314 = 4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_d#22','math',6,2,'u5','','tb_g6_2_math_u5_review_d','unit_review','M6-2-u5-C4',3,'mc','auto','지름이 48 cm인 원판을 몇 바퀴 굴렸더니 753.6 cm만큼 굴러갔어요. 원판이 굴러간 바퀴 수는 몇 바퀴인가요?',ARRAY['M6-2-u5-X07','M6-2-u5-X01','M6-2-u5-X20']::text[],true,'{"seq":22,"concept":"M6-2-u5-C4","difficulty":3,"kind":"mc","stem":"지름이 48 cm인 원판을 몇 바퀴 굴렸더니 753.6 cm만큼 굴러갔어요. 원판이 굴러간 바퀴 수는 몇 바퀴인가요?","options":[{"t":"5바퀴","correct":true},{"t":"10바퀴","mis":"M6-2-u5-X07"},{"t":"2.5바퀴","mis":"M6-2-u5-X01"},{"t":"15바퀴","mis":"M6-2-u5-X20"}],"explanation":["한 바퀴 굴러간 거리는 원판의 원주예요.","지름 48 cm — 원주는 48 × 3.14 = 150.72 cm예요.","753.6 ÷ 150.72 = 5 — 5바퀴예요."],"variant_rule":{"alt":[{"stem":"반지름이 15 cm인 원판을 몇 바퀴 굴렸더니 471 cm만큼 굴러갔어요. 원판이 굴러간 바퀴 수는 몇 바퀴인가요?","options":[{"t":"5바퀴","correct":true},{"t":"10바퀴","mis":"M6-2-u5-X07"},{"t":"2.5바퀴","mis":"M6-2-u5-X01"},{"t":"15바퀴","mis":"M6-2-u5-X20"}],"explanation":["한 바퀴 굴러간 거리는 원판의 원주예요.","지름 30 cm — 원주는 30 × 3.14 = 94.2 cm예요.","471 ÷ 94.2 = 5 — 5바퀴예요."]},{"stem":"지름이 20 cm인 원판을 몇 바퀴 굴렸더니 628 cm만큼 굴러갔어요. 원판이 굴러간 바퀴 수는 몇 바퀴인가요?","options":[{"t":"10바퀴","correct":true},{"t":"20바퀴","mis":"M6-2-u5-X07"},{"t":"5바퀴","mis":"M6-2-u5-X01"},{"t":"30바퀴","mis":"M6-2-u5-X20"}],"explanation":["한 바퀴 굴러간 거리는 원판의 원주예요.","지름 20 cm — 원주는 20 × 3.14 = 62.8 cm예요.","628 ÷ 62.8 = 10 — 10바퀴예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_d#23','math',6,2,'u5','','tb_g6_2_math_u5_review_d','unit_review','M6-2-u5-C2',4,'essay','teacher','잘못된 문장을 찾고, 바르게 고쳐 써 보세요. ㉠ 원의 크기가 달라져도 원주율은 일정합니다. ㉡ 반지름이 길어지면 원주도 길어집니다. ㉢ 원주에 대한 원의 지름의 비율을 원주율이라고 합니다.','{}'::text[],true,'{"seq":23,"concept":"M6-2-u5-C2","difficulty":4,"kind":"essay","stem":"잘못된 문장을 찾고, 바르게 고쳐 써 보세요. ㉠ 원의 크기가 달라져도 원주율은 일정합니다. ㉡ 반지름이 길어지면 원주도 길어집니다. ㉢ 원주에 대한 원의 지름의 비율을 원주율이라고 합니다.","answer_guide":{"answer":"예: ㉢ — 바른 문장: 원의 지름에 대한 원주의 비율을 원주율이라고 합니다.","scoring_points":["잘못된 문장(㉢)을 찾았는가","바른 문장으로 고쳐 썼는가","고친 까닭(원주율은 지름에 대한 원주의 비율(기준량 = 지름))을 알고 있는가"]},"explanation":["문장마다 원주·원주율의 뜻과 견주어 봐요.","잘못된 문장은 ㉢이에요.","바르게 고치면 「원의 지름에 대한 원주의 비율을 원주율이라고 합니다.」예요."],"variant_rule":{"alt":[{"stem":"잘못된 문장을 찾고, 바르게 고쳐 써 보세요. ㉠ 지름이 길어지면 원주도 길어집니다. ㉡ 원이 커지면 원주율도 커집니다. ㉢ 원주는 지름의 약 3.14배입니다. ㉣ 원주율을 소수로 나타내면 3.141592…와 같이 끝없이 계속됩니다.","answer_guide":{"answer":"예: ㉡ — 바른 문장: 원주율은 원의 크기에 상관없이 일정합니다.","scoring_points":["잘못된 문장(㉡)을 찾았는가","바른 문장으로 고쳐 썼는가","고친 까닭(원이 커지면 원주와 지름이 함께 늘어나 비율은 그대로)을 알고 있는가"]},"explanation":["문장마다 원주·원주율의 뜻과 견주어 봐요.","잘못된 문장은 ㉡이에요.","바르게 고치면 「원주율은 원의 크기에 상관없이 일정합니다.」예요."]},{"stem":"잘못된 문장을 찾고, 바르게 고쳐 써 보세요. ㉠ 지름이 길어지면 원주도 길어집니다. ㉡ 원의 지름에 대한 원주의 비율은 지름마다 다릅니다. ㉢ 원주는 지름의 약 3.14배입니다.","answer_guide":{"answer":"예: ㉡ — 바른 문장: 원의 지름에 대한 원주의 비율은 일정합니다.","scoring_points":["잘못된 문장(㉡)을 찾았는가","바른 문장으로 고쳐 썼는가","고친 까닭(어떤 원을 재어도 (원주) ÷ (지름)은 약 3.14)을 알고 있는가"]},"explanation":["문장마다 원주·원주율의 뜻과 견주어 봐요.","잘못된 문장은 ㉡이에요.","바르게 고치면 「원의 지름에 대한 원주의 비율은 일정합니다.」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_d#24','math',6,2,'u5','','tb_g6_2_math_u5_review_d','unit_review','M6-2-u5-C7',4,'essay','teacher','한 변이 20 cm인 정사각형의 네 꼭짓점을 중심으로 반지름이 10 cm인 사분원을 그렸어요. 노란색 사분원 4개와 가운데 초록색 부분의 넓이를 각각 구하는 과정을 써 보세요.','{}'::text[],true,'{"seq":24,"concept":"M6-2-u5-C7","difficulty":4,"kind":"essay","stem":"한 변이 20 cm인 정사각형의 네 꼭짓점을 중심으로 반지름이 10 cm인 사분원을 그렸어요. 노란색 사분원 4개와 가운데 초록색 부분의 넓이를 각각 구하는 과정을 써 보세요.","answer_guide":{"answer":"예: 노란색 사분원 4개를 직각인 꼭짓점을 중심으로 모으면 반지름 10 cm인 원이 되어 10 × 10 × 3.14 = 314 cm²이다. 초록색 부분은 정사각형에서 노란색 부분을 빼어 20 × 20 − 314 = 86 cm²이다.","scoring_points":["사분원 4개를 원 하나로 모았는가","노란색 314 cm²를 구했는가","초록색 86 cm²를 구했는가"]},"explanation":["사분원 4개 = 반지름 10 cm인 원이에요.","노란색은 314 cm²예요.","초록색은 400 − 314 = 86 cm²예요."],"variant_rule":{"alt":[{"stem":"가로 12 cm, 세로 15 cm인 직사각형 안에 그릴 수 있는 가장 큰 원의 넓이는 몇 cm²인지 풀이 과정을 쓰고 답을 구해 보세요.","answer_guide":{"answer":"예: 직사각형 안에 그릴 수 있는 가장 큰 원의 지름은 짧은 변의 길이인 12 cm이다. 반지름은 6 cm이므로 넓이는 6 × 6 × 3.14 = 113.04 cm²이다.","scoring_points":["가장 큰 원의 지름이 짧은 변 12 cm라고 썼는가","반지름 6 cm로 식을 세웠는가","113.04 cm²를 구했는가"]},"explanation":["가장 큰 원의 지름은 짧은 변 12 cm예요.","반지름은 6 cm예요.","6 × 6 × 3.14 = 113.04 cm²예요."]},{"stem":"가는 반지름이 9 cm인 원, 나는 반지름이 3 cm인 원이에요. 가의 넓이는 나의 넓이의 몇 배인지 풀이 과정을 쓰고 답을 구해 보세요.","answer_guide":{"answer":"예: 가의 넓이는 9 × 9 × 3.14 = 254.34 cm², 나의 넓이는 3 × 3 × 3.14 = 28.26 cm²이다. 254.34 ÷ 28.26 = 9이므로 9배이다. (반지름이 3배이니 3 × 3 = 9배로 구해도 된다.)","scoring_points":["두 넓이 254.34 cm²·28.26 cm²를 구했는가","나눗셈으로 9배를 구했는가","반지름 3배 → 넓이 9배를 설명했는가"]},"explanation":["가는 254.34 cm², 나는 28.26 cm²예요.","254.34 ÷ 28.26 = 9예요.","반지름이 3배라 넓이는 3 × 3 = 9배예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u5_review_d#25','math',6,2,'u5','','tb_g6_2_math_u5_review_d','unit_review','M6-2-u5-C6',4,'essay','teacher','고대 이집트 사람들은 지름이 9인 원의 넓이를 한 변이 8인 정사각형의 넓이와 같다고 생각했어요. 원주율을 3.14로 하여 지름이 9 m인 원의 넓이를 구하고, 이 생각이 얼마나 맞는지 설명해 보세요.','{}'::text[],true,'{"seq":25,"concept":"M6-2-u5-C6","difficulty":4,"kind":"essay","stem":"고대 이집트 사람들은 지름이 9인 원의 넓이를 한 변이 8인 정사각형의 넓이와 같다고 생각했어요. 원주율을 3.14로 하여 지름이 9 m인 원의 넓이를 구하고, 이 생각이 얼마나 맞는지 설명해 보세요.","answer_guide":{"answer":"예: 반지름이 4.5 m이므로 원의 넓이는 4.5 × 4.5 × 3.14 = 63.585 m²이다. 한 변이 8 m인 정사각형의 넓이는 8 × 8 = 64 m²이다. 차가 0.415 m²로 매우 작아 꽤 비슷하게 어림했다.","scoring_points":["원의 넓이 63.585 m²를 구했는가","정사각형 64 m²를 구했는가","두 넓이가 비슷하다고 견주었는가"]},"explanation":["반지름은 4.5 m예요.","4.5 × 4.5 × 3.14 = 63.585 m², 8 × 8 = 64 m²예요.","차가 0.415 m² — 꽤 가까워요."],"variant_rule":{"alt":[{"stem":"반지름이 5 cm인 원 안쪽에 맞닿는 정사각형, 정육각형, 정십이각형, 정이십이각형의 둘레는 28.28 cm, 30 cm, 31.08 cm, 31.24 cm예요. (둘레) ÷ (지름)을 구하고 원주율과 견주어 알게 된 점을 써 보세요.","answer_guide":{"answer":"예: 2.828, 3, 3.108, 3.124이다. 정다각형의 변의 수가 늘어날수록 원에 가까워지고 (둘레) ÷ (지름)은 원주율 3.14에 가까워진다.","scoring_points":["네 값을 구했는가","변의 수가 늘수록 원에 가까워진다고 썼는가","값이 원주율 3.14에 가까워진다고 썼는가"]},"explanation":["지름은 10 cm예요.","2.828 → 3 → 3.108 → 3.124예요.","변이 늘수록 3.14에 가까워져요."]},{"stem":"반지름이 3배가 되면 원주와 원의 넓이는 각각 몇 배가 되는지 쓰고, 두 배수가 다른 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 원주는 3배, 넓이는 9배가 된다. 원주는 (지름) × (원주율)로 길이를 한 번 곱하지만 넓이는 반지름을 두 번 곱하므로 3 × 3 = 9배가 된다.","scoring_points":["원주 3배를 썼는가","넓이 9배를 썼는가","한 번·두 번 곱하는 차이로 설명했는가"]},"explanation":["원주는 3배예요.","넓이는 3 × 3 = 9배예요.","넓이는 반지름을 두 번 곱해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
